t14Shell.Items.Add(new ShellContent { Title = "Beta", ContentTemplate = new DataTemplate(() => new ContentPage { Title = "Beta", Content = new Label { Text = "beta" } }) });
t14Shell.FlyoutHeader = t14Header;
t14Shell.FlyoutFooter = t14Footer;
