bool t14MenuRowsOk = t14MenuRows.Count == 3 &&
    t14RowText(t14MenuRows[0]) == "Home" && t14MenuRows[0].Target is ShellContent && t14MenuRows[0].ItemIndex == 0 &&
    t14MenuRows[1].Target is MenuItem && t14MenuRows[1].ItemIndex == -1 &&
