// Audit batch 2 assertions.
var graphicsCtl = root.Children.OfType<GraphicsView>().FirstOrDefault();
if (graphicsCtl?.Handler?.PlatformView is OpenHarmonyView graphicsPlatform)
{
    var rendererForGraphics = app.Services.GetRequiredService<OpenHarmonyWindowRenderer>();
    rendererForGraphics.Render(navRoot, 1080, 1920);
    Console.WriteLine($"[verify] graphicsview drawCalled={gestures.Drawable?.DrawCalls} frame={graphicsCtl.Frame}");
    Rect gf = graphicsCtl.Frame;
    // The audit layout is taller than the surface, so the GraphicsView is arranged below the
    // viewport and the compositor's frame-based hit test correctly ignores taps there. Probe it
    // at a known on-screen rect (same size) and restore the layout after the interaction.
    graphicsCtl.Arrange(new Rect(24, 120, gf.Width, gf.Height));
    Rect gp = graphicsCtl.Frame;

    // T3: the IGraphicsView interaction contract. The compositor routes presses, moves and the
    // release/cancel of the whole gesture stream (multi-touch) plus mouse hover; Controls'
    // GraphicsView raises its events from those calls. Count every callback and pin the point
    // payload (window coordinates: the same space as the drawable's dirty rect).
    int gvStart = 0, gvDrag = 0, gvEnd = 0, gvCancel = 0;
    int gvHoverStart = 0, gvHoverMove = 0, gvHoverEnd = 0;
    int gvStartPoints = 0, gvDragPoints = 0, gvEndPoints = 0;
    bool gvFirstInside = false, gvSecondInside = true;
    float gvFirstX = float.NaN, gvFirstY = float.NaN;
    // The latest drag payload: per-pointer coordinates after both pointers of the stream moved
    // (the renderer tracks each pointer id separately, so each entry keeps its own position).
    PointF[] gvDragLatest = Array.Empty<PointF>();
    graphicsCtl.StartInteraction += (_, e) =>
    {
        gvStart++;
        gvStartPoints = Math.Max(gvStartPoints, e.Touches.Length);
        if (gvStart == 1)
        {
            gvFirstX = e.Touches[0].X;
            gvFirstY = e.Touches[0].Y;
        }
    };
    graphicsCtl.DragInteraction += (_, e) =>
    {
        gvDrag++;
        gvDragPoints = Math.Max(gvDragPoints, e.Touches.Length);
        gvDragLatest = e.Touches;
    };
    graphicsCtl.EndInteraction += (_, e) =>
    {
        gvEnd++;
        gvEndPoints = Math.Max(gvEndPoints, e.Touches.Length);
        if (gvEnd == 1)
        {
            gvFirstInside = e.IsInsideBounds;
        }
        else if (gvEnd == 2)
        {
            gvSecondInside = e.IsInsideBounds;
        }
    };
    graphicsCtl.CancelInteraction += (_, _) => gvCancel++;
    graphicsCtl.StartHoverInteraction += (_, _) => gvHoverStart++;
    graphicsCtl.MoveHoverInteraction += (_, _) => gvHoverMove++;
    graphicsCtl.EndHoverInteraction += (_, _) => gvHoverEnd++;

    float gx = (float)(gp.X + 10), gy = (float)(gp.Y + 10);
    host.HandleTouch(true, false, gx, gy);
    host.HandleTouch(false, true, gx, gy);
    Console.WriteLine($"[verify] graphicsview touchCalls={gestures.Drawable?.TouchCalls}");
    // Drag out of the frame and release outside: EndInteraction reports the outside release.
    host.HandleTouch(true, false, gx, gy);
    host.HandleMove(gx + 40, gy + 20);
    host.HandleMove((float)(gp.X + gp.Width + 40), (float)(gp.Y + 40));
    host.HandleTouch(false, true, (float)(gp.X + gp.Width + 40), (float)(gp.Y + 40));
    // A second pointer joins the captured gesture: drag and release carry both points.
    host.HandleTouch(true, false, gx, gy, 7);
    host.HandleMove(gx + 12, gy, 7);
    host.HandleTouch(true, false, gx + 30, gy + 10, 9);
    host.HandleMove(gx + 40, gy + 10, 9);
    // Per-pointer association: pointer 7 keeps the position from its own move while pointer 9
    // moves (the pre-N1 host reported point 0 for every event, so both entries collapsed).
    bool gvPointerPointsOk = gvDragLatest.Length == 2 &&
        Math.Abs(gvDragLatest[0].X - (gx + 12)) < 0.01f && Math.Abs(gvDragLatest[0].Y - gy) < 0.01f &&
        Math.Abs(gvDragLatest[1].X - (gx + 40)) < 0.01f && Math.Abs(gvDragLatest[1].Y - (gy + 10)) < 0.01f;
    host.HandleTouch(false, true, gx + 40, gy + 10, 9);
    host.HandleMove(gx + 20, gy, 7);
    host.HandleTouch(false, true, gx + 20, gy, 7);
    // Cancel drops the captured gesture without a release event.
    host.HandleTouch(true, false, gx, gy, 3);
    host.HandleCancel(gx, gy);
    // Hover: pointer moves with no press behind them.
    host.HandleMove(gx + 5, gy + 5);
    host.HandleMove(gx + 6, gy + 6);
    host.HandleMove((float)(gp.X + gp.Width + 200), gy);
    // Invalidate: the drawable's repaint request reaches the platform bridge.
    int gvRedraws = 0;
    Action gvRedraw = () => gvRedraws++;

    bool gvPointerOk = gvStart == 5 && gvDrag == 5 && gvEnd == 4 && gvCancel == 1;
    bool gvPointPinned = Math.Abs(gvFirstX - gx) < 0.01f && Math.Abs(gvFirstY - gy) < 0.01f;
    Console.WriteLine($"[verify] graphicsview interaction start={gvStart} drag={gvDrag} end={gvEnd} cancel={gvCancel} startPoints={gvStartPoints} dragPoints={gvDragPoints} endPoints={gvEndPoints} pointerPoints={gvPointerPointsOk}");
    Console.WriteLine($"[verify] graphicsview interaction bounds tapInside={gvFirstInside} dragOutside={!gvSecondInside} pointPinned={gvPointPinned} pointerOk={gvPointerOk}");
    Console.WriteLine($"[verify] graphicsview interaction hover start={gvHoverStart} move={gvHoverMove} end={gvHoverEnd}");
    Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.RedrawRequested += gvRedraw;
    graphicsCtl.Invalidate();
    Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.RedrawRequested -= gvRedraw;
    Console.WriteLine($"[verify] graphicsview invalidate redraws={gvRedraws}");
    // Restore the audit layout: the following assertions read the normal frames again.
    host.Arrange(1080, 1920);
    bool gvOk = gvPointerOk && gvStartPoints == 2 && gvDragPoints == 2 && gvEndPoints == 2 &&
        gvFirstInside && !gvSecondInside && gvPointPinned && gvPointerPointsOk &&
        gvHoverStart == 1 && gvHoverMove == 1 && gvHoverEnd == 1 && gvRedraws == 1;
    if (!gvOk)
    {
        throw new InvalidOperationException("the GraphicsView interaction contract (press/drag/multi-touch/cancel/hover/invalidate) is missing or drifted");
    }
}

// N1: the host reports every pointer of a touch event (element/surface coordinates, see
// FIX-ITOUCH) and the managed bridge keeps each point addressable by id; the app host
// dispatches the changed pointer by id.
// The native OnTouch builds the array from the XComponent event (source-pinned below), so the
// managed half is driven off-device through the registered thunk with a crafted native buffer.
{
    var n1TouchHandlers = typeof(Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge)
        .GetField("s_touchHandlers", BindingFlags.NonPublic | BindingFlags.Static)
        ?? throw new InvalidOperationException("OpenHarmonyBridge.s_touchHandlers was not found; the N1 touch contract needs the handler seam");
    object? n1TouchHandlersBefore = n1TouchHandlers.GetValue(null);
    var n1TouchEvents = new List<Microsoft.OpenHarmony.Hosting.OpenHarmonyTouchEventArgs>();
    n1TouchHandlers.SetValue(null, (Action<Microsoft.OpenHarmony.Hosting.OpenHarmonyTouchEventArgs>)n1TouchEvents.Add);
    try
    {
        var n1TouchPoints = new[]
        {
            new NativeThunks.TouchPoint { Id = 7, X = 10f, Y = 20f },
            new NativeThunks.TouchPoint { Id = 9, X = 30f, Y = 40f },
        };
        unsafe
        {
            fixed (NativeThunks.TouchPoint* n1TouchFirst = n1TouchPoints)
            {
                NativeThunks.Invoker<NativeThunks.TouchCallback>(
                    NativeThunks.Pointer(typeof(Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge), "s_touchThunk"))(
                    2, (IntPtr)n1TouchFirst, n1TouchPoints.Length, 9, 30f, 40f);
            }
            // A final up whose lifted point is already gone from the list still reports the
            // changed pointer's own coordinates (count 0, no points).
            NativeThunks.Invoker<NativeThunks.TouchCallback>(
                NativeThunks.Pointer(typeof(Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge), "s_touchThunk"))(
                1, IntPtr.Zero, 0, 9, 55f, 66f);
        }
    }
    finally
    {
        n1TouchHandlers.SetValue(null, n1TouchHandlersBefore);
    }

    var n1TouchMove = n1TouchEvents.Count > 0 ? n1TouchEvents[0] : null;
    var n1TouchUp = n1TouchEvents.Count > 1 ? n1TouchEvents[1] : null;
    // The primary coordinates follow the changed pointer (id 9 at 30,40), not point 0 (id 7).
    bool n1TouchMoveOk = n1TouchMove is not null &&
        n1TouchMove.Action == Microsoft.OpenHarmony.Hosting.OpenHarmonyTouchAction.Move &&
        n1TouchMove.PointerCount == 2 && n1TouchMove.PointerId == 9 &&
        Math.Abs(n1TouchMove.X - 30f) < 0.01f && Math.Abs(n1TouchMove.Y - 40f) < 0.01f &&
        n1TouchMove.Points.Length == 2 &&
        n1TouchMove.Points[0].Id == 7 && Math.Abs(n1TouchMove.Points[0].X - 10f) < 0.01f &&
        Math.Abs(n1TouchMove.Points[0].Y - 20f) < 0.01f &&
        n1TouchMove.Points[1].Id == 9 && Math.Abs(n1TouchMove.Points[1].X - 30f) < 0.01f &&
        Math.Abs(n1TouchMove.Points[1].Y - 40f) < 0.01f;
    bool n1TouchUpOk = n1TouchUp is not null &&
        n1TouchUp.Action == Microsoft.OpenHarmony.Hosting.OpenHarmonyTouchAction.Up &&
        n1TouchUp.PointerCount == 0 && n1TouchUp.Points.Length == 0 && n1TouchUp.PointerId == 9 &&
        Math.Abs(n1TouchUp.X - 55f) < 0.01f && Math.Abs(n1TouchUp.Y - 66f) < 0.01f;
    // Native half: the XComponent walk must report every active point and match the changed
    // pointer by id (the pre-N1 code read window point 0 for every event).
    string? n1TouchNativePath = FindHostSource("src/OpenHarmonyHost/host_napi.cpp");
    string n1TouchNative = n1TouchNativePath is null ? string.Empty : File.ReadAllText(n1TouchNativePath);
    string? n1TouchHeaderPath = FindHostSource("src/OpenHarmonyHost/openharmony_host.h");
    string n1TouchHeader = n1TouchHeaderPath is null ? string.Empty : File.ReadAllText(n1TouchHeaderPath);
    // FIX-ITOUCH: the reported coordinates must be the touch point's element-relative x/y -
    // the window accessors include the system title bar on a decorated window and shifted
    // every injected tap by the decoration height (uitest clicks resolved a full title bar
    // below their target). The window/display accessors must not come back.
    bool n1TouchNativeOk = n1TouchNative.Contains("ohos_host_notify_touch_points(") &&
        n1TouchNative.Contains("i < total") && n1TouchNative.Contains("event.touchPoints[i].id") &&
        n1TouchNative.Contains("points[count].x = event.touchPoints[i].x") &&
        n1TouchNative.Contains("points[count].y = event.touchPoints[i].y") &&
        !n1TouchNative.Contains("GetTouchPointWindowX(component") &&
        n1TouchNative.Contains("points[i].id == static_cast<int>(event.id)") &&
        n1TouchHeader.Contains("} OhosTouchPoint;") &&
        n1TouchHeader.Contains("element (surface) coordinates") &&
        n1TouchHeader.Contains("ohos_host_notify_touch_points(int type, const OhosTouchPoint* points, int count,");
    // The ABI struct the thunk reads must stay 12 bytes with the native field order (int id,
    // float x, float y), otherwise the host would write coordinates the managed side misreads.
    bool n1TouchLayoutOk = Marshal.SizeOf<NativeThunks.TouchPoint>() == 12 &&
        (int)Marshal.OffsetOf<NativeThunks.TouchPoint>("Id") == 0 &&
        (int)Marshal.OffsetOf<NativeThunks.TouchPoint>("X") == 4 &&
        (int)Marshal.OffsetOf<NativeThunks.TouchPoint>("Y") == 8;
    Console.WriteLine($"[verify] host touch multi-pointer reported={n1TouchMove?.Points.Length ?? -1} changed={n1TouchMove?.PointerId ?? -1} primary={n1TouchMove?.X ?? float.NaN},{n1TouchMove?.Y ?? float.NaN} assert={n1TouchMoveOk}");
    Console.WriteLine($"[verify] host touch multi-pointer empty count={n1TouchUp?.PointerCount ?? -1} changed={n1TouchUp?.PointerId ?? -1} primary={n1TouchUp?.X ?? float.NaN},{n1TouchUp?.Y ?? float.NaN} assert={n1TouchUpOk}");
    Console.WriteLine($"[verify] host touch multi-pointer native allPoints={n1TouchNativeOk} layout={n1TouchLayoutOk} assert={n1TouchNativeOk && n1TouchLayoutOk}");
    if (!n1TouchMoveOk || !n1TouchUpOk || !n1TouchNativeOk || !n1TouchLayoutOk)
    {
        throw new InvalidOperationException("the N1 host multi-pointer contract (all points reported, changed pointer by id) is missing or drifted");
    }
}

// T5: the layout semantics the compositor keeps in its own walk. Z-order: siblings stack by
// ZIndex (the highest is drawn last and the hit-test walks resolve it as the topmost) and a
// ZIndex change requests a repaint; clip: a view's Clip excludes the clipped-away regions from
// hit-testing; input transparency: a transparent view never receives input, a cascading layout
// also excludes its subtree and a non-cascading layout keeps its children interactive.
// AnchorX/AnchorY is pinned through the renderer's pivot seam (rotation/scale must pivot at the
// anchor point, not the frame centre). The probes are handler-connected standalone trees; the
// audit page itself is never touched.
var t5Renderer = app.Services.GetRequiredService<OpenHarmonyWindowRenderer>();
var t5ZGrid = new Grid();
var t5ZBottom = new BoxView { Color = Colors.Gray };
var t5ZTop = new BoxView { Color = Colors.OrangeRed, ZIndex = 1 };
int t5ZTopEntered = 0, t5ZBottomEntered = 0;
var t5ZTopPointer = new PointerGestureRecognizer();
t5ZTopPointer.PointerEntered += (_, _) => t5ZTopEntered++;
t5ZTop.GestureRecognizers.Add(t5ZTopPointer);
var t5ZBottomPointer = new PointerGestureRecognizer();
t5ZBottomPointer.PointerEntered += (_, _) => t5ZBottomEntered++;
t5ZBottom.GestureRecognizers.Add(t5ZBottomPointer);
t5ZGrid.Add(t5ZBottom);
t5ZGrid.Add(t5ZTop);
OpenHarmonyHandlerConnector.ConnectTree(t5ZGrid);
t5ZGrid.Measure(300, 200);
t5ZGrid.Arrange(new Rect(0, 0, 300, 200));
t5Renderer.HandlePointerMove(t5ZGrid, 150, 100);
bool t5ZTopFirst = t5ZTopEntered == 1 && t5ZBottomEntered == 0;
int t5ZIndexRedraws = 0;
Action t5ZIndexRedraw = () => t5ZIndexRedraws++;
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.RedrawRequested += t5ZIndexRedraw;
t5ZTop.ZIndex = -1;
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.RedrawRequested -= t5ZIndexRedraw;
t5Renderer.HandlePointerMove(t5ZGrid, 150, 100);
bool t5ZSwapped = t5ZTopEntered == 1 && t5ZBottomEntered == 1;
Console.WriteLine($"[verify] t5 z-order hover top={t5ZTopEntered} bottom={t5ZBottomEntered} topFirst={t5ZTopFirst} bottomAfterSwap={t5ZSwapped} zindexRedraws={t5ZIndexRedraws}");

var t5InputRoot = new VerticalStackLayout();
int t5NormalClicks = 0, t5TransparentClicks = 0, t5CascadeClicks = 0, t5NonCascadeClicks = 0;
var t5Normal = new Button { Text = "normal", HeightRequest = 60 };
t5Normal.Clicked += (_, _) => t5NormalClicks++;
var t5Transparent = new Button { Text = "transparent", HeightRequest = 60, InputTransparent = true };
t5Transparent.Clicked += (_, _) => t5TransparentClicks++;
var t5Cascade = new VerticalStackLayout { InputTransparent = true };
var t5CascadeButton = new Button { Text = "cascade child", HeightRequest = 60 };
t5CascadeButton.Clicked += (_, _) => t5CascadeClicks++;
t5Cascade.Add(t5CascadeButton);
var t5NonCascade = new VerticalStackLayout { InputTransparent = true, CascadeInputTransparent = false };
var t5NonCascadeButton = new Button { Text = "non-cascade child", HeightRequest = 60 };
t5NonCascadeButton.Clicked += (_, _) => t5NonCascadeClicks++;
t5NonCascade.Add(t5NonCascadeButton);
t5InputRoot.Add(t5Normal);
t5InputRoot.Add(t5Transparent);
t5InputRoot.Add(t5Cascade);
t5InputRoot.Add(t5NonCascade);
OpenHarmonyHandlerConnector.ConnectTree(t5InputRoot);
t5InputRoot.Measure(300, 240);
t5InputRoot.Arrange(new Rect(0, 0, 300, 240));
void TapT5(IView target)
{
    Rect frame = target.Frame;
    float cx = (float)(frame.X + frame.Width / 2), cy = (float)(frame.Y + frame.Height / 2);
    t5Renderer.HandleTouch(t5InputRoot, true, false, cx, cy);
    t5Renderer.HandleTouch(t5InputRoot, false, true, cx, cy);
}
TapT5(t5Normal);
TapT5(t5Transparent);
TapT5(t5CascadeButton);
TapT5(t5NonCascadeButton);
bool t5InputOk = t5NormalClicks == 1 && t5TransparentClicks == 0 && t5CascadeClicks == 0 && t5NonCascadeClicks == 1;
Console.WriteLine($"[verify] t5 input transparency normal={t5NormalClicks} transparent={t5TransparentClicks} cascade={t5CascadeClicks} nonCascade={t5NonCascadeClicks}");

var t5ClipRoot = new Grid();
var t5Clipped = new Button { Text = "clipped" };
t5Clipped.Clip = new Microsoft.Maui.Controls.Shapes.RectangleGeometry { Rect = new Rect(0, 0, 300, 50) };
int t5ClipClicks = 0;
t5Clipped.Clicked += (_, _) => t5ClipClicks++;
t5ClipRoot.Add(t5Clipped);
OpenHarmonyHandlerConnector.ConnectTree(t5ClipRoot);
t5ClipRoot.Measure(300, 100);
t5ClipRoot.Arrange(new Rect(0, 0, 300, 100));
t5Renderer.HandleTouch(t5ClipRoot, true, false, 150, 25);
t5Renderer.HandleTouch(t5ClipRoot, false, true, 150, 25);
t5Renderer.HandleTouch(t5ClipRoot, true, false, 150, 75);
t5Renderer.HandleTouch(t5ClipRoot, false, true, 150, 75);
bool t5ClipOk = t5ClipClicks == 1;
Console.WriteLine($"[verify] t5 clip hit inside=1 outside=0 clicks={t5ClipClicks}");

var t5AnchorRoot = new Grid();
var t5Anchored = new BoxView { Color = Colors.Gold, Rotation = 10, AnchorX = 0, AnchorY = 0 };
t5AnchorRoot.Add(t5Anchored);
OpenHarmonyHandlerConnector.ConnectTree(t5AnchorRoot);
float t5PivotX = float.NaN, t5PivotY = float.NaN;
OpenHarmonyWindowRenderer.TransformPivotObserved = (x, y) => { t5PivotX = x; t5PivotY = y; };
t5Renderer.Render(t5AnchorRoot, 200, 120);
Rect t5AnchorFrame = t5Anchored.Frame;
bool t5AnchorTopLeftOk = Math.Abs(t5PivotX - t5AnchorFrame.X) < 0.01f && Math.Abs(t5PivotY - t5AnchorFrame.Y) < 0.01f;
t5Anchored.AnchorX = 1;
t5Anchored.AnchorY = 1;
t5Renderer.Render(t5AnchorRoot, 200, 120);
bool t5AnchorBottomRightOk = Math.Abs(t5PivotX - t5AnchorFrame.Right) < 0.01f && Math.Abs(t5PivotY - t5AnchorFrame.Bottom) < 0.01f;
t5Anchored.AnchorX = 0.5;
t5Anchored.AnchorY = 0.5;
t5Renderer.Render(t5AnchorRoot, 200, 120);
bool t5AnchorCenterOk = Math.Abs(t5PivotX - t5AnchorFrame.Center.X) < 0.01f && Math.Abs(t5PivotY - t5AnchorFrame.Center.Y) < 0.01f;
OpenHarmonyWindowRenderer.TransformPivotObserved = null;
Console.WriteLine($"[verify] t5 anchor pivots frame={t5AnchorFrame} topLeft={t5AnchorTopLeftOk} bottomRight={t5AnchorBottomRightOk} center={t5AnchorCenterOk}");

if (!(t5ZTopFirst && t5ZSwapped && t5ZIndexRedraws >= 1 && t5InputOk && t5ClipOk
    && t5AnchorTopLeftOk && t5AnchorBottomRightOk && t5AnchorCenterOk))
{
    throw new InvalidOperationException("the T5 layout semantics (z-order, clip, input transparency, anchors) are missing or drifted");
}

// T6: RTL/FlowDirection. Upstream MAUI defers RTL to the platform (dotnet/maui#9558): the
// compositor mirrors the canvas placement of every child of a right-to-left layout (the native
// platforms' arrange flip), keeps IView.Frame logical for arrange-time readers, resolves
// Start/End text alignment and trailing affordances against the view's own direction, and
// mirrors the laid-out chrome (navigation bar/toolbar, shell flyout menu, picker dropdown,
// calendar) in both drawing and hit testing. MatchParent inherits; LTR trees map to themselves.
var t6Renderer = app.Services.GetRequiredService<OpenHarmonyWindowRenderer>();
var t6Stack = new HorizontalStackLayout { FlowDirection = FlowDirection.RightToLeft, Spacing = 0 };
var t6BoxA = new BoxView { WidthRequest = 100, HeightRequest = 60, Color = Colors.Red };
var t6BoxB = new BoxView { WidthRequest = 100, HeightRequest = 60, Color = Colors.Green };
var t6BoxC = new BoxView { WidthRequest = 100, HeightRequest = 60, Color = Colors.Blue };
t6Stack.Add(t6BoxA);
t6Stack.Add(t6BoxB);
t6Stack.Add(t6BoxC);
OpenHarmonyHandlerConnector.ConnectTree(t6Stack);
t6Stack.Measure(300, 60);
t6Stack.Arrange(new Rect(0, 0, 300, 60));
bool t6Rendered = t6Renderer.Render(t6Stack, 300, 60);
var t6PlatformA = (OpenHarmonyView)t6BoxA.Handler!.PlatformView!;
var t6PlatformB = (OpenHarmonyView)t6BoxB.Handler!.PlatformView!;
var t6PlatformC = (OpenHarmonyView)t6BoxC.Handler!.PlatformView!;
bool t6LayoutMirrored = Math.Abs(t6PlatformA.CanvasFrame.X - 200) < 0.01
    && Math.Abs(t6PlatformB.CanvasFrame.X - 100) < 0.01
    && Math.Abs(t6PlatformC.CanvasFrame.X) < 0.01;
bool t6LogicalKept = t6BoxA.Frame.X == 0 && t6BoxB.Frame.X == 100 && t6BoxC.Frame.X == 200;
bool t6MatchParent = t6PlatformA.FlowRightToLeft && t6PlatformB.FlowRightToLeft && t6PlatformC.FlowRightToLeft;
bool t6LayoutOk = t6Rendered && t6LayoutMirrored && t6LogicalKept && t6MatchParent;
Console.WriteLine($"[verify] t6 layout mirror rendered={t6Rendered} physical={t6PlatformA.CanvasFrame.X:0}/{t6PlatformB.CanvasFrame.X:0}/{t6PlatformC.CanvasFrame.X:0} logical={t6BoxA.Frame.X:0}/{t6BoxB.Frame.X:0}/{t6BoxC.Frame.X:0} matchParent={t6MatchParent} assert={t6LayoutOk}");
if (!t6LayoutOk)
{
    throw new InvalidOperationException("the T6 RTL placement mirroring (child frames, logical frames kept, MatchParent inheritance) is missing or drifted");
}

// T6: hits follow the mirrored placement: the physical right half of the RTL stack is the first
// (logical) child and the physical left half the second.
var t6HitStack = new HorizontalStackLayout { FlowDirection = FlowDirection.RightToLeft, Spacing = 0 };
var t6HitFirst = new Button { Text = "first", WidthRequest = 100, HeightRequest = 60 };
var t6HitSecond = new Button { Text = "second", WidthRequest = 100, HeightRequest = 60 };
int t6FirstClicks = 0, t6SecondClicks = 0;
t6HitFirst.Clicked += (_, _) => t6FirstClicks++;
t6HitSecond.Clicked += (_, _) => t6SecondClicks++;
t6HitStack.Add(t6HitFirst);
t6HitStack.Add(t6HitSecond);
OpenHarmonyHandlerConnector.ConnectTree(t6HitStack);
t6HitStack.Measure(200, 60);
t6HitStack.Arrange(new Rect(0, 0, 200, 60));
t6Renderer.Render(t6HitStack, 200, 60);
t6Renderer.HandleTouch(t6HitStack, true, false, 150, 30);
t6Renderer.HandleTouch(t6HitStack, false, true, 150, 30);
t6Renderer.HandleTouch(t6HitStack, true, false, 50, 30);
t6Renderer.HandleTouch(t6HitStack, false, true, 50, 30);
bool t6HitOk = t6FirstClicks == 1 && t6SecondClicks == 1;
Console.WriteLine($"[verify] t6 hit mirror first={t6FirstClicks} second={t6SecondClicks} assert={t6HitOk}");
if (!t6HitOk)
{
    throw new InvalidOperationException("the T6 mirrored hit testing (RTL stack taps) is missing or drifted");
}

// T6: an RTL entry starts its text at the physical right edge (Start; End flips to the left) and
// the clear button moves to the trailing (physical left) edge.
// No WidthRequest: the entry's desired size is its text metrics, while the arranged frame
// (the root here) is the 200 px render box the origin math is checked against.
var t6Entry = new Entry
{
    Text = "abc",
    FlowDirection = FlowDirection.RightToLeft,
    HeightRequest = 40,
    ClearButtonVisibility = ClearButtonVisibility.WhileEditing,
};
OpenHarmonyHandlerConnector.ConnectTree(t6Entry);
t6Entry.Measure(200, 40);
t6Entry.Arrange(new Rect(0, 0, 200, 40));
t6Renderer.Render(t6Entry, 200, 40);
var t6EntryPlatform = (OpenHarmonyView)t6Entry.Handler!.PlatformView!;
t6EntryPlatform.IsFocused = true;
float t6RtlStart = t6EntryPlatform.TextOriginX("abc");
t6EntryPlatform.HorizontalTextAlignment = TextAlignment.End;
float t6RtlEnd = t6EntryPlatform.TextOriginX("abc");
t6EntryPlatform.HorizontalTextAlignment = TextAlignment.Start;
bool t6TextOk = t6EntryPlatform.FlowRightToLeft
    && t6RtlStart > t6EntryPlatform.CanvasFrame.Center.X
    && t6RtlEnd < t6EntryPlatform.CanvasFrame.Center.X
    && Math.Abs(t6EntryPlatform.ClearButtonCenter.X - (t6EntryPlatform.CanvasFrame.X + 9f + 12f)) < 0.01;
Console.WriteLine($"[verify] t6 text start={t6RtlStart:0.#} end={t6RtlEnd:0.#} clearX={t6EntryPlatform.ClearButtonCenter.X:0.#} rtl={t6EntryPlatform.FlowRightToLeft} canvas={t6EntryPlatform.CanvasFrame} assert={t6TextOk}");
if (!t6TextOk)
{
    throw new InvalidOperationException("the T6 RTL text alignment / trailing clear button is missing or drifted");
}

// T6: the navigation chrome's slots follow the direction: the back region is the physical right
// strip and the toolbar items dock to the physical left.
var t6Nav = new NavigationPage(new ContentPage { Title = "rtl", Content = new Label { Text = "nav" } })
{
    FlowDirection = FlowDirection.RightToLeft,
};
OpenHarmonyHandlerConnector.ConnectTree(t6Nav);
t6Nav.Measure(300, 200);
t6Nav.Arrange(new Rect(0, 0, 300, 200));
t6Renderer.Render(t6Nav, 300, 200);
var t6NavPlatform = (OpenHarmonyView)t6Nav.Handler!.PlatformView!;
t6NavPlatform.CanGoBack = true;
t6NavPlatform.ToolbarItems.Add(new OpenHarmonyToolbarItem { Text = "item", Activate = () => { } });
bool t6NavBackOk = t6NavPlatform.InBackRegion(290, 10) && !t6NavPlatform.InBackRegion(10, 10);
RectF t6ToolbarRect = t6NavPlatform.ToolbarItemRect(0);
bool t6NavToolbarOk = Math.Abs(t6ToolbarRect.X - t6NavPlatform.CanvasFrame.X) < 0.01
    && t6NavPlatform.ToolbarItemAt(20, 10) == 0
    && t6NavPlatform.ToolbarItemAt(280, 10) == -1;
bool t6NavOk = t6NavBackOk && t6NavToolbarOk;
Console.WriteLine($"[verify] t6 nav chrome back={t6NavBackOk} toolbar={t6ToolbarRect.X:0} toolbarHit={t6NavPlatform.ToolbarItemAt(20, 10)} outside={t6NavPlatform.ToolbarItemAt(280, 10)} assert={t6NavOk}");
if (!t6NavOk)
{
    throw new InvalidOperationException("the T6 RTL navigation chrome (back slot, toolbar dock) is missing or drifted");
}

// T6: the shell flyout menu opens from the hamburger at the physical right, its panel is docked
// to the right, and a row tap selects the item while a tap left of the panel is a dismiss.
var t6Shell = new Shell { FlowDirection = FlowDirection.RightToLeft };
t6Shell.Items.Add(new ShellContent { Title = "One", ContentTemplate = new DataTemplate(() => new ContentPage { Title = "One", Content = new Label { Text = "one" } }) });
t6Shell.Items.Add(new ShellContent { Title = "Two", ContentTemplate = new DataTemplate(() => new ContentPage { Title = "Two", Content = new Label { Text = "two" } }) });
OpenHarmonyHandlerConnector.ConnectTree(t6Shell);
t6Shell.Measure(500, 400);
t6Shell.Arrange(new Rect(0, 0, 500, 400));
t6Renderer.Render(t6Shell, 500, 400);
var t6ShellPlatform = (OpenHarmonyView)t6Shell.Handler!.PlatformView!;
t6ShellPlatform.ChromeRefresh?.Invoke();
bool t6MenuClosed = !t6ShellPlatform.FlyoutOpen && t6ShellPlatform.FlyoutItems.Count >= 2;
t6Renderer.HandleTouch(t6Shell, true, false, 490, 20);
t6Renderer.HandleTouch(t6Shell, false, true, 490, 20);
bool t6MenuOpened = t6ShellPlatform.FlyoutOpen;
// The shell panel is docked to the physical right: the right-side point is row 0 and the
// left-of-panel point is the dismiss region (-2).
bool t6MenuRows = t6ShellPlatform.FlyoutItemAt(400, 42) == 0 && t6ShellPlatform.FlyoutItemAt(100, 42) == -2;
t6Renderer.HandleTouch(t6Shell, true, false, 400, 94);
t6Renderer.HandleTouch(t6Shell, false, true, 400, 94);
bool t6MenuSelected = !t6ShellPlatform.FlyoutOpen && ReferenceEquals(t6Shell.Items[1], t6Shell.CurrentItem);
bool t6MenuOk = t6MenuClosed && t6MenuOpened && t6MenuRows && t6MenuSelected;
Console.WriteLine($"[verify] t6 flyout menu closed={t6MenuClosed} opened={t6MenuOpened} rows={t6MenuRows} selected={t6MenuSelected} assert={t6MenuOk}");
if (!t6MenuOk)
{
    throw new InvalidOperationException("the T6 RTL shell flyout menu (hamburger side, panel dock, row hits) is missing or drifted");
}

// T6: the picker dropdown opens from the field's physical right edge and grows left; hitting a
// row selects the item and closes the popup.
var t6Picker = new Picker { FlowDirection = FlowDirection.RightToLeft, WidthRequest = 160, HeightRequest = 48 };
t6Picker.Items.Add("alpha");
t6Picker.Items.Add("beta");
t6Picker.Items.Add("gamma");
OpenHarmonyHandlerConnector.ConnectTree(t6Picker);
t6Picker.Measure(400, 300);
t6Picker.Arrange(new Rect(0, 0, 400, 300));
t6Renderer.Render(t6Picker, 400, 300);
var t6PickerPlatform = (OpenHarmonyView)t6Picker.Handler!.PlatformView!;
RectF t6PickerFrame = t6PickerPlatform.CanvasFrame;
t6Renderer.HandleTouch(t6Picker, true, false, t6PickerFrame.Center.X, t6PickerFrame.Center.Y);
t6Renderer.HandleTouch(t6Picker, false, true, t6PickerFrame.Center.X, t6PickerFrame.Center.Y);
bool t6PopupOpened = t6PickerPlatform.PopupVisible;
// The dropdown's width is max(field, 220) and it opens from the field's physical right edge.
float t6PopupWidth = Math.Max(t6PickerFrame.Width, 220f);
float t6PopupLeft = t6PickerFrame.Right - t6PopupWidth;
float t6PopupRowY = t6PickerFrame.Y + t6PickerFrame.Height + OpenHarmonyView.PopupRowHeight * 1.5f;
bool t6PopupSide = t6PickerPlatform.PopupIndexAt(t6PickerFrame.Right - 10f, t6PopupRowY) == 1
    && t6PickerPlatform.PopupIndexAt(t6PopupLeft + 10f, t6PopupRowY) == 1
    && t6PickerPlatform.PopupIndexAt(t6PopupLeft - 10f, t6PopupRowY) == -1;
t6Renderer.HandleTouch(t6Picker, true, false, t6PickerFrame.Right - 10f, t6PopupRowY);
t6Renderer.HandleTouch(t6Picker, false, true, t6PickerFrame.Right - 10f, t6PopupRowY);
bool t6PopupSelected = t6Picker.SelectedIndex == 1 && !t6PickerPlatform.PopupVisible;
bool t6PopupOk = t6PopupOpened && t6PopupSide && t6PopupSelected;
Console.WriteLine($"[verify] t6 picker popup opened={t6PopupOpened} side={t6PopupSide} selected={t6Picker.SelectedIndex} closed={!t6PickerPlatform.PopupVisible} assert={t6PopupOk}");
if (!t6PopupOk)
{
    throw new InvalidOperationException("the T6 RTL picker dropdown (right-edge origin, row hits, selection) is missing or drifted");
}

// T6: the RTL calendar mirrors its columns and header arrows: the previous-month arrow is the
// physical right one, next is the left, and a day cell hit follows the mirrored column.
var t6Date = new DatePicker
{
    Date = new DateTime(2026, 9, 17),
    FlowDirection = FlowDirection.RightToLeft,
    WidthRequest = 160,
    HeightRequest = 48,
};
OpenHarmonyHandlerConnector.ConnectTree(t6Date);
t6Date.Measure(500, 400);
t6Date.Arrange(new Rect(0, 0, 500, 400));
t6Renderer.Render(t6Date, 500, 400);
var t6DatePlatform = (OpenHarmonyView)t6Date.Handler!.PlatformView!;
RectF t6DateFrame = t6DatePlatform.CanvasFrame;
t6Renderer.HandleTouch(t6Date, true, false, t6DateFrame.Center.X, t6DateFrame.Center.Y);
t6Renderer.HandleTouch(t6Date, false, true, t6DateFrame.Center.X, t6DateFrame.Center.Y);
bool t6CalendarOpened = t6DatePlatform.PopupVisible && t6DatePlatform.CalendarSelectedDay == 17;
// The calendar opens below the field: previous is the physical right header arrow, next the
// left, and the day columns are mirrored (Monday-first from the right).
float t6HeaderY = t6DateFrame.Y + t6DateFrame.Height + OpenHarmonyView.CalendarHeaderHeight / 2;
bool t6CalendarArrows = t6DatePlatform.CalendarHit(t6DateFrame.X + OpenHarmonyView.CalendarWidth - 20, t6HeaderY) == -2
    && t6DatePlatform.CalendarHit(t6DateFrame.X + 20, t6HeaderY) == -3;
int t6Leading = ((int)new DateTime(2026, 9, 1).DayOfWeek + 6) % 7;
int t6Cell = t6Leading + 15 - 1;
int t6Column = 6 - (t6Cell % 7);
float t6CellX = t6DateFrame.X + t6Column * (OpenHarmonyView.CalendarWidth / 7f) + OpenHarmonyView.CalendarWidth / 14f;
float t6CellY = t6DateFrame.Y + t6DateFrame.Height + OpenHarmonyView.CalendarHeaderHeight
    + ((t6Cell / 7) + 1) * OpenHarmonyView.CalendarRowHeight + OpenHarmonyView.CalendarRowHeight / 2;
bool t6CalendarDay = t6DatePlatform.CalendarHit(t6CellX, t6CellY) == 15;
t6Renderer.HandleTouch(t6Date, true, false, t6CellX, t6CellY);
t6Renderer.HandleTouch(t6Date, false, true, t6CellX, t6CellY);
bool t6CalendarPicked = t6Date.Date == new DateTime(2026, 9, 15) && !t6DatePlatform.PopupVisible;
bool t6CalendarOk = t6CalendarOpened && t6CalendarArrows && t6CalendarDay && t6CalendarPicked;
Console.WriteLine($"[verify] t6 calendar open={t6CalendarOpened} arrows={t6CalendarArrows} day15Hit={t6CalendarDay} picked={t6Date.Date:yyyy-MM-dd} assert={t6CalendarOk}");
if (!t6CalendarOk)
{
    throw new InvalidOperationException("the T6 RTL calendar (mirrored arrows/columns, day hit) is missing or drifted");
}

// T22: the MainThread bridge. rc.1's Essentials initialization bridges the MAUI application
// dispatcher into the netstandard MainThread (EssentialsMauiAppBuilderExtensions ->
// MainThread.SetCustomImplementation), so MainThread works on this platform slice without a
// native MainThread partial: IsMainThread mirrors the application dispatcher's
// IsDispatchRequired and BeginInvokeOnMainThread / InvokeOnMainThreadAsync post through the
// slice's OpenHarmonyDispatcher queue. The safety-net timer drains that queue on a pool
// thread, and the async continuation thread can itself become the drain thread, so the
// BeginInvoke/InvokeAsync probes run on dedicated worker threads where IsDispatchRequired is
// deterministically true: the bridge must queue (never run the callback inline on the worker)
// and the drained callback must observe IsMainThread true on the drain thread.
var t22Dispatcher = Application.Current?.Dispatcher;
bool t22IsMainThread = false;
bool t22DispatchRequired = false;
string t22BridgeProbe;
try
{
    t22IsMainThread = Microsoft.Maui.ApplicationModel.MainThread.IsMainThread;
    t22DispatchRequired = t22Dispatcher?.IsDispatchRequired ?? true;
    t22BridgeProbe = $"isMainThread={t22IsMainThread} dispatchRequired={t22DispatchRequired}";
}
catch (Exception ex)
{
    t22BridgeProbe = $"probe threw {ex.GetType().Name}: {ex.Message}";
}

bool t22BridgeOk = t22Dispatcher is Microsoft.Maui.Platform.OpenHarmonyDispatcher
    && t22IsMainThread == !t22DispatchRequired;
Console.WriteLine($"[verify] t22 mainthread bridge dispatcher={t22Dispatcher?.GetType().Name ?? "null"} {t22BridgeProbe} assert={t22BridgeOk}");
if (!t22BridgeOk)
{
    throw new InvalidOperationException("the rc.1 MainThread bridge (application dispatcher -> MainThread with no native MainThread partial) is missing or does not mirror the OpenHarmony dispatcher");
}

async Task<bool> T22WaitFor(Func<bool> condition, int timeoutMs = 3000)
{
    var t22Watch = System.Diagnostics.Stopwatch.StartNew();
    while (t22Watch.ElapsedMilliseconds < timeoutMs)
    {
        if (condition())
        {
            return true;
        }
        await Task.Delay(25);
    }
    return condition();
}

// BeginInvokeOnMainThread from a fresh worker thread: the dispatcher reports dispatch-required
// there, so the framework must go through the bridge's dispatcher.Dispatch (queued), never run
// the callback inline on the worker; the drained callback must observe IsMainThread true.
int t22PostThreadId = 0;
bool t22PostIsMain = true;
bool t22PostRequired = false;
bool t22PostInline = false;
bool t22PostRan = false;
int t22PostRunThread = 0;
bool t22PostInsideMain = false;
using (var t22PostGate = new ManualResetEventSlim(false))
{
    var t22PostWorker = new System.Threading.Thread(() =>
    {
        t22PostThreadId = Environment.CurrentManagedThreadId;
        t22PostIsMain = Microsoft.Maui.ApplicationModel.MainThread.IsMainThread;
        t22PostRequired = t22Dispatcher!.IsDispatchRequired;
        bool t22PostReturned = false;
        Microsoft.Maui.ApplicationModel.MainThread.BeginInvokeOnMainThread(() =>
        {
            if (!Volatile.Read(ref t22PostReturned) && Environment.CurrentManagedThreadId == t22PostThreadId)
            {
                t22PostInline = true;
            }
            t22PostRunThread = Environment.CurrentManagedThreadId;
            t22PostInsideMain = Microsoft.Maui.ApplicationModel.MainThread.IsMainThread;
            t22PostRan = true;
            t22PostGate.Set();
        });
        Volatile.Write(ref t22PostReturned, true);
        t22PostGate.Wait(3000);
    })
    { IsBackground = true };
    t22PostWorker.Start();
    bool t22PostJoined = t22PostWorker.Join(4000);
    bool t22PostOk = t22PostJoined && t22PostRequired && !t22PostIsMain && !t22PostInline
        && t22PostRan && t22PostInsideMain;
    Console.WriteLine($"[verify] t22 begin-invoke worker={t22PostThreadId} workerIsMainThread={t22PostIsMain} dispatchRequired={t22PostRequired} inline={t22PostInline} drained={t22PostRan} runThread={t22PostRunThread} insideIsMainThread={t22PostInsideMain} joined={t22PostJoined} assert={t22PostOk}");
    if (!t22PostOk)
    {
        throw new InvalidOperationException("MainThread.BeginInvokeOnMainThread did not queue through the OpenHarmony dispatcher (inline execution / drain / IsMainThread-on-drain contract)");
    }
}

// InvokeOnMainThreadAsync<T> from a fresh worker thread completes with the value the drained
// callback computed, and that callback runs on the drain thread with IsMainThread true.
string t22FuncValue = "<not-completed>";
bool t22FuncCompleted = false;
int t22FuncRunThread = 0;
bool t22FuncInsideMain = false;
bool t22FuncWorkerIsMain = true;
Exception? t22FuncError = null;
var t22FuncWorker = new System.Threading.Thread(() =>
{
    t22FuncWorkerIsMain = Microsoft.Maui.ApplicationModel.MainThread.IsMainThread;
    try
    {
        Task<string> t22FuncTask = Microsoft.Maui.ApplicationModel.MainThread.InvokeOnMainThreadAsync(() =>
        {
            t22FuncRunThread = Environment.CurrentManagedThreadId;
            t22FuncInsideMain = Microsoft.Maui.ApplicationModel.MainThread.IsMainThread;
            return "t22-dispatched";
        });
        t22FuncCompleted = t22FuncTask.Wait(3000) && t22FuncTask.IsCompletedSuccessfully;
        if (t22FuncCompleted)
        {
            t22FuncValue = t22FuncTask.Result;
        }
    }
    catch (Exception ex)
    {
        t22FuncError = ex;
    }
})
{ IsBackground = true };
t22FuncWorker.Start();
bool t22FuncJoined = t22FuncWorker.Join(4000);
bool t22FuncOk = t22FuncJoined && t22FuncError is null && t22FuncCompleted
    && t22FuncValue == "t22-dispatched" && !t22FuncWorkerIsMain && t22FuncInsideMain;
Console.WriteLine($"[verify] t22 invoke-async func value='{t22FuncValue}' completed={t22FuncCompleted} workerIsMainThread={t22FuncWorkerIsMain} runThread={t22FuncRunThread} insideIsMainThread={t22FuncInsideMain} error={t22FuncError?.GetType().Name ?? "none"} joined={t22FuncJoined} assert={t22FuncOk}");
if (!t22FuncOk)
{
    throw new InvalidOperationException("MainThread.InvokeOnMainThreadAsync<T> did not round-trip through the OpenHarmony dispatcher");
}

// The non-generic InvokeOnMainThreadAsync(Action) overload from a fresh worker thread
// completes successfully with exactly one callback that observes IsMainThread true.
int t22ActionRan = 0;
bool t22ActionCompleted = false;
int t22ActionRunThread = 0;
bool t22ActionInsideMain = false;
bool t22ActionWorkerIsMain = true;
Exception? t22ActionError = null;
var t22ActionWorker = new System.Threading.Thread(() =>
{
    t22ActionWorkerIsMain = Microsoft.Maui.ApplicationModel.MainThread.IsMainThread;
    try
    {
        Task t22ActionTask = Microsoft.Maui.ApplicationModel.MainThread.InvokeOnMainThreadAsync(() =>
        {
            Interlocked.Increment(ref t22ActionRan);
            t22ActionRunThread = Environment.CurrentManagedThreadId;
            t22ActionInsideMain = Microsoft.Maui.ApplicationModel.MainThread.IsMainThread;
        });
        t22ActionCompleted = t22ActionTask.Wait(3000) && t22ActionTask.IsCompletedSuccessfully;
    }
    catch (Exception ex)
    {
        t22ActionError = ex;
    }
})
{ IsBackground = true };
t22ActionWorker.Start();
bool t22ActionJoined = t22ActionWorker.Join(4000);
bool t22ActionOk = t22ActionJoined && t22ActionError is null && t22ActionCompleted
    && t22ActionRan == 1 && !t22ActionWorkerIsMain && t22ActionInsideMain;
Console.WriteLine($"[verify] t22 invoke-async action completed={t22ActionCompleted} ran={t22ActionRan} workerIsMainThread={t22ActionWorkerIsMain} runThread={t22ActionRunThread} insideIsMainThread={t22ActionInsideMain} error={t22ActionError?.GetType().Name ?? "none"} joined={t22ActionJoined} assert={t22ActionOk}");
if (!t22ActionOk)
{
    throw new InvalidOperationException("MainThread.InvokeOnMainThreadAsync(Action) did not complete through the OpenHarmony dispatcher");
}

// The bridge posts into the application dispatcher's own queue: a MainThread post and a direct
// IDispatcher.Dispatch post drain in FIFO order (whether the bridge call queued or ran inline
// on this thread), which pins the "application dispatcher" half of the bridge.
int t22FifoSequence = 0;
int t22FifoBridgeSeq = -1;
int t22FifoDispatchSeq = -1;
Microsoft.Maui.ApplicationModel.MainThread.BeginInvokeOnMainThread(() =>
    Volatile.Write(ref t22FifoBridgeSeq, Interlocked.Increment(ref t22FifoSequence)));
bool t22FifoDispatched = t22Dispatcher is not null && t22Dispatcher.Dispatch(() =>
    Volatile.Write(ref t22FifoDispatchSeq, Interlocked.Increment(ref t22FifoSequence)));
bool t22FifoDrained = await T22WaitFor(() => Volatile.Read(ref t22FifoBridgeSeq) >= 1 && Volatile.Read(ref t22FifoDispatchSeq) >= 1);
bool t22FifoOk = t22FifoDispatched && t22FifoDrained
    && Volatile.Read(ref t22FifoBridgeSeq) == 1
    && Volatile.Read(ref t22FifoDispatchSeq) == 2;
Console.WriteLine($"[verify] t22 begin-invoke shares the app dispatcher queue bridgeSeq={Volatile.Read(ref t22FifoBridgeSeq)} dispatchSeq={Volatile.Read(ref t22FifoDispatchSeq)} dispatched={t22FifoDispatched} drained={t22FifoDrained} assert={t22FifoOk}");
if (!t22FifoOk)
{
    throw new InvalidOperationException("MainThread.BeginInvokeOnMainThread did not post into the application dispatcher's queue (FIFO with IDispatcher.Dispatch)");
}
// ---- T21: system font scale -------------------------------------------------------------------
// OpenHarmony reports the user's font size setting as a scale factor; the slice applies it at the
// one boundary every text path shares (OpenHarmonyFontManager). The checks pin the public API
// (default 1, clamps, invalid resets, the PublicAPI baseline entries), the logical MAUI font
// values (a Label keeps FontSize 20 and its platform view keeps the logical size), the measured
// plain and FormattedText blocks following the scale through the generation-keyed caches (and
// serving the original metrics again after the reset), the entry caret metrics, and the scaled
// size the draw pass hands the canvas through a recording canvas (the CanvasFactory test hook).

string? t21ApiPath = FindHostSource("src/Core/src/PublicAPI/net-openharmony/PublicAPI.Unshipped.txt");
string t21ApiText = t21ApiPath is null ? string.Empty : File.ReadAllText(t21ApiPath);
bool t21ApiPin = t21ApiText.Contains("OpenHarmonyFontManager.SetSystemFontScale(float scale) -> void") &&
    t21ApiText.Contains("OpenHarmonyFontManager.SystemFontScale.get -> float");
float t21Default = OpenHarmonyFontManager.SystemFontScale;
OpenHarmonyFontManager.SetSystemFontScale(99f);
float t21ClampHigh = OpenHarmonyFontManager.SystemFontScale;
OpenHarmonyFontManager.SetSystemFontScale(float.NaN);
float t21Invalid = OpenHarmonyFontManager.SystemFontScale;
OpenHarmonyFontManager.SetSystemFontScale(-2f);
float t21Negative = OpenHarmonyFontManager.SystemFontScale;
OpenHarmonyFontManager.SetSystemFontScale(0.1f);
float t21ClampLow = OpenHarmonyFontManager.SystemFontScale;
OpenHarmonyFontManager.SetSystemFontScale(1f);
bool t21ApiOk = t21ApiPin
    && Math.Abs(t21Default - 1f) < 0.0001f
    && Math.Abs(t21ClampHigh - 3f) < 0.0001f
    && Math.Abs(t21Invalid - 1f) < 0.0001f
    && Math.Abs(t21Negative - 1f) < 0.0001f
    && Math.Abs(t21ClampLow - 0.5f) < 0.0001f
    && Math.Abs(OpenHarmonyFontManager.SystemFontScale - 1f) < 0.0001f;
Console.WriteLine($"[verify] t21 font scale api default={t21Default} clampHigh={t21ClampHigh} invalid={t21Invalid} negative={t21Negative} clampLow={t21ClampLow} pin={t21ApiPin} assert={t21ApiOk}");
if (!t21ApiOk)
{
    throw new InvalidOperationException("the T21 system font scale API (default, clamps, invalid values, public API pin) is missing or drifted");
}

// The plain label: the logical FontSize stays untouched while the measured block follows the
// scale; returning to 1 must serve the original metrics again (the measurement/layout caches
// are keyed by the scale generation, so a stale block can never come back).
var t21Label = new Label { Text = "ScaleMe", FontSize = 20 };
OpenHarmonyHandlerConnector.Connect(t21Label);
var t21LabelHandler = (OpenHarmonyLabelHandler)t21Label.Handler!;
var t21LabelView = (OpenHarmonyTextView)t21LabelHandler.PlatformView!;
var t21Label1 = t21LabelHandler.GetDesiredSize(double.PositiveInfinity, double.PositiveInfinity);
OpenHarmonyFontManager.SetSystemFontScale(2f);
var t21Label2 = t21LabelHandler.GetDesiredSize(double.PositiveInfinity, double.PositiveInfinity);
OpenHarmonyFontManager.SetSystemFontScale(1f);
var t21Label3 = t21LabelHandler.GetDesiredSize(double.PositiveInfinity, double.PositiveInfinity);
bool t21LabelOk = t21Label2.Width > t21Label1.Width * 1.9 &&
    t21Label2.Height > t21Label1.Height * 1.9 &&
    Math.Abs(t21Label3.Width - t21Label1.Width) < 0.01 &&
    Math.Abs(t21Label3.Height - t21Label1.Height) < 0.01 &&
    Math.Abs(t21LabelView.FontSize - 20f) < 0.001f;
Console.WriteLine($"[verify] t21 label scale w={t21Label1.Width:0.#}->{t21Label2.Width:0.#}->{t21Label3.Width:0.#} h={t21Label1.Height:0.#}->{t21Label2.Height:0.#}->{t21Label3.Height:0.#} logical={t21LabelView.FontSize} assert={t21LabelOk}");
if (!t21LabelOk)
{
    throw new InvalidOperationException("the T21 plain-text scaling (desired size follows the scale, caches invalidate, logical FontSize kept) is missing or drifted");
}

// FormattedText runs carry their own sizes: the run-aware layout measures them with the scale too.
var t21FormattedLabel = new Label { FontSize = 16 };
var t21Formatted = new FormattedString();
t21Formatted.Spans.Add(new Span { Text = "big", FontSize = 40 });
t21FormattedLabel.FormattedText = t21Formatted;
OpenHarmonyHandlerConnector.Connect(t21FormattedLabel);
var t21FormattedHandler = (OpenHarmonyLabelHandler)t21FormattedLabel.Handler!;
var t21Formatted1 = t21FormattedHandler.GetDesiredSize(double.PositiveInfinity, double.PositiveInfinity);
OpenHarmonyFontManager.SetSystemFontScale(1.5f);
var t21Formatted2 = t21FormattedHandler.GetDesiredSize(double.PositiveInfinity, double.PositiveInfinity);
OpenHarmonyFontManager.SetSystemFontScale(1f);
bool t21FormattedOk = t21Formatted2.Width > t21Formatted1.Width * 1.4 &&
    t21Formatted2.Height > t21Formatted1.Height * 1.4;
Console.WriteLine($"[verify] t21 formatted scale w={t21Formatted1.Width:0.#}->{t21Formatted2.Width:0.#} h={t21Formatted1.Height:0.#}->{t21Formatted2.Height:0.#} assert={t21FormattedOk}");
if (!t21FormattedOk)
{
    throw new InvalidOperationException("the T21 FormattedText run layout does not measure with the system font scale");
}

// The text entry: the drawn metrics (origin/caret) follow the scale; the same x lands on a
// different caret index once the glyph advances double.
var t21Entry = new Entry { Text = "abcd", FontSize = 20 };
OpenHarmonyHandlerConnector.Connect(t21Entry);
t21Entry.Measure(400, 40);
t21Entry.Arrange(new Rect(0, 0, 400, 40));
var t21EntryView = (OpenHarmonyView)t21Entry.Handler!.PlatformView!;
float t21Caret1 = t21EntryView.TextPositionX("abcd", 4);
int t21Index1 = t21EntryView.CursorIndexFromX(32);
OpenHarmonyFontManager.SetSystemFontScale(2f);
float t21Caret2 = t21EntryView.TextPositionX("abcd", 4);
int t21Index2 = t21EntryView.CursorIndexFromX(32);
OpenHarmonyFontManager.SetSystemFontScale(1f);
int t21IndexBack = t21EntryView.CursorIndexFromX(32);
float t21Origin = t21EntryView.TextOriginX("abcd");
bool t21EntryOk = t21Caret2 - t21Origin > (t21Caret1 - t21Origin) * 1.9
    && t21Index1 == 2 && t21Index2 == 1 && t21IndexBack == 2;
Console.WriteLine($"[verify] t21 entry scale caret={t21Caret1:0.#}->{t21Caret2:0.#} index={t21Index1}->{t21Index2}->{t21IndexBack} origin={t21Origin:0.#} assert={t21EntryOk}");
if (!t21EntryOk)
{
    throw new InvalidOperationException("the T21 text-entry metrics (caret position, hit index, back after reset) are missing or drifted");
}

// The draw path: the renderer is constructed with a recording canvas (the CanvasFactory hook);
// the label's glyphs reach the canvas at the scaled size, and back at the logical size after
// the scale resets.
var t21DrawLabel = new Label { Text = "DrawMe", FontSize = 18, TextColor = Colors.White };
OpenHarmonyHandlerConnector.Connect(t21DrawLabel);
t21DrawLabel.Measure(200, 60);
t21DrawLabel.Arrange(new Rect(0, 0, 200, 60));
var t21Canvas = new T21RecordingCanvas();
var t21SavedFactory = OpenHarmonyWindowRenderer.CanvasFactory;
OpenHarmonyWindowRenderer.CanvasFactory = () => t21Canvas;
try
{
    var t21DrawRenderer = new OpenHarmonyWindowRenderer();
    t21DrawRenderer.Render(t21DrawLabel, 200, 60);
    float t21Draw1 = t21Canvas.LastTextFontSize;
    t21Canvas.Clear();
    OpenHarmonyFontManager.SetSystemFontScale(2f);
    t21DrawRenderer.Render(t21DrawLabel, 200, 60);
    float t21Draw2 = t21Canvas.LastTextFontSize;
    bool t21DrawOk = t21Canvas.LastText == "DrawMe" && Math.Abs(t21Draw1 - 18f) < 0.01f
        && Math.Abs(t21Draw2 - 36f) < 0.01f;
    Console.WriteLine($"[verify] t21 draw scale font={t21Draw1:0.#}->{t21Draw2:0.#} text='{t21Canvas.LastText}' assert={t21DrawOk}");
    if (!t21DrawOk)
    {
        throw new InvalidOperationException("the T21 draw path does not hand the scaled size to the canvas");
    }
}
finally
{
    OpenHarmonyFontManager.SetSystemFontScale(1f);
    OpenHarmonyWindowRenderer.CanvasFactory = t21SavedFactory;
}

// T21 leftovers: the system font scale's source wiring. The ArkTS abilities read
// Configuration.fontSizeScale (create + onConfigurationUpdated) and forward it with
// host.notifyFontScale; the native host keeps the last value and replays it to the managed
// listener (ohos_host_font_scale_set). Off-device the host library is absent, so the pins cover
// the shell/host contract and the managed path is driven directly.
string? t21ScalePath = FindHostSource("OpenHarmonySystemFontScale.cs");
string t21ScaleSource = t21ScalePath is null ? string.Empty : File.ReadAllText(t21ScalePath);
string? t21HostPath = FindHostSource("src/OpenHarmonyHost/host_napi.cpp");
string t21HostSource = t21HostPath is null ? string.Empty : File.ReadAllText(t21HostPath);
string? t21ExportsPath = FindHostSource("src/OpenHarmonyHost/host-exports.txt");
string t21ExportsSource = t21ExportsPath is null ? string.Empty : File.ReadAllText(t21ExportsPath);
string[] t21ShellVersions = { "1.0.0-preview.22", "1.0.0-preview.23", "1.0.0-preview.24" };
bool t21ShellPinsOk = true;
bool t21ShellIdentical = true;
string t21ShellFirstHead = string.Empty;
string t21ShellFirstUi = string.Empty;
foreach (string t21ShellVersion in t21ShellVersions)
{
    string? t21HeadPath = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{t21ShellVersion}/templates/ets/entryability/EntryAbility.ets");
    string? t21UiPath = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{t21ShellVersion}/templates/ets/entryability/EntryAbility.ui.ets");
    string t21Head = t21HeadPath is null ? string.Empty : File.ReadAllText(t21HeadPath);
    string t21Ui = t21UiPath is null ? string.Empty : File.ReadAllText(t21UiPath);
    if (t21ShellFirstHead.Length == 0)
    {
        t21ShellFirstHead = t21Head;
        t21ShellFirstUi = t21Ui;
    }
    else if (!string.Equals(t21ShellFirstHead, t21Head, StringComparison.Ordinal) ||
        !string.Equals(t21ShellFirstUi, t21Ui, StringComparison.Ordinal))
    {
        t21ShellIdentical = false;
    }
    t21ShellPinsOk &= t21Head.Contains("import { UIAbility, AbilityConstant, Want, Configuration } from '@kit.AbilityKit';") &&
        t21Head.Contains("const initialFontScale: number | undefined = this.context.config.fontSizeScale;") &&
        t21Head.Contains("this.reportFontScale(initialFontScale);") &&
        t21Head.Contains("private reportFontScale(scale: number): void {") &&
        t21Head.Contains("host.notifyFontScale(scale);") &&
        t21Head.Contains("onConfigurationUpdated(config: Configuration): void {") &&
        t21Head.Contains("this.reportFontScale(config.fontSizeScale);") &&
        t21Ui.Contains("const initialFontScale: number | undefined = this.context.config.fontSizeScale;") &&
        t21Ui.Contains("this.reportFontScale(initialFontScale);") &&
        t21Ui.Contains("host.notifyFontScale(scale);") &&
