t9Window.TitleBar = null;
bool t9Cleared = t9Window.Handler is OpenHarmonyWindowHandler t9ClearHandler && t9ClearHandler.TitleBar is null;
bool t9BackOk = t9ShowsBack && t9Popped && t9OutsideNoPop && t9Cleared;
