// WebView JavaScript bridge (host ohos_host_web_eval/notifyWebEvalResult + shell
// registerWebEvalSink/notifyJsMessage): the managed handler must complete
// WebView.EvaluateJavaScriptAsync without throwing when no host library is present, and the
// native message callback (OnJsMessageNative -> HandleJsMessage) must raise JsMessage with the
// dotnetHost.postMessage payload.
var webProbe = new Microsoft.Maui.Controls.WebView { HeightRequest = 200 };
OpenHarmonyHandlerConnector.Connect(webProbe);
string? webEval = null;
bool webEvalThrew = false;
try
{
    webEval = await webProbe.EvaluateJavaScriptAsync("1 + 1");
}
catch (Exception ex)
{
    webEvalThrew = true;
    Console.WriteLine($"[verify] webview eval threw {ex.GetType().Name}: {ex.Message}");
}
bool webEvalOk = !webEvalThrew && webEval is null or "";
Console.WriteLine($"[verify] webview handler={webProbe.Handler?.GetType().Name ?? "null"} evaluateAsync completes={webEvalOk} result={(webEval is null ? "<null>" : $"'{webEval}'")} (no host library)");
if (!webEvalOk || webProbe.Handler is not OpenHarmonyWebViewHandler)
{
    throw new InvalidOperationException("WebView.EvaluateJavaScriptAsync did not degrade to null/empty off-device");
}

string? jsMessage = null;
void OnJsMessageProbe(string payload) => jsMessage = payload;
OpenHarmonyWebViewHandler.JsMessage += OnJsMessageProbe;
try
{
    // This is exactly what the native notifyJsMessage callback invokes (OnJsMessageNative).
    OpenHarmonyWebViewHandler.HandleJsMessage("{\"hello\":\"bridge\"}");
}
finally
{
    OpenHarmonyWebViewHandler.JsMessage -= OnJsMessageProbe;
}
bool jsMessageOk = jsMessage == "{\"hello\":\"bridge\"}";
Console.WriteLine($"[verify] webview JsMessage raised={jsMessageOk} payload='{jsMessage}'");
if (!jsMessageOk)
{
    throw new InvalidOperationException("the WebView JsMessage event did not carry the payload");
}

// ---- W-series: WebView wiring (history, cookie/storage, frame, load events, B1 sample) --------
// The six small ArkWeb gaps are wired through the shell: GoBack/GoForward/Reload commands and
// the history state that mirrors IWebView.CanGoBack/CanGoForward, the WebCookieManager
// set/read pair over the eval-result channel, DOM storage, the non-full-window frame and the
// page-end/page-error events that raise IWebView.Navigated. All three preview packs stay
// byte-identical (the build gate pins that), so these structural pins run on every pack.

// W1: the shell half in every pack: the forward/refresh ops, the history report, the frame
// command with its position/size state, the cookie set/get pair and the error event.
string[] wShellVersions = { "1.0.0-preview.22", "1.0.0-preview.23", "1.0.0-preview.24", "1.0.0-preview.28" };
bool wShellHistory = true;
bool wShellFrame = true;
bool wShellCookie = true;
bool wShellStorage = true;
bool wShellError = true;
foreach (string wVersion in wShellVersions)
{
    string? wShellPath = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{wVersion}/templates/ets/pages/Index.ets");
    string wShell = wShellPath is null ? string.Empty : File.ReadAllText(wShellPath);
    wShellHistory &= wShell.Contains("op === 'forward'") && wShell.Contains("op === 'refresh'") &&
        wShell.Contains("private reportWebHistory(slot: number): void {") &&
        wShell.Contains("this.slotController(slot)") &&
        wShell.Contains("host.notifyWebEvent(this.webEventState(slot, `history|${canBack ? 1 : 0}|${canForward ? 1 : 0}`), '');") &&
        wShell.Contains("this.reportWebHistory(slot);");
    wShellFrame &= wShell.Contains("private applyWebFrame(arg: string): void {") &&
        wShell.Contains("op === 'frame'") &&
        wShell.Contains(".position({ x: this.webFrameX[slot], y: this.webFrameY[slot] })") &&
        wShell.Contains(".width(this.webFrameW[slot] > 0 ? `${this.webFrameW[slot]}vp` : '100%')") &&
        wShell.Contains(".height(this.webFrameH[slot] > 0 ? `${this.webFrameH[slot]}vp` : '100%')");
    wShellCookie &= wShell.Contains("web_webview.WebCookieManager.configCookieSync(cookieUrl, cookieValue);") &&
        wShell.Contains("web_webview.WebCookieManager.fetchCookieSync(cookieUrl);") &&
        wShell.Contains("host.notifyWebEvalResult(requestId, cookieValue, cookieFailed);");
    wShellStorage &= wShell.Contains(".domStorageAccess(true)");
    wShellError &= wShell.Contains(".onErrorReceive((event) => {") &&
        wShell.Contains("host.notifyWebEvent(this.webEventState(slot, 'error'), errorUrl);");
}
bool wShellOk = wShellHistory && wShellFrame && wShellCookie && wShellStorage && wShellError;
Console.WriteLine($"[verify] w1 shell web wiring packs=22,23,24,28 history={wShellHistory} frame={wShellFrame} cookie={wShellCookie} storage={wShellStorage} error={wShellError} assert={wShellOk}");
if (!wShellOk)
{
    throw new InvalidOperationException(
        $"the WebView shell wiring is missing or drifted: history={wShellHistory} frame={wShellFrame} " +
        $"cookie={wShellCookie} storage={wShellStorage} error={wShellError}");
}

// W2: the managed half: the command mapping, the history/Navigated bookkeeping and the frame
// handoff shared by the three web handlers.
string? wHandlerPath = FindHostSource("OpenHarmonyWebViewHandler.cs");
string wHandler = wHandlerPath is null ? string.Empty : File.ReadAllText(wHandlerPath);
string? wHybridHandlerPath = FindHostSource("OpenHarmonyHybridWebViewHandler.cs");
