// WASM-MIME: a .wasm response must carry application/wasm, or Blazor's instantiateStreaming
// falls back to an ArrayBuffer load (perf/memory regression, the MONO_WASM warning pair in
// dotnet.native.js). The contract is pinned in both rawfile servers: every preview pack's shell
// maps the extension in hybridMimeType (the payload read takes the response MIME from it), and
// the standalone rawfile host (test/hello-blazorwasm/arkts-host) maps it too plus logs the
// one-shot `wasm mime:` evidence line and forwards Emscripten's streaming-fallback warnings as
// `wasm fallback:`; the device run requires the MIME line and no fallback line, and
// pack-host.sh --bad-mime (BLZ_HOST_BAD_MIME) is the negative-control build that flips it.
bool b2WasmMimeShell = true;
foreach (string b2MimeVersion in wShellVersions)
{
    string? b2MimeShellPath = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{b2MimeVersion}/templates/ets/pages/Index.ets");
    string b2MimeShell = b2MimeShellPath is null ? string.Empty : File.ReadAllText(b2MimeShellPath);
    b2WasmMimeShell &= b2MimeShell.Contains("if (lower.endsWith('.wasm')) {") &&
        b2MimeShell.Contains("return 'application/wasm';");
}
string b2HostPath = FindHostSource("test/hello-blazorwasm/arkts-host/project/entry/src/main/ets/pages/Index.ets") is { } b2HostResolved
    ? File.ReadAllText(b2HostResolved)
    : string.Empty;
bool b2WasmMimeHost = b2HostPath.Contains("if (lower.endsWith('.wasm')) {") &&
    b2HostPath.Contains("return 'application/wasm';");
bool b2WasmMimeOk = b2WasmMimeShell && b2WasmMimeHost;
Console.WriteLine($"[verify] b2 wasm mime shell={b2WasmMimeShell} host={b2WasmMimeHost} packs=22,23,24 assert={b2WasmMimeOk}");
if (!b2WasmMimeOk)
{
    throw new InvalidOperationException(
        $"the .wasm -> application/wasm mapping is missing or drifted: shell={b2WasmMimeShell} host={b2WasmMimeHost}");
}

// The device-verifiable half of WASM-MIME: the host's one-shot `wasm mime:` evidence line, the
// forwarded Emscripten fallback warnings, and the pack-host.sh negative-control switch.
string b2PackHostPath = FindHostSource("test/hello-blazorwasm/arkts-host/pack-host.sh") is { } b2PackHostResolved
    ? File.ReadAllText(b2PackHostResolved)
    : string.Empty;
bool b2WasmFallbackInstrumented = b2HostPath.Contains("const WASM_FALLBACK_COMPILE = 'wasm streaming compile failed';") &&
    b2HostPath.Contains("const WASM_FALLBACK_ARRAYBUFFER = 'falling back to ArrayBuffer';") &&
    b2HostPath.Contains("hilog.warn(DOMAIN, TAG, 'wasm fallback: %{public}s [blz:%{public}s]'") &&
    b2HostPath.Contains("hilog.info(DOMAIN, TAG, 'wasm mime: %{public}s -> %{public}s'") &&
    b2HostPath.Contains("this.wasmMimeLogged = true;") &&
    b2PackHostPath.Contains("--bad-mime") &&
    b2PackHostPath.Contains("BLZ_HOST_BAD_MIME") &&
    b2PackHostPath.Contains("return 'application/octet-stream';");
Console.WriteLine($"[verify] b2 wasm fallback hostInstrumentation={b2WasmFallbackInstrumented} assert={b2WasmFallbackInstrumented}");
if (!b2WasmFallbackInstrumented)
{
    throw new InvalidOperationException(
        "the wasm MIME evidence/fallback instrumentation or the pack-host.sh --bad-mime control is missing or drifted");
}

// W10 shell: the payload-in-libs probe accepts the NativeAOT form next to the marker and both
// bundle libs roots the device images use - <bundleCodeDir>/libs/<abi> (libIsolation) and
// <bundleCodeDir>/<moduleName>/libs/<abi> (the module layout measured on 7.0.0.111+:
// /data/storage/el1/bundle/entry/libs/arm64). A NativeAOT publish replaces the managed
// <assembly> with lib<stem>.so; the zip fallback carries no AOT image (the packaging excludes
// the root *.so), so without this the launch fell through to an extracted app_dir the device
// namespace refuses to dlopen from. Both ability variants of every synced pack carry the probe.
bool w10Shell = true;
bool w10Roots = true;
foreach (string w10Version in new[] { "1.0.0-preview.22", "1.0.0-preview.23", "1.0.0-preview.24", "1.0.0-preview.28" })
{
    string? w10AbilityPath = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{w10Version}/templates/ets/entryability/EntryAbility.ets");
    string? w10AbilityUiPath = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{w10Version}/templates/ets/entryability/EntryAbility.ui.ets");
    string w10Ability = w10AbilityPath is null ? string.Empty : File.ReadAllText(w10AbilityPath);
    string w10AbilityUi = w10AbilityUiPath is null ? string.Empty : File.ReadAllText(w10AbilityUiPath);
    w10Shell &= w10Ability.Contains("function libsAotEntryName(assembly: string): string {") &&
        w10AbilityUi.Contains("function libsAotEntryName(assembly: string): string {") &&
        w10Ability.Contains("const aotEntry = libsAotEntryName(assembly);") &&
        w10AbilityUi.Contains("const aotEntry = libsAotEntryName(assembly);") &&
        w10Ability.Contains("!fs.accessSync(`${dir}/${assembly}`) && !fs.accessSync(`${dir}/${aotEntry}`)") &&
        w10AbilityUi.Contains("!fs.accessSync(`${dir}/${assembly}`) && !fs.accessSync(`${dir}/${aotEntry}`)") &&
        w10Ability.Contains("return `lib${stem}.so`;") &&
        w10AbilityUi.Contains("return `lib${stem}.so`;");
    // The module-scoped root: bundleCodeDir alone misses the installed module layout, so the
    // probe builds both roots from the ability's module name (the W10 follow-up fix).
    w10Roots &= w10Ability.Contains("function findLibsPayloadDir(bundleCodeDir: string, moduleName: string, assembly: string): string | undefined {") &&
        w10AbilityUi.Contains("function findLibsPayloadDir(bundleCodeDir: string, moduleName: string, assembly: string): string | undefined {") &&
        w10Ability.Contains("? [`${bundleCodeDir}/${moduleName}/libs`, `${bundleCodeDir}/libs`]") &&
        w10AbilityUi.Contains("? [`${bundleCodeDir}/${moduleName}/libs`, `${bundleCodeDir}/libs`]") &&
        w10Ability.Contains("findLibsPayloadDir(this.context.bundleCodeDir, this.context.abilityInfo.moduleName, config.assembly)") &&
        w10AbilityUi.Contains("findLibsPayloadDir(this.context.bundleCodeDir, this.context.abilityInfo.moduleName, config.assembly)");
    string? w10IndexPath = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{w10Version}/templates/ets/pages/Index.ets");
    string w10Index = w10IndexPath is null ? string.Empty : File.ReadAllText(w10IndexPath);
    // Page shell: the payload read uses the single `fs` alias (the duplicate `fileIo` binding
    // never resolved on device: "fileIo is not defined" -> every served asset 404), and the
    // static-asset fingerprint map resolves both directions (10 lowercase alnum fingerprint).
    w10Shell &= w10Index.Contains("import { fileIo as fs, fileUri, picker } from '@kit.CoreFileKit';") &&
        !w10Index.Contains("fileIo.") &&
        w10Index.Contains("private staticFingerprintFile(filePath: string): string | undefined {") &&
        w10Index.Contains("new RegExp('^(.+)\\\\.[0-9a-z]{10}$').exec(stem)") &&
        w10Index.Contains("const resolved: string | undefined = this.staticFingerprintFile(filePath);");
}
Console.WriteLine($"[verify] w10 shell aot payload probe packs=22,23,24,28 markerAotEntry={w10Shell} moduleRoot={w10Roots} variants=2 assert={w10Shell && w10Roots}");
if (!(w10Shell && w10Roots))
{
    throw new InvalidOperationException("the W10 AOT-aware payload-in-libs probe (or the module-scoped libs root) is missing or drifted in the shell variants");
}

// ---- T1: InputView mapping (Entry/Editor/SearchBar + OpenHarmonyView) -------------------------
// The mapper entries and the platform-view state behind them: MaxLength and IsReadOnly gate the
// shell's text, IsPassword masks what is drawn, Keyboard restricts numeric/telephone input,
// ClearButtonVisibility adds a hit-tested clear button, PlaceholderColor and
// HorizontalTextAlignment move the drawn text/caret, ReturnType records the return-key kind.

string? i1EntryPath = FindHostSource("OpenHarmonyEntryHandler.cs");
string i1Entry = i1EntryPath is null ? string.Empty : File.ReadAllText(i1EntryPath);
string? i1EditorPath = FindHostSource("OpenHarmonyEditorHandler.cs");
string i1Editor = i1EditorPath is null ? string.Empty : File.ReadAllText(i1EditorPath);
