bool a2SignatureOk = nativeNodeParameters.Length == 16 && nativeGetParameters.Length == 17 && headerNodeParameters.Length == 16;
bool a2Ok = a2BeginLock && a2NodeLock && a2CommitLock && a2CountLock && a2GetLock &&
