    NativeThunks.Invoker<NativeThunks.KeystoreResultCallback>(
        NativeThunks.Pointer(typeof(Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge), "s_keystoreResultThunk"))(99999, 1, IntPtr.Zero));

// MB-2 (status channel): the swallowed failures reach dotnet-status.txt as one flattened line
// per boundary, and the hosting bridge reports its own ten boundaries the same way.
string n30StatusLog = File.Exists(n30StatusPath) ? File.ReadAllText(n30StatusPath) : string.Empty;
bool n30FlattenedOk =
    n30StatusLog.Contains("web js message callback failed: InvalidOperationException: app js handler failed second line") &&
    n30StatusLog.Contains("bluetooth gatt event callback failed: InvalidOperationException: app gatt handler failed") &&
    n30StatusLog.Contains("clipboard changed callback failed: InvalidOperationException: app clipboard handler failed") &&
    n30StatusLog.Contains("sensor reading callback failed: InvalidOperationException: app sensor handler failed");
Console.WriteLine($"[verify] audit3 mb2 status flattened={n30FlattenedOk} bytes={n30StatusLog.Length} assert={n30FlattenedOk}");
if (!n30FlattenedOk)
{
    throw new InvalidOperationException("a swallowed native-callback failure (MB-2) did not reach dotnet-status.txt as one flattened line");
}

string[] n30HostStatusLines =
{
    "touch callback failed: InvalidOperationException: app touch handler failed",
    "frame callback failed: InvalidOperationException: app frame handler failed",
    "text input callback failed: InvalidOperationException: app text input handler failed",
    "text submitted callback failed: InvalidOperationException: app text submitted handler failed",
    "lifecycle callback failed: InvalidOperationException: app lifecycle handler failed",
    "surface callback failed: InvalidOperationException: app surface handler failed",
    "pinch callback failed: InvalidOperationException: app pinch handler failed",
    "web event callback failed: InvalidOperationException: app web event handler failed",
    "picker result callback failed: InvalidOperationException: app picker result handler failed",
    "keystore result callback failed: InvalidOperationException: app keystore result handler failed",
};
int n30HostLogged = n30HostStatusLines.Count(line => n30StatusLog.Contains(line, StringComparison.Ordinal));
string? n30HostingPath = FindHostSource("src/Microsoft.OpenHarmony.Hosting/OpenHarmonyApp.cs");
string n30HostingSource = n30HostingPath is null ? string.Empty : File.ReadAllText(n30HostingPath);
int n30HostGuardsPinned = 0;
foreach (string n30Boundary in new[]
{
    "touch", "frame", "text input", "text submitted", "lifecycle", "surface", "pinch",
    "web event", "picker result", "keystore result",
})
{
    n30HostGuardsPinned += n30HostingSource.Contains($"ReportCallbackFailure(\"{n30Boundary}\", ex)") ? 1 : 0;
}
bool n30HostOk = n30HostEntries == 10 && n30HostEscapes.Count == 0 &&
    n30HostLogged == n30HostStatusLines.Length && n30HostGuardsPinned == 10;
Console.WriteLine($"[verify] audit3 host callbacks entries={n30HostEntries} escaped={n30HostEscapes.Count} status={n30HostLogged}/{n30HostStatusLines.Length} guards={n30HostGuardsPinned}/10 source='{n30HostingPath ?? "<missing>"}' assert={n30HostOk}");
if (!n30HostOk)
{
    throw new InvalidOperationException(
        $"a hosting native-callback guard (MB-2) drifted: entries={n30HostEntries} escaped={string.Join(",", n30HostEscapes)} " +
        $"status={n30HostLogged}/{n30HostStatusLines.Length} guards={n30HostGuardsPinned}/10");
}

SetBridgeContext(n30ContextBefore);
n30SurfaceField.SetValue(null, n30SurfaceBefore);
try
{
    Directory.Delete(n30AuditRoot, true);
}
catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
{
    // The audit scratch directory is diagnostic only; leaving it behind must not fail the suite.
}

// ---- Performance budget (bounded, deterministic, seedless) ------------------------------------
// The frame path (OpenHarmonyWindowRenderer.Render: measure/arrange, the iterative view walk, the
// accessibility shadow tree rebuild + frame diff and the surface hooks) is timed over a fixed
// ~400-node tree so an accidental O(n^2) walk, a blocking call or a per-frame allocation storm
// fails the suite. The tree shape, the frame count and the warm-up split are fixed constants (no
// Random -> identical work on every run/machine); only the wall-clock numbers vary. A warm-up pass
// primes the JIT/static caches and one blocking collection runs before the timed loop so a
// mid-loop Gen0 pause cannot dominate the maximum.
//
// Budget rationale - deliberately generous: CI runners are shared and noisy, the suite runs in
// Debug, and off-device Render still calls the absent native host once per frame (the background
// FillColor -> ClearEffects lookup, ~4 ms per failed native call on the OpenHarmony dev host,
// sub-ms on a normal CI runner). Measured on this host: ~4 ms/frame. The perf renderer is built
// through the slice's documented CanvasFactory test hook with a canvas that no-ops the one
// rasterizer call Render makes for a detached tree (FillRectangle -> Polyline); without that, a
// second failed lookup per frame would add ~1 s to the section and swamp the managed work. The
// factory is restored immediately so no other renderer picks up the substitution.
//   * average <= 20 ms - very loose in managed terms (the actual renderer work is sub-ms) and
//     wide enough for the off-device floor plus debug JIT plus a loaded dev host; a uniform
//     regression (extra walk, blocking wait, quadratic layout) has to add >14 ms/frame to trip
//     it, and no plausible runner noise makes a healthy frame path average 20 ms.
//   * max <= 250 ms - a very loose absolute ceiling that only catches a genuine hang/stall;
//     intentionally far above any plausible single-frame cost.
//   * max/average <= 100x - the relative outlier check: single frames are routinely preempted on
//     a shared runner (10-30x a sub-millisecond average), so the documented multiple is generous
//     and only catastrophic outliers fail it even where the absolute ceilings are too loose.
// The tree is intentionally detached (no handler connection): with handlers every canvas
// primitive of the ~400 nodes pays the absent-host lookup, which measured ~1.2 s per frame here
// and would swamp the managed frame path and the suite's time budget. A detached tree keeps
// Render's managed work (measure/arrange, traversal, accessibility) plus the renderer-level
// canvas calls - the same shape the deep-tree fuzz section uses.
//   * alloc/frame <= 13,824 B - the allocation gate, re-based after the managed perf batch
//     (maui-ohos 0e9d90cd: text metrics, carousel slides and rawfile answer caches): 3x the
//     4,504 B/frame baseline measured on this host, where the delta is deterministic
//     (900,800 B per 200-frame run on every repeat), so unlike the wall-clock budgets this gate
//     needs no noise slack. 3x = 13,512 B, rounded up to the next 512-byte boundary (13.5 KiB =
//     3.07x) so the ceiling is a tidy unit with a hair of margin and stays at the lower end of
//     the review's documented 3-4x band. The pre-batch baseline was 72,864 B/frame here
//     (72,056-72,080 B/frame on CI, the same Debug codegen within 1.1%) and the pre-FIX-P2 storm
//     measured 241,688 B/frame = 3.3x of it, which the old 218,592 B ceiling caught; if a
//     legitimate baseline growth lands near the new ceiling, raise the constant deliberately
//     rather than loosening the check silently.
//   * jitter (p95/avg) <= 2.0 - the frame-to-frame stability gate. The raw max/avg (bounded by
//     the loose 100x outlier guard above) is not a stable signal on a loaded shared host: a
//     single preempted frame measured 3.4x here while the frame path was healthy, and the
//     pre-FIX-P2 baseline run logged 8.1x. p95/avg is robust to one or two preempted frames and
//     still catches a sustained regression (every frame, or at least one frame in twenty,
//     getting slower): it measured 1.08x on CI and 1.3-1.7x on the dev host (1.30-1.31x after
//     the managed perf batch), so 2.0x keeps a documented margin while the old 100x guard stays
//     as the single-frame hang check.
const int perfWarmupFrames = 8;
const int perfFrames = 200;
const double perfAverageCeilingMs = 20.0;
const double perfMaxCeilingMs = 250.0;
const double perfMaxAverageRatio = 100.0;
const double perfJitterCeiling = 2.0;
const double perfAllocPerFrameCeiling = 13_824.0;
var perfDefaultCanvasFactory = OpenHarmonyWindowRenderer.CanvasFactory;
OpenHarmonyWindowRenderer.CanvasFactory = () => new PerfCanvas();
var perfRenderer = new OpenHarmonyWindowRenderer();
OpenHarmonyWindowRenderer.CanvasFactory = perfDefaultCanvasFactory;
var perfWatch = System.Diagnostics.Stopwatch.StartNew();
var perfRoot = new VerticalStackLayout { Spacing = 1 };
int perfNodes = 1;   // the root layout
for (int row = 0; row < 100; row++)
{
    var perfRow = new HorizontalStackLayout { Spacing = 1 };
    for (int cell = 0; cell < 3; cell++)
    {
        perfRow.Add(new Label { Text = $"perf node {row}.{cell}", FontSize = 10 });
        perfNodes++;
    }
    perfRoot.Add(perfRow);
    perfNodes++;
}
var perfPage = new ContentPage { Content = perfRoot };
perfPage.Measure(1080, 1920);
perfPage.Arrange(new Rect(0, 0, 1080, 1920));

// Warm up the renderer/app host: the first frames pay for JIT/static initialization and the first
// layout pass; they are excluded so the measurement is steady state, not startup.
bool perfWarm = true;
for (int i = 0; i < perfWarmupFrames; i++)
{
    perfWarm &= perfRenderer.Render(perfPage, 1080, 1920);
}
GC.Collect();
GC.WaitForPendingFinalizers();
GC.Collect();

var perfTimes = new double[perfFrames];
long perfAllocBefore = GC.GetAllocatedBytesForCurrentThread();
for (int i = 0; i < perfFrames; i++)
{
    long perfStart = System.Diagnostics.Stopwatch.GetTimestamp();
    if (!perfRenderer.Render(perfPage, 1080, 1920))
    {
        perfWarm = false;
    }
    perfTimes[i] = System.Diagnostics.Stopwatch.GetElapsedTime(perfStart).TotalMilliseconds;
}
long perfAllocDelta = GC.GetAllocatedBytesForCurrentThread() - perfAllocBefore;

var perfSorted = (double[])perfTimes.Clone();
Array.Sort(perfSorted);
double perfAverage = perfTimes.Sum() / perfFrames;
double perfP50 = perfSorted[perfFrames / 2];
double perfP95 = perfSorted[Math.Min(perfFrames - 1, (int)Math.Ceiling(perfFrames * 0.95) - 1)];
double perfMax = perfSorted[^1];
double perfMaxAverage = perfMax / Math.Max(perfAverage, 1e-9);
double perfJitter = perfP95 / Math.Max(perfAverage, 1e-9);
double perfAllocPerFrame = perfAllocDelta / (double)perfFrames;
bool perfWithinBudget = perfAverage <= perfAverageCeilingMs
    && perfMax <= perfMaxCeilingMs
    && perfMaxAverage <= perfMaxAverageRatio
    && perfJitter <= perfJitterCeiling
    && perfAllocPerFrame <= perfAllocPerFrameCeiling;
Console.WriteLine($"[verify] perf warmup={perfWarmupFrames} frames={perfFrames} nodes={perfNodes} avg={perfAverage:0.###}ms p50={perfP50:0.###}ms p95={perfP95:0.###}ms max={perfMax:0.###}ms max/avg={perfMaxAverage:0.##} jitter={perfJitter:0.##} allocDelta={perfAllocDelta}B alloc/frame={perfAllocPerFrame:0.#}B elapsed={(int)perfWatch.ElapsedMilliseconds}ms budget=avg<={perfAverageCeilingMs:0.###}ms,max<={perfMaxCeilingMs:0.###}ms,max/avg<={perfMaxAverageRatio:0.###},jitter<={perfJitterCeiling:0.##},alloc/frame<={perfAllocPerFrameCeiling:0.#}B warmupOk={perfWarm} within={perfWithinBudget}");
if (!perfWarm || !perfWithinBudget)
{
    throw new InvalidOperationException(
        $"the frame-path performance budget failed: avg={perfAverage:0.###}ms (limit {perfAverageCeilingMs}ms) " +
        $"max={perfMax:0.###}ms (limit {perfMaxCeilingMs}ms) max/avg={perfMaxAverage:0.##} (limit {perfMaxAverageRatio}) " +
        $"jitter={perfJitter:0.##} (limit {perfJitterCeiling}, p95/avg) " +
        $"alloc/frame={perfAllocPerFrame:0.#}B (limit {perfAllocPerFrameCeiling:0.#}B) " +
        $"warmupOk={perfWarm} frames={perfFrames} nodes={perfNodes}");
}

// ---- Accessibility publish-path budget (skip vs republish) ------------------------------------
// The frame budget above times the whole render; this block isolates the accessibility step of a
// frame over the same fixed tree in its two shapes: repeated unchanged frames (the skip path) and
// a frame whose tree was mutated since the last publish (the republish path). The slice's Publish
// diffs the rebuilt shadow tree against the previous frame and skips all host traffic when nothing
// moved; otherwise every pass marshals the whole tree (one P/Invoke plus UTF-8 strings per node).
// This gate pins that saving so a change that reintroduces per-frame marshalling - or makes the
// skip decision pathologically expensive - fails here instead of on a device.
//
// Two numbers are collected per pass: the render step (Refresh + Publish, what a frame pays) and
// the publish pass itself (Publish alone). The publish pass is where the skip decision and the host
// boundary live; the shadow-tree rebuild is shared work and the frame budget already covers it.
//
// Off-device there is no host library: the first publish attempt fails and flips the slice's
// internal provider-availability flag, after which every pass (changed or not) returns before the
// host boundary and the two paths become indistinguishable. The harness therefore restores that
// flag through the same reflection hook the publish-contract checks use, so the republish block
// really takes the host-boundary branch (failing there exactly like the first real publish would
// off-device) while the skip block takes the "nothing moved" branch. The flag is restored to its
// previous value when the block ends, so the fuzz tail sees the same state the interaction checks
// left behind.
//
// Budget rationale - deliberately generous, same style as the frame budget: CI runners are shared,
// the suite runs in Debug, and off-device a republish pass pays one failed native lookup whose cost
// is host-dependent (~10 ms on the OpenHarmony dev host, sub-ms on a normal CI runner).
//   * skip avg <= 20 ms and max <= 250 ms (both shapes) - the same loose managed ceilings as the
//     frame budget: the rebuild, the diff and the skip decision are sub-millisecond managed work,
//     and a regression (per-frame marshalling, an allocation storm, a blocking wait) has to add far
//     more than that to trip the ceilings.
//   * republish avg <= 50 ms and max <= 500 ms (both shapes) - the republish pass additionally
//     crosses the host boundary once per pass; the ceilings leave room for the absent-host probe on
//     a loaded host while still catching a genuine hang.
//   * render republish/skip >= 1.25x and publish republish/skip >= 2x - the documented relative
//     floors: the skip path must be materially cheaper than a republish pass. Measured on CI
//     runners the render ratio is ~1.6-1.7x and the publish ratio ~3.8-3.9x; on the OpenHarmony dev
//     host they are ~10-15x and ~80x. The floors sit well below the observed values so runner noise
//     and CPU-speed differences cannot trip them.
// The tree, the mutation sequence, the pass counts and the warm-up split are fixed constants (the
// mutated text alternates between two fixed values), so every run does identical work; only the
// wall-clock numbers vary. The whole block must stay inside a 2 s wall-clock bound.
const int a11yWarmupFrames = 8;
const int a11ySkipFrames = 50;
const int a11yRepublishFrames = 50;
const double a11ySkipAverageCeilingMs = 20.0;
const double a11ySkipMaxCeilingMs = 250.0;
const double a11yRepublishAverageCeilingMs = 50.0;
const double a11yRepublishMaxCeilingMs = 500.0;
const double a11yRenderRatioFloor = 1.25;
const double a11yPublishRatioFloor = 2.0;
const double a11yElapsedCeilingMs = 2000.0;
var a11yWatch = System.Diagnostics.Stopwatch.StartNew();
FieldInfo a11yAvailability = typeof(OpenHarmonyAccessibility).GetField("_available", BindingFlags.NonPublic | BindingFlags.Static)
    ?? throw new InvalidOperationException("OpenHarmonyAccessibility._available was not found; the a11y perf gate needs the provider-availability hook to isolate the skip and republish paths off-device");
bool a11yAvailabilityBefore = (bool)a11yAvailability.GetValue(null)!;
void SetA11yAvailability(bool value) => a11yAvailability.SetValue(null, value);
var a11yPerfLabels = new List<Label>();
foreach (IView a11yChild in perfRoot.Children)
{
    if (a11yChild is HorizontalStackLayout a11yRow)
    {
        foreach (IView a11yCell in a11yRow.Children)
        {
            if (a11yCell is Label a11yLabel)
            {
                a11yPerfLabels.Add(a11yLabel);
            }
        }
    }
}
Label a11yMutatedLabel = a11yPerfLabels[0];
string a11yMutatedBase = a11yMutatedLabel.Text!;

static (double Average, double P50, double P95, double Max) A11yStats(double[] samples)
{
    var sorted = (double[])samples.Clone();
    Array.Sort(sorted);
    double average = samples.Sum() / samples.Length;
    double p50 = sorted[samples.Length / 2];
    double p95 = sorted[Math.Min(samples.Length - 1, (int)Math.Ceiling(samples.Length * 0.95) - 1)];
    return (average, p50, p95, sorted[^1]);
}

// A fresh shadow tree for the fixed perf page, so both blocks start from the same snapshot.
SetA11yAvailability(true);
OpenHarmonyAccessibility.Refresh(perfPage);
int a11yNodeCount = OpenHarmonyAccessibility.Nodes.Count;

// Skip path: repeated unchanged frames. Availability is restored before every pass so Publish
// takes the "nothing moved" branch; off-device the very first republish below would otherwise leave
// the provider marked unavailable and collapse the two paths into the same early return.
int a11ySkippedBefore = OpenHarmonyAccessibility.FramesSkipped;
bool a11ySkipSawWouldPublish = false;
for (int i = 0; i < a11yWarmupFrames; i++)
{
    SetA11yAvailability(true);
    OpenHarmonyAccessibility.Refresh(perfPage);
    OpenHarmonyAccessibility.Publish();
    a11ySkipSawWouldPublish |= OpenHarmonyAccessibility.WouldPublish;
}
GC.Collect();
GC.WaitForPendingFinalizers();
GC.Collect();
var a11ySkipRenderTimes = new double[a11ySkipFrames];
var a11ySkipPublishTimes = new double[a11ySkipFrames];
for (int i = 0; i < a11ySkipFrames; i++)
{
    SetA11yAvailability(true);
    long renderStart = System.Diagnostics.Stopwatch.GetTimestamp();
    OpenHarmonyAccessibility.Refresh(perfPage);
    long publishStart = System.Diagnostics.Stopwatch.GetTimestamp();
    OpenHarmonyAccessibility.Publish();
    long publishEnd = System.Diagnostics.Stopwatch.GetTimestamp();
    a11ySkipRenderTimes[i] = System.Diagnostics.Stopwatch.GetElapsedTime(renderStart, publishEnd).TotalMilliseconds;
    a11ySkipPublishTimes[i] = System.Diagnostics.Stopwatch.GetElapsedTime(publishStart, publishEnd).TotalMilliseconds;
    a11ySkipSawWouldPublish |= OpenHarmonyAccessibility.WouldPublish;
}
int a11ySkipDelta = OpenHarmonyAccessibility.FramesSkipped - a11ySkippedBefore;
var a11ySkipRender = A11yStats(a11ySkipRenderTimes);
var a11ySkipPublish = A11yStats(a11ySkipPublishTimes);

// Republish path: a mutated tree. The mutation is a tree edit (setup, outside the timed region);
// the measured step is the same Refresh + Publish pair. Alternating between two fixed texts keeps
// the change detectable on every pass without adding work inside the timed region.
int a11yRepublishSkippedBefore = OpenHarmonyAccessibility.FramesSkipped;
int a11yRepublishDetected = 0;
int a11yHostAttempts = 0;
for (int i = 0; i < a11yWarmupFrames; i++)
{
    a11yMutatedLabel.Text = a11yMutatedBase + (i % 2 == 0 ? " warm A" : " warm B");
    SetA11yAvailability(true);
    OpenHarmonyAccessibility.Refresh(perfPage);
    OpenHarmonyAccessibility.Publish();
}
GC.Collect();
GC.WaitForPendingFinalizers();
GC.Collect();
var a11yRepublishRenderTimes = new double[a11yRepublishFrames];
var a11yRepublishPublishTimes = new double[a11yRepublishFrames];
for (int i = 0; i < a11yRepublishFrames; i++)
{
    a11yMutatedLabel.Text = a11yMutatedBase + (i % 2 == 0 ? " pub A" : " pub B");
    SetA11yAvailability(true);
    long renderStart = System.Diagnostics.Stopwatch.GetTimestamp();
    OpenHarmonyAccessibility.Refresh(perfPage);
    long publishStart = System.Diagnostics.Stopwatch.GetTimestamp();
    OpenHarmonyAccessibility.Publish();
    long publishEnd = System.Diagnostics.Stopwatch.GetTimestamp();
    a11yRepublishRenderTimes[i] = System.Diagnostics.Stopwatch.GetElapsedTime(renderStart, publishEnd).TotalMilliseconds;
    a11yRepublishPublishTimes[i] = System.Diagnostics.Stopwatch.GetElapsedTime(publishStart, publishEnd).TotalMilliseconds;
    if (OpenHarmonyAccessibility.WouldPublish)
    {
        a11yRepublishDetected++;
        if (!(bool)a11yAvailability.GetValue(null)!)
        {
            a11yHostAttempts++;
        }
    }
}
int a11yRepublishSkippedDelta = OpenHarmonyAccessibility.FramesSkipped - a11yRepublishSkippedBefore;
var a11yRepublishRender = A11yStats(a11yRepublishRenderTimes);
var a11yRepublishPublish = A11yStats(a11yRepublishPublishTimes);
SetA11yAvailability(a11yAvailabilityBefore);

double a11yRenderRatio = a11yRepublishRender.Average / Math.Max(a11ySkipRender.Average, 1e-9);
double a11yPublishRatio = a11yRepublishPublish.Average / Math.Max(a11ySkipPublish.Average, 1e-9);
bool a11ySkipWithin = a11ySkipRender.Average <= a11ySkipAverageCeilingMs && a11ySkipRender.Max <= a11ySkipMaxCeilingMs
    && a11ySkipPublish.Average <= a11ySkipAverageCeilingMs && a11ySkipPublish.Max <= a11ySkipMaxCeilingMs;
bool a11yRepublishWithin = a11yRepublishRender.Average <= a11yRepublishAverageCeilingMs && a11yRepublishRender.Max <= a11yRepublishMaxCeilingMs
    && a11yRepublishPublish.Average <= a11yRepublishAverageCeilingMs && a11yRepublishPublish.Max <= a11yRepublishMaxCeilingMs;
bool a11yRatioWithin = a11yRenderRatio >= a11yRenderRatioFloor && a11yPublishRatio >= a11yPublishRatioFloor;
bool a11yElapsedWithin = a11yWatch.ElapsedMilliseconds <= a11yElapsedCeilingMs;

// Integrity: the skip passes must never have asked the host for a publish; the republish passes
// must each have detected the mutation and reached the host boundary (which off-device fails and
// on-device publishes the whole tree), without a single skip. Snapshot indexing is pinned too, so
// the publish path is measured on a well-formed tree.
bool a11yIdsOk = a11yNodeCount > 0;
for (int i = 0; i < a11yNodeCount; i++)
{
    a11yIdsOk &= OpenHarmonyAccessibility.Nodes[i].Id == i + 1;
}
bool a11yFindOk = a11yNodeCount > 0
    && OpenHarmonyAccessibility.TryFindNode(OpenHarmonyAccessibility.Nodes[^1].Id, out var a11yFound)
    && a11yFound?.Id == OpenHarmonyAccessibility.Nodes[^1].Id;
bool a11ySkipAssert = a11ySkipDelta >= a11ySkipFrames && !a11ySkipSawWouldPublish;
bool a11yRepublishAssert = a11yRepublishDetected == a11yRepublishFrames
    && a11yRepublishSkippedDelta == 0
    && (a11yHostAttempts == 0 || a11yHostAttempts == a11yRepublishFrames)
    && (OpenHarmonyAccessibility.LastPublishedCount == 0 || OpenHarmonyAccessibility.LastPublishedCount == a11yNodeCount);
bool a11yIntegrity = a11yIdsOk
    && a11yFindOk
    && a11yNodeCount == perfNodes + 1
    && a11ySkipAssert
    && a11yRepublishAssert;
bool a11yAllWithin = a11yIntegrity && a11ySkipWithin && a11yRepublishWithin && a11yRatioWithin && a11yElapsedWithin;

Console.WriteLine($"[verify] perf a11y render skip warmup={a11yWarmupFrames} repeats={a11ySkipFrames} nodes={a11yNodeCount} avg={a11ySkipRender.Average:0.###}ms p50={a11ySkipRender.P50:0.###}ms p95={a11ySkipRender.P95:0.###}ms max={a11ySkipRender.Max:0.###}ms budget=avg<={a11ySkipAverageCeilingMs:0.###}ms,max<={a11ySkipMaxCeilingMs:0.###}ms within={a11ySkipWithin}");
Console.WriteLine($"[verify] perf a11y render republish warmup={a11yWarmupFrames} repeats={a11yRepublishFrames} nodes={a11yNodeCount} avg={a11yRepublishRender.Average:0.###}ms p50={a11yRepublishRender.P50:0.###}ms p95={a11yRepublishRender.P95:0.###}ms max={a11yRepublishRender.Max:0.###}ms budget=avg<={a11yRepublishAverageCeilingMs:0.###}ms,max<={a11yRepublishMaxCeilingMs:0.###}ms within={a11yRepublishWithin}");
Console.WriteLine($"[verify] perf a11y publish skip repeats={a11ySkipFrames} avg={a11ySkipPublish.Average:0.###}ms p50={a11ySkipPublish.P50:0.###}ms p95={a11ySkipPublish.P95:0.###}ms max={a11ySkipPublish.Max:0.###}ms within={a11ySkipWithin}");
Console.WriteLine($"[verify] perf a11y publish republish repeats={a11yRepublishFrames} avg={a11yRepublishPublish.Average:0.###}ms p50={a11yRepublishPublish.P50:0.###}ms p95={a11yRepublishPublish.P95:0.###}ms max={a11yRepublishPublish.Max:0.###}ms within={a11yRepublishWithin}");
Console.WriteLine($"[verify] perf a11y ratio render={a11yRenderRatio:0.##}x floor={a11yRenderRatioFloor:0.###}x publish={a11yPublishRatio:0.##}x floor={a11yPublishRatioFloor:0.###}x assert={a11yRatioWithin}");
Console.WriteLine($"[verify] perf a11y skip decision unchanged={a11ySkipFrames} wouldPublish={a11ySkipSawWouldPublish} framesSkipped=+{a11ySkipDelta} published={OpenHarmonyAccessibility.LastPublishedCount} assert={a11ySkipAssert}");
Console.WriteLine($"[verify] perf a11y republish decision changed={a11yRepublishDetected} framesSkipped=+{a11yRepublishSkippedDelta} hostAttempts={a11yHostAttempts} published={OpenHarmonyAccessibility.LastPublishedCount} pending=0x{OpenHarmonyAccessibility.PendingEventCount:x} assert={a11yRepublishAssert}");
Console.WriteLine($"[verify] perf a11y budget elapsed={(int)a11yWatch.ElapsedMilliseconds}ms limit={(int)a11yElapsedCeilingMs}ms repeats={a11ySkipFrames + a11yRepublishFrames} warmup={a11yWarmupFrames * 2} skipWithin={a11ySkipWithin} republishWithin={a11yRepublishWithin} ratioWithin={a11yRatioWithin} elapsedWithin={a11yElapsedWithin} integrity nodes={a11yNodeCount} expected={perfNodes + 1} idsSequential={a11yIdsOk} tryFindNode={a11yFindOk} assert={a11yAllWithin}");
if (!a11yAllWithin)
{
    throw new InvalidOperationException(
        $"the accessibility publish-path performance budget failed: render skip avg={a11ySkipRender.Average:0.###}ms (limit {a11ySkipAverageCeilingMs}ms) max={a11ySkipRender.Max:0.###}ms (limit {a11ySkipMaxCeilingMs}ms) " +
        $"render republish avg={a11yRepublishRender.Average:0.###}ms (limit {a11yRepublishAverageCeilingMs}ms) max={a11yRepublishRender.Max:0.###}ms (limit {a11yRepublishMaxCeilingMs}ms) " +
        $"publish skip avg={a11ySkipPublish.Average:0.###}ms publish republish avg={a11yRepublishPublish.Average:0.###}ms " +
        $"ratio render={a11yRenderRatio:0.##} (floor {a11yRenderRatioFloor}) publish={a11yPublishRatio:0.##} (floor {a11yPublishRatioFloor}) " +
        $"integrity={a11yIntegrity} elapsed={(int)a11yWatch.ElapsedMilliseconds}ms (limit {(int)a11yElapsedCeilingMs}ms) nodes={a11yNodeCount}");
}

// ---- P1a-ANIM: frame-driven animations and transitions ----------------------------------------
// The shared frame loop is stepped with an injected clock so every pass is deterministic; the
// previous clock is restored at the end of the block. Checks: page enter (push/pop), the
// reduce-motion gate, the ticker's frame-loop redraw driver, MAUI FadeTo/TranslateTo/ScaleTo
// sampling + end callbacks on the compositor, the control-state channels (switch/check/press),
// and the minimal AutomationId-keyed shared morph.
Func<long> previousAnimClock = OpenHarmonyAnimationLoop.Clock;
OpenHarmonyAnimationLoop.Stop();
long animNow = 500_000;
OpenHarmonyAnimationLoop.Clock = () => animNow;
void PumpAnim(int milliseconds)
{
    animNow += milliseconds;
    OpenHarmonyAnimationLoop.Pump(animNow, 1f / 60f);
}
int animFailures = 0;
void AnimCheck(bool ok, string detail)
{
    if (!ok)
    {
        animFailures++;
    }
    Console.WriteLine($"[verify] anim {detail} assert={ok}");
}

// Page enter push: the incoming page fades in from 0 with a right-hand slide, then commits
// exactly (opacity/translation restored, loop unregistered).
var animRootPage = new ContentPage { Title = "anim root", Content = new Label { Text = "anim root" } };
var animNav = new NavigationPage(animRootPage);
OpenHarmonyHandlerConnector.ConnectTree(animNav);
animNav.Measure(1080, 1920);
animNav.Arrange(new Rect(0, 0, 1080, 1920));
var animDetailPage = new ContentPage { Title = "anim detail", Content = new Label { Text = "anim detail" } };
await animNav.PushAsync(animDetailPage, false);
// The device renderer arranges the tree before the loop steps; mirror that here so the enter
// pass sees the page's real width (the slide offset is prepared from it).
animNav.Measure(1080, 1920);
animNav.Arrange(new Rect(0, 0, 1080, 1920));
bool pushActive = OpenHarmonyPageTransitions.IsActive &&
    ReferenceEquals(OpenHarmonyPageTransitions.PendingPage, animDetailPage);
double pushStartOpacity = animDetailPage.Opacity;
PumpAnim(40);
double pushMidOpacity = animDetailPage.Opacity;
double pushMidTranslation = animDetailPage.TranslationX;
PumpAnim(400);
bool pushSettled = !OpenHarmonyPageTransitions.IsActive &&
    Math.Abs(animDetailPage.Opacity - 1) < 0.0001 && Math.Abs(animDetailPage.TranslationX) < 0.0001;
AnimCheck(pushActive && pushStartOpacity == 0 && pushMidOpacity > 0 && pushMidOpacity < 1 &&
    pushMidTranslation > 0 && pushSettled,
    $"page enter push active={pushActive} start={pushStartOpacity:0.###} mid={pushMidOpacity:0.###} " +
    $"slide={pushMidTranslation:0.#} settled={pushSettled}");

// Page enter pop: the revealed page enters from the left and settles the same way.
await animNav.PopAsync(false);
animNav.Measure(1080, 1920);
animNav.Arrange(new Rect(0, 0, 1080, 1920));
bool popActive = OpenHarmonyPageTransitions.IsActive &&
    ReferenceEquals(OpenHarmonyPageTransitions.PendingPage, animRootPage);
PumpAnim(40);
double popMidTranslation = animRootPage.TranslationX;
PumpAnim(400);
bool popSettled = !OpenHarmonyPageTransitions.IsActive &&
    Math.Abs(animRootPage.Opacity - 1) < 0.0001 && Math.Abs(animRootPage.TranslationX) < 0.0001;
AnimCheck(popActive && popMidTranslation < 0 && popSettled,
    $"page enter pop active={popActive} slide={popMidTranslation:0.#} settled={popSettled}");

// Reduce motion: navigation commits instantly, and a running pass commits on its next frame.
OpenHarmonyMotion.OnPlatformReduceMotionChanged(true);
var animReducePage = new ContentPage { Title = "anim reduced", Content = new Label { Text = "reduced" } };
await animNav.PushAsync(animReducePage, false);
bool reduceSkips = !OpenHarmonyPageTransitions.IsActive && animReducePage.Opacity == 1 &&
    animReducePage.TranslationX == 0;
OpenHarmonyMotion.OnPlatformReduceMotionChanged(false);
await animNav.PopAsync(false);
PumpAnim(400);
AnimCheck(reduceSkips, $"page enter reduce-motion skips active={!reduceSkips}");

// The ticker's frame-loop driver: Start registers one redraw-only entry, a frame requests a
// repaint, Stop retires it; SystemEnabled follows the reduce-motion flag.
var animTicker = (OpenHarmonyTicker)app.Services.GetRequiredService<Microsoft.Maui.Animations.ITicker>();
int animDriversBefore = OpenHarmonyAnimationLoop.ActiveCount;
int animRedrawsBefore = OpenHarmonyAnimationLoop.RedrawRequests;
animTicker.Start();
int animDriversDuring = OpenHarmonyAnimationLoop.ActiveCount;
PumpAnim(16);
int animRedrawsAfter = OpenHarmonyAnimationLoop.RedrawRequests;
animTicker.Stop();
int animDriversAfter = OpenHarmonyAnimationLoop.ActiveCount;
OpenHarmonyMotion.OnPlatformReduceMotionChanged(true);
bool tickerGated = !animTicker.SystemEnabled;
OpenHarmonyMotion.OnPlatformReduceMotionChanged(false);
bool tickerReenabled = animTicker.SystemEnabled;
AnimCheck(animTicker.IsRunning == false && animDriversDuring == animDriversBefore + 1 &&
    animRedrawsAfter > animRedrawsBefore && animDriversAfter == animDriversBefore &&
    tickerGated && tickerReenabled,
    $"ticker driver active={animDriversDuring - animDriversBefore} redraw+={animRedrawsAfter - animRedrawsBefore} " +
    $"retired={animDriversAfter == animDriversBefore} reduceGate={tickerGated} released={tickerReenabled}");

// MAUI's public animations: sampling starts the driver (the surface stays dirty while the
// manager ticks) and every end callback lands on the exact target value. The label lives in
// the app's tree (a handler-backed element uses the app's animation manager/ticker, the same
// one the W22-7 fade above exercised).
var animPropsLabel = root.Children.OfType<Label>().FirstOrDefault(l => l.Text == "fade me");
if (animPropsLabel is null)
{
    animPropsLabel = new Label { Text = "anim props" };
    root.Add(animPropsLabel);
    host.Arrange(1080, 1920);
}
animPropsLabel.Opacity = 1;
animPropsLabel.TranslationX = 0;
animPropsLabel.TranslationY = 0;
animPropsLabel.Scale = 1;
Task<bool> animFade = animPropsLabel.FadeToAsync(0.4, 600, Easing.Linear);
// The manager adds the animation on a dispatcher hop (drained per frame, with a 50 ms safety
// net), so poll briefly: by the time it runs, the ticker and its frame-loop redraw driver
// must be live while the fade is still in flight.
bool animDriverLive = false;
for (int i = 0; i < 40 && !animDriverLive; i++)
{
    await Task.Delay(10);
    animDriverLive = OpenHarmonyAnimationLoop.ActiveCount >= 1 && animTicker.IsRunning;
}
double animMidOpacity = animPropsLabel.Opacity;
bool animFadeEnd = await animFade;
bool animTranslateEnd = await animPropsLabel.TranslateToAsync(30, 12, 150, Easing.Linear);
bool animScaleEnd = await animPropsLabel.ScaleToAsync(1.5, 150, Easing.Linear);
bool animEndsOk =
    Math.Abs(animPropsLabel.Opacity - 0.4) < 0.0001 &&
    Math.Abs(animPropsLabel.TranslationX - 30) < 0.0001 &&
    Math.Abs(animPropsLabel.TranslationY - 12) < 0.0001 &&
    Math.Abs(animPropsLabel.Scale - 1.5) < 0.0001;
AnimCheck(animDriverLive && animEndsOk,
    $"maui fade/translate/scale driver={animDriverLive} mid={animMidOpacity:0.###} " +
    $"ends={animFadeEnd},{animTranslateEnd},{animScaleEnd} " +
    $"o={animPropsLabel.Opacity:0.##} tx={animPropsLabel.TranslationX:0.#} ty={animPropsLabel.TranslationY:0.#} " +
    $"scale={animPropsLabel.Scale:0.##}");
// Put the shared label back so the app tree is where the earlier tests left it.
await animPropsLabel.FadeToAsync(1.0, 40, Easing.Linear);
await animPropsLabel.TranslateToAsync(0, 0, 40, Easing.Linear);
await animPropsLabel.ScaleToAsync(1.0, 40, Easing.Linear);

// Control-state channels: switch knob, check-mark draw-on and press feedback interpolate on the
// frame loop and reach their exact target; reduce-motion snaps instead of ticking.
var animSwitchView = new OpenHarmonyView { IsSwitch = true };
animSwitchView.IsOn = true;
PumpAnim(40);
float switchMid = animSwitchView.SwitchProgress;
PumpAnim(400);
float switchEnd = animSwitchView.SwitchProgress;
var animCheckView = new OpenHarmonyView { IsCheckBox = true };
animCheckView.IsChecked = true;
PumpAnim(40);
float checkMid = animCheckView.CheckProgress;
PumpAnim(400);
float checkEnd = animCheckView.CheckProgress;
var animPressView = new OpenHarmonyView();
animPressView.Pressed = true;
PumpAnim(30);
float pressMid = animPressView.PressProgress;
PumpAnim(300);
float pressEnd = animPressView.PressProgress;
animPressView.Pressed = false;
PumpAnim(300);
float pressReleased = animPressView.PressProgress;
AnimCheck(switchMid > 0 && switchMid < 1 && switchEnd == 1 &&
    checkMid > 0 && checkMid < 1 && checkEnd == 1 &&
    pressMid > 0 && pressMid < 1 && pressEnd == 1 && pressReleased == 0,
    $"controls switch={switchMid:0.##}->{switchEnd:0.##} check={checkMid:0.##}->{checkEnd:0.##} " +
    $"press={pressMid:0.##}->{pressEnd:0.##}->{pressReleased:0.##}");

OpenHarmonyMotion.OnPlatformReduceMotionChanged(true);
var animSnapView = new OpenHarmonyView();
animSnapView.Pressed = true;
bool pressSnapped = animSnapView.PressProgress == 1;
var animSnapSwitch = new OpenHarmonyView { IsSwitch = true };
animSnapSwitch.IsOn = true;
bool switchSnapped = animSnapSwitch.SwitchProgress == 1;
OpenHarmonyMotion.OnPlatformReduceMotionChanged(false);
AnimCheck(pressSnapped && switchSnapped,
    $"controls reduce-motion snap press={pressSnapped} switch={switchSnapped}");

// Minimal shared element: an AutomationId-keyed element morphs from the outgoing page's
// arranged frame to the incoming page's frame (position + uniform scale), then restores
// exactly. The handler path is exercised (Capture on RequestNavigation, Run on Pushed); the
// frames are set explicitly so the morph math is deterministic without a platform layout.
var sharedSource = new Image
{
    AutomationId = OpenHarmonySharedTransition.KeyPrefix + "hero",
    Opacity = 1,
};
sharedSource.Frame = new Rect(40, 40, 120, 120);
var sharedSourceLayout = new VerticalStackLayout { Padding = new Thickness(40) };
sharedSourceLayout.Add(sharedSource);
var sharedSourcePage = new ContentPage { Content = sharedSourceLayout };
var sharedNav = new NavigationPage(sharedSourcePage);
OpenHarmonyHandlerConnector.ConnectTree(sharedNav);
sharedNav.Measure(1080, 1920);
sharedNav.Arrange(new Rect(0, 0, 1080, 1920));
sharedSource.Frame = new Rect(40, 40, 120, 120);
Rect sharedSourceFrame = sharedSource.Frame;
var sharedTarget = new Image
{
    AutomationId = OpenHarmonySharedTransition.KeyPrefix + "hero",
};
var sharedTargetLayout = new VerticalStackLayout { Padding = new Thickness(40) };
sharedTargetLayout.Add(new Label { Text = "shared header", HeightRequest = 200 });
sharedTargetLayout.Add(sharedTarget);
var sharedTargetPage = new ContentPage { Content = sharedTargetLayout };
await sharedNav.PushAsync(sharedTargetPage, false);
sharedNav.Measure(1080, 1920);
sharedNav.Arrange(new Rect(0, 0, 1080, 1920));
// The morph reads the frames on its first step; pin the hero target to a known pose.
sharedTarget.Frame = new Rect(40, 240, 360, 360);
Rect sharedTargetFrame = sharedTarget.Frame;
bool sharedActive = OpenHarmonySharedTransition.IsActive;
PumpAnim(16);
double sharedTranslationX = sharedTarget.TranslationX;
double sharedTranslationY = sharedTarget.TranslationY;
double sharedScale = sharedTarget.Scale;
PumpAnim(500);
bool sharedSettled = !OpenHarmonySharedTransition.IsActive &&
    Math.Abs(sharedTarget.TranslationX) < 0.0001 && Math.Abs(sharedTarget.TranslationY) < 0.0001 &&
    Math.Abs(sharedTarget.Scale - 1) < 0.0001 && Math.Abs(sharedTarget.Opacity - 1) < 0.0001;
bool sharedFramesDiffer = sharedSourceFrame.X != sharedTargetFrame.X || sharedSourceFrame.Y != sharedTargetFrame.Y;
bool sharedMoved = Math.Abs(sharedTranslationX) > 0.5 || Math.Abs(sharedTranslationY) > 0.5;
AnimCheck(sharedActive && sharedFramesDiffer && sharedMoved &&
    sharedScale > 0 && sharedScale < 1 && sharedSettled,
    $"shared morph active={sharedActive} source={sharedSourceFrame.X:0},{sharedSourceFrame.Y:0},{sharedSourceFrame.Width:0}x{sharedSourceFrame.Height:0} " +
    $"target={sharedTargetFrame.X:0},{sharedTargetFrame.Y:0},{sharedTargetFrame.Width:0}x{sharedTargetFrame.Height:0} " +
    $"tx={sharedTranslationX:0.#} ty={sharedTranslationY:0.#} scale={sharedScale:0.###} settled={sharedSettled}");

// Shared morph under reduce motion: nothing starts, the target keeps its own pose.
OpenHarmonyMotion.OnPlatformReduceMotionChanged(true);
OpenHarmonySharedTransition.Capture(sharedSourcePage);
OpenHarmonySharedTransition.Run(sharedTargetPage);
bool sharedReduceSkips = !OpenHarmonySharedTransition.IsActive && sharedTarget.TranslationX == 0 &&
    sharedTarget.Scale == 1;
OpenHarmonyMotion.OnPlatformReduceMotionChanged(false);
AnimCheck(sharedReduceSkips, $"shared morph reduce-motion skips active={!sharedReduceSkips}");

// Config surface: a zero duration disables the page pass (instant commit), and everything is
// idle once the pass is restored.
double animSavedDuration = OpenHarmonyPageTransitions.DurationMs;
OpenHarmonyPageTransitions.DurationMs = 0;
var animInstantPage = new ContentPage { Title = "anim instant", Content = new Label { Text = "instant" } };
await animNav.PushAsync(animInstantPage, false);
bool zeroDurationSkips = !OpenHarmonyPageTransitions.IsActive && animInstantPage.Opacity == 1;
await animNav.PopAsync(false);
bool zeroDurationPopSkips = !OpenHarmonyPageTransitions.IsActive && animRootPage.Opacity == 1;
OpenHarmonyPageTransitions.DurationMs = animSavedDuration;
PumpAnim(400);
AnimCheck(zeroDurationSkips && zeroDurationPopSkips && OpenHarmonyAnimationLoop.ActiveCount == 0,
    $"transitions config zero-duration={zeroDurationSkips}/{zeroDurationPopSkips} loopIdle={OpenHarmonyAnimationLoop.ActiveCount == 0}");

OpenHarmonyAnimationLoop.Clock = previousAnimClock;
if (animFailures > 0)
{
    throw new InvalidOperationException($"the animation/transition checks failed ({animFailures})");
}

// ---- P1b-LIST: incremental loading, ScrollTo, group collapse, scroll physics -------------------
// The self-drawn list pipeline is exercised live: the shared materializer (one-shot
// RemainingItemsThreshold, ItemsUpdatingScrollMode anchors, full ScrollTo positions and their
// animation, grouped header/footer rows and collapse) plus the scroll physics/scrollbar modules
// (rubber-band drag, edge return spring, fling bounce, reduce-motion coordination, bar
// parameters). The long-list check scrolls a 1,200-item list end to end and pins the bounded
// materialization window and the per-step allocation budget.
Func<long> p1bSavedClock = OpenHarmonyAnimationLoop.Clock;
OpenHarmonyAnimationLoop.Stop();
OpenHarmonyScrollAnimation.ResetForTests();
OpenHarmonyScrollPhysics.ResetForTests();
OpenHarmonyScrollbars.ResetForTests();
long p1bNow = 900_000;
OpenHarmonyAnimationLoop.Clock = () => p1bNow;
int p1bFailures = 0;
void P1bCheck(bool ok, string detail)
{
    if (!ok)
    {
        p1bFailures++;
    }
    Console.WriteLine($"[verify] p1b {detail} assert={ok}");
}

DataTemplate p1bTemplate = new(() =>
{
    var row = new Label { FontSize = 20, HeightRequest = 40 };
    row.SetBinding(Label.TextProperty, ".");
    return row;
});

CollectionView P1bList(System.Collections.IEnumerable items, bool grouped = false, double height = 200,
    DataTemplate? header = null, DataTemplate? footer = null)
{
    var list = new CollectionView
    {
        ItemsSource = items,
        ItemTemplate = p1bTemplate,
        IsGrouped = grouped,
        HeightRequest = height,
    };
    if (header is not null)
    {
        list.GroupHeaderTemplate = header;
    }
    if (footer is not null)
    {
        list.GroupFooterTemplate = footer;
    }
    var host = new ContentPage { Content = new VerticalStackLayout { Children = { list } } };
    OpenHarmonyHandlerConnector.ConnectTree(host);
    host.Measure(1080, height + 80);
    host.Arrange(new Rect(0, 0, 1080, height + 80));
    return list;
}

OpenHarmonyView P1bPlatform(CollectionView list) => (OpenHarmonyView)list.Handler!.PlatformView!;

List<string> P1bTexts(OpenHarmonyView platform)
{
    var texts = new List<string>();
    foreach (IView child in platform.ViewChildren)
    {
        if (child.Handler?.PlatformView is OpenHarmonyView row && row.Text is { } text)
        {
            texts.Add(text);
        }
    }
    return texts;
}

string P1bVisibleText(OpenHarmonyView platform, bool last)
{
    string result = "<none>";
    double best = last ? double.NegativeInfinity : double.PositiveInfinity;
    double offset = platform.ScrollOffsetY;
    double viewport = platform.Frame.Height;
    foreach (IView child in platform.ViewChildren)
    {
        if (child.Handler?.PlatformView is not OpenHarmonyView row || row.Text is null)
        {
            continue;
        }
        double y = child.Frame.Y;
        if (y + child.Frame.Height <= offset + 0.5 || y >= offset + viewport - 0.5)
        {
            continue;
        }
        if (last ? y > best : y < best)
        {
            best = y;
            result = row.Text;
        }
    }
    return result;
}

double P1bScreenY(OpenHarmonyView platform, string text)
{
    foreach (IView child in platform.ViewChildren)
    {
        if (child.Handler?.PlatformView is OpenHarmonyView row && row.Text == text)
        {
            return child.Frame.Y - platform.ScrollOffsetY;
        }
    }
    return double.NaN;
}

double P1bRowY(OpenHarmonyView platform, string text)
{
    foreach (IView child in platform.ViewChildren)
    {
        if (child.Handler?.PlatformView is OpenHarmonyView row && row.Text == text)
        {
            return child.Frame.Y;
        }
    }
    return double.NaN;
}

double P1bRowHeight(OpenHarmonyView platform, string text)
{
    foreach (IView child in platform.ViewChildren)
    {
        if (child.Handler?.PlatformView is OpenHarmonyView row && row.Text == text)
        {
            return child.Frame.Height;
        }
    }
    return double.NaN;
}

// RemainingItemsThreshold: one shot per zone entry, stable while scrolling inside the zone and
// re-armed after leaving it (or after the source grows).
int p1bReached = 0;
var p1bThresholdCv = P1bList(Enumerable.Range(0, 30).Select(i => $"row {i}").ToList());
p1bThresholdCv.RemainingItemsThresholdReached += (_, _) => p1bReached++;
p1bThresholdCv.RemainingItemsThreshold = 2;
p1bThresholdCv.Handler!.UpdateValue(nameof(ItemsView.RemainingItemsThreshold));
p1bThresholdCv.ScrollTo(29, position: ScrollToPosition.End, animate: false);
bool p1bThresholdOne = p1bReached == 1;
p1bThresholdCv.ScrollTo(28, position: ScrollToPosition.MakeVisible, animate: false);
p1bThresholdCv.ScrollTo(29, position: ScrollToPosition.End, animate: false);
bool p1bThresholdStay = p1bReached == 1;
p1bThresholdCv.ScrollTo(0, position: ScrollToPosition.Start, animate: false);
p1bThresholdCv.ScrollTo(29, position: ScrollToPosition.End, animate: false);
bool p1bThresholdRearm = p1bReached == 2;
P1bCheck(p1bThresholdOne && p1bThresholdStay && p1bThresholdRearm,
    $"threshold one-shot={p1bThresholdOne} stay={p1bThresholdStay} rearm={p1bThresholdRearm} fired={p1bReached}");

// ItemsUpdatingScrollMode: prepending five items anchors the requested edge (the same
// prepend/mode combination is what incremental loading and chat-style sources hit). The
// expectations are the item's own screen position, so the check does not depend on the
// template's measured height.
var p1bBase = Enumerable.Range(0, 30).Select(i => $"row {i}").ToList();
var p1bPrepended = Enumerable.Range(100, 5).Select(i => $"new {i}").Concat(p1bBase).ToList();
(string FirstBefore, string LastBefore, double OffsetBefore, double FirstScreenBefore,
    string FirstAfter, string LastAfter, double OffsetAfter, double FirstScreenAfter,
    double LastBottomAfter, double Viewport) P1bModeProbe(ItemsUpdatingScrollMode mode)
{
    var list = P1bList(new List<string>(p1bBase));
    var platform = P1bPlatform(list);
    list.ItemsUpdatingScrollMode = mode;
    list.Handler!.UpdateValue(nameof(ItemsView.ItemsUpdatingScrollMode));
    platform.ScrollOffsetY = 100;
    platform.ScrollOffsetChanged?.Invoke();
    string firstBefore = P1bVisibleText(platform, last: false);
    string lastBefore = P1bVisibleText(platform, last: true);
    double offsetBefore = platform.ScrollOffsetY;
    double firstScreenBefore = P1bScreenY(platform, firstBefore);
    list.ItemsSource = new List<string>(p1bPrepended);
    list.Handler!.UpdateValue(nameof(ItemsView.ItemsSource));
    string firstAfter = P1bVisibleText(platform, last: false);
    string lastAfter = P1bVisibleText(platform, last: true);
    double firstScreenAfter = P1bScreenY(platform, firstBefore);
    double lastBottomAfter = P1bScreenY(platform, lastBefore) + P1bRowHeight(platform, lastBefore);
    return (firstBefore, lastBefore, offsetBefore, firstScreenBefore,
        firstAfter, lastAfter, platform.ScrollOffsetY, firstScreenAfter, lastBottomAfter,
        platform.Frame.Height);
}
var p1bKeepItems = P1bModeProbe(ItemsUpdatingScrollMode.KeepItemsInView);
bool p1bKeepItemsOk = p1bKeepItems.FirstAfter == p1bKeepItems.FirstBefore &&
    Math.Abs(p1bKeepItems.FirstScreenAfter - p1bKeepItems.FirstScreenBefore) < 0.5 &&
    p1bKeepItems.OffsetAfter > p1bKeepItems.OffsetBefore;
var p1bKeepLast = P1bModeProbe(ItemsUpdatingScrollMode.KeepLastItemInView);
// KeepLastItemInView slides the anchor to the viewport bottom (the item's bottom edge sits on
// the viewport bottom), so the check pins that alignment and the item identity.
bool p1bKeepLastOk = p1bKeepLast.LastAfter == p1bKeepLast.LastBefore &&
    Math.Abs(p1bKeepLast.LastBottomAfter - p1bKeepLast.Viewport) < 1.0 &&
    p1bKeepLast.OffsetAfter > p1bKeepLast.OffsetBefore;
var p1bKeepOffset = P1bModeProbe(ItemsUpdatingScrollMode.KeepScrollOffset);
bool p1bKeepOffsetOk = Math.Abs(p1bKeepOffset.OffsetAfter - p1bKeepOffset.OffsetBefore) < 0.01 &&
    p1bKeepOffset.FirstAfter != p1bKeepOffset.FirstBefore;
P1bCheck(p1bKeepItemsOk && p1bKeepLastOk && p1bKeepOffsetOk,
    $"updating keepItems={p1bKeepItems.FirstAfter}@{p1bKeepItems.OffsetAfter:0.##} " +
    $"keepLast={p1bKeepLast.LastAfter}@{p1bKeepLast.OffsetAfter:0.##} " +
    $"keepOffset={p1bKeepOffset.OffsetAfter:0.##} first='{p1bKeepOffset.FirstAfter}'");

// ScrollTo full parameters: Start/Center/End land the slot at the exact alignment and
// MakeVisible leaves an already-visible row untouched. The expectations derive from the
// template's measured slot (the harness measures Label templates at their text height).
var p1bPosCv = P1bList(Enumerable.Range(0, 30).Select(i => $"row {i}").ToList());
var p1bPosPlatform = P1bPlatform(p1bPosCv);
double p1bSlot = P1bRowY(p1bPosPlatform, "row 1") - P1bRowY(p1bPosPlatform, "row 0");
double p1bExtent = P1bRowHeight(p1bPosPlatform, "row 0");
double p1bViewport = p1bPosPlatform.Frame.Height;
double p1bExpectStart = 10 * p1bSlot;
double p1bExpectCenter = 20 * p1bSlot + p1bExtent / 2 - p1bViewport / 2;
double p1bExpectEnd = 25 * p1bSlot + p1bExtent - p1bViewport;
p1bPosCv.ScrollTo(10, position: ScrollToPosition.Start, animate: false);
double p1bStart = p1bPosPlatform.ScrollOffsetY;
p1bPosCv.ScrollTo(20, position: ScrollToPosition.Center, animate: false);
double p1bCenter = p1bPosPlatform.ScrollOffsetY;
p1bPosCv.ScrollTo(25, position: ScrollToPosition.End, animate: false);
double p1bEnd = p1bPosPlatform.ScrollOffsetY;
p1bPosCv.ScrollTo(22, position: ScrollToPosition.MakeVisible, animate: false);
double p1bVisible = p1bPosPlatform.ScrollOffsetY;
bool p1bPositionsOk = Math.Abs(p1bStart - p1bExpectStart) < 1 && Math.Abs(p1bCenter - p1bExpectCenter) < 1 &&
    Math.Abs(p1bEnd - p1bExpectEnd) < 1 && Math.Abs(p1bVisible - p1bEnd) < 0.01;
P1bCheck(p1bPositionsOk,
    $"scrollto start={p1bStart:0} center={p1bCenter:0} end={p1bEnd:0} makeVisible={p1bVisible:0} " +
    $"(expected {p1bExpectStart:0}/{p1bExpectCenter:0}/{p1bExpectEnd:0})");

// ScrollTo(animate: true) slides through the shared frame loop and commits exactly; reduced
// motion snaps to the target without registering an animation.
p1bPosCv.ScrollTo(0, position: ScrollToPosition.Start, animate: false);
p1bPosCv.ScrollTo(25, position: ScrollToPosition.End, animate: true);
bool p1bAnimActive = OpenHarmonyScrollAnimation.IsAnimating(p1bPosPlatform);
float p1bAnimTarget = OpenHarmonyScrollAnimation.TargetFor(p1bPosPlatform);
p1bNow += 16;
OpenHarmonyAnimationLoop.Pump(p1bNow, 1f / 60f);
double p1bAnimMid = p1bPosPlatform.ScrollOffsetY;
for (int i = 0; i < 40; i++)
{
    p1bNow += 16;
    OpenHarmonyAnimationLoop.Pump(p1bNow, 1f / 60f);
}
bool p1bAnimSettled = Math.Abs(p1bPosPlatform.ScrollOffsetY - p1bExpectEnd) < 0.5 &&
    !OpenHarmonyScrollAnimation.IsAnimating(p1bPosPlatform) && OpenHarmonyScrollAnimation.ActiveCount == 0;
bool p1bAnimOk = p1bAnimActive && Math.Abs(p1bAnimTarget - p1bExpectEnd) < 1 &&
    p1bAnimMid > 0 && p1bAnimMid < p1bExpectEnd && p1bAnimSettled;
P1bCheck(p1bAnimOk,
    $"scrollto animated active={p1bAnimActive} target={p1bAnimTarget:0} mid={p1bAnimMid:0} settled={p1bAnimSettled}");

OpenHarmonyMotion.OnPlatformReduceMotionChanged(true);
p1bPosCv.ScrollTo(0, position: ScrollToPosition.Start, animate: false);
p1bPosCv.ScrollTo(25, position: ScrollToPosition.End, animate: true);
bool p1bAnimReduceOk = !OpenHarmonyScrollAnimation.IsAnimating(p1bPosPlatform) &&
    Math.Abs(p1bPosPlatform.ScrollOffsetY - p1bExpectEnd) < 0.5;
OpenHarmonyMotion.OnPlatformReduceMotionChanged(false);
P1bCheck(p1bAnimReduceOk, $"scrollto animated reduce-motion snap offset={p1bPosPlatform.ScrollOffsetY:0}");

// Grouped rows: header + items + footer per group (the footer template adds one row per group);
// collapse hides a group's items and footer from the viewport without touching ItemsSource, and
// header taps toggle the group when the opt-in is enabled.
var p1bGroups = new List<List<string>>
{
    new() { "a1", "a2", "a3", "a4" },
    new() { "b1", "b2", "b3", "b4" },
    new() { "c1", "c2", "c3", "c4" },
};
DataTemplate p1bHeaderTemplate = new(() => new Label { Text = "header", FontSize = 20, HeightRequest = 40 });
DataTemplate p1bFooterTemplate = new(() => new Label { Text = "footer", FontSize = 20, HeightRequest = 40 });
var p1bGroupCv = P1bList(p1bGroups, grouped: true, height: 300, header: p1bHeaderTemplate, footer: p1bFooterTemplate);
var p1bGroupPlatform = P1bPlatform(p1bGroupCv);
double p1bGroupSlot = P1bRowY(p1bGroupPlatform, "a2") - P1bRowY(p1bGroupPlatform, "a1");
double p1bGroupRows = p1bGroupPlatform.ScrollContentHeight / p1bGroupSlot;
List<string> p1bGroupTexts = P1bTexts(p1bGroupPlatform);
bool p1bFooterOk = Math.Abs(p1bGroupRows - 18) < 0.01 && p1bGroupTexts.Contains("header") &&
    p1bGroupTexts.Contains("footer") && p1bGroupTexts.Contains("a1");
P1bCheck(p1bFooterOk, $"group footer rows={p1bGroupRows:0} (18=3*(1+4+1)) slot={p1bGroupSlot:0} texts=[{string.Join(",", p1bGroupTexts.Take(8))}]");

p1bGroupPlatform.ScrollOffsetY = 300;
p1bGroupPlatform.ScrollOffsetChanged?.Invoke();
double p1bBeforeScreen = P1bScreenY(p1bGroupPlatform, "b2");
bool p1bCollapseCalled = p1bGroupCv.SetGroupCollapsed(p1bGroups[0], true);
double p1bCollapsedRows = p1bGroupPlatform.ScrollContentHeight / p1bGroupSlot;
double p1bAfterScreen = P1bScreenY(p1bGroupPlatform, "b2");
double p1bExpectedCollapseOffset = 300 - Math.Min(5 * p1bGroupSlot, 300);
bool p1bCollapseOk = p1bCollapseCalled && p1bGroupCv.IsGroupCollapsed(p1bGroups[0]) &&
    Math.Abs(p1bCollapsedRows - 13) < 0.01 && Math.Abs(p1bGroupPlatform.ScrollOffsetY - p1bExpectedCollapseOffset) < 0.5 &&
    Math.Abs(p1bBeforeScreen - p1bAfterScreen) < 0.5 && !P1bTexts(p1bGroupPlatform).Contains("a1");
P1bCheck(p1bCollapseOk,
    $"group collapse rows={p1bCollapsedRows:0} (13) offset={p1bGroupPlatform.ScrollOffsetY:0} ({p1bExpectedCollapseOffset:0}) " +
    $"b2screen={p1bBeforeScreen:0}->{p1bAfterScreen:0}");

bool p1bExpandCalled = p1bGroupCv.SetGroupCollapsed(p1bGroups[0], false);
double p1bExpandedRows = p1bGroupPlatform.ScrollContentHeight / p1bGroupSlot;
bool p1bExpandOk = p1bExpandCalled && !p1bGroupCv.IsGroupCollapsed(p1bGroups[0]) &&
    Math.Abs(p1bExpandedRows - 18) < 0.01 && P1bTexts(p1bGroupPlatform).Contains("a1");
P1bCheck(p1bExpandOk, $"group expand rows={p1bExpandedRows:0} (18) a1visible={P1bTexts(p1bGroupPlatform).Contains("a1")}");

p1bGroupCv.SetGroupHeaderTogglesCollapse(true);
foreach (IView child in p1bGroupPlatform.ViewChildren)
{
    if (child.Handler?.PlatformView is OpenHarmonyView headerRow && headerRow.Text == "header")
    {
        headerRow.Tap?.Invoke();
        break;
    }
}
bool p1bTapCollapsed = p1bGroupCv.IsGroupCollapsed(p1bGroups[0]);
bool p1bTapOk = p1bTapCollapsed;
P1bCheck(p1bTapOk, $"group header tap collapses={p1bTapCollapsed}");
// T13: a GroupFooterTemplate that materialises a full View (not just a Label) is drawn as the
// footer row itself, bound to the group object (the plain text path stays for Label templates).
var p1bViewGroups = new List<T13Group>
{
    new("g1", new[] { "v1a", "v1b", "v1c" }),
    new("g2", new[] { "v2a", "v2b", "v2c" }),
};
DataTemplate p1bViewFooter = new(() =>
{
    var label = new Label { FontSize = 18 };
    label.SetBinding(Label.TextProperty, nameof(T13Group.Name));
    var accent = new BoxView { Color = Colors.Orange, WidthRequest = 12 };
    var grid = new Grid
    {
        HeightRequest = 40,
        ColumnSpacing = 6,
        ColumnDefinitions = { new ColumnDefinition(GridLength.Star), new ColumnDefinition(GridLength.Auto) },
    };
    grid.Children.Add(label);
    grid.Children.Add(accent);
    Grid.SetColumn(accent, 1);
    return grid;
});
var p1bViewCv = P1bList(p1bViewGroups, grouped: true, height: 300, header: p1bHeaderTemplate, footer: p1bViewFooter);
var p1bViewPlatform = P1bPlatform(p1bViewCv);
List<View> p1bViewRows = p1bViewPlatform.ViewChildren.OfType<View>().ToList();
var p1bViewFooters = p1bViewRows.OfType<Grid>().ToList();
string p1bViewFooterText(int index) => (p1bViewFooters[index].Children[0] as Label)?.Text ?? "<none>";
bool p1bViewFooterOk = p1bViewRows.Count == 10 && p1bViewFooters.Count == 2 &&
    ReferenceEquals(p1bViewFooters[0].BindingContext, p1bViewGroups[0]) &&
    ReferenceEquals(p1bViewFooters[1].BindingContext, p1bViewGroups[1]) &&
    p1bViewFooterText(0) == "g1" && p1bViewFooterText(1) == "g2" &&
    p1bViewRows[3] is Label && p1bViewRows[4] is Grid && p1bViewRows[8] is Label && p1bViewRows[9] is Grid;
P1bCheck(p1bViewFooterOk,
    $"group footer view rows={p1bViewRows.Count} (10) footers={p1bViewFooters.Count} " +
    $"texts=[{p1bViewFooterText(0)},{p1bViewFooterText(1)}] " +
    $"bound={ReferenceEquals(p1bViewFooters[0].BindingContext, p1bViewGroups[0])}/{ReferenceEquals(p1bViewFooters[1].BindingContext, p1bViewGroups[1])}");

// Scroll physics: rubber-band drag past an edge, the release spring, and a fling that carries
// the content past the edge before the spring returns it (reduced motion clamps instead).
var p1bDragView = new OpenHarmonyView();
var p1bDragScroll = new ScrollView();
p1bDragView.VirtualView = p1bDragScroll;
p1bDragScroll.Frame = new Rect(0, 0, 400, 600);
p1bDragView.ScrollContentHeight = 2000;
float p1bBandTop = OpenHarmonyScrollPhysics.DragOffset(p1bDragView, 10f, -40f, 1400f);
float p1bBandBottom = OpenHarmonyScrollPhysics.DragOffset(p1bDragView, 1390f, 40f, 1400f);
float p1bBandInside = OpenHarmonyScrollPhysics.DragOffset(p1bDragView, 500f, 40f, 1400f);
float p1bBandTopExpected = -30f * OpenHarmonyScrollPhysics.RubberBandFactor;
float p1bBandBottomExpected = 1400f + 30f * OpenHarmonyScrollPhysics.RubberBandFactor;
OpenHarmonyMotion.OnPlatformReduceMotionChanged(true);
float p1bBandReduced = OpenHarmonyScrollPhysics.DragOffset(p1bDragView, 10f, -40f, 1400f);
OpenHarmonyMotion.OnPlatformReduceMotionChanged(false);
bool p1bBandOk = Math.Abs(p1bBandTop - p1bBandTopExpected) < 0.01f &&
    Math.Abs(p1bBandBottom - p1bBandBottomExpected) < 0.01f &&
    Math.Abs(p1bBandInside - 540f) < 0.01f && p1bBandReduced == 0f;
P1bCheck(p1bBandOk,
    $"physics rubberband top={p1bBandTop:0.#} bottom={p1bBandBottom:0.#} inside={p1bBandInside:0.#} reduced={p1bBandReduced:0.#}");

p1bDragView.ScrollOffsetY = -30f;
bool p1bSpringStarted = OpenHarmonyScrollPhysics.TryReturnToEdge(p1bDragView);
bool p1bSpringLeftEdge = false;
for (int i = 0; i < 60; i++)
{
    p1bNow += 16;
    OpenHarmonyAnimationLoop.Pump(p1bNow, 1f / 60f);
    if (p1bDragView.ScrollOffsetY < -0.5f)
    {
        p1bSpringLeftEdge = true;
    }
}
bool p1bSpringSettled = Math.Abs(p1bDragView.ScrollOffsetY) < 0.5f && !OpenHarmonyScrollPhysics.IsBouncing(p1bDragView);
P1bCheck(p1bSpringStarted && p1bSpringLeftEdge && p1bSpringSettled,
    $"physics edge-return started={p1bSpringStarted} offset={p1bDragView.ScrollOffsetY:0.##} settled={p1bSpringSettled}");

OpenHarmonyScrollPhysics.ResetForTests();
var p1bFlingView = new OpenHarmonyView();
var p1bFlingScroll = new ScrollView();
p1bFlingView.VirtualView = p1bFlingScroll;
p1bFlingScroll.Frame = new Rect(0, 0, 400, 600);
p1bFlingView.ScrollContentHeight = 2000;
for (int i = 1; i <= 4; i++)
{
    p1bNow += 16;
    p1bFlingView.ScrollOffsetY = 1200f + i * 40f;
}
bool p1bFlingStarted = OpenHarmonyScrollPhysics.TryStartFling(p1bFlingView);
float p1bFlingMax = p1bFlingView.ScrollOffsetY;
for (int i = 0; i < 120; i++)
{
    p1bNow += 16;
    OpenHarmonyAnimationLoop.Pump(p1bNow, 1f / 60f);
    p1bFlingMax = Math.Max(p1bFlingMax, p1bFlingView.ScrollOffsetY);
}
bool p1bFlingOk = p1bFlingStarted && p1bFlingMax > 1400.5f &&
    p1bFlingMax <= 1400f + OpenHarmonyScrollPhysics.MaxOverscroll + 0.5f &&
    Math.Abs(p1bFlingView.ScrollOffsetY - 1400f) < 0.5f && OpenHarmonyScrollPhysics.ActiveFlings == 0;
P1bCheck(p1bFlingOk,
    $"physics fling bounce started={p1bFlingStarted} max={p1bFlingMax:0.#} settle={p1bFlingView.ScrollOffsetY:0.##} flings={OpenHarmonyScrollPhysics.ActiveFlings}");

OpenHarmonyScrollPhysics.ResetForTests();
OpenHarmonyMotion.OnPlatformReduceMotionChanged(true);
var p1bReducedFling = new OpenHarmonyView();
var p1bReducedScroll = new ScrollView();
p1bReducedFling.VirtualView = p1bReducedScroll;
p1bReducedScroll.Frame = new Rect(0, 0, 400, 600);
p1bReducedFling.ScrollContentHeight = 2000;
for (int i = 1; i <= 4; i++)
{
    p1bNow += 16;
    p1bReducedFling.ScrollOffsetY = 1200f + i * 40f;
}
bool p1bReducedStarted = OpenHarmonyScrollPhysics.TryStartFling(p1bReducedFling);
float p1bReducedMax = p1bReducedFling.ScrollOffsetY;
for (int i = 0; i < 60; i++)
{
    p1bNow += 16;
    OpenHarmonyAnimationLoop.Pump(p1bNow, 1f / 60f);
    p1bReducedMax = Math.Max(p1bReducedMax, p1bReducedFling.ScrollOffsetY);
}
OpenHarmonyMotion.OnPlatformReduceMotionChanged(false);
bool p1bReducedFlingOk = p1bReducedStarted && p1bReducedMax <= 1400.5f &&
    Math.Abs(p1bReducedFling.ScrollOffsetY - 1400f) < 0.5f;
P1bCheck(p1bReducedFlingOk,
    $"physics fling reduce-motion max={p1bReducedMax:0.#} settle={p1bReducedFling.ScrollOffsetY:0.##}");

// Scrollbar parameters + reduce-motion coordination: the documented defaults, a settable
// hold/fade, the fade itself, and the instant hide under reduced motion.
bool p1bBarDefaults = OpenHarmonyScrollbars.DefaultHoldMs == 900 && OpenHarmonyScrollbars.DefaultFadeMs == 250 &&
    OpenHarmonyScrollbars.Thickness == 4f && OpenHarmonyScrollbars.Margin == 3f;
OpenHarmonyScrollbars.HoldMs = 40;
OpenHarmonyScrollbars.FadeMs = 80;
var p1bBarView = new OpenHarmonyView();
var p1bBarScroll = new ScrollView();
p1bBarView.VirtualView = p1bBarScroll;
p1bBarScroll.Frame = new Rect(0, 0, 400, 600);
p1bBarView.ScrollContentHeight = 2000;
OpenHarmonyScrollbars.NotifyScrolled(p1bBarView);
bool p1bBarFull = OpenHarmonyScrollbars.OpacityFor(p1bBarView) == 1f && OpenHarmonyScrollbars.ShouldDraw(p1bBarView);
p1bNow += 20;
OpenHarmonyAnimationLoop.Pump(p1bNow, 1f / 60f);
bool p1bBarHeld = OpenHarmonyScrollbars.OpacityFor(p1bBarView) == 1f;
p1bNow += 40;
OpenHarmonyAnimationLoop.Pump(p1bNow, 1f / 60f);
float p1bBarMid = OpenHarmonyScrollbars.OpacityFor(p1bBarView);
for (int i = 0; i < 8; i++)
{
    p1bNow += 16;
    OpenHarmonyAnimationLoop.Pump(p1bNow, 1f / 60f);
}
bool p1bBarFaded = p1bBarMid < 1f && p1bBarMid > 0f && OpenHarmonyScrollbars.OpacityFor(p1bBarView) == 0f &&
    !OpenHarmonyScrollbars.ShouldDraw(p1bBarView);
OpenHarmonyScrollbars.NotifyScrolled(p1bBarView);
OpenHarmonyMotion.OnPlatformReduceMotionChanged(true);
p1bNow += 20;
OpenHarmonyAnimationLoop.Pump(p1bNow, 1f / 60f);
bool p1bBarReduceHeld = OpenHarmonyScrollbars.OpacityFor(p1bBarView) == 1f;
p1bNow += 40;
OpenHarmonyAnimationLoop.Pump(p1bNow, 1f / 60f);
bool p1bBarReduceHidden = OpenHarmonyScrollbars.OpacityFor(p1bBarView) == 0f;
OpenHarmonyMotion.OnPlatformReduceMotionChanged(false);
P1bCheck(p1bBarDefaults && p1bBarFull && p1bBarHeld && p1bBarFaded && p1bBarReduceHeld && p1bBarReduceHidden,
    $"scrollbar defaults={p1bBarDefaults} full={p1bBarFull} hold={p1bBarHeld} fade={p1bBarMid:0.##} hidden={p1bBarFaded} " +
    $"reduceHold={p1bBarReduceHeld} reduceHidden={p1bBarReduceHidden}");

// Long list: 1,200 items materialize a bounded window. Scrolling inside the current window is
// a pure frame-path update (no allocation), and scrolling the whole content materializes each
// row at most once (pool reuse keeps the window bounded).
var p1bLongCv = P1bList(Enumerable.Range(0, 1200).Select(i => $"long {i}").ToList(), height: 400);
var p1bLongPlatform = P1bPlatform(p1bLongCv);
double p1bLongSlot = P1bRowY(p1bLongPlatform, "long 1") - P1bRowY(p1bLongPlatform, "long 0");
int p1bLongChildren = p1bLongPlatform.ViewChildren.Count;
double p1bLongContent = p1bLongPlatform.ScrollContentHeight;
p1bLongPlatform.ScrollOffsetY = 5000;
p1bLongPlatform.ScrollOffsetChanged?.Invoke();
for (int i = 0; i < 20; i++)
{
    p1bLongPlatform.ScrollOffsetY = 5000 + (i % 5);
    p1bLongPlatform.ScrollOffsetChanged?.Invoke();
}
long p1bLongSteadyBefore = GC.GetAllocatedBytesForCurrentThread();
int p1bLongMaxChildren = 0;
for (int i = 0; i < 200; i++)
{
    // A few pixels inside one slot: the materialization window does not move, so this is the
    // per-frame path a moving finger drives (offset sample + scrollbar notify + window check).
    p1bLongPlatform.ScrollOffsetY = 5000 + (i % 9);
    p1bLongPlatform.ScrollOffsetChanged?.Invoke();
    p1bLongMaxChildren = Math.Max(p1bLongMaxChildren, p1bLongPlatform.ViewChildren.Count);
}
long p1bLongSteadyPerStep = (GC.GetAllocatedBytesForCurrentThread() - p1bLongSteadyBefore) / 200;
long p1bLongFullBefore = GC.GetAllocatedBytesForCurrentThread();
for (int i = 0; i < 200; i++)
{
    p1bLongPlatform.ScrollOffsetY = 5000 + i * 60;
    p1bLongPlatform.ScrollOffsetChanged?.Invoke();
    p1bLongMaxChildren = Math.Max(p1bLongMaxChildren, p1bLongPlatform.ViewChildren.Count);
}
long p1bLongFullAlloc = GC.GetAllocatedBytesForCurrentThread() - p1bLongFullBefore;
const long p1bLongSteadyCeiling = 1024;   // measured 461 B/step; a per-frame list would add hundreds
const long p1bLongFullCeiling = 6 * 1024 * 1024;
bool p1bLongOk = Math.Abs(p1bLongContent - 1200 * p1bLongSlot) < 0.01 && p1bLongChildren is > 0 and < 40 &&
    p1bLongMaxChildren < 40 && p1bLongSteadyPerStep <= p1bLongSteadyCeiling &&
    p1bLongFullAlloc <= p1bLongFullCeiling;
P1bCheck(p1bLongOk,
    $"longlist items=1200 slot={p1bLongSlot:0} height={p1bLongContent:0} children={p1bLongChildren} " +
    $"maxChildren={p1bLongMaxChildren} steadyAllocPerStep={p1bLongSteadyPerStep}B ceiling={p1bLongSteadyCeiling}B " +
    $"fullAlloc={p1bLongFullAlloc / 1024}KiB ceiling={p1bLongFullCeiling / 1024}KiB");

// Source pins: the new semantics live in the named members (and the public collapse surface is
// declared in the net-openharmony API baseline).
string? p1bHandlerPath = FindHostSource("OpenHarmonyCollectionViewHandler.cs");
string p1bHandler = p1bHandlerPath is null ? string.Empty : File.ReadAllText(p1bHandlerPath);
string? p1bMatPath = FindHostSource("OpenHarmonyItemListMaterializer.cs");
string p1bMat = p1bMatPath is null ? string.Empty : File.ReadAllText(p1bMatPath);
string? p1bPhysPath = FindHostSource("OpenHarmonyScrollPhysics.cs");
string p1bPhys = p1bPhysPath is null ? string.Empty : File.ReadAllText(p1bPhysPath);
string? p1bAnimPath = FindHostSource("OpenHarmonyScrollAnimation.cs");
string p1bAnim = p1bAnimPath is null ? string.Empty : File.ReadAllText(p1bAnimPath);
string? p1bExtPath = FindHostSource("OpenHarmonyCollectionViewExtensions.cs");
string p1bExt = p1bExtPath is null ? string.Empty : File.ReadAllText(p1bExtPath);
string? p1bApiPath = FindHostSource("src/Core/src/PublicAPI/net-openharmony/PublicAPI.Unshipped.txt");
string p1bApi = p1bApiPath is null ? string.Empty : File.ReadAllText(p1bApiPath);
bool p1bPinThreshold = p1bHandler.Contains("_thresholdArmed = false;") &&
    p1bHandler.Contains("if (!_thresholdArmed || _thresholdFiring)");
bool p1bPinUpdating = p1bHandler.Contains("[nameof(ItemsView.ItemsUpdatingScrollMode)] = MapItemsUpdatingScrollMode,") &&
    p1bMat.Contains("public ItemsUpdatingScrollMode UpdateMode { get; set; } = ItemsUpdatingScrollMode.KeepItemsInView;") &&
    p1bMat.Contains("ApplyAnchorOffset(mode, anchorItem, anchorOffset);");
bool p1bPinScrollTo = p1bHandler.Contains("materializer.ScrollTo(row, args.ScrollToPosition, args.IsAnimated);") &&
    p1bMat.Contains("public void ScrollTo(int row, ScrollToPosition position, bool animated)") &&
    p1bMat.Contains("OpenHarmonyScrollAnimation.Start(_platformView, (float)target, ApplyScrollOffset);");
bool p1bPinCollapse = p1bMat.Contains("public bool SetGroupCollapsed(object? group, bool collapsed)") &&
    p1bMat.Contains("public bool IsGroupCollapsed(object? group)") &&
    p1bMat.Contains("_footerRows") && p1bHandler.Contains("[nameof(GroupableItemsView.GroupFooterTemplate)] = MapGroupFooter,") &&
    p1bHandler.Contains("SetGroupHeaderTogglesCollapse");
bool p1bPinPhysics = p1bPhys.Contains("internal static float DragOffset(") &&
    p1bPhys.Contains("internal static bool TryReturnToEdge(") &&
    p1bPhys.Contains("internal const float MaxOverscroll = 64f;") &&
    p1bPhys.Contains("internal static void BeginProgrammatic()") &&
    p1bAnim.Contains("internal static class OpenHarmonyScrollAnimation") &&
    p1bAnim.Contains("internal const long MaxDurationMs = 420;");
bool p1bPinApi = p1bApi.Contains("Microsoft.Maui.Platform.OpenHarmonyCollectionViewExtensions") &&
    p1bApi.Contains("OpenHarmonyCollectionViewExtensions.SetGroupCollapsed(") &&
    p1bApi.Contains("OpenHarmonyCollectionViewExtensions.ToggleGroupCollapsed(") &&
    p1bExt.Contains("public static bool ToggleGroupCollapsed(this CollectionView collectionView, object group)");
bool p1bPinsOk = p1bPinThreshold && p1bPinUpdating && p1bPinScrollTo && p1bPinCollapse && p1bPinPhysics && p1bPinApi;
P1bCheck(p1bPinsOk,
    $"pins threshold={p1bPinThreshold} updating={p1bPinUpdating} scrollto={p1bPinScrollTo} collapse={p1bPinCollapse} " +
    $"physics={p1bPinPhysics} api={p1bPinApi} source='{p1bHandlerPath ?? "<missing>"}'");

OpenHarmonyScrollAnimation.ResetForTests();
OpenHarmonyScrollPhysics.ResetForTests();
OpenHarmonyScrollbars.ResetForTests();
OpenHarmonyAnimationLoop.Clock = p1bSavedClock;
if (p1bFailures > 0)
{
    throw new InvalidOperationException($"the P1b-LIST checks failed ({p1bFailures})");
}

// ---- T12 CarouselView group slides -------------------------------------------------------------
// A grouped carousel flattens to item slides by default (CarouselView has no group templates of
// its own). OpenHarmonyCarouselView.GroupHeaderTemplate/GroupFooterTemplate attach the missing
// half: with a template set the slide stream gains a header/footer slide per group, bound to the
// group object; the attached-property change re-materialises a connected carousel (Position,
// CurrentItem and the page-indicator count then all run over the slide stream), and clearing a
// template removes its slides again.
int t12Failures = 0;
void T12Check(bool ok, string detail)
{
    if (!ok)
    {
        t12Failures++;
    }
    Console.WriteLine($"[verify] t12 {detail} assert={ok}");
}

var t12Groups = new List<T13Group>
{
    new("g1", new[] { "a1", "a2" }),
    new("g2", new[] { "b1", "b2" }),
};
DataTemplate t12Item = new(() =>
{
    var label = new Label { FontSize = 30 };
    label.SetBinding(Label.TextProperty, ".");
    return label;
});
DataTemplate t12Header = new(() =>
{
    var label = new Label { FontSize = 28 };
    label.SetBinding(Label.TextProperty, new Binding(nameof(T13Group.Name)) { StringFormat = "H:{0}" });
    return label;
});
DataTemplate t12Footer = new(() =>
{
    var label = new Label { FontSize = 26 };
    label.SetBinding(Label.TextProperty, new Binding(nameof(T13Group.Name)) { StringFormat = "F:{0}" });
    return label;
});
var t12Carousel = new CarouselView
{
    ItemsSource = t12Groups,
    ItemTemplate = t12Item,
    HeightRequest = 140,
};
var t12Page = new ContentPage { Content = new VerticalStackLayout { Children = { t12Carousel } } };
OpenHarmonyHandlerConnector.ConnectTree(t12Page);
t12Page.Measure(1080, 220);
t12Page.Arrange(new Rect(0, 0, 1080, 220));
var t12Platform = (OpenHarmonyView)t12Carousel.Handler!.PlatformView!;
string T12Kinds() => string.Join(",", Microsoft.Maui.Platform.OpenHarmonyCarouselViewHandler
    .MaterializeSlides(t12Carousel).Select(slide => slide.Kind));
string T12Current() => (t12Platform.ViewChildren.FirstOrDefault()?.Handler?.PlatformView as OpenHarmonyView)?.Text ?? "<none>";
bool T12BoundTo(object group) => t12Platform.ViewChildren.FirstOrDefault() is View view &&
    ReferenceEquals(view.BindingContext, group);

var t12Flat = Microsoft.Maui.Platform.OpenHarmonyCarouselViewHandler.MaterializeSlides(t12Carousel);
bool t12FlatOk = t12Flat.Count == 4 &&
    t12Flat.All(slide => slide.Kind == Microsoft.Maui.Platform.OpenHarmonyCarouselViewHandler.CarouselSlideKind.Item) &&
    T12Current() == "a1";
T12Check(t12FlatOk, $"grouped no-template slides={t12Flat.Count} (4) kinds={T12Kinds()} text='{T12Current()}'");

Microsoft.Maui.Platform.OpenHarmonyCarouselView.SetGroupHeaderTemplate(t12Carousel, t12Header);
Microsoft.Maui.Platform.OpenHarmonyCarouselView.SetGroupFooterTemplate(t12Carousel, t12Footer);
var t12All = Microsoft.Maui.Platform.OpenHarmonyCarouselViewHandler.MaterializeSlides(t12Carousel);
bool t12AllOk = t12All.Count == 8 &&
    T12Kinds() == "GroupHeader,Item,Item,GroupFooter,GroupHeader,Item,Item,GroupFooter" &&
    ReferenceEquals(t12All[0].Data, t12Groups[0]) && Equals(t12All[1].Data, "a1") &&
    ReferenceEquals(t12All[3].Data, t12Groups[0]) && T12Current() == "H:g1" && T12BoundTo(t12Groups[0]);
T12Check(t12AllOk,
    $"grouped templates slides={t12All.Count} (8) kinds={T12Kinds()} text='{T12Current()}' bound={T12BoundTo(t12Groups[0])}");

t12Carousel.Position = 3;
t12Carousel.Handler!.UpdateValue(nameof(Microsoft.Maui.Controls.CarouselView.Position));
string t12FooterText = T12Current();
bool t12FooterOk = t12FooterText == "F:g1" && t12Carousel.Position == 3 &&
    ReferenceEquals(t12Carousel.CurrentItem, t12Groups[0]) && T12BoundTo(t12Groups[0]);
T12Check(t12FooterOk,
    $"grouped footer position={t12Carousel.Position} text='{t12FooterText}' currentItem={(t12Carousel.CurrentItem as T13Group)?.Name ?? "<none>"} bound={T12BoundTo(t12Groups[0])}");

t12Platform.Swipe?.Invoke(-60f, 0f);
string t12HeaderText = T12Current();
bool t12SwipeOk = t12Carousel.Position == 4 && t12HeaderText == "H:g2" &&
    ReferenceEquals(t12Carousel.CurrentItem, t12Groups[1]);
T12Check(t12SwipeOk,
    $"grouped swipe position={t12Carousel.Position} (4) text='{t12HeaderText}' currentItem={(t12Carousel.CurrentItem as T13Group)?.Name ?? "<none>"}");

Microsoft.Maui.Platform.OpenHarmonyCarouselView.SetGroupHeaderTemplate(t12Carousel, null);
var t12FooterOnly = Microsoft.Maui.Platform.OpenHarmonyCarouselViewHandler.MaterializeSlides(t12Carousel);
bool t12ClearOk = t12FooterOnly.Count == 6 && T12Kinds() == "Item,Item,GroupFooter,Item,Item,GroupFooter" &&
    T12Current() == "b2" && Equals(t12Carousel.CurrentItem, "b2");
T12Check(t12ClearOk, $"grouped clear header slides={t12FooterOnly.Count} (6) kinds={T12Kinds()} text='{T12Current()}'");

if (t12Failures > 0)
{
    throw new InvalidOperationException($"the T12 CarouselView group-slide checks failed ({t12Failures})");
}

// ---- Deterministic fuzz (bounded, seeded) -----------------------------------------------------
// A seeded storm of touch sequences with extreme but finite (mostly out-of-bounds) coordinates,
// two very long strings through the simulated bridge payloads and a ~300-node deep view tree that
// drives the iterative accessibility/diagnostics walks. It is bounded (300 sequences, 32-48 KiB
// payloads, no big buffers), deterministic (fixed seed) and must finish in seconds, so it asserts
// "no unhandled exception, no hang" without slowing the suite down.
var fuzzWatch = System.Diagnostics.Stopwatch.StartNew();
var fuzzRandom = new Random(20260920);   // fixed seed -> identical sequences on every run
string fuzzTouchResult = "no throw";
for (int i = 0; i < 300; i++)
{
    // Every fifth sequence lands inside the 1080x1920 surface; the rest uses finite but extreme
    // coordinates (including +-float.MaxValue) that no device would ever produce.
    float x0, y0, x1, y1;
    if (i % 5 == 0)
    {
        x0 = (float)(fuzzRandom.NextDouble() * 1080);
        y0 = (float)(fuzzRandom.NextDouble() * 1920);
        x1 = (float)(fuzzRandom.NextDouble() * 1080);
        y1 = (float)(fuzzRandom.NextDouble() * 1920);
    }
    else if (i % 97 == 0)
    {
        x0 = float.MaxValue; y0 = -float.MaxValue;
        x1 = float.MinValue; y1 = float.MaxValue;
    }
    else
    {
        x0 = (float)(fuzzRandom.NextDouble() * 4_000_000 - 2_000_000);
        y0 = (float)(fuzzRandom.NextDouble() * 4_000_000 - 2_000_000);
        x1 = (float)(fuzzRandom.NextDouble() * 4_000_000 - 2_000_000);
        y1 = (float)(fuzzRandom.NextDouble() * 4_000_000 - 2_000_000);
    }
    try
    {
        host.HandleTouch(true, false, x0, y0);
        for (int moves = fuzzRandom.Next(3); moves > 0; moves--)
        {
            host.HandleMove((float)(fuzzRandom.NextDouble() * 4_000_000 - 2_000_000),
                            (float)(fuzzRandom.NextDouble() * 4_000_000 - 2_000_000));
        }
        host.HandleTouch(false, true, x1, y1);
    }
    catch (Exception ex)
    {
        fuzzTouchResult = $"sequence {i} threw {ex.GetType().Name}: {ex.Message}";
        break;
    }
}
Console.WriteLine($"[verify] fuzz touch sequences=300 seed=20260920 extreme=finite out-of-bounds=true result={fuzzTouchResult}");
if (fuzzTouchResult != "no throw")
{
    throw new InvalidOperationException($"the seeded touch fuzz raised {fuzzTouchResult}");
}

// Two very long payloads through the simulated JS -> .NET bridge: the HybridWebView
// __RawMessage channel (escaped/unescaped) and the native notifyJsMessage callback, both must
// round-trip the full string without throwing.
string fuzzLongRaw = new string('r', 32 * 1024);
string fuzzLongJson = new string('j', 48 * 1024);
string? fuzzRawSeen = null;
string? fuzzJsSeen = null;
void FuzzOnJs(string payload) => fuzzJsSeen = payload;
hybridProbe.RawMessageReceived += (_, e) => fuzzRawSeen = e.Message;
OpenHarmonyWebViewHandler.JsMessage += FuzzOnJs;
string fuzzPayloadResult;
try
{
    OpenHarmonyHybridWebViewHandler.OnJsMessage(hybridEnvelope + "__RawMessage|" + Uri.EscapeDataString(fuzzLongRaw));
    string? fuzzRawAfterHybrid = fuzzRawSeen;
    OpenHarmonyWebViewHandler.HandleJsMessage("{\"pad\":\"" + fuzzLongJson + "\"}");
    string expectedJson = "{\"pad\":\"" + fuzzLongJson + "\"}";
    // The native WebView callback is also fanned out to the HybridWebView raw channel (the shell
    // routes every dotnetHost.postMessage payload through it), but that JSON carries no
    // document-origin envelope, so the hybrid channel now rejects it instead of broadcasting it:
    // the raw probe keeps the last accepted (enveloped) message.
    fuzzPayloadResult = fuzzRawAfterHybrid == fuzzLongRaw && fuzzJsSeen == expectedJson
        ? "round-trip ok"
        : $"hybrid={fuzzRawAfterHybrid?.Length ?? -1} js={fuzzJsSeen?.Length ?? -1} rawAfterJs={fuzzRawSeen?.Length ?? -1}";
}
catch (Exception ex)
{
    fuzzPayloadResult = $"{ex.GetType().Name}: {ex.Message}";
}
finally
{
    OpenHarmonyWebViewHandler.JsMessage -= FuzzOnJs;
}
Console.WriteLine($"[verify] fuzz bridge payloads raw={fuzzLongRaw.Length}B json={fuzzLongJson.Length}B result={fuzzPayloadResult}");
if (fuzzPayloadResult != "round-trip ok")
{
    throw new InvalidOperationException($"the long bridge payload fuzz failed: {fuzzPayloadResult}");
}

// A ~300-node deep tree (150 nested layouts, each with a label) through the iterative walks:
// OpenHarmonyAccessibility.Visit (the Stack-based shadow tree) and the diagnostics overlay walk,
// both reached through OpenHarmonyWindowRenderer.Render, plus the recursive Describe log. The tree
// is kept detached so the assertion is independent of the app page the touch fuzz left behind.
var fuzzRenderer = app.Services.GetRequiredService<OpenHarmonyWindowRenderer>();
var fuzzTree = new VerticalStackLayout { Spacing = 1 };
Microsoft.Maui.ILayout fuzzCursor = fuzzTree;
for (int i = 0; i < 150; i++)
{
    var fuzzLabel = new Label { Text = $"fuzz node {i}", FontSize = 8 };
    var fuzzNested = new VerticalStackLayout { Spacing = 1 };
    fuzzCursor.Add(fuzzLabel);
    fuzzCursor.Add(fuzzNested);
    fuzzCursor = fuzzNested;
}
string fuzzTreeResult;
try
{
    OpenHarmonyDiagnostics.Enabled = true;
    bool fuzzRendered = fuzzRenderer.Render(fuzzTree, 1080, 1920);
    OpenHarmonyDiagnostics.Enabled = false;
    int fuzzNodes = OpenHarmonyAccessibility.Nodes.Count;
    int fuzzDescribeChars = fuzzRenderer.Describe(fuzzTree).Length;
    fuzzTreeResult = fuzzRendered && fuzzNodes >= 300 && fuzzDescribeChars > 0
        ? "render=True walk ok"
        : $"render={fuzzRendered} nodes={fuzzNodes} describeChars={fuzzDescribeChars}";
}
catch (Exception ex)
{
    OpenHarmonyDiagnostics.Enabled = false;
    fuzzTreeResult = $"{ex.GetType().Name}: {ex.Message}";
}
Console.WriteLine($"[verify] fuzz deep tree nodes=301 depth=150 seed=20260920 result={fuzzTreeResult}");
if (fuzzTreeResult != "render=True walk ok")
{
    throw new InvalidOperationException($"the deep-tree fuzz failed: {fuzzTreeResult}");
}

int fuzzMillis = (int)fuzzWatch.ElapsedMilliseconds;
Console.WriteLine($"[verify] fuzz bounded elapsed={fuzzMillis}ms limit=30000ms seed=20260920 (no hang)");
if (fuzzWatch.Elapsed > TimeSpan.FromSeconds(30))
{
    throw new InvalidOperationException($"the fuzz section took {fuzzMillis} ms");
}

// ---- P2c-DEEPLINK: want/activation routing ----------------------------------------------------
// The shell captures the cold-start want in onCreate and forwards every onNewWant through
// host.notifyActivation; the host queues the payload until the managed activation thunk
// registers; OpenHarmonyAppLinks de-duplicates by want sequence, applies through
// Shell.GoToAsync (which is the Navigating approval chain) or a registered NavigationPage
// route, and keeps a request queued while no navigation target exists. These checks pin the
// shell sources, the host transport and every managed decision point off-device.
string? p2cHeadlessPath = FindHostSource("packs/Microsoft.OpenHarmony.Sdk/1.0.0-preview.24/templates/ets/entryability/EntryAbility.ets");
string? p2cUiPath = FindHostSource("packs/Microsoft.OpenHarmony.Sdk/1.0.0-preview.24/templates/ets/entryability/EntryAbility.ui.ets");
string p2cHeadless = p2cHeadlessPath is null ? string.Empty : File.ReadAllText(p2cHeadlessPath);
string p2cUi = p2cUiPath is null ? string.Empty : File.ReadAllText(p2cUiPath);
bool p2cShellOnCreate = p2cHeadless.Contains("this.pendingWant = want;") && p2cUi.Contains("this.pendingWant = want;");
bool p2cShellOnNewWant = p2cHeadless.Contains("onNewWant(want: Want, launchParam: AbilityConstant.LaunchParam)") &&
    p2cUi.Contains("onNewWant(want: Want, launchParam: AbilityConstant.LaunchParam)") &&
    p2cHeadless.Contains("this.publishActivation(want);") && p2cUi.Contains("this.publishActivation(want);");
bool p2cShellPreStart = p2cHeadless.Contains("this.publishActivation(this.pendingWant);") &&
    p2cUi.Contains("this.publishActivation(this.pendingWant);") &&
    p2cHeadless.Contains("this.activationReady = true;") && p2cUi.Contains("this.activationReady = true;");
bool p2cShellPayload = p2cHeadless.Contains("host.notifyActivation(payload)") && p2cUi.Contains("host.notifyActivation(payload)") &&
    p2cHeadless.Contains("linkHosts: this.linkHosts") && p2cUi.Contains("linkHosts: this.linkHosts");
int p2cPackSources = 0;
foreach (string p2cPackVersion in new[] { "1.0.0-preview.22", "1.0.0-preview.23", "1.0.0-preview.24" })
{
    string? head = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{p2cPackVersion}/templates/ets/entryability/EntryAbility.ets");
    string? ui = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{p2cPackVersion}/templates/ets/entryability/EntryAbility.ui.ets");
    if (head is not null && ui is not null && File.ReadAllText(head) == p2cHeadless && File.ReadAllText(ui) == p2cUi)
    {
        p2cPackSources++;
    }
}
bool p2cShellOk = p2cShellOnCreate && p2cShellOnNewWant && p2cShellPreStart && p2cShellPayload && p2cPackSources == 3;
Console.WriteLine($"[verify] p2c shell activation onCreate={p2cShellOnCreate} onNewWant={p2cShellOnNewWant} preStart={p2cShellPreStart} payload={p2cShellPayload} packs={p2cPackSources}/3 assert={p2cShellOk}");
if (!p2cShellOk)
{
    throw new InvalidOperationException("the shell does not carry the P2c activation plumbing (onCreate/onNewWant/notifyActivation across all three packs)");
}

// Host transport: the NAPI method is exported as a plain C symbol, the source keeps the
// bounded pending queue and the export contract lists it (the nm gate has the built half).
string? p2cHostNapiPath = FindHostSource("src/OpenHarmonyHost/host_napi.cpp");
string? p2cExportsPath = FindHostSource("src/OpenHarmonyHost/host-exports.txt");
string p2cHostNapi = p2cHostNapiPath is null ? string.Empty : File.ReadAllText(p2cHostNapiPath);
string p2cExports = p2cExportsPath is null ? string.Empty : File.ReadAllText(p2cExportsPath);
bool p2cHostOk = p2cHostNapi.Contains("napi_value NotifyActivation(") &&
    p2cHostNapi.Contains("extern \"C\" int ohos_host_notify_activation(const char* payload_json)") &&
    p2cHostNapi.Contains("extern \"C\" void ohos_host_register_activation(void* callback)") &&
    p2cHostNapi.Contains("{\"notifyActivation\", nullptr, NotifyActivation") &&
    p2cHostNapi.Contains("kMaxPendingActivations") &&
    p2cExports.Contains("ohos_host_notify_activation") && p2cExports.Contains("ohos_host_register_activation");
Console.WriteLine($"[verify] p2c host transport napi={p2cHostNapi.Contains("notifyActivation")} queue={p2cHostNapi.Contains("kMaxPendingActivations")} exports={p2cExports.Contains("ohos_host_register_activation")} assert={p2cHostOk}");
if (!p2cHostOk)
{
    throw new InvalidOperationException("the native host lacks the P2c activation transport (notifyActivation / register_activation / export list)");
}

// Managed hosting transport: the parsing payload type, the event and the registration path.
string? p2cHostingPath = FindHostSource("src/Microsoft.OpenHarmony.Hosting/OpenHarmonyApp.cs");
string p2cHosting = p2cHostingPath is null ? string.Empty : File.ReadAllText(p2cHostingPath);
bool p2cHostingOk = p2cHosting.Contains("public sealed class OpenHarmonyActivationEventArgs") &&
    p2cHosting.Contains("public static event Action<OpenHarmonyActivationEventArgs>? Activation") &&
    p2cHosting.Contains("RegisterActivationNative(s_activationThunk)") &&
    p2cHosting.Contains("HostJsonContext.Default.ActivationJson") &&
    p2cHosting.Contains("private static void OnActivationNative(IntPtr payloadUtf8)");
Console.WriteLine($"[verify] p2c hosting api args={p2cHosting.Contains("OpenHarmonyActivationEventArgs")} event={p2cHosting.Contains("? Activation")} register={p2cHosting.Contains("RegisterActivationNative(s_activationThunk)")} parse={p2cHosting.Contains("HostJsonContext.Default.ActivationJson")} assert={p2cHostingOk}");
if (!p2cHostingOk)
{
    throw new InvalidOperationException("the hosting bridge lacks the P2c activation event/registration/payload parse");
}

// Managed behavior: parse one payload, drive the registered native entry and assert the event.
var p2cActivations = new List<Microsoft.OpenHarmony.Hosting.OpenHarmonyActivationEventArgs>();
void OnP2cActivation(Microsoft.OpenHarmony.Hosting.OpenHarmonyActivationEventArgs activation) => p2cActivations.Add(activation);
string P2cPayload(long sequence, string uri, string linkHost = "") =>
    System.Text.Json.JsonSerializer.Serialize(new
    {
        uri,
        action = "ohos.want.action.viewData",
        parameters = "{\"k\":\"v\"}",
        linkHosts = linkHost is { Length: > 0 } ? new[] { linkHost } : Array.Empty<string>(),
        sequence,
    });

Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.Activation += OnP2cActivation;
int p2cEventsBeforeParse = p2cActivations.Count;
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.CompleteActivation(P2cPayload(900, "app://p2c/parse", "example.com"));
int p2cMalformedEvents = p2cActivations.Count;
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.CompleteActivation("{not json");
bool p2cParseOk = p2cMalformedEvents == p2cEventsBeforeParse + 1 && p2cActivations.Count == p2cMalformedEvents &&
    p2cActivations[^1].Uri == "app://p2c/parse" && p2cActivations[^1].Action == "ohos.want.action.viewData" &&
    p2cActivations[^1].Parameters == "{\"k\":\"v\"}" && p2cActivations[^1].LinkHosts.Contains("example.com") &&
    p2cActivations[^1].Sequence == 900;
Console.WriteLine($"[verify] p2c activation parse events={p2cActivations.Count} uri='{p2cActivations[^1].Uri}' seq={p2cActivations[^1].Sequence} hosts={p2cActivations[^1].LinkHosts.Length} malformedIgnored={p2cParseOk} assert={p2cParseOk}");
if (!p2cParseOk)
{
    throw new InvalidOperationException("the activation payload parse or the malformed-payload guard is wrong");
}

IntPtr p2cActivationThunk = NativeThunks.Pointer(typeof(Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge), "s_activationThunk");
var p2cNativeActivation = NativeThunks.Invoker<NativeThunks.ActivationCallback>(p2cActivationThunk);
IntPtr p2cThunkPayload = Marshal.StringToCoTaskMemUTF8(P2cPayload(901, "app://p2c/thunk"));
try
{
    p2cNativeActivation(p2cThunkPayload);
}
finally
{
    Marshal.FreeCoTaskMem(p2cThunkPayload);
}
bool p2cThunkOk = p2cActivations.Count == p2cMalformedEvents + 1 && p2cActivations[^1].Uri == "app://p2c/thunk" && p2cActivations[^1].Sequence == 901;
Console.WriteLine($"[verify] p2c activation thunk registered={p2cActivationThunk != IntPtr.Zero} events={p2cActivations.Count} last='{p2cActivations[^1].Uri}' assert={p2cThunkOk}");
if (!p2cThunkOk)
{
    throw new InvalidOperationException("the registered native activation thunk did not reach the Activation event");
}

// Managed dispatch against the harness's NavigationPage: malformed uri, the https allow-list,
// registered routes and the sequence de-duplication, with the status channel as evidence.
Directory.CreateDirectory(Path.Combine(Path.GetTempPath(), "verify-p2c-status"));
string p2cStatusDir = Path.Combine(Path.GetTempPath(), "verify-p2c-status");
var p2cSavedBridgeContext = (Microsoft.OpenHarmony.Hosting.OpenHarmonyAppContext?)bridgeContextField.GetValue(null);
SetBridgeContext(new Microsoft.OpenHarmony.Hosting.OpenHarmonyAppContext { FilesDir = p2cStatusDir });
string p2cStatusPath = Path.Combine(p2cStatusDir, "dotnet-status.txt");
File.Delete(p2cStatusPath);
string P2cStatus() => File.Exists(p2cStatusPath) ? File.ReadAllText(p2cStatusPath) : string.Empty;
async Task<bool> P2cWaitFor(Func<bool> condition, int timeoutMs = 4000)
{
    var p2cWatch = System.Diagnostics.Stopwatch.StartNew();
    while (p2cWatch.ElapsedMilliseconds < timeoutMs)
    {
        if (condition())
        {
            return true;
        }
        await Task.Delay(25);
    }
    return condition();
}

Routing.RegisterRoute("p2c-detail", typeof(RoutedPage));
Routing.RegisterRoute("p2c-other", typeof(RoutedPage));
Routing.RegisterRoute("p2c-remote", typeof(RoutedPage));
Routing.RegisterRoute("p2c-pending", typeof(RoutedPage));
int P2cDepth() => navRoot.Navigation.NavigationStack.Count;
int p2cDepthBefore = P2cDepth();

Microsoft.Maui.Platform.OpenHarmonyAppLinks.Activate("nonsense");
bool p2cMalformedLink = await P2cWaitFor(() => P2cStatus().Contains("deep link ignored")) &&
    P2cDepth() == p2cDepthBefore;

Microsoft.Maui.Platform.OpenHarmonyAppLinks.Activate("https://blocked.example.org/p2c-remote");
bool p2cHttpsRefused = await P2cWaitFor(() => P2cStatus().Contains("not in the app-link allow-list")) &&
    P2cDepth() == p2cDepthBefore;
bool p2cHostsSeeded = Microsoft.Maui.Platform.OpenHarmonyAppLinks.AllowedHttpsHosts.Contains("example.com");
Microsoft.Maui.Platform.OpenHarmonyAppLinks.Activate("https://example.com/p2c-remote");
bool p2cHttpsApplied = await P2cWaitFor(() => P2cDepth() == p2cDepthBefore + 1);
bool p2cLinksOk = p2cMalformedLink && p2cHttpsRefused && p2cHostsSeeded && p2cHttpsApplied;
Console.WriteLine($"[verify] p2c link https malformed={p2cMalformedLink} refused={p2cHttpsRefused} seeded={p2cHostsSeeded} applied={p2cHttpsApplied} depth={P2cDepth()} assert={p2cLinksOk}");
if (!p2cLinksOk)
{
    throw new InvalidOperationException("the P2c app-link scheme/allow-list handling is wrong");
}

Microsoft.Maui.Platform.OpenHarmonyAppLinks.Activate("app://p2c/never-registered");
bool p2cUnknownRoute = await P2cWaitFor(() => P2cStatus().Contains("no registered NavigationPage page for route 'p2c/never-registered'")) &&
    P2cDepth() == p2cDepthBefore + 1;
Console.WriteLine($"[verify] p2c link unknown route logged={p2cUnknownRoute} depth={P2cDepth()} assert={p2cUnknownRoute}");
if (!p2cUnknownRoute)
{
    throw new InvalidOperationException("an unregistered deep-link route was not ignored with a status line");
}

Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.CompleteActivation(P2cPayload(1001, "app://p2c-detail"));
bool p2cFirstApplied = await P2cWaitFor(() => P2cDepth() == p2cDepthBefore + 2);
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.CompleteActivation(P2cPayload(1001, "app://p2c-detail"));
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.CompleteActivation(P2cPayload(1000, "app://p2c-other"));
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.CompleteActivation(P2cPayload(1002, "app://p2c-other"));
bool p2cSecondApplied = await P2cWaitFor(() => P2cDepth() == p2cDepthBefore + 3);
int p2cDepthAfterDedup = P2cDepth();
bool p2cDedupOk = p2cFirstApplied && p2cSecondApplied && p2cDepthAfterDedup == p2cDepthBefore + 3 &&
    P2cStatus().Contains("already seen");
Console.WriteLine($"[verify] p2c link dedup first={p2cFirstApplied} second={p2cSecondApplied} depth={p2cDepthAfterDedup} (expected {p2cDepthBefore + 3}) duplicateLogged={P2cStatus().Contains("already seen")} assert={p2cDedupOk}");
if (!p2cDedupOk)
{
    throw new InvalidOperationException("the deep-link sequence de-duplication/order handling is wrong");
}

// Cold start: a want that arrives while no navigation target exists stays queued and is
// applied when the target comes back (the host-ready retry the app host drives).
var p2cWindow = (Microsoft.Maui.Controls.Window)host.Window!;
Microsoft.Maui.Controls.Page p2cRealPage = p2cWindow.Page;
p2cWindow.Page = new ContentPage { Title = "p2c no target" };
int p2cBeforePending = P2cDepth();
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.CompleteActivation(P2cPayload(2001, "app://p2c-pending"));
bool p2cPendingHeld = await P2cWaitFor(() => P2cStatus().Contains("deep link pending")) && P2cDepth() == p2cBeforePending;
p2cWindow.Page = p2cRealPage;
Microsoft.Maui.Platform.OpenHarmonyAppLinks.OnHostReady();
bool p2cPendingApplied = await P2cWaitFor(() => P2cDepth() == p2cBeforePending + 1);
bool p2cPendingOk = p2cPendingHeld && p2cPendingApplied;
Console.WriteLine($"[verify] p2c cold start pending held={p2cPendingHeld} appliedAfterReady={p2cPendingApplied} depth={P2cDepth()} assert={p2cPendingOk}");
if (!p2cPendingOk)
{
    throw new InvalidOperationException("a cold-start deep link was not held until a navigation target existed");
}

// Shell: the deep link maps to GoToAsync, so the Navigating approval chain can cancel it and
// the canceled request never half-applies; after approval the same route lands.
var p2cShell = new Microsoft.Maui.Controls.Shell();
var p2cShellItem = new Microsoft.Maui.Controls.ShellItem { Route = "p2c" };
var p2cShellSection = new Microsoft.Maui.Controls.ShellSection { Route = "section" };
p2cShellSection.Items.Add(new Microsoft.Maui.Controls.ShellContent
{
    Route = "home",
    ContentTemplate = new DataTemplate(() => new ContentPage { Title = "p2c home", Content = new Label { Text = "p2c home" } }),
});
p2cShellItem.Items.Add(p2cShellSection);
p2cShell.Items.Add(p2cShellItem);
Routing.RegisterRoute("linked", typeof(RoutedPage));
OpenHarmonyHandlerConnector.ConnectTree(p2cShell);
p2cShell.Measure(1080, 1920);
p2cShell.Arrange(new Rect(0, 0, 1080, 1920));
Microsoft.Maui.Controls.Page p2cSavedPage = p2cWindow.Page;
p2cWindow.Page = p2cShell;
bool p2cDenyOnce = true;
void OnP2cShellNavigating(object? sender, Microsoft.Maui.Controls.ShellNavigatingEventArgs args)
{
    if (p2cDenyOnce && args.Target.Location.OriginalString.Contains("linked"))
    {
        args.Cancel();
    }
}
p2cShell.Navigating += OnP2cShellNavigating;
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.CompleteActivation(P2cPayload(3001, "app://p2c/linked?from=deeplink"));
bool p2cCanceled = await P2cWaitFor(() => P2cStatus().Contains("not applied") || P2cStatus().Contains("canceled"));
bool p2cCancelHeld = p2cShell.CurrentPage?.Title != "Routed";
p2cDenyOnce = false;
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.CompleteActivation(P2cPayload(3002, "app://p2c/linked?from=deeplink"));
bool p2cLinked = await P2cWaitFor(() => p2cShell.CurrentPage?.Title == "Routed");
p2cShell.Navigating -= OnP2cShellNavigating;
p2cWindow.Page = p2cSavedPage;
bool p2cShellApprovalOk = p2cCanceled && p2cCancelHeld && p2cLinked;
Console.WriteLine($"[verify] p2c shell approval canceled={p2cCanceled} held={p2cCancelHeld} linked={p2cLinked} current='{p2cShell.CurrentPage?.Title}' assert={p2cShellApprovalOk}");
if (!p2cShellApprovalOk)
{
    throw new InvalidOperationException("the Shell deep-link path did not cooperate with the Navigating approval chain");
}

Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.Activation -= OnP2cActivation;
SetBridgeContext(p2cSavedBridgeContext);
// Remove the temporary status file so the check leaves no residue; the context restore above
// already repoints the status channel.
try
{
    Directory.Delete(p2cStatusDir, true);
}
catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
{
    // Diagnostic leftovers must not fail the suite.
}

// T20: media playback bridge (ArkTS AVPlayer sink + host exports + managed surface). The shell
// half lives in the byte-identical preview templates; the host half is pinned in the native
// sources and the export contract; the managed half is OpenHarmonyMediaPlayer.cs.
string? t20MediaPath = FindHostSource("OpenHarmonyMediaPlayer.cs");
string t20MediaSource = t20MediaPath is null ? string.Empty : File.ReadAllText(t20MediaPath);
string? t20HostPath = FindHostSource("src/OpenHarmonyHost/host_napi.cpp");
string t20Host = t20HostPath is null ? string.Empty : File.ReadAllText(t20HostPath);
string? t20ExportsPath = FindHostSource("src/OpenHarmonyHost/host-exports.txt");
string t20Exports = t20ExportsPath is null ? string.Empty : File.ReadAllText(t20ExportsPath);
string[] t20ShellVersions = { "1.0.0-preview.22", "1.0.0-preview.23", "1.0.0-preview.24" };
bool t20ShellPinsOk = true;
bool t20ShellIdentical = true;
string t20ShellFirst = string.Empty;
foreach (string t20ShellVersion in t20ShellVersions)
{
    string? t20IndexPath = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{t20ShellVersion}/templates/ets/pages/Index.ets");
    string t20Index = t20IndexPath is null ? string.Empty : File.ReadAllText(t20IndexPath);
    if (t20ShellFirst.Length == 0)
    {
        t20ShellFirst = t20Index;
    }
    else if (!string.Equals(t20ShellFirst, t20Index, StringComparison.Ordinal))
    {
        t20ShellIdentical = false;
    }
    t20ShellPinsOk &= t20Index.Contains("import type { media } from '@kit.MediaKit';") &&
        t20Index.Contains("host.registerMediaSink(async (requestId: number, op: number, payload: string): Promise<void> => {") &&
        t20Index.Contains("const kit = await import('@kit.MediaKit');") &&
        t20Index.Contains("const player: media.AVPlayer = await mediaKit.createAVPlayer();") &&
        t20Index.Contains("interface MediaKitNamespace {") &&
        t20Index.Contains("typeof mediaKit.createAVPlayer !== 'function'") &&
        t20Index.Contains("player.url = location;") &&
        t20Index.Contains("player.fdSrc = rawFd;") &&
        t20Index.Contains("player.fdSrc = fileFd;") &&
        t20Index.Contains("await player.prepare();") &&
        t20Index.Contains("await player.play();") &&
        t20Index.Contains("await player.pause();") &&
        t20Index.Contains("await player.stop();") &&
        t20Index.Contains("player.seek(Math.trunc(positionMs));") &&
        t20Index.Contains("await player.release();") &&
        t20Index.Contains("`state\\t${state}\\t${this.mediaReasonName(reason)}`") &&
        t20Index.Contains("`time\\t${Math.max(0, Math.trunc(position))}`") &&
        t20Index.Contains("`duration\\t${Math.max(0, Math.trunc(duration))}`") &&
        t20Index.Contains("host.notifyMediaResult(requestId, code, payload);");
}
bool t20PinsOk = t20ShellPinsOk && t20ShellIdentical &&
    t20MediaSource.Contains("EntryPoint = \"ohos_host_media_request\"") &&
    t20MediaSource.Contains("EntryPoint = \"ohos_host_media_register_result\"") &&
    t20MediaSource.Contains("EntryPoint = \"ohos_host_media_register_event\"") &&
    t20MediaSource.Contains("private const int OpLoad = 0;") &&
    t20MediaSource.Contains("private const int OpStatus = 6;") &&
    t20MediaSource.Contains("OpenHarmonyBridge.WriteStatus(\"[maui] media sink is not available\")") &&
    t20Host.Contains("extern \"C\" int ohos_host_media_request(int request_id, int op, const char* payload)") &&
    t20Host.Contains("napi_value RegisterMediaSink(") &&
    t20Host.Contains("napi_value NotifyMediaResult(") &&
    t20Host.Contains("napi_value NotifyMediaEvent(") &&
    t20Host.Contains("{\"registerMediaSink\"") &&
    t20Host.Contains("HostSink media{\"media\", false};") &&
    t20Exports.Contains("ohos_host_media_register_event") &&
    t20Exports.Contains("ohos_host_media_register_result") &&
    t20Exports.Contains("ohos_host_media_request");
Console.WriteLine($"[verify] t20 media pins slice={t20MediaPath is not null} host={t20HostPath is not null} shell={t20ShellPinsOk} identical={t20ShellIdentical} assert={t20PinsOk}");
if (!t20PinsOk)
{
    throw new InvalidOperationException($"the T20 media bridge source contract drifted: shell={t20ShellPinsOk} identical={t20ShellIdentical} slice='{t20MediaPath ?? "<missing>"}' host='{t20HostPath ?? "<missing>"}'");
}

// t20 media degrade: off-device (no host library) every call answers Unavailable without
// throwing; an invalid source and a negative seek fail before the bridge is touched; the
// static surface keeps the documented initial values.
bool t20DegradeOk = false;
bool t20InvalidSourceOk = false;
string t20DegradeDetail = string.Empty;
try
{
    OpenHarmonyMediaResult t20InvalidSource = await OpenHarmonyMediaPlayer.LoadAsync(OpenHarmonyMediaSource.FromRawFile(""));
    t20InvalidSourceOk = t20InvalidSource.Status == OpenHarmonyMediaStatus.Failed &&
        t20InvalidSource.Message.Contains("the source location is empty or too long");
    OpenHarmonyMediaResult t20Load = await OpenHarmonyMediaPlayer.LoadAsync(OpenHarmonyMediaSource.FromFile("/nonexistent/w9d-probe.wav"));
    OpenHarmonyMediaResult t20Play = await OpenHarmonyMediaPlayer.PlayAsync();
    OpenHarmonyMediaResult t20Pause = await OpenHarmonyMediaPlayer.PauseAsync();
    OpenHarmonyMediaResult t20Stop = await OpenHarmonyMediaPlayer.StopAsync();
    OpenHarmonyMediaResult t20Seek = await OpenHarmonyMediaPlayer.SeekAsync(TimeSpan.FromMilliseconds(100));
    OpenHarmonyMediaResult t20SeekInvalid = await OpenHarmonyMediaPlayer.SeekAsync(TimeSpan.FromSeconds(-1));
    OpenHarmonyMediaResult t20Release = await OpenHarmonyMediaPlayer.ReleaseAsync();
    OpenHarmonyMediaStatusResult t20Status = await OpenHarmonyMediaPlayer.StatusAsync();
    t20DegradeOk = t20InvalidSourceOk &&
        t20Load.Status == OpenHarmonyMediaStatus.Unavailable &&
        t20Play.Status == OpenHarmonyMediaStatus.Unavailable &&
        t20Pause.Status == OpenHarmonyMediaStatus.Unavailable &&
        t20Stop.Status == OpenHarmonyMediaStatus.Unavailable &&
        t20Seek.Status == OpenHarmonyMediaStatus.Unavailable &&
        t20SeekInvalid.Status == OpenHarmonyMediaStatus.Failed &&
        t20Release.Status == OpenHarmonyMediaStatus.Unavailable &&
        t20Status.Status == OpenHarmonyMediaStatus.Unavailable &&
        !OpenHarmonyMediaPlayer.IsSupported &&
        OpenHarmonyMediaPlayer.State == OpenHarmonyMediaPlaybackState.Unknown &&
        OpenHarmonyMediaPlayer.Position == TimeSpan.Zero &&
        OpenHarmonyMediaPlayer.Duration == TimeSpan.Zero;
    t20DegradeDetail = $"load={t20Load.Status} play={t20Play.Status} pause={t20Pause.Status} stop={t20Stop.Status} seek={t20Seek.Status} seekNeg={t20SeekInvalid.Status} release={t20Release.Status} status={t20Status.Status} invalid={t20InvalidSource.Status}";
}
catch (Exception ex)
{
    t20DegradeDetail = $"threw {ex.GetType().Name}: {ex.Message}";
}
Console.WriteLine($"[verify] t20 media degrade supported={OpenHarmonyMediaPlayer.IsSupported} {t20DegradeDetail} assert={t20DegradeOk}");
if (!t20DegradeOk)
{
    throw new InvalidOperationException($"the T20 media bridge did not degrade cleanly off-device: {t20DegradeDetail}");
}

// t20 media events: the native-shaped event parser maps every AVPlayer push onto the managed
// events, mirrors state/position/duration and ignores malformed payloads.
int t20StateEvents = 0;
int t20PositionEvents = 0;
int t20DurationEvents = 0;
int t20ErrorEvents = 0;
OpenHarmonyMediaPlaybackState t20LastState = OpenHarmonyMediaPlaybackState.Unknown;
string t20LastReason = string.Empty;
TimeSpan t20LastPosition = TimeSpan.Zero;
TimeSpan t20LastDuration = TimeSpan.Zero;
string t20LastError = string.Empty;
void t20OnState(object? sender, OpenHarmonyMediaStateChangedEventArgs args)
{
    t20StateEvents++;
    t20LastState = args.State;
    t20LastReason = args.Reason;
}
void t20OnPosition(object? sender, OpenHarmonyMediaPositionChangedEventArgs args)
{
    t20PositionEvents++;
    t20LastPosition = args.Position;
}
void t20OnDuration(object? sender, OpenHarmonyMediaDurationChangedEventArgs args)
{
    t20DurationEvents++;
    t20LastDuration = args.Duration;
}
void t20OnError(object? sender, OpenHarmonyMediaFailedEventArgs args)
{
    t20ErrorEvents++;
    t20LastError = args.Message;
}
OpenHarmonyMediaPlayer.StateChanged += t20OnState;
OpenHarmonyMediaPlayer.PositionChanged += t20OnPosition;
OpenHarmonyMediaPlayer.DurationChanged += t20OnDuration;
OpenHarmonyMediaPlayer.Failed += t20OnError;
OpenHarmonyMediaPlayer.OnEventPayload("state\tprepared\tuser");
OpenHarmonyMediaPlayer.OnEventPayload("time\t1234");
OpenHarmonyMediaPlayer.OnEventPayload("duration\t4321");
OpenHarmonyMediaPlayer.OnEventPayload("state\tbogus");
OpenHarmonyMediaPlayer.OnEventPayload("time\tnope");
OpenHarmonyMediaPlayer.OnEventPayload(null);
OpenHarmonyMediaPlayer.OnEventPayload("error\t5400102\tboom");
OpenHarmonyMediaPlayer.StateChanged -= t20OnState;
OpenHarmonyMediaPlayer.PositionChanged -= t20OnPosition;
OpenHarmonyMediaPlayer.DurationChanged -= t20OnDuration;
OpenHarmonyMediaPlayer.Failed -= t20OnError;
bool t20EventsOk = t20StateEvents == 1 && t20PositionEvents == 1 && t20DurationEvents == 1 && t20ErrorEvents == 1 &&
    t20LastState == OpenHarmonyMediaPlaybackState.Prepared &&
    t20LastReason == "user" &&
    t20LastPosition == TimeSpan.FromMilliseconds(1234) &&
    t20LastDuration == TimeSpan.FromMilliseconds(4321) &&
    t20LastError == "boom" &&
    OpenHarmonyMediaPlayer.State == OpenHarmonyMediaPlaybackState.Error &&
    OpenHarmonyMediaPlayer.Position == TimeSpan.FromMilliseconds(1234) &&
    OpenHarmonyMediaPlayer.Duration == TimeSpan.FromMilliseconds(4321) &&
    OpenHarmonyMediaPlayer.ParseState("playing") == OpenHarmonyMediaPlaybackState.Playing &&
    OpenHarmonyMediaPlayer.ParseState("nonsense") == OpenHarmonyMediaPlaybackState.Unknown;
Console.WriteLine($"[verify] t20 media events states={t20StateEvents} positions={t20PositionEvents} durations={t20DurationEvents} errors={t20ErrorEvents} last='{t20LastState}/{t20LastReason}' assert={t20EventsOk}");
if (!t20EventsOk)
{
    throw new InvalidOperationException("the T20 media event parser drifted");
}

// t20 media status parse: the op 6 status payload ("state\tpositionMs\tdurationMs") mirrors
// into the managed surface; a malformed payload leaves the previous snapshot untouched.
bool t20StatusParseOk = false;
try
{
    OpenHarmonyMediaPlayer.ApplyStatusPayload("playing\t1500\t6500");
    bool t20Applied = OpenHarmonyMediaPlayer.State == OpenHarmonyMediaPlaybackState.Playing &&
        OpenHarmonyMediaPlayer.Position == TimeSpan.FromMilliseconds(1500) &&
        OpenHarmonyMediaPlayer.Duration == TimeSpan.FromMilliseconds(6500);
    OpenHarmonyMediaPlayer.ApplyStatusPayload("garbage");
    OpenHarmonyMediaPlayer.ApplyStatusPayload("playing\tnan\t6500");
    OpenHarmonyMediaPlayer.ApplyStatusPayload("bogus\t10\t20");
    OpenHarmonyMediaPlayer.ApplyStatusPayload(null);
    bool t20Held = OpenHarmonyMediaPlayer.State == OpenHarmonyMediaPlaybackState.Playing &&
        OpenHarmonyMediaPlayer.Position == TimeSpan.FromMilliseconds(1500) &&
        OpenHarmonyMediaPlayer.Duration == TimeSpan.FromMilliseconds(6500);
    OpenHarmonyMediaPlayer.ApplyStatusPayload("released\t0\t0");
    bool t20Second = OpenHarmonyMediaPlayer.State == OpenHarmonyMediaPlaybackState.Released &&
        OpenHarmonyMediaPlayer.Position == TimeSpan.Zero &&
        OpenHarmonyMediaPlayer.Duration == TimeSpan.Zero;
    t20StatusParseOk = t20Applied && t20Held && t20Second;
}
catch (Exception ex)
{
    Console.WriteLine($"[verify] t20 media status parse threw {ex.GetType().Name}: {ex.Message}");
}
Console.WriteLine($"[verify] t20 media status parse state={OpenHarmonyMediaPlayer.State} pos={OpenHarmonyMediaPlayer.Position.TotalMilliseconds} dur={OpenHarmonyMediaPlayer.Duration.TotalMilliseconds} assert={t20StatusParseOk}");
if (!t20StatusParseOk)
{
    throw new InvalidOperationException("the T20 media status parser drifted");
}

// ---- FIX-SLICERACE: handler wiring must be serialized ----------------------------------------
// The device JIT startup crashed with "Handler is already being set elsewhere": the managed app
// runs on the host's launch thread while the ArkTS shell delivers surface/frame callbacks on the
// shell thread, and both paths call OpenHarmonyHandlerConnector.ConnectTree (Run vs
// Arrange). MAUI's Element.SetHandler is not re-entrant, so the race also surfaced as
// "PlatformView cannot be null here" and non-concurrent collection corruption (WX-HOST-PRCTL
// JIT logs). The fix serializes the connector and the app host. These checks reduce the race to
// its primitive: many threads racing ConnectTree over one fresh device-shaped tree (FlyoutPage ->
// TabbedPage -> NavigationPage -> ContentPage) and a host Arrange/Render storm; the pins keep a
// future refactor from dropping the locks.
var sliceRaceTrees = 60;
var sliceRaceThreads = 4;
int sliceRaceErrors = 0;
int sliceRaceUnconnected = 0;
int sliceRaceNodes = 0;
string sliceRaceFirstError = string.Empty;
for (int i = 0; i < sliceRaceTrees; i++)
{
    FlyoutPage sliceRaceRoot = BuildSliceRaceTree();
    sliceRaceNodes = SliceRaceCount(sliceRaceRoot);
    var sliceRaceFailures = new System.Collections.Concurrent.ConcurrentQueue<Exception>();
    var sliceRaceWorkers = new System.Threading.Thread[sliceRaceThreads];
    var sliceRaceGo = new ManualResetEventSlim(false);
    for (int w = 0; w < sliceRaceThreads; w++)
    {
        sliceRaceWorkers[w] = new System.Threading.Thread(() =>
        {
            sliceRaceGo.Wait();
            try
            {
                // Every entry point the device startup uses concurrently: the host connects the
                // whole tree, its handlers' mappers connect flyout/detail, and the tabbed/flyout
                // arrange paths connect the current page.
                for (int k = 0; k < 3; k++)
                {
                    OpenHarmonyHandlerConnector.ConnectTree(sliceRaceRoot);
                    OpenHarmonyHandlerConnector.ConnectTree(sliceRaceRoot.Flyout);
                    OpenHarmonyHandlerConnector.ConnectTree(sliceRaceRoot.Detail);
                    if (sliceRaceRoot.Detail is TabbedPage raceTabbed && raceTabbed.CurrentPage is IElement raceTab)
                    {
                        OpenHarmonyHandlerConnector.ConnectTree(raceTab);
                    }
                }
            }
            catch (Exception ex)
            {
                sliceRaceFailures.Enqueue(ex);
            }
        }) { IsBackground = true };
    }
    foreach (System.Threading.Thread worker in sliceRaceWorkers) worker.Start();
    sliceRaceGo.Set();
    foreach (System.Threading.Thread worker in sliceRaceWorkers) worker.Join();
    foreach (Exception ex in sliceRaceFailures)
    {
        sliceRaceErrors++;
        if (sliceRaceFirstError.Length == 0) sliceRaceFirstError = $"{ex.GetType().Name}: {ex.Message}";
    }
    sliceRaceUnconnected += SliceRaceUnconnected(sliceRaceRoot);
}
bool sliceRaceConnectorOk = sliceRaceErrors == 0 && sliceRaceUnconnected == 0;
Console.WriteLine($"[verify] slicerace connect storm trees={sliceRaceTrees} threads={sliceRaceThreads} nodes={sliceRaceNodes} errors={sliceRaceErrors} unconnected={sliceRaceUnconnected} assert={sliceRaceConnectorOk}");
if (!sliceRaceConnectorOk)
{
    throw new InvalidOperationException($"concurrent ConnectTree failed: {sliceRaceFirstError} (errors={sliceRaceErrors} unconnected={sliceRaceUnconnected})");
}

int sliceRaceHostErrors = 0;
string sliceRaceHostFirstError = string.Empty;
var sliceRaceHostWorkers = new System.Threading.Thread[6];
var sliceRaceHostGo = new ManualResetEventSlim(false);
for (int w = 0; w < sliceRaceHostWorkers.Length; w++)
{
    sliceRaceHostWorkers[w] = new System.Threading.Thread(() =>
    {
        sliceRaceHostGo.Wait();
        try
        {
            for (int k = 0; k < 80; k++)
            {
                host.Arrange(1080, 1920);
                _ = host.Render();
                _ = host.Describe();
            }
        }
        catch (Exception ex)
        {
            Interlocked.Increment(ref sliceRaceHostErrors);
            if (sliceRaceHostFirstError.Length == 0) sliceRaceHostFirstError = $"{ex.GetType().Name}: {ex.Message}";
        }
    }) { IsBackground = true };
}
foreach (System.Threading.Thread worker in sliceRaceHostWorkers) worker.Start();
sliceRaceHostGo.Set();
foreach (System.Threading.Thread worker in sliceRaceHostWorkers) worker.Join();
bool sliceRaceHostOk = sliceRaceHostErrors == 0;
Console.WriteLine($"[verify] slicerace host storm threads={sliceRaceHostWorkers.Length} rounds=80 errors={sliceRaceHostErrors} assert={sliceRaceHostOk}");
if (!sliceRaceHostOk)
{
    throw new InvalidOperationException($"concurrent host Arrange/Render failed: {sliceRaceHostFirstError}");
}

string? sliceRaceConnectorPath = FindHostSource("OpenHarmonyHandlerConnector.cs");
string? sliceRaceHostPath = FindHostSource("OpenHarmonyMauiAppHost.cs");
string sliceRaceConnectorSource = sliceRaceConnectorPath is null ? string.Empty : File.ReadAllText(sliceRaceConnectorPath);
string sliceRaceHostSource = sliceRaceHostPath is null ? string.Empty : File.ReadAllText(sliceRaceHostPath);
bool sliceRaceConnectorPin = sliceRaceConnectorSource.Contains("private static readonly object s_connectSync = new();", StringComparison.Ordinal)
    && sliceRaceConnectorSource.Contains("lock (s_connectSync)", StringComparison.Ordinal);
bool sliceRaceHostPin = sliceRaceHostSource.Contains("private readonly object _sync = new();", StringComparison.Ordinal)
    && sliceRaceHostSource.Contains("private bool _ready;", StringComparison.Ordinal)
    && sliceRaceHostSource.Contains("if (!_ready)", StringComparison.Ordinal)
    && sliceRaceHostSource.Contains("lock (_sync)", StringComparison.Ordinal);
bool sliceRacePinsOk = sliceRaceConnectorPin && sliceRaceHostPin;
Console.WriteLine($"[verify] slicerace pins connector={sliceRaceConnectorPin} host={sliceRaceHostPin} source='OpenHarmonyHandlerConnector.cs' assert={sliceRacePinsOk}");
if (!sliceRacePinsOk)
{
    throw new InvalidOperationException("the FIX-SLICERACE serialization (connector lock / host ready gate) is missing from the slice source");
}

// ---- INTERP-DRAW2: compositor off-surface cull + draw-cost seam -------------------------------
// The off-surface cull skips a node's own drawing when its canvas rectangle lies outside the
// render surface and no canvas shift (view translation/scale/rotation or scroll) can move its
// pixels back in; the subtree is still walked, so a child outside its parent's frame keeps
// painting. The DrawCostTick seam reports the coarse kind of every node that actually draws.
// These checks pin the seam kinds, the cull and the translated-node rescue.
var id2Canvas = new CullProbeCanvas();
var id2SavedFactory = OpenHarmonyWindowRenderer.CanvasFactory;
var id2Root = new AbsoluteLayout();
var id2Near = new Label { Text = "near", FontSize = 10 };
var id2Far = new Label { Text = "far", FontSize = 10 };
AbsoluteLayout.SetLayoutBounds(id2Near, new Rect(0, 0, 100, 20));
AbsoluteLayout.SetLayoutBounds(id2Far, new Rect(0, 3000, 100, 20));
id2Root.Add(id2Near);
id2Root.Add(id2Far);
OpenHarmonyHandlerConnector.ConnectTree(id2Root);
var id2Kinds = new List<int>();
try
{
    OpenHarmonyWindowRenderer.CanvasFactory = () => id2Canvas;
    OpenHarmonyWindowRenderer.DrawCostTick = id2Kinds.Add;
    var id2Renderer = new OpenHarmonyWindowRenderer();
    bool id2Tall = id2Renderer.Render(id2Root, 400, 4000);
    int id2TextTall = id2Kinds.Count(k => k == OpenHarmonyWindowRenderer.DrawKindText);
    int id2ContainersTall = id2Kinds.Count(k => k == OpenHarmonyWindowRenderer.DrawKindContainer);
    bool id2SeamOk = id2Tall && id2Kinds.Count == 3 && id2TextTall == 2 && id2ContainersTall == 1;
    Console.WriteLine($"[verify] drawcost seam kinds={string.Join(',', id2Kinds)} text={id2TextTall} container={id2ContainersTall} assert={id2SeamOk}");
    if (!id2SeamOk)
    {
        throw new InvalidOperationException("the DrawCostTick seam no longer reports one kind per drawing node");
    }

    id2Kinds.Clear();
    _ = id2Renderer.Render(id2Root, 400, 400);
    int id2TextSmall = id2Kinds.Count(k => k == OpenHarmonyWindowRenderer.DrawKindText);
    bool id2CullOk = id2TextSmall == 1;
    Console.WriteLine($"[verify] draw cull surface=400x400 text={id2TextSmall} of 2 assert={id2CullOk}");
    if (!id2CullOk)
    {
        throw new InvalidOperationException("the off-surface draw cull drifted");
    }

    id2Kinds.Clear();
    id2Far.TranslationY = -2950;
    _ = id2Renderer.Render(id2Root, 400, 400);
    int id2TextShifted = id2Kinds.Count(k => k == OpenHarmonyWindowRenderer.DrawKindText);
    bool id2ShiftedOk = id2TextShifted == 2;
    Console.WriteLine($"[verify] draw cull translated text={id2TextShifted} of 2 assert={id2ShiftedOk}");
    if (!id2ShiftedOk)
    {
        throw new InvalidOperationException("the cull skips a node translated back into the surface");
    }
    id2Far.TranslationY = 0;

    // SEC-SCAN-4 boundary pins: the cull must fail closed on the shapes a bypass would use - a
    // zero-size frame is never skipped (a degenerate measure cannot make pixels disappear), a
    // shadow whose extent reaches the surface rescues an off-surface owner (the margin covers
    // radius + offset), and an off-surface Image keeps drawing so its progressive decode stays
    // driven. All three would regress silently into missing pixels without these.
    var id2EdgeRoot = new AbsoluteLayout();
    var id2Zero = new Label { Text = "zero", FontSize = 10 };
    var id2Shadowed = new Label { Text = "shadow", FontSize = 10, Shadow = new Shadow { Radius = 100, Opacity = 1 } };
    var id2Image = new Microsoft.Maui.Controls.Image { Source = ImageSource.FromFile(progressiveImagePath) };
    AbsoluteLayout.SetLayoutBounds(id2Zero, new Rect(0, 9000, 0, 0));
    AbsoluteLayout.SetLayoutBounds(id2Shadowed, new Rect(0, 430, 100, 20));
    AbsoluteLayout.SetLayoutBounds(id2Image, new Rect(0, 9000, 20, 20));
    id2EdgeRoot.Add(id2Zero);
    id2EdgeRoot.Add(id2Shadowed);
    id2EdgeRoot.Add(id2Image);
    OpenHarmonyHandlerConnector.ConnectTree(id2EdgeRoot);
    id2Kinds.Clear();
    _ = id2Renderer.Render(id2EdgeRoot, 400, 400);
    int id2EdgeText = id2Kinds.Count(k => k == OpenHarmonyWindowRenderer.DrawKindText);
    bool id2EdgeImage = id2Kinds.Contains(OpenHarmonyWindowRenderer.DrawKindImage);
    bool id2EdgeOk = id2EdgeText == 2 && id2EdgeImage;
    Console.WriteLine($"[verify] draw cull edge zeroAndShadowText={id2EdgeText} image={id2EdgeImage} kinds=[{string.Join(',', id2Kinds)}] assert={id2EdgeOk}");
    if (!id2EdgeOk)
    {
        throw new InvalidOperationException("the off-surface cull skipped a zero-size frame, a shadow that reaches the surface, or an image");
    }
}
finally
{
    OpenHarmonyWindowRenderer.DrawCostTick = null;
    OpenHarmonyWindowRenderer.CanvasFactory = id2SavedFactory;
}

// A0 multi-window form adaptation: the app host must re-arrange on a live surface resize
// (Changed), not only on the first Created publish, and must keep the last frame for a
// Destroyed/0x0 report. The gate predicate is checked directly, then a Changed replay drives
// the real bridge -> host handler and the window frame must follow the new size.
Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceInfo resizeCreatedSurface =
    new(IntPtr.Zero, 1080, 1920, Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Created);
Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceInfo resizeChangedSurface =
    new(IntPtr.Zero, 800, 1200, Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Changed);
Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceInfo resizeDestroyedSurface =
    new(IntPtr.Zero, 0, 0, Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Destroyed);
Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceInfo resizeZeroChangedSurface =
    new(IntPtr.Zero, 0, 0, Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Changed);
bool resizeGateCreated = OpenHarmonyMauiAppHost.CanArrangeSurface(resizeCreatedSurface);
bool resizeGateChanged = OpenHarmonyMauiAppHost.CanArrangeSurface(resizeChangedSurface);
bool resizeGateDestroyed = OpenHarmonyMauiAppHost.CanArrangeSurface(resizeDestroyedSurface);
bool resizeGateZero = OpenHarmonyMauiAppHost.CanArrangeSurface(resizeZeroChangedSurface);
bool resizeGateOk = resizeGateCreated && resizeGateChanged && !resizeGateDestroyed && !resizeGateZero;
Console.WriteLine($"[verify] surface resize gate created={resizeGateCreated} changed={resizeGateChanged} destroyed={resizeGateDestroyed} zero={resizeGateZero} assert={resizeGateOk}");
if (!resizeGateOk)
{
    throw new InvalidOperationException("the surface arrange gate no longer accepts Created/Changed and rejects Destroyed/0x0");
}
FieldInfo resizeSurfaceField = typeof(Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge)
    .GetField("s_surfaceHandlers", BindingFlags.NonPublic | BindingFlags.Static)
    ?? throw new InvalidOperationException("OpenHarmonyBridge.s_surfaceHandlers was not found; the surface resize drill replays SurfaceChanged");
void ReplayResizeSurface(Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceInfo surface)
    => ((Action<Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceInfo>?)resizeSurfaceField.GetValue(null))?.Invoke(surface);
Microsoft.Maui.Controls.Window resizeWindow = (Microsoft.Maui.Controls.Window)window;
ReplayResizeSurface(resizeChangedSurface);
bool resizeArranged = resizeWindow.Width == 800 && resizeWindow.Height == 1200;
ReplayResizeSurface(resizeDestroyedSurface);
bool resizeDestroyedKeepsFrame = resizeWindow.Width == 800 && resizeWindow.Height == 1200;
bool resizeReplayOk = resizeArranged && resizeDestroyedKeepsFrame;
Console.WriteLine($"[verify] surface resize changed frame={resizeWindow.Width}x{resizeWindow.Height} destroyedKeeps={resizeDestroyedKeepsFrame} assert={resizeReplayOk}");
if (!resizeReplayOk)
{
    throw new InvalidOperationException("a Changed surface did not re-arrange the window frame, or Destroyed moved it");
}
host.Arrange(1080, 1920);

// MULTIWINDOW-M: the in-app subwindow contract. The slice's OpenHarmonySubWindow is a
// command/event state machine over the native bridge (managed -> shell commands, shell ->
// managed lifecycle/geometry/touch reports); the shell side is pinned by source. The device
// run covers create/move/resize/close against the real ArkTS Window API.
var subWindowCommands = new List<(int Op, string Payload)>();
OpenHarmonySubWindow.CommandSender = (op, payload) =>
{
    subWindowCommands.Add((op, payload));
    return true;
};
bool subWindowCreateSent = OpenHarmonySubWindow.Create("maui-demo", 120, 160, 720, 480, "child");
bool subWindowMoveSent = OpenHarmonySubWindow.Move(420, 360);
bool subWindowResizeSent = OpenHarmonySubWindow.Resize(900, 600);
bool subWindowShowSent = OpenHarmonySubWindow.Show();
bool subWindowCloseSent = OpenHarmonySubWindow.Close();
bool subWindowCommandShapeOk = subWindowCommands.Count == 5
    && subWindowCommands[0].Op == OpenHarmonySubWindow.CreateCommand
    && subWindowCommands[1].Op == OpenHarmonySubWindow.MoveCommand
    && subWindowCommands[2].Op == OpenHarmonySubWindow.ResizeCommand
    && subWindowCommands[3].Op == OpenHarmonySubWindow.ShowCommand
    && subWindowCommands[4].Op == OpenHarmonySubWindow.CloseCommand;
bool subWindowPayloadOk = false;
if (subWindowCommandShapeOk)
{
    using JsonDocument createPayload = JsonDocument.Parse(subWindowCommands[0].Payload);
    using JsonDocument movePayload = JsonDocument.Parse(subWindowCommands[1].Payload);
    using JsonDocument resizePayload = JsonDocument.Parse(subWindowCommands[2].Payload);
    subWindowPayloadOk =
        createPayload.RootElement.GetProperty("name").GetString() == "maui-demo"
        && createPayload.RootElement.GetProperty("title").GetString() == "child"
        && createPayload.RootElement.GetProperty("x").GetInt32() == 120
        && createPayload.RootElement.GetProperty("y").GetInt32() == 160
        && createPayload.RootElement.GetProperty("w").GetInt32() == 720
        && createPayload.RootElement.GetProperty("h").GetInt32() == 480
        && movePayload.RootElement.GetProperty("x").GetInt32() == 420
        && movePayload.RootElement.GetProperty("y").GetInt32() == 360
        && resizePayload.RootElement.GetProperty("w").GetInt32() == 900
        && resizePayload.RootElement.GetProperty("h").GetInt32() == 600;
}
bool subWindowCommandOk = subWindowCreateSent && subWindowMoveSent && subWindowResizeSent
    && subWindowShowSent && subWindowCloseSent && subWindowCommandShapeOk && subWindowPayloadOk;
Console.WriteLine($"[verify] subwindow commands sent={subWindowCommands.Count} ops=[{string.Join(',', subWindowCommands.Select(c => c.Op))}] payload={subWindowPayloadOk} assert={subWindowCommandOk}");
if (!subWindowCommandOk)
{
    throw new InvalidOperationException("the subwindow command set (create/move/resize/show/close) or its JSON payload drifted");
}

var subWindowEvents = new List<OpenHarmonySubWindowEventArgs>();
EventHandler<OpenHarmonySubWindowEventArgs> subWindowChanged = (_, e) => subWindowEvents.Add(e);
OpenHarmonySubWindow.Changed += subWindowChanged;
try
{
    OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Created, "{\"id\":42,\"x\":120,\"y\":160,\"w\":720,\"h\":480}");
    bool subWindowCreatedOk = OpenHarmonySubWindow.IsOpen && OpenHarmonySubWindow.IsVisible
        && OpenHarmonySubWindow.WindowId == 42 && OpenHarmonySubWindow.Bounds.X == 120
        && OpenHarmonySubWindow.Bounds.Width == 720;
    OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.PageReady, "{\"id\":42}");
    bool subWindowReadyOk = OpenHarmonySubWindow.IsContentReady;
    OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Moved, "{\"x\":420,\"y\":360}");
    OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Resized, "{\"w\":900,\"h\":600}");
    bool subWindowGeometryOk = OpenHarmonySubWindow.Bounds.X == 420 && OpenHarmonySubWindow.Bounds.Y == 360
        && OpenHarmonySubWindow.Bounds.Width == 900 && OpenHarmonySubWindow.Bounds.Height == 600;
    OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Suspended, "{}");
    bool subWindowSuspendedOk = OpenHarmonySubWindow.IsSuspended && !OpenHarmonySubWindow.IsVisible;
    OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Resumed, "{}");
    bool subWindowResumedOk = !OpenHarmonySubWindow.IsSuspended && OpenHarmonySubWindow.IsVisible;
    OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Closed, "{}");
    bool subWindowClosedOk = !OpenHarmonySubWindow.IsOpen && OpenHarmonySubWindow.WindowId == 0
        && !OpenHarmonySubWindow.IsContentReady;
    bool subWindowStateOk = subWindowCreatedOk && subWindowReadyOk && subWindowGeometryOk
        && subWindowSuspendedOk && subWindowResumedOk && subWindowClosedOk
        && subWindowEvents.Count == 7
        && subWindowEvents[0].Kind == OpenHarmonySubWindowEventKind.Created
        && subWindowEvents[4].Kind == OpenHarmonySubWindowEventKind.Suspended
        && subWindowEvents[6].Kind == OpenHarmonySubWindowEventKind.Closed;
    Console.WriteLine($"[verify] subwindow state created={subWindowCreatedOk} ready={subWindowReadyOk} geometry={subWindowGeometryOk} suspended={subWindowSuspendedOk} resumed={subWindowResumedOk} closed={subWindowClosedOk} events={subWindowEvents.Count} assert={subWindowStateOk}");
    if (!subWindowStateOk)
    {
        throw new InvalidOperationException("the subwindow lifecycle state machine (created/page-ready/moved/resized/suspended/resumed/closed) drifted");
    }

    OpenHarmonySubWindowTouchEventArgs? subWindowTouch = null;
    EventHandler<OpenHarmonySubWindowTouchEventArgs> subWindowTouched = (_, e) => subWindowTouch = e;
    OpenHarmonySubWindow.Touched += subWindowTouched;
    try
    {
        OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Touch, "{\"action\":0,\"x\":12.5,\"y\":24.5,\"count\":2}");
    }
    finally
    {
        OpenHarmonySubWindow.Touched -= subWindowTouched;
    }
    bool subWindowTouchOk = subWindowTouch is not null && subWindowTouch.Action == 0
        && Math.Abs(subWindowTouch.X - 12.5f) < 0.01f && Math.Abs(subWindowTouch.Y - 24.5f) < 0.01f
        && subWindowTouch.PointerCount == 2
        && subWindowEvents[^1].Kind == OpenHarmonySubWindowEventKind.Touch;
    Console.WriteLine($"[verify] subwindow touch action={subWindowTouch?.Action} x={subWindowTouch?.X} y={subWindowTouch?.Y} pointers={subWindowTouch?.PointerCount} assert={subWindowTouchOk}");
    if (!subWindowTouchOk)
    {
        throw new InvalidOperationException("a subwindow touch event did not reach the managed Touched handler with its coordinates");
    }

    int subWindowEventsBeforeMalformed = subWindowEvents.Count;
    OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Moved, "{not-json");
    bool subWindowMalformedOk = subWindowEvents.Count == subWindowEventsBeforeMalformed + 1
        && subWindowEvents[^1].Kind == OpenHarmonySubWindowEventKind.Failed
        && subWindowEvents[^1].Code == -1;
    OpenHarmonySubWindow.HandleNativeEvent(42, "{}");
    bool subWindowUnknownOk = subWindowEvents.Count == subWindowEventsBeforeMalformed + 1;
    bool subWindowRobustnessOk = subWindowMalformedOk && subWindowUnknownOk;
    Console.WriteLine($"[verify] subwindow malformed={subWindowMalformedOk} unknownIgnored={subWindowUnknownOk} assert={subWindowRobustnessOk}");
    if (!subWindowRobustnessOk)
    {
        throw new InvalidOperationException("a malformed subwindow payload did not become Failed, or an unknown event kind moved the state");
    }
}
finally
{
    OpenHarmonySubWindow.Changed -= subWindowChanged;
}

OpenHarmonySubWindow.CommandSender = null;
bool subWindowNativeCreate = OpenHarmonySubWindow.Create("off-device", 0, 0, 320, 240);
bool subWindowUnsupportedOk = !subWindowNativeCreate && !OpenHarmonySubWindow.IsSupported;
Console.WriteLine($"[verify] subwindow unsupported create={subWindowNativeCreate} supported={OpenHarmonySubWindow.IsSupported} assert={subWindowUnsupportedOk}");
if (!subWindowUnsupportedOk)
{
    throw new InvalidOperationException("the subwindow API did not degrade to false without libopenharmonyhost.so");
}

// MULTIWINDOW-M shell/host source contract: the four preview packs' Index.ets and SubWindow.ets
// must stay byte-identical, the main page must wire the sink and drive
// createSubWindowWithOptions/loadContentByName, the named-route page must keep the window-id
// drag guard and report touches, and the native host must export the command/listener pair.
bool subWindowShellPinsOk = true;
bool subWindowShellIdentical = true;
string subWindowShellFirst = string.Empty;
foreach (string subWindowShellVersion in new[] { "1.0.0-preview.22", "1.0.0-preview.23", "1.0.0-preview.24", "1.0.0-preview.28" })
{
    string? subWindowIndexPath = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{subWindowShellVersion}/templates/ets/pages/Index.ets");
    string? subWindowPagePath = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{subWindowShellVersion}/templates/ets/pages/SubWindow.ets");
    string subWindowIndex = subWindowIndexPath is null ? string.Empty : File.ReadAllText(subWindowIndexPath);
    string subWindowPage = subWindowPagePath is null ? string.Empty : File.ReadAllText(subWindowPagePath);
    string subWindowPair = subWindowIndex + "\n" + subWindowPage;
    if (subWindowShellFirst.Length == 0)
    {
        subWindowShellFirst = subWindowPair;
    }
    else if (!string.Equals(subWindowShellFirst, subWindowPair, StringComparison.Ordinal))
    {
        subWindowShellIdentical = false;
    }
    subWindowShellPinsOk &= subWindowIndex.Contains("registerSubWindowSink") &&
        subWindowIndex.Contains("createSubWindowWithOptions(childName, options)") &&
        subWindowIndex.Contains("const childName: string = this.subWindowChildName(surfaceId, generation);") &&
        subWindowIndex.Contains("loadContentByName(SUB_WINDOW_ROUTE, storage)") &&
        subWindowIndex.Contains("handleSubWindowCommand(op, payload)") &&
        subWindowIndex.Contains("suspended ? SUB_EVENT_SUSPENDED : SUB_EVENT_RESUMED") &&
        subWindowIndex.Contains("SUB_CMD_CLOSE") &&
        subWindowPage.Contains("routeName: 'ohos_dotnet_subwindow'") &&
        subWindowPage.Contains("dragEnabled") &&
        subWindowPage.Contains("PanGesture()") &&
        subWindowPage.Contains("notifyHost(SUB_EVENT_TOUCH, payload)") &&
        subWindowPage.Contains("SUB_EVENT_PAGE_READY");
}
string subWindowHostSource = FindHostSource("src/OpenHarmonyHost/host_napi.cpp") is { } subWindowHostPath
    ? File.ReadAllText(subWindowHostPath) : string.Empty;
string subWindowExportsSource = FindHostSource("src/OpenHarmonyHost/host-exports.txt") is { } subWindowExportsPath
    ? File.ReadAllText(subWindowExportsPath) : string.Empty;
string subWindowSliceSource = FindHostSource("OpenHarmonySubWindow.cs") is { } subWindowSlicePath
    ? File.ReadAllText(subWindowSlicePath) : string.Empty;
bool subWindowSourceOk = subWindowShellPinsOk && subWindowShellIdentical &&
    subWindowHostSource.Contains("ohos_host_sub_window_command") &&
    subWindowHostSource.Contains("registerSubWindowSink") &&
    subWindowHostSource.Contains("ohos_host_sub_window_event_listener") &&
    subWindowHostSource.Contains("notifySubWindowEvent") &&
    subWindowExportsSource.Contains("ohos_host_sub_window_command") &&
    subWindowExportsSource.Contains("ohos_host_sub_window_event_listener") &&
    subWindowSliceSource.Contains("EntryPoint = \"ohos_host_sub_window_command\"") &&
    subWindowSliceSource.Contains("EntryPoint = \"ohos_host_sub_window_event_listener\"");
Console.WriteLine($"[verify] subwindow source shellPins={subWindowShellPinsOk} identical={subWindowShellIdentical} host={subWindowHostSource.Length > 0} slice={subWindowSliceSource.Length > 0} assert={subWindowSourceOk}");
if (!subWindowSourceOk)
{
    throw new InvalidOperationException("the subwindow shell/host/slice source contract drifted (sink wiring, named route, export pair or pack identity)");
}

// MULTIWINDOW-L M2 (M2-01 + M2-ow): dual-window headless pin. A second MauiApp (its own
// application and host, so the suite's primary window above stays untouched) drives TWO
// managed windows through the hosting bridge's window-id tagged channel: the tagged thunks
// (the exact [UnmanagedCallersOnly] pointers the native host calls) raise
// OpenHarmonyBridge.WindowSurfaceChanged / WindowTouch / WindowFrame, this harness forwards
// them by id into the slice's RouteSurface/RouteTouch/RouteFrame adapters (the managed side of
// the M2-ow bridge), and each window's renderer draws through its own CanvasFactory canvas.
// The 20 scratch assertions from the mw-l/m2 headless harness are pinned here, plus the two
// bridge-contract checks (exact ids on every channel, late-subscriber replay).
List<M2RecordingCanvas> m2Canvases = new();
var m2SavedCanvasFactory = OpenHarmonyWindowRenderer.CanvasFactory;
OpenHarmonyWindowRenderer.CanvasFactory = () =>
{
    var m2Canvas = new M2RecordingCanvas();
    m2Canvases.Add(m2Canvas);
    return m2Canvas;
};
int m2Failures = 0;
void M2Check(string name, bool ok)
{
    Console.WriteLine($"[verify] m2 {name} assert={ok}");
    if (!ok)
    {
        m2Failures++;
    }
}
var m2Builder = MauiApp.CreateBuilder();
m2Builder.UseOpenHarmony();
m2Builder.UseMauiApp<M2PerWindowApp>();
var m2MauiApp = m2Builder.Build();
var m2Application = (Microsoft.Maui.Controls.Application)m2MauiApp.Services.GetRequiredService<IApplication>();
var m2Host = m2MauiApp.Services.GetRequiredService<OpenHarmonyMauiAppHost>();
List<string> m2BridgeIds = new();
bool m2LastFrameRouted = false;
// MULTIWINDOW-L M3: the slice's app host now consumes the tagged channel itself (production
// wiring, pinned by the m3 checks below). These observers only record what the bridge delivered
// (and freeze the post-production state), so a routing regression fails the checks instead of
// being masked by test-side forwarding.
Action<string, Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceInfo> m2OnWindowSurface = (id, info) =>
{
    m2BridgeIds.Add("surface:" + id);
};
Action<string, Microsoft.OpenHarmony.Hosting.OpenHarmonyTouchEventArgs> m2OnWindowTouch = (id, args) =>
{
    m2BridgeIds.Add("touch:" + id);
};
Action<string, Microsoft.OpenHarmony.Hosting.OpenHarmonyFrameEventArgs> m2OnWindowFrame = (id, args) =>
{
    m2BridgeIds.Add("frame:" + id);
    m2LastFrameRouted = m2Host.FindSecondaryWindow(id) is not null;
};
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.WindowSurfaceChanged += m2OnWindowSurface;
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.WindowTouch += m2OnWindowTouch;
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.WindowFrame += m2OnWindowFrame;
// The window-id tagged native entries, driven through the same function pointers the host
// calls; an empty id must be dropped by the bridge and an id must arrive verbatim.
var m2SurfaceThunk = NativeThunks.Invoker<NativeThunks.WindowSurfaceCallback>(
    NativeThunks.Pointer(typeof(Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge), "s_windowSurfaceThunk"));
var m2TouchThunk = NativeThunks.Invoker<NativeThunks.WindowTouchCallback>(
    NativeThunks.Pointer(typeof(Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge), "s_windowTouchThunk"));
var m2FrameThunk = NativeThunks.Invoker<NativeThunks.WindowFrameCallback>(
    NativeThunks.Pointer(typeof(Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge), "s_windowFrameThunk"));
void M2Surface(string id, Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState state, int width, int height)
{
    IntPtr m2IdUtf8 = Marshal.StringToCoTaskMemUTF8(id);
    try
    {
        m2SurfaceThunk(m2IdUtf8, (IntPtr)0x2000, width, height, (int)state);
    }
    finally
    {
        Marshal.FreeCoTaskMem(m2IdUtf8);
    }
}
void M2Touch(string id, Microsoft.OpenHarmony.Hosting.OpenHarmonyTouchAction action, float x, float y)
{
    IntPtr m2IdUtf8 = Marshal.StringToCoTaskMemUTF8(id);
    try
    {
        m2TouchThunk(m2IdUtf8, (int)action, IntPtr.Zero, 0, 1, x, y);
    }
    finally
    {
        Marshal.FreeCoTaskMem(m2IdUtf8);
    }
}
void M2FrameEvent(string id)
{
    IntPtr m2IdUtf8 = Marshal.StringToCoTaskMemUTF8(id);
    try
    {
        m2FrameThunk(m2IdUtf8, 100, 116);
    }
    finally
    {
        Marshal.FreeCoTaskMem(m2IdUtf8);
    }
}
int m2EmptyIdEvents = 0;
Action<string, Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceInfo> m2EmptyIdProbe = (id, info) => m2EmptyIdEvents++;
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.WindowSurfaceChanged += m2EmptyIdProbe;
IntPtr m2EmptyIdUtf8 = Marshal.StringToCoTaskMemUTF8(string.Empty);
try
{
    m2SurfaceThunk(m2EmptyIdUtf8, IntPtr.Zero, 1, 1, (int)Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Created);
}
finally
{
    Marshal.FreeCoTaskMem(m2EmptyIdUtf8);
}
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.WindowSurfaceChanged -= m2EmptyIdProbe;

// --- primary window (zero-change path) -------------------------------------------------------
m2Host.Run(m2Application);
var m2Handler = (OpenHarmonyApplicationHandler)m2Application.Handler!;
IWindow m2MainWindow = m2Host.Window!;
M2Check("primary adopted", m2MainWindow is not null && m2Host.SecondaryWindows.Count == 0);

m2Host.Arrange(1080, 1920);
bool m2PrimaryFrame = m2Host.Render();
M2Check("primary frame", m2PrimaryFrame && m2Canvases.Count == 1 && m2Canvases[0].Texts.Contains("main-label"));
M2Check("primary size", m2MainWindow.Width == 1080 && m2MainWindow.Height == 1920);

// --- single-surface degrade: OpenWindow with no second surface is declined once --------------
var m2Declined = new M2Content("declined-label", "declined-button");
m2Application.OpenWindow(new Window(m2Declined.Page));
M2Check("decline result", m2Handler.LastOpenWindowResult == OpenHarmonyOpenWindowResult.CurrentWindowKept);
M2Check("decline keeps windows", m2Application.Windows.Count == 1 && m2Host.PendingSurfaceCount == 0);

// --- secondary surface before its window: recorded, then bound at OpenWindow -----------------
M2Surface("sub-1", Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Created, 640, 480);
M2Check("pending recorded", m2Host.PendingSurfaceCount == 1);

var m2SubContent = new M2Content("sub-label", "sub-button");
var m2SubWindow = new Window(m2SubContent.Page);
m2Application.OpenWindow(m2SubWindow);
OpenHarmonyWindowHost? m2SubHost = m2Host.FindSecondaryWindow("sub-1");
M2Check("secondary opened", m2Handler.LastOpenWindowResult == OpenHarmonyOpenWindowResult.OpenedWindow);
M2Check("secondary windows", m2Application.Windows.Count == 2 && m2Host.SecondaryWindows.Count == 1 && m2Host.PendingSurfaceCount == 0);
M2Check("secondary session", m2SubHost is not null && ReferenceEquals(m2SubHost!.Window, m2SubWindow));
M2Check("secondary size", m2SubWindow.Width == 640 && m2SubWindow.Height == 480);

M2FrameEvent("sub-1");
M2Check("secondary frame", m2LastFrameRouted && m2SubHost!.FrameTicks == 1 && m2Canvases.Count == 2 &&
    m2Canvases[1].Texts.Contains("sub-label") && !m2Canvases[1].Texts.Contains("main-label"));
M2Check("secondary frame isolated", m2Canvases[0].Texts.Contains("main-label") && !m2Canvases[0].Texts.Contains("sub-label"));

// --- independent resize: the secondary surface change must not touch the primary -------------
M2Surface("sub-1", Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Changed, 800, 600);
M2Check("secondary resized", m2SubWindow.Width == 800 && m2SubWindow.Height == 600);
M2Check("primary untouched", m2MainWindow.Width == 1080 && m2MainWindow.Height == 1920 && ReferenceEquals(m2Host.Window, m2MainWindow));

// --- independent input: a tap routed by window id lands in that window only ------------------
m2SubContent.Page.Measure(800, 600);
m2SubContent.Page.Arrange(new Rect(0, 0, 800, 600));
float m2SubX = (float)(m2SubContent.Button.Frame.X + m2SubContent.Button.Frame.Width / 2);
float m2SubY = (float)(m2SubContent.Button.Frame.Y + m2SubContent.Button.Frame.Height / 2);
M2Touch("sub-1", Microsoft.OpenHarmony.Hosting.OpenHarmonyTouchAction.Down, m2SubX, m2SubY);
M2Touch("sub-1", Microsoft.OpenHarmony.Hosting.OpenHarmonyTouchAction.Up, m2SubX, m2SubY);
M2Check("secondary input", m2SubContent.Clicks == 1 && ((M2PerWindowApp)m2Application).Main.Clicks == 0);

// --- independent destroy: closing the secondary window drops only its session ----------------
m2Application.CloseWindow(m2SubWindow);
M2Check("secondary closed", m2Host.FindSecondaryWindow("sub-1") is null && m2Host.SecondaryWindows.Count == 0 && m2Application.Windows.Count == 1);
M2Check("primary survives close", ReferenceEquals(m2Host.Window, m2MainWindow) && m2Host.Render());
M2FrameEvent("sub-1");
M2Check("closed routed away", !m2LastFrameRouted);
M2Surface("sub-1", Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Destroyed, 800, 600);
M2Check("closed surface dropped", m2Host.PendingSurfaceCount == 0);

// --- rebuild: a new secondary surface + window works after a close ---------------------------
M2Surface("sub-2", Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Created, 720, 500);
var m2RebuiltContent = new M2Content("rebuilt-label", "rebuilt-button");
var m2RebuiltWindow = new Window(m2RebuiltContent.Page);
m2Application.OpenWindow(m2RebuiltWindow);
M2FrameEvent("sub-2");
bool m2Rebuilt = m2Handler.LastOpenWindowResult == OpenHarmonyOpenWindowResult.OpenedWindow
    && m2Host.FindSecondaryWindow("sub-2") is { Window: not null }
    && m2LastFrameRouted;
M2Check("secondary rebuilt", m2Rebuilt && m2Canvases[^1].Texts.Contains("rebuilt-label"));

// --- bridge contract: every tagged event carried its window id, and the hosting bridge's
// per-window surface map replays the last report of every window to a late subscriber -------
bool m2IdsOk = m2BridgeIds.Contains("surface:sub-1") && m2BridgeIds.Contains("touch:sub-1")
    && m2BridgeIds.Contains("frame:sub-1") && m2BridgeIds.Contains("surface:sub-2")
    && m2BridgeIds.Contains("frame:sub-2") && m2EmptyIdEvents == 0
    && m2BridgeIds.TrueForAll(id => id.EndsWith(":sub-1") || id.EndsWith(":sub-2"));
M2Check("bridge ids", m2IdsOk);

List<string> m2Replayed = new();
Action<string, Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceInfo> m2LateSubscriber =
    (id, info) => m2Replayed.Add($"{id}:{info.State}:{info.Width}x{info.Height}");
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.WindowSurfaceChanged += m2LateSubscriber;
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.WindowSurfaceChanged -= m2LateSubscriber;
bool m2ReplayOk = m2Replayed.Contains("sub-1:Destroyed:800x600") && m2Replayed.Contains("sub-2:Created:720x500");
M2Check("bridge replay", m2ReplayOk);

// ---------------------------------------------------------------------------------------------
// MULTIWINDOW-L M3: production tagged-event consumption, deferred OpenWindow -> shell subwindow
// XComponent, per-window draw target and close/reopen. The slice's app host subscribes to the
// tagged channel in its constructor; no test-side forwarding happens here any more. Red controls:
// removing the constructor subscription / the deferred branch / the awaiting bind / the per-window
// BeginWindow makes the matching check fail (the last by the compiled hosting seam).
int m3Failures = 0;
void M3Check(string name, bool ok)
{
    Console.WriteLine($"[verify] m3 {name} assert={ok}");
    if (!ok)
    {
        m3Failures++;
    }
}

// Start clean: close the M2 sub-2 session so the lowest-free allocation hands out sub-1 again.
if (m2Host.FindSecondaryWindow("sub-2") is not null)
{
    m2Application.CloseWindow(m2RebuiltWindow);
}
M3Check("start cleared", m2Host.SecondaryWindows.Count == 0 && m2Host.AwaitingWindowCount == 0
    && m2Application.Windows.Count == 1);

List<string> m3Requests = new();
m2Host.SubWindowSurfaceRequester = id =>
{
    m3Requests.Add(id);
    return true;
};

// Deferred OpenWindow: no surface is reported yet, so the host asks the shell for sub-1 and parks
// the realized window instead of declining.
M2Content m3Content = new("m3-label", "m3-button");
Window m3Window = new(m3Content.Page);
m2Application.OpenWindow(m3Window);
M3Check("deferred request", m2Handler.LastOpenWindowResult == OpenHarmonyOpenWindowResult.OpenedWindow
    && m3Requests.Count == 1 && m3Requests[0] == "sub-1"
    && m2Host.AwaitingWindowCount == 1 && m2Host.FindSecondaryWindow("sub-1") is null
    && m2Application.Windows.Count == 2);

// The shell answers with the XComponent surface; RouteSurface (reached by the production
// subscription through the tagged thunk) binds the parked window and draws its first frame.
int m3CanvasBase = m2Canvases.Count;
M2Surface("sub-1", Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Created, 700, 500);
OpenHarmonyWindowHost? m3SubHost = m2Host.FindSecondaryWindow("sub-1");
M3Check("deferred bind", m3SubHost is not null && ReferenceEquals(m3SubHost!.Window, m3Window)
    && m2Host.AwaitingWindowCount == 0 && m3Window.Width == 700 && m3Window.Height == 500);
M3Check("deferred first frame", m2Canvases.Count == m3CanvasBase + 1
    && m2Canvases[^1].Texts.Contains("m3-label") && !m2Canvases[^1].Texts.Contains("main-label"));
M3Check("primary untouched", m2MainWindow.Width == 1080 && m2MainWindow.Height == 1920
    && ((M2PerWindowApp)m2Application).Main.Clicks == 0 && ReferenceEquals(m2Host.Window, m2MainWindow));

m3Content.Page.Measure(700, 500);
m3Content.Page.Arrange(new Rect(0, 0, 700, 500));
float m3X = (float)(m3Content.Button.Frame.X + m3Content.Button.Frame.Width / 2);
float m3Y = (float)(m3Content.Button.Frame.Y + m3Content.Button.Frame.Height / 2);
M2Touch("sub-1", Microsoft.OpenHarmony.Hosting.OpenHarmonyTouchAction.Down, m3X, m3Y);
M2Touch("sub-1", Microsoft.OpenHarmony.Hosting.OpenHarmonyTouchAction.Up, m3X, m3Y);
M3Check("deferred input", m3Content.Clicks == 1 && ((M2PerWindowApp)m2Application).Main.Clicks == 0);

int m3FramesBefore = m3SubHost!.FrameTicks;
M2FrameEvent("sub-1");
M3Check("deferred frame", m3SubHost.FrameTicks == m3FramesBefore + 1);

// The shell child closes: its XComponent surface is destroyed, the session drops and the managed
// window leaves the application; no registry residue is left behind.
M2Surface("sub-1", Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Destroyed, 700, 500);
M3Check("deferred close", m2Host.FindSecondaryWindow("sub-1") is null
    && m2Host.SecondaryWindows.Count == 0 && m2Host.AwaitingWindowCount == 0
    && m2Application.Windows.Count == 1 && m3Window.Handler is null);

// Re-open after the close reuses the same id (lowest free) and rebinds the same way.
m3Requests.Clear();
M2Content m3Content2 = new("m3-reopen", "m3-reopen-button");
Window m3Window2 = new(m3Content2.Page);
m2Application.OpenWindow(m3Window2);
M3Check("reopen same id", m3Requests.Count == 1 && m3Requests[0] == "sub-1"
    && m2Host.AwaitingWindowCount == 1);
int m3CanvasBase2 = m2Canvases.Count;
M2Surface("sub-1", Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Created, 640, 480);
OpenHarmonyWindowHost? m3SubHost2 = m2Host.FindSecondaryWindow("sub-1");
M3Check("reopen bound", m3SubHost2 is not null && ReferenceEquals(m3SubHost2!.Window, m3Window2)
    && m2Canvases.Count == m3CanvasBase2 + 1 && m2Canvases[^1].Texts.Contains("m3-reopen"));
m2Application.CloseWindow(m3Window2);
M3Check("reopen closed clean", m2Host.SecondaryWindows.Count == 0
    && m2Host.AwaitingWindowCount == 0 && m2Application.Windows.Count == 1);
m2Host.SubWindowSurfaceRequester = null;

// M3 source pins: the four packs' SubWindow.ets carries the host XComponent with the requested
// surface id and the register/unregister lifecycle plus the preserved drawn fallback; Index.ets
// threads cmd.surfaceId into the LocalStorage; the host exports and implements the per-window
// draw entry points; the slice consumes the tagged channel, opens deferred windows and targets
// the per-window canvas.
bool m3ShellPinsOk = true;
foreach (string m3ShellVersion in new[] { "1.0.0-preview.22", "1.0.0-preview.23", "1.0.0-preview.24", "1.0.0-preview.28" })
{
    string m3Index = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{m3ShellVersion}/templates/ets/pages/Index.ets") is { } m3IndexPath
        ? File.ReadAllText(m3IndexPath) : string.Empty;
    string m3Page = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{m3ShellVersion}/templates/ets/pages/SubWindow.ets") is { } m3PagePath
        ? File.ReadAllText(m3PagePath) : string.Empty;
    m3ShellPinsOk &= m3Index.Contains("cmd.surfaceId") && m3Index.Contains("subWindowSurfaceId")
        && m3Index.Contains("storage.setOrCreate('subWindowSurfaceId'")
        && m3Page.Contains("XComponent(") && m3Page.Contains("id: this.surfaceId")
        && m3Page.Contains("libraryname: 'openharmonyhost'")
        && m3Page.Contains("host.registerXComponent(this.surfaceId)")
        && m3Page.Contains("host.unregisterXComponent(this.surfaceId)")
        && m3Page.Contains("notifyHost(SUB_EVENT_TOUCH, payload)");
}
M3Check("shell source", m3ShellPinsOk);

string m3HostSource = FindHostSource("src/OpenHarmonyHost/openharmony_host.c") is { } m3HostPath
    ? File.ReadAllText(m3HostPath) : string.Empty;
string m3HostExports = FindHostSource("src/OpenHarmonyHost/host-exports.txt") is { } m3HostExportsPath
    ? File.ReadAllText(m3HostExportsPath) : string.Empty;
string m3HostingSource = FindHostSource("src/Microsoft.OpenHarmony.Hosting/OpenHarmonyApp.cs") is { } m3HostingPath
    ? File.ReadAllText(m3HostingPath) : string.Empty;
M3Check("host source", m3HostSource.Contains("ohos_host_draw_begin_window")
    && m3HostSource.Contains("ohos_host_draw_present_window")
    && m3HostSource.Contains("OhosHostPresentTarget")
    && m3HostExports.Contains("ohos_host_draw_begin_window")
    && m3HostExports.Contains("ohos_host_draw_present_window")
    && m3HostingSource.Contains("ohos_host_draw_begin_window")
    && m3HostingSource.Contains("BeginWindowNative"));

string m3SliceHost = FindHostSource("OpenHarmonyMauiAppHost.cs") is { } m3SliceHostPath
    ? File.ReadAllText(m3SliceHostPath) : string.Empty;
string m3SliceSurface = FindHostSource("OpenHarmonyWindowSurface.cs") is { } m3SliceSurfacePath
    ? File.ReadAllText(m3SliceSurfacePath) : string.Empty;
string m3SliceHandler = FindHostSource("OpenHarmonyApplicationHandler.cs") is { } m3SliceHandlerPath
    ? File.ReadAllText(m3SliceHandlerPath) : string.Empty;
string m3SliceSubWindow = FindHostSource("OpenHarmonySubWindow.cs") is { } m3SliceSubWindowPath
    ? File.ReadAllText(m3SliceSubWindowPath) : string.Empty;
M3Check("slice source", m3SliceHost.Contains("OpenHarmonyBridge.WindowSurfaceChanged +=")
    && m3SliceHost.Contains("RouteSurface(id, info)")
    && m3SliceHost.Contains("TryOpenWindowDeferred")
    && m3SliceSurface.Contains("OpenHarmonyCanvas.BeginWindow(WindowId")
    && m3SliceSurface.Contains("OpenHarmonyCanvas.PresentWindow(WindowId)")
    && m3SliceHandler.Contains("host.TryOpenWindowDeferred(window)")
    && m3SliceSubWindow.Contains("CreateManagedSurface")
    && m3SliceSubWindow.Contains("writer.WriteString(\"surfaceId\", surfaceId)"));

if (m3Failures > 0)
{
    throw new InvalidOperationException(
        $"{m3Failures} MULTIWINDOW-L M3 assertion(s) failed (production tagged routing, the deferred OpenWindow path or the per-window draw target regressed)");
}

Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.WindowSurfaceChanged -= m2OnWindowSurface;
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.WindowTouch -= m2OnWindowTouch;
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.WindowFrame -= m2OnWindowFrame;
OpenHarmonyWindowRenderer.CanvasFactory = m2SavedCanvasFactory;
if (m2Failures > 0)
{
    throw new InvalidOperationException(
        $"{m2Failures} MULTIWINDOW-L M2 per-window assertion(s) failed (the dual-window state or the window-id bridge regressed)");
}

// ---------------------------------------------------------------------------------------------
// MULTIWINDOW-L M4 (first wave): per-window focus/lifecycle (M4-05), the per-window
// keyboard/IME wire (M4-02), the per-window accessibility frame partition and alert ownership
// (M4-03/M4-04 offline half). Everything is driven through the production consumers: the app
// host's subwindow subscription, the slice's text router/key hook and the shell channel thunks
// (the exact callbacks the ArkTS shell reaches through host.notifySubWindowEvent).
// M4-04 (second wave) adds the per-window pinch channel, driven through the registered
// s_windowPinchThunk exactly like the host's own per-window touch/frame entries.
int m4Failures = 0;
void M4Check(string name, bool ok)
{
    Console.WriteLine($"[verify] m4 {name} assert={ok}");
    if (!ok)
    {
        m4Failures++;
    }
}
void M4SubEvent(OpenHarmonySubWindowEventKind kind, string payload)
    => OpenHarmonySubWindow.HandleNativeEvent((int)kind, payload);
string m4StatePayload = "{\"id\":430,\"x\":0,\"y\":0,\"w\":700,\"h\":500,\"surfaceId\":\"sub-1\"}";

// --- M4-05: per-window focus/suspend/resume state machine ------------------------------------
List<string> m4Requests = new();
m2Host.SubWindowSurfaceRequester = id => { m4Requests.Add(id); return true; };
M4InputContent m4LifeContent = new("m4-life-label", "m4-life-entry", "m4-life-button");
Window m4LifeWindow = new(m4LifeContent.Page);
m2Application.OpenWindow(m4LifeWindow);
M2Surface("sub-1", Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Created, 700, 500);
OpenHarmonyWindowHost? m4LifeHost = m2Host.FindSecondaryWindow("sub-1");
M4Check("life bound", m4Requests.Count == 1 && m4Requests[0] == "sub-1"
    && m4LifeHost is not null && ReferenceEquals(m4LifeHost!.Window, m4LifeWindow) && m4LifeWindow.Width == 700);

// Controls.Window exposes the IWindow lifecycle as methods (no public events), so the checks
// observe the platform-facing state: the host's counters/flags are raised by the production
// handler, and Controls mirrors activation in Window.IsActivated.
M4SubEvent(OpenHarmonySubWindowEventKind.Inactive, m4StatePayload);
bool m4InactiveOk = m4LifeHost!.DeactivatedCount == 1 && m4LifeHost.IsDeactivated
    && m4LifeWindow.IsActivated == false;
M4SubEvent(OpenHarmonySubWindowEventKind.Active, m4StatePayload);
bool m4FocusOk = m4InactiveOk
    && m4LifeHost.ActivatedCount == 1 && !m4LifeHost.IsDeactivated
    && m4LifeWindow.IsActivated && OpenHarmonySubWindow.IsFocused;
M4Check("life focus", m4FocusOk);

M4SubEvent(OpenHarmonySubWindowEventKind.Suspended, "{}");
M4SubEvent(OpenHarmonySubWindowEventKind.Suspended, "{}");
bool m4StoppedOk = m4LifeHost.StoppedCount == 1 && m4LifeHost.IsStopped;
M4SubEvent(OpenHarmonySubWindowEventKind.Resumed, "{}");
M4SubEvent(OpenHarmonySubWindowEventKind.Resumed, "{}");
bool m4SuspendOk = m4StoppedOk
    && m4LifeHost.ResumedCount == 1 && !m4LifeHost.IsStopped;
M4Check("life suspend", m4SuspendOk);

// The primary window keeps its process-level lifecycle untouched by the child's focus/suspend
// events (only the secondary windows stop/resume here). The suite's primary never saw the
// platform activation event, so the check compares the state across the child events instead of
// asserting a fixed value.
bool m4PrimaryActivatedBefore = ((Microsoft.Maui.Controls.Window)m2MainWindow).IsActivated;
M4SubEvent(OpenHarmonySubWindowEventKind.Inactive, m4StatePayload);
M4SubEvent(OpenHarmonySubWindowEventKind.Suspended, "{}");
M4Check("life primary untouched",
    ((Microsoft.Maui.Controls.Window)m2MainWindow).IsActivated == m4PrimaryActivatedBefore
    && ReferenceEquals(m2Host.Window, m2MainWindow)
    && m2Host.FindSecondaryWindow("sub-1") is not null);

// The shell's Closed report alone (the surface-Destroyed report may arrive after page teardown,
// SEC5B-L3) still closes the managed session: Destroying + out of Application.Windows.
M4SubEvent(OpenHarmonySubWindowEventKind.Closed, m4StatePayload);
M4Check("life closed belt", m2Host.FindSecondaryWindow("sub-1") is null && m2Host.AwaitingWindowCount == 0
    && m2Application.Windows.Count == 1 && m4LifeWindow.Handler is null);

// --- M4-02: per-window keyboard/IME wire ------------------------------------------------------
List<string> m4Commands = new();
OpenHarmonySubWindow.CommandSender = (op, payload) => { m4Commands.Add($"{op}:{payload}"); return true; };
M4InputContent m4Input = new("m4-input-label", "seed", "m4-input-button");
Window m4InputWindow = new(m4Input.Page);
m2Application.OpenWindow(m4InputWindow);
M2Surface("sub-1", Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Created, 700, 500);
OpenHarmonyWindowHost? m4InputHost = m2Host.FindSecondaryWindow("sub-1");
m4Input.Page.Measure(700, 500);
m4Input.Page.Arrange(new Rect(0, 0, 700, 500));
float m4Ex = (float)(m4Input.Entry.Frame.X + m4Input.Entry.Frame.Width / 2);
float m4Ey = (float)(m4Input.Entry.Frame.Y + m4Input.Entry.Frame.Height / 2);
M2Touch("sub-1", Microsoft.OpenHarmony.Hosting.OpenHarmonyTouchAction.Down, m4Ex, m4Ey);
M2Touch("sub-1", Microsoft.OpenHarmony.Hosting.OpenHarmonyTouchAction.Up, m4Ex, m4Ey);
string m4FocusCommand = m4Commands.FirstOrDefault(c => c.StartsWith("6:")) ?? string.Empty;
M4Check("input focus wire", m4InputHost is not null && m4Input.Entry.IsFocused
    && m4FocusCommand.Contains("\"surfaceId\":\"sub-1\"")
    && m4FocusCommand.Contains("\"show\":1") && m4FocusCommand.Contains("\"text\":\"seed\""));

string m4PrimaryEntryTextBefore = entry?.Text ?? string.Empty;
M4SubEvent(OpenHarmonySubWindowEventKind.TextInput,
    "{\"surfaceId\":\"sub-1\",\"text\":\"sub-only\"}");
M4Check("input text routed", m4Input.Entry.Text == "sub-only"
    && (entry?.Text ?? string.Empty) == m4PrimaryEntryTextBefore);

M4SubEvent(OpenHarmonySubWindowEventKind.TextComposition,
    "{\"surfaceId\":\"sub-1\",\"value\":\"ni\",\"offset\":1}");
bool m4CompositionOk = m4Input.Entry.Handler?.PlatformView is OpenHarmonyView m4Platform
    && m4Platform.CompositionText == "ni" && m4Platform.CompositionOffset == 1;
M4Check("input composition routed", m4CompositionOk);

bool m4Completed = false;
m4Input.Entry.Completed += (_, _) => m4Completed = true;
M4SubEvent(OpenHarmonySubWindowEventKind.TextSubmitted,
    "{\"surfaceId\":\"sub-1\",\"text\":\"sub-only\"}");
M4Check("input submitted routed", m4Completed);

// SEC-SCAN-5c reverse isolation: the primary window's global text path (driven through the raw
// thunk the host's text-input callback calls) must not reach the secondary window's focused
// input. Its platform view stays IsFocused across a window switch, so only its tagged port may
// consume; red before the fix - this thunk appended 'main-only' to the child entry.
var m4GlobalTextThunk = NativeThunks.Invoker<NativeThunks.PtrCallback>(
    NativeThunks.Pointer(typeof(Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge), "s_textInputThunk"));
string m4ChildTextBeforeGlobal = m4Input.Entry.Text;
IntPtr m4GlobalTextUtf8 = Marshal.StringToCoTaskMemUTF8("main-only");
try
{
    m4GlobalTextThunk(m4GlobalTextUtf8);
}
finally
{
    Marshal.FreeCoTaskMem(m4GlobalTextUtf8);
}
M4Check("input main->child isolation", m4Input.Entry.Text == m4ChildTextBeforeGlobal);

List<string> m4Keys = new();
Action<string, int, int> m4KeyRecorder = (id, code, type) => m4Keys.Add($"{id}:{code}:{type}");
OpenHarmonyKeyListener.WindowKeyEvent += m4KeyRecorder;
int m4KeyEventsBefore = OpenHarmonyKeyListener.WindowEventsReceived;
M4SubEvent(OpenHarmonySubWindowEventKind.Key, "{\"surfaceId\":\"sub-1\",\"code\":2019,\"type\":0}");
OpenHarmonyKeyListener.WindowKeyEvent -= m4KeyRecorder;
M4Check("key routed", m4Keys.Count == 1 && m4Keys[0] == "sub-1:2019:0"
    && OpenHarmonyKeyListener.WindowEventsReceived == m4KeyEventsBefore + 1);

List<string> m4Backs = new();
Action<string> m4BackRecorder = id => m4Backs.Add(id);
OpenHarmonyWindowInputRouter.Back += m4BackRecorder;
M4SubEvent(OpenHarmonySubWindowEventKind.Back, m4StatePayload);
OpenHarmonyWindowInputRouter.Back -= m4BackRecorder;
M4Check("back routed", m4Backs.Count == 1 && m4Backs[0] == "sub-1");

M4Check("input ports", OpenHarmonyWindowInputRouter.PortCount("sub-1") >= 1
    && OpenHarmonyWindowInputRouter.PortCount(OpenHarmonyWindowSurface.PrimaryWindowId) >= 1);

// --- M4-04: per-window pinch routing ----------------------------------------------------------
// The shell computes each window's pinch stream from that window's own touches (host_napi.cpp)
// and reports it on the tagged bridge; the app host routes it to the owning window's renderer.
// Driven through the exact registered thunk the host calls.
var m4PinchThunk = NativeThunks.Invoker<NativeThunks.WindowPinchCallback>(
    NativeThunks.Pointer(typeof(Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge), "s_windowPinchThunk"));
List<string> m4Pinches = new();
Action<string, int, double, float, float> m4PinchRecorder =
    (id, phase, scale, x, y) => m4Pinches.Add($"{id}:{phase}:{scale:0.0}");
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.WindowPinch += m4PinchRecorder;
void M4Pinch(string id, int phase, double scale, float x, float y)
{
    IntPtr m4IdUtf8 = Marshal.StringToCoTaskMemUTF8(id);
    try
    {
        m4PinchThunk(m4IdUtf8, phase, scale, x, y);
    }
    finally
    {
        Marshal.FreeCoTaskMem(m4IdUtf8);
    }
}
float m4Px = (float)(m4Input.PinchLabel.Frame.X + m4Input.PinchLabel.Frame.Width / 2);
float m4Py = (float)(m4Input.PinchLabel.Frame.Y + m4Input.PinchLabel.Frame.Height / 2);
M4Pinch("sub-1", 0, 1.0, m4Px, m4Py);
M4Pinch("sub-1", 1, 1.5, m4Px, m4Py);
M4Pinch("sub-1", 2, 1.0, m4Px, m4Py);
M4Check("pinch routed", m4InputHost is not null && m4InputHost.PinchCount == 3
    && m4Input.PinchLog.Contains("Started") && m4Input.PinchLog.Contains("Running")
    && m4Pinches.Count == 3 && m4Pinches.All(entry => entry.StartsWith("sub-1:")));

// A primary-tagged report belongs to the untagged legacy path; an id with no live window is
// dropped. Neither may reach the child's recognizer.
string m4PinchLogBefore = m4Input.PinchLog;
int m4PinchCountBefore = m4InputHost!.PinchCount;
M4Pinch("main", 0, 1.0, 10f, 10f);
M4Pinch("sub-404", 1, 2.0, 10f, 10f);
M4Pinch(string.Empty, 1, 2.0, 10f, 10f);
M4Check("pinch main/unknown ignored", m4Input.PinchLog == m4PinchLogBefore
    && m4InputHost.PinchCount == m4PinchCountBefore
    && m4Pinches.Count == 5 && m4Pinches[3].StartsWith("main:"));

// SEC-SCAN-5c E: a malformed report must not reach the app's recognizer. A NaN scale would
// poison Scale *= e.Scale forever, an Inf centre would be dropped by the hit test only after
// the tree walk, and a 0/negative/absurd running scale cannot come from the shell's two-point
// distance (host_napi.cpp ComputePinch). The guards drop at the managed boundary before a
// dispatch; every report is still routed through the tagged bridge (m4Pinches grows), so the
// red shape is exactly "routed but dispatched".
string secEPinchLogBefore = m4Input.PinchLog;
int secEPinchCountBefore = m4InputHost!.PinchCount;
M4Pinch("sub-1", 1, double.NaN, m4Px, m4Py);
M4Pinch("sub-1", 1, double.PositiveInfinity, m4Px, m4Py);
M4Pinch("sub-1", 0, 1.0, float.NaN, m4Py);
M4Pinch("sub-1", 1, float.NegativeInfinity, m4Px, float.NaN);
M4Pinch("sub-1", 1, 0.0, m4Px, m4Py);
M4Pinch("sub-1", 1, -2.0, m4Px, m4Py);
bool secEPinchDrops = m4Input.PinchLog == secEPinchLogBefore
    && m4InputHost.PinchCount == secEPinchCountBefore
    && m4Pinches.Count == 11;
M4Check("sec5c pinch non-finite dropped", secEPinchDrops);

// A finite but extreme running scale is clamped into [MinScale, MaxScale] (1e-3..1e3) instead
// of reaching the recognizer; the earlier normal 1.5 report is still delivered untouched.
M4Pinch("sub-1", 1, 1e6, m4Px, m4Py);
M4Pinch("sub-1", 1, 1e-6, m4Px, m4Py);
bool secEPinchClamp = m4Input.PinchLog.EndsWith("Running:1000.0 Running:0.0 ")
    && !m4Input.PinchLog.Contains("1000000.0")
    && m4Input.PinchLog.Contains("Running:1.5")
    && m4InputHost.PinchCount == secEPinchCountBefore + 2;
M4Check("sec5c pinch scale clamped", secEPinchClamp);
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.WindowPinch -= m4PinchRecorder;

// --- M4-03/M4-04: per-window accessibility frames + alert ownership ---------------------------
var m4TreeA = new VerticalStackLayout { Children = { new Label { Text = "m4-a11y-A" } } };
var m4TreeB = new VerticalStackLayout { Children = { new Label { Text = "m4-a11y-B" } } };
OpenHarmonyHandlerConnector.ConnectTree(m4TreeA);
OpenHarmonyHandlerConnector.ConnectTree(m4TreeB);
OpenHarmonyAccessibility.Refresh(OpenHarmonyWindowSurface.PrimaryWindowId, m4TreeA);
OpenHarmonyAccessibility.Publish(OpenHarmonyWindowSurface.PrimaryWindowId);
OpenHarmonyAccessibility.Refresh("sub-1", m4TreeB);
OpenHarmonyAccessibility.Publish("sub-1");
bool m4A11yPrimaryKeepsA = OpenHarmonyAccessibility.NodesForWindow(OpenHarmonyWindowSurface.PrimaryWindowId)
    .Any(n => n.Text == "m4-a11y-A");
bool m4A11ySubHasB = OpenHarmonyAccessibility.NodesForWindow("sub-1").Any(n => n.Text == "m4-a11y-B");
bool m4A11ySubNoA = !OpenHarmonyAccessibility.NodesForWindow("sub-1").Any(n => n.Text == "m4-a11y-A");
bool m4A11yPrimaryNoB = !OpenHarmonyAccessibility.NodesForWindow(OpenHarmonyWindowSurface.PrimaryWindowId)
    .Any(n => n.Text == "m4-a11y-B");
M4Check("a11y partition", m4A11yPrimaryKeepsA && m4A11ySubHasB && m4A11ySubNoA && m4A11yPrimaryNoB
    && OpenHarmonyAccessibility.SecondaryPublishes >= 1);

// An alert owned by the child must appear in the child's shadow frame only; the primary tree
// keeps its nodes and the primary provider path is never gated by a foreign dialog.
OpenHarmonyAlertHost.Show(new OpenHarmonyAlertState
{
    WindowId = "sub-1",
    Title = "m4-owned-alert",
    Message = "child dialog",
    Accept = "OK",
    Cancel = "Cancel",
    Complete = _ => { },
});
OpenHarmonyAlertHost.SetSurface("sub-1", 700, 500);
OpenHarmonyAccessibility.Refresh(OpenHarmonyWindowSurface.PrimaryWindowId, m4TreeA);
OpenHarmonyAccessibility.Refresh("sub-1", m4TreeB);
bool m4AlertOwnerOk = OpenHarmonyAlertHost.CurrentFor("sub-1") is not null
    && OpenHarmonyAlertHost.CurrentFor(OpenHarmonyWindowSurface.PrimaryWindowId) is null
    && !OpenHarmonyAccessibility.NodesForWindow(OpenHarmonyWindowSurface.PrimaryWindowId)
        .Any(n => n.Role == "dialog")
    && OpenHarmonyAccessibility.NodesForWindow("sub-1").Any(n => n.Role == "dialog" && n.Text == "m4-owned-alert");
OpenHarmonyAlertHost.Hide();
M4Check("a11y alert owner", m4AlertOwnerOk);

// --- MULTIWINDOW-L2 a (W1): per-window a11y frames, lookups, actions, the provider gate --------
// The window's frame is rebuilt from the window's real content so the action targets are the
// views that window renders; node ids are positional, so every assertion resolves window-first.
OpenHarmonyAccessibility.Refresh("sub-1", m4Input.Page);
OpenHarmonyAccessibility.Publish("sub-1");
OpenHarmonyAccessibility.Refresh(OpenHarmonyWindowSurface.PrimaryWindowId, m2MainWindow.Content);
OpenHarmonyAccessibilityNode? l2SubButton = OpenHarmonyAccessibility.NodesForWindow("sub-1")
    .FirstOrDefault(n => n.Role == "button");
OpenHarmonyAccessibilityNode? l2MainButton = OpenHarmonyAccessibility
    .NodesForWindow(OpenHarmonyWindowSurface.PrimaryWindowId).FirstOrDefault(n => n.Role == "button");
bool l2SubButtonResolves = l2SubButton is not null
    && OpenHarmonyAccessibility.TryFindNode("sub-1", l2SubButton.Id, out OpenHarmonyAccessibilityNode l2SubNode)
    && ReferenceEquals(l2SubNode, l2SubButton)
    && OpenHarmonyAccessibility.TryFindView("sub-1", l2SubButton.Id, out IView l2SubView)
    && ReferenceEquals(l2SubView, m4Input.Button);
bool l2WindowFirst = l2MainButton is not null
    && OpenHarmonyAccessibility.TryFindView(OpenHarmonyWindowSurface.PrimaryWindowId, l2MainButton.Id, out IView l2MainView)
    && ReferenceEquals(l2MainView, ((M2PerWindowApp)m2Application).Main.Button)
    && (!OpenHarmonyAccessibility.TryFindView(OpenHarmonyWindowSurface.PrimaryWindowId, l2SubButton!.Id, out IView l2Foreign)
        || !ReferenceEquals(l2Foreign, m4Input.Button));
M4Check("a11y window lookup", l2SubButtonResolves && l2WindowFirst);

// The action dispatch: a child-window node id executes on the child's renderer/view only, the
// primary path still executes on the primary window, and an unknown window id is rejected.
int l2SubClicks = m4Input.Clicks;
int l2MainClicks = ((M2PerWindowApp)m2Application).Main.Clicks;
bool l2SubAction = m2Host.HandleAccessibilityAction("sub-1", l2SubButton!.Id,
    (int)OpenHarmonyAccessibilityAction.Click) && m4Input.Clicks == l2SubClicks + 1;
bool l2MainUntouched = ((M2PerWindowApp)m2Application).Main.Clicks == l2MainClicks;
bool l2MainAction = m2Host.HandleAccessibilityAction(OpenHarmonyWindowSurface.PrimaryWindowId, l2MainButton!.Id,
    (int)OpenHarmonyAccessibilityAction.Click) && ((M2PerWindowApp)m2Application).Main.Clicks == l2MainClicks + 1;
bool l2UnknownWindow = !m2Host.HandleAccessibilityAction("sub-404", l2SubButton.Id,
    (int)OpenHarmonyAccessibilityAction.Click);
M4Check("a11y window action routed", l2SubAction && l2MainUntouched && l2MainAction && l2UnknownWindow);

// The registered per-instance listener thunk (the exact reverse P/Invoke the host's WithInstance
// callbacks use): the window id travels with the action and selects the window; a NULL id is
// rejected without touching any window.
// The per-instance listener slots are process-global (one app host per process); the suite runs
// a second host that owns the subwindows, so the owning host is wired here exactly as its first
// primary input would on device (HandleCancel is the cheapest production entry that wires).
m2Host.HandleCancel(0, 0);
int l2ThunkClicks = m4Input.Clicks;
var l2WindowActionThunk = NativeThunks.Invoker<NativeThunks.WindowActionCallback>(
    NativeThunks.Pointer(typeof(OpenHarmonyAccessibility), "_windowActionThunk"));
IntPtr l2SubIdUtf8 = Marshal.StringToCoTaskMemUTF8("sub-1");
try
{
    l2WindowActionThunk(l2SubIdUtf8, l2SubButton.Id, (int)OpenHarmonyAccessibilityAction.Click);
}
finally
{
    Marshal.FreeCoTaskMem(l2SubIdUtf8);
}
bool l2ThunkRouted = m4Input.Clicks == l2ThunkClicks + 1;
l2WindowActionThunk(IntPtr.Zero, l2SubButton.Id, (int)OpenHarmonyAccessibilityAction.Click);
bool l2ThunkEmptyRejected = m4Input.Clicks == l2ThunkClicks + 1;
M4Check("a11y window action thunk", l2ThunkRouted && l2ThunkEmptyRejected);

// Provider gate: without a per-instance provider attached (no host library off-device) the
// secondary publish stays local - no partial publish, no primary traffic, frame kept.
int l2SecondaryPasses = OpenHarmonyAccessibility.SecondaryPublishes;
int l2ProviderPasses = OpenHarmonyAccessibility.SecondaryProviderPublishes;
OpenHarmonyAccessibility.Publish("sub-1");
bool l2ProviderGate = OpenHarmonyAccessibility.SecondaryProviderPublishes == l2ProviderPasses
    && OpenHarmonyAccessibility.SecondaryPublishes > l2SecondaryPasses
    && OpenHarmonyAccessibility.NodesForWindow("sub-1").Count == OpenHarmonyAccessibility.LastSecondaryPublishedCount;
M4Check("a11y secondary provider local", l2ProviderGate);

// SEC-SCAN-4 pin copied to the child window: a password entry in the subwindow frame publishes
// bullets, never its plaintext (the walk is shared, so the masking must hold per window too).
string l2Plain = m4Input.Entry.Text ?? string.Empty;
m4Input.Entry.IsPassword = true;
try
{
    OpenHarmonyAccessibility.Refresh("sub-1", m4Input.Page);
    bool l2PlainHidden = !OpenHarmonyAccessibility.NodesForWindow("sub-1").Any(n => n.Text == l2Plain);
    bool l2Masked = OpenHarmonyAccessibility.NodesForWindow("sub-1").Any(n =>
        n.Role == "textInput" && n.Text == new string('\u2022', l2Plain.Length));
    M4Check("a11y subwindow password masked", l2Plain.Length > 0 && l2PlainHidden && l2Masked);
}
finally
{
    m4Input.Entry.IsPassword = false;
    OpenHarmonyAccessibility.Refresh("sub-1", m4Input.Page);
}

// A child-owned alert traps the child's frame only: the background child node is inert while
// the primary window's action path keeps working (its own CurrentFor is null).
OpenHarmonyAlertHost.Show(new OpenHarmonyAlertState
{
    WindowId = "sub-1",
    Title = "l2-owned-modal",
    Message = "child modal",
    Accept = "OK",
    Cancel = "Cancel",
    Complete = _ => { },
});
OpenHarmonyAlertHost.SetSurface("sub-1", 700, 500);
OpenHarmonyAccessibility.Refresh("sub-1", m4Input.Page);
OpenHarmonyAccessibility.Refresh(OpenHarmonyWindowSurface.PrimaryWindowId, m2MainWindow.Content);
int l2ModalClicks = m4Input.Clicks;
bool l2ModalBackgroundInert = !m2Host.HandleAccessibilityAction("sub-1", l2SubButton.Id,
    (int)OpenHarmonyAccessibilityAction.Click) && m4Input.Clicks == l2ModalClicks;
bool l2PrimaryUnaffected = m2Host.HandleAccessibilityAction(OpenHarmonyWindowSurface.PrimaryWindowId,
    l2MainButton.Id, (int)OpenHarmonyAccessibilityAction.Click);
OpenHarmonyAlertHost.Hide();
M4Check("a11y per-window modal gate", l2ModalBackgroundInert && l2PrimaryUnaffected);

// Source pins: the host table partition + WithInstance provider + shell ContentSlot + the
// managed window-parameterized path all ship together.
string l2Napi = FindHostSource("src/OpenHarmonyHost/host_napi.cpp") is { } l2NapiPath
    ? File.ReadAllText(l2NapiPath) : string.Empty;
string l2Table = FindHostSource("src/OpenHarmonyHost/host_a11y_table.c") is { } l2TablePath
    ? File.ReadAllText(l2TablePath) : string.Empty;
string l2Exports = FindHostSource("src/OpenHarmonyHost/host-exports.txt") is { } l2A11yExportsPath
    ? File.ReadAllText(l2A11yExportsPath) : string.Empty;
string l2SliceA11y = FindHostSource("OpenHarmonyAccessibility.cs") is { } l2SlicePath
    ? File.ReadAllText(l2SlicePath) : string.Empty;
bool l2A11yShellPinsOk = true;
foreach (string l2ShellVersion in new[] { "1.0.0-preview.22", "1.0.0-preview.23", "1.0.0-preview.24", "1.0.0-preview.28" })
{
    string l2Page = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{l2ShellVersion}/templates/ets/pages/SubWindow.ets") is { } l2PagePath
        ? File.ReadAllText(l2PagePath) : string.Empty;
    l2A11yShellPinsOk &= l2Page.Contains("import { NodeContent } from '@kit.ArkUI';")
        && l2Page.Contains("private content: NodeContent = new NodeContent();")
        && l2Page.Contains("ContentSlot(this.content)")
        && l2Page.Contains("host.attachAccessibilityNodeFor(this.surfaceId, this.content)")
        && l2Page.Contains("onPageShow(): void");
}
bool l2NativePinsOk = l2Napi.Contains("OH_ArkUI_AccessibilityProviderRegisterCallbackWithInstance")
    && l2Napi.Contains("AttachAccessibilityValueFor")
    && l2Napi.Contains("\"attachAccessibilityNodeFor\"")
    && l2Napi.Contains("\"accessibilityStatusFor\"")
    && l2Napi.Contains("\"accessibilityNodeCountFor\"")
    && l2Napi.Contains("g_a11y_window_action_listener")
    && l2Napi.Contains("ohos_host_accessibility_set_window_action_listener")
    && l2Napi.Contains("ohos_host_accessibility_send_event_for")
    && l2Table.Contains("ohos_host_accessibility_begin_for")
    && l2Table.Contains("OhosA11yPartitionForLocked")
    && l2Table.Contains("OHOS_A11Y_MAX_NAMED_PARTITIONS")
    && l2Table.Contains("ohos_host_accessibility_table_release")
    && l2Exports.Contains("ohos_host_accessibility_begin_for")
    && l2Exports.Contains("ohos_host_accessibility_set_window_action_listener")
    && l2Exports.Contains("ohos_host_accessibility_release_for")
    && l2Napi.Contains("ohos_host_accessibility_release_for")
    && l2Napi.Contains("g_a11y_instances")
    && l2SliceA11y.Contains("TryFindNode(string windowId, int id")
    && l2SliceA11y.Contains("TryFindView(string windowId, int id")
    && l2SliceA11y.Contains("PublishSecondary")
    && l2SliceA11y.Contains("WindowProviderAttached")
    && l2SliceA11y.Contains("SetWindowActionHandler")
    && l2SliceA11y.Contains("OnWindowAction")
    && l2SliceA11y.Contains("ohos_host_accessibility_begin_for")
    && l2SliceA11y.Contains("ohos_host_accessibility_release_for")
    && l2SliceA11y.Contains("ReleaseProviderState(windowId);");
M4Check("a11y provider source pins", l2A11yShellPinsOk && l2NativePinsOk);

// --- source pins: the shell and slice carry the M4 wires --------------------------------------
bool m4ShellPinsOk = true;
foreach (string m4ShellVersion in new[] { "1.0.0-preview.22", "1.0.0-preview.23", "1.0.0-preview.24", "1.0.0-preview.28" })
{
    string m4Index = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{m4ShellVersion}/templates/ets/pages/Index.ets") is { } m4IndexPath
        ? File.ReadAllText(m4IndexPath) : string.Empty;
    string m4Page = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{m4ShellVersion}/templates/ets/pages/SubWindow.ets") is { } m4PagePath
        ? File.ReadAllText(m4PagePath) : string.Empty;
    m4ShellPinsOk &= m4Index.Contains("SUB_CMD_TEXT_FOCUS") && m4Index.Contains("forwardSubWindowTextFocus")
        && m4Index.Contains("reportSubWindowState(SUB_EVENT_ACTIVE, session)")
        && m4Index.Contains("reportSubWindowState(SUB_EVENT_INACTIVE, session)")
        && m4Index.Contains("SUB_WINDOW_FOCUS_REQUEST_KEY")
        && m4Page.Contains("@StorageLink('ohos_dotnet_subwindow_focus_request')")
        && m4Page.Contains("SUB_EVENT_TEXT,") && m4Page.Contains("SUB_EVENT_KEY")
        && m4Page.Contains("SUB_EVENT_BACK") && m4Page.Contains("onBackPress()")
        && m4Page.Contains(".focusable(true)") && m4Page.Contains("onKeyEvent(");
}
string m4SliceEntry = FindHostSource("OpenHarmonyEntryHandler.cs") is { } m4EntryPath
    ? File.ReadAllText(m4EntryPath) : string.Empty;
string m4SliceHost = FindHostSource("OpenHarmonyMauiAppHost.cs") is { } m4HostPath
    ? File.ReadAllText(m4HostPath) : string.Empty;
string m4SliceRouter = FindHostSource("OpenHarmonyWindowInputRouter.cs") is { } m4RouterPath
    ? File.ReadAllText(m4RouterPath) : string.Empty;
string m4SliceA11y = FindHostSource("OpenHarmonyAccessibility.cs") is { } m4A11yPath
    ? File.ReadAllText(m4A11yPath) : string.Empty;
string m4SliceAlert = FindHostSource("OpenHarmonyAlertHost.cs") is { } m4AlertPath
    ? File.ReadAllText(m4AlertPath) : string.Empty;
string m4SliceWindowHost = FindHostSource("OpenHarmonyWindowHost.cs") is { } m4WindowHostPath
    ? File.ReadAllText(m4WindowHostPath) : string.Empty;
bool m4SlicePinsOk = m4SliceEntry.Contains("OpenHarmonySubWindow.RequestTextFocus(windowId")
    && m4SliceRouter.Contains("DispatchText") && m4SliceRouter.Contains("DispatchSubmitted")
    && m4SliceHost.Contains("OnSubWindowChanged") && m4SliceHost.Contains("StopSecondaryWindows")
    && m4SliceHost.Contains("CloseSecondaryBySurface") && m4SliceHost.Contains("ResolveWindowId")
    && m4SliceHost.Contains("WindowPinch") && m4SliceHost.Contains("RoutePinch")
    && m4SliceA11y.Contains("Refresh(string windowId, IView root)")
    && m4SliceA11y.Contains("Publish(string windowId)")
    && m4SliceAlert.Contains("CurrentFor(string windowId)")
    && m4SliceAlert.Contains("SetSurface(string windowId, double width, double height)")
    && m4SliceWindowHost.Contains("OpenHarmonySystemFontScale.Changed += OnSystemFontScaleChanged")
    && m4SliceWindowHost.Contains("public bool HandlePinch(int phase, double scale, float x, float y)");
M4Check("source pins", m4ShellPinsOk && m4SlicePinsOk);

// --- A11Y-SELFCHECK: a provider attached after the window's last frame still gets its frame ----
// The shell attaches the child provider while the managed window can already hold its first
// (local) frame; the host must repaint once on the next frame tick so the first per-window
// publish reaches the provider inside the shell's 3s self-check window (the M3 device round
// observed `selfcheck status=1 nodes=0`). Red control: without the OpenHarmonyWindowHost
// pending-repaint check the second frame tick is a no-op and this check prints assert=False.
OpenHarmonyAccessibility.ProviderStatusProbe = id => id == "sub-1" ? 1 : 0;
Action<int>? a11ySelfcheckSavedPhaseTick = OpenHarmonyWindowRenderer.RenderPhaseTick;
int a11ySelfcheckFrames = 0;
OpenHarmonyWindowRenderer.RenderPhaseTick = phase =>
{
    if (phase == 5)
    {
        a11ySelfcheckFrames++;
    }
};
try
{
    // A focused Entry keeps the window's NeedsAnimation redraw loop alive and would mask the
    // pending-repaint signal; the M3 device shape is a static child window whose frame tick
    // does not repaint by itself.
    m4Input.Entry.Unfocus();
    OpenHarmonyAccessibility.Refresh("sub-1", m4Input.Page);
    OpenHarmonyAccessibility.Publish("sub-1");
    M2FrameEvent("sub-1");   // settle any dirty state left by the earlier input/action drills
    int a11ySelfcheckBase = a11ySelfcheckFrames;
    bool a11ySelfcheckPending = OpenHarmonyAccessibility.WindowPublishPending("sub-1");
    bool a11ySelfcheckDirtyBefore = m4InputHost!.Dirty;
    M2FrameEvent("sub-1");   // the pending first publish must force exactly this repaint
    bool a11ySelfcheckRepainted = a11ySelfcheckFrames == a11ySelfcheckBase + 1;
    bool a11ySelfcheckPins = l2SliceA11y.Contains("WindowPublishPending")
        && l2SliceA11y.Contains("ProviderStatusProbe")
        && !l2SliceA11y.Contains("WindowProviderExportAvailable && WindowProviderAttached")
        && m4SliceWindowHost.Contains("OpenHarmonyAccessibility.WindowPublishPending(WindowId)");
    M4Check($"a11y selfcheck pending repaint pending={a11ySelfcheckPending} dirty={a11ySelfcheckDirtyBefore} repainted={a11ySelfcheckRepainted} pins={a11ySelfcheckPins}",
        a11ySelfcheckPending && !a11ySelfcheckDirtyBefore && a11ySelfcheckRepainted && a11ySelfcheckPins);
}
finally
{
    OpenHarmonyWindowRenderer.RenderPhaseTick = a11ySelfcheckSavedPhaseTick;
    OpenHarmonyAccessibility.ProviderStatusProbe = null;
}

OpenHarmonySubWindow.CommandSender = null;
m2Host.SubWindowSurfaceRequester = null;

// ---------------------------------------------------------------------------------------------
// SEC-SCAN-5c F: shadow-frame bounds (cap / empty / oversized) and release consistency --------
// The per-window shadow frames and their diff baselines are bounded so id churn that never
// closes a window cannot grow them, a secondary frame longer than the node cap is truncated to
// a well-formed prefix, releasing a window returns its frame slot, and an empty frame publishes
// nothing (no baseline, no provider probe). The primary frame path is untouched.
var secFBigTree = new VerticalStackLayout();
for (int secFI = 0; secFI < OpenHarmonyAccessibility.MaxWindowFrameNodes + 64; secFI++)
{
    secFBigTree.Children.Add(new Label { Text = "sec-f-node-" + secFI });
}
int secFTruncatedBefore = OpenHarmonyAccessibility.WindowFrameWalksTruncated;
OpenHarmonyAccessibility.Refresh("sec-f-big", secFBigTree);
var secFBigNodes = OpenHarmonyAccessibility.NodesForWindow("sec-f-big");
bool secFNodeCap = secFBigNodes.Count == OpenHarmonyAccessibility.MaxWindowFrameNodes
    && OpenHarmonyAccessibility.WindowFrameWalksTruncated == secFTruncatedBefore + 1
    && secFBigNodes.All(n => n.ParentId == 0 || n.ParentId < n.Id);
M4Check("sec5c a11y frame node cap", secFNodeCap);
OpenHarmonyAccessibility.ReleaseWindow("sec-f-big");

int secFDroppedBefore = OpenHarmonyAccessibility.WindowFramesDropped;
List<string> secFAccepted = new();
string? secFDropped = null;
for (int secFI = 0; secFI < OpenHarmonyAccessibility.MaxWindowFrames + 2 && secFDropped is null; secFI++)
{
    string secFId = $"sec-f-cap-{secFI}";
    OpenHarmonyAccessibility.Refresh(secFId, m4TreeA);
    if (OpenHarmonyAccessibility.HasWindowFrame(secFId))
    {
        secFAccepted.Add(secFId);
    }
    else
    {
        secFDropped = secFId;
    }
}
bool secFPrimaryCounted = OpenHarmonyAccessibility
    .NodesForWindow(OpenHarmonyWindowSurface.PrimaryWindowId).Count > 0;
bool secFFrameCap = secFDropped is not null
    && OpenHarmonyAccessibility.WindowFramesDropped == secFDroppedBefore + 1
    && OpenHarmonyAccessibility.FrameWindowCount == OpenHarmonyAccessibility.MaxWindowFrames + (secFPrimaryCounted ? 1 : 0)
    && OpenHarmonyAccessibility.NodesForWindow(secFDropped).Count == 0
    && secFAccepted.Count > 0;
M4Check("sec5c a11y frame cap", secFFrameCap);

// Releasing a window frees its frame slot (its baseline goes with it), so the dropped id is
// accepted again and the drop counter does not move.
bool secFReleaseReuse = false;
if (secFDropped is not null && secFAccepted.Count > 0)
{
    string secFReleased = secFAccepted[0];
    OpenHarmonyAccessibility.Publish(secFReleased);
    OpenHarmonyAccessibility.ReleaseWindow(secFReleased);
    bool secFReleasedGone = !OpenHarmonyAccessibility.HasWindowFrame(secFReleased)
        && OpenHarmonyAccessibility.NodesForWindow(secFReleased).Count == 0;
    OpenHarmonyAccessibility.Refresh(secFDropped, m4TreeA);
    secFReleaseReuse = secFReleasedGone
        && OpenHarmonyAccessibility.HasWindowFrame(secFDropped)
        && OpenHarmonyAccessibility.WindowFramesDropped == secFDroppedBefore + 1;
}
M4Check("sec5c a11y frame cap release reuse", secFReleaseReuse);

// An empty/unknown secondary frame publishes nothing: no diff baseline for an id without a
// frame, no provider probe, no counters; the null-root defensive path keeps the last frame
// instead of clearing it.
int secFBaselinesBefore = OpenHarmonyAccessibility.BaselineWindowCount;
int secFProviderBefore = OpenHarmonyAccessibility.SecondaryProviderPublishes;
int secFSecondaryBefore = OpenHarmonyAccessibility.SecondaryPublishes;
OpenHarmonyAccessibility.Publish("sec-f-unknown");
bool secFEmptyPublish = OpenHarmonyAccessibility.BaselineWindowCount == secFBaselinesBefore
    && OpenHarmonyAccessibility.SecondaryProviderPublishes == secFProviderBefore
    && OpenHarmonyAccessibility.SecondaryPublishes == secFSecondaryBefore
    && !OpenHarmonyAccessibility.HasWindowFrame("sec-f-unknown");
int secFKeptNodes = OpenHarmonyAccessibility.NodesForWindow("sub-1").Count;
OpenHarmonyAccessibility.Refresh("sub-1", null!);
bool secFNullRoot = secFKeptNodes > 0
    && OpenHarmonyAccessibility.NodesForWindow("sub-1").Count == secFKeptNodes
    && OpenHarmonyAccessibility.HasWindowFrame("sub-1");
M4Check("sec5c a11y empty frame no-op", secFEmptyPublish && secFNullRoot);

foreach (string secFId in secFAccepted)
{
    OpenHarmonyAccessibility.ReleaseWindow(secFId);
}
if (secFDropped is not null)
{
    OpenHarmonyAccessibility.ReleaseWindow(secFDropped);
}

if (m4Failures > 0)
{
    throw new InvalidOperationException(
        $"{m4Failures} MULTIWINDOW-L M4 assertion(s) failed (per-window lifecycle, keyboard/IME routing, the accessibility partition or the alert ownership regressed)");
}

// ---------------------------------------------------------------------------------------------
// MULTIWINDOW-L3 M1: two managed subwindow sessions coexist. The second deferred OpenWindow is
// served while a session slot is free (the managed bound mirrors the shell's SUB_WINDOW_MAX),
// both windows keep their own surface/input/frame state, a close targets only its own shell
// session (the app-level close payload names the closed window; the shell's Closed report names
// the session) and a third request is declined without touching the live two. The shell session
// registry contract is pinned in every pack's Index.ets and the slice in maui-ohos.
int m1Failures = 0;
void M1Check(string name, bool ok)
{
    Console.WriteLine($"[verify] m1 {name} assert={ok}");
    if (!ok)
    {
        m1Failures++;
    }
}

List<string> m1Requests = new();
m2Host.SubWindowSurfaceRequester = id => { m1Requests.Add(id); return true; };
List<string> m1Commands = new();
OpenHarmonySubWindow.CommandSender = (op, payload) => { m1Commands.Add($"{op}:{payload}"); return true; };

// The M4 input window (sub-1) is still live; the next deferred request takes the free sub-2.
M4InputContent m1ContentB = new("m1-b-label", "m1-b-entry", "m1-b-button");
Window m1WindowB = new(m1ContentB.Page);
m2Application.OpenWindow(m1WindowB);
M1Check("second deferred", m2Handler.LastOpenWindowResult == OpenHarmonyOpenWindowResult.OpenedWindow
    && m1Requests.Count == 1 && m1Requests[0] == "sub-2"
    && m2Host.AwaitingWindowCount == 1 && m2Host.FindSecondaryWindow("sub-2") is null
    && m2Application.Windows.Count == 3);
M2Surface("sub-2", Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Created, 700, 500);
OpenHarmonyWindowHost? m1HostB = m2Host.FindSecondaryWindow("sub-2");
M1Check("second bound", m1HostB is not null && ReferenceEquals(m1HostB!.Window, m1WindowB)
    && m1WindowB.Width == 700 && m1WindowB.Height == 500
    && m2Host.FindSecondaryWindow("sub-1") is not null && m2Host.SecondaryWindows.Count == 2);

// The two windows keep their own trees: a touch in the second lands only in the second.
m1ContentB.Page.Measure(700, 500);
m1ContentB.Page.Arrange(new Rect(0, 0, 700, 500));
float m1Bx = (float)(m1ContentB.Button.Frame.X + m1ContentB.Button.Frame.Width / 2);
float m1By = (float)(m1ContentB.Button.Frame.Y + m1ContentB.Button.Frame.Height / 2);
int m1AClicksBefore = m4Input.Clicks;
M2Touch("sub-2", Microsoft.OpenHarmony.Hosting.OpenHarmonyTouchAction.Down, m1Bx, m1By);
M2Touch("sub-2", Microsoft.OpenHarmony.Hosting.OpenHarmonyTouchAction.Up, m1Bx, m1By);
M1Check("second input", m1ContentB.Clicks == 1 && m4Input.Clicks == m1AClicksBefore);

// Frames stay per window too.
int m1AFrames = m2Host.FindSecondaryWindow("sub-1")!.FrameTicks;
int m1BFrames = m1HostB.FrameTicks;
M2FrameEvent("sub-1");
M2FrameEvent("sub-2");
M1Check("frames per window", m2Host.FindSecondaryWindow("sub-1")!.FrameTicks == m1AFrames + 1
    && m1HostB.FrameTicks == m1BFrames + 1);

// The shell's own Closed report for one session drops exactly that managed window: the payload
// carries the surface id, so the other child and the primary window are untouched.
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Closed,
    "{\"id\":431,\"x\":0,\"y\":0,\"w\":0,\"h\":0,\"surfaceId\":\"sub-2\"}");
M1Check("shell closed targets sub-2", m2Host.FindSecondaryWindow("sub-2") is null
    && m1WindowB.Handler is null && m2Application.Windows.Count == 2
    && m2Host.FindSecondaryWindow("sub-1") is not null);

// The freed session id is reusable; closing the reopened window through the app-level path asks
// the shell for exactly that session ("surfaceId":"sub-2") and leaves sub-1 live.
m1Requests.Clear();
M4InputContent m1ContentC = new("m1-c-label", "m1-c-entry", "m1-c-button");
Window m1WindowC = new(m1ContentC.Page);
m2Application.OpenWindow(m1WindowC);
bool m1ReopenRequested = m1Requests.Count == 1 && m1Requests[0] == "sub-2";
M2Surface("sub-2", Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Created, 640, 480);
bool m1ReopenBound = m2Host.FindSecondaryWindow("sub-2") is not null
    && ReferenceEquals(m2Host.FindSecondaryWindow("sub-2")!.Window, m1WindowC);
m1Commands.Clear();
m2Application.CloseWindow(m1WindowC);
bool m1TargetedClose = m1Commands.Any(entry => entry.StartsWith("5:", StringComparison.Ordinal)
        && entry.Contains("\"surfaceId\":\"sub-2\"", StringComparison.Ordinal))
    && m2Host.FindSecondaryWindow("sub-2") is null
    && m2Host.FindSecondaryWindow("sub-1") is not null
    && m2Application.Windows.Count == 2;
M1Check($"reopen targeted close requested={m1ReopenRequested} bound={m1ReopenBound} close={m1TargetedClose}",
    m1ReopenRequested && m1ReopenBound && m1TargetedClose);

// Capacity: with two sessions live a third OpenWindow is declined, the realized window is
// dropped again (no ghost in Application.Windows) and the live pair is untouched.
m1Requests.Clear();
M4InputContent m1ContentD = new("m1-d-label", "m1-d-entry", "m1-d-button");
Window m1WindowD = new(m1ContentD.Page);
m2Application.OpenWindow(m1WindowD);
M2Surface("sub-2", Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Created, 640, 480);
var m1Overflow = new M2Content("m1-over-label", "m1-over-button");
Window m1WindowE = new(m1Overflow.Page);
int m1WindowsBeforeThird = m2Application.Windows.Count;
m2Application.OpenWindow(m1WindowE);
M1Check("capacity declines third", m2Handler.LastOpenWindowResult == OpenHarmonyOpenWindowResult.NotSupported
    && m1WindowE.Handler is null && m2Application.Windows.Count == m1WindowsBeforeThird
    && m2Host.SecondaryWindows.Count == 2 && m1Requests.Count == 1);

// Cleanup: close sub-2, leave the M4 sub-1 session live for the L2 section below.
m2Application.CloseWindow(m1WindowD);
M1Check("cleanup", m2Host.SecondaryWindows.Count == 1
    && m2Host.FindSecondaryWindow("sub-1") is not null
    && m2Application.Windows.Count == 2);
m2Host.SubWindowSurfaceRequester = null;
OpenHarmonySubWindow.CommandSender = null;

// Shell source pins: every pack carries the session registry (map keyed by surface id), the
// bounded create, the per-session state payload/events and the targeted close; all four packs
// stay byte-identical.
bool m1ShellPinsOk = true;
string m1ShellFirst = string.Empty;
foreach (string m1ShellVersion in new[] { "1.0.0-preview.22", "1.0.0-preview.23", "1.0.0-preview.24", "1.0.0-preview.28" })
{
    string m1Index = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{m1ShellVersion}/templates/ets/pages/Index.ets") is { } m1IndexPath
        ? File.ReadAllText(m1IndexPath) : string.Empty;
    if (m1ShellFirst.Length == 0)
    {
        m1ShellFirst = m1Index;
    }
    else
    {
        m1ShellPinsOk &= m1Index == m1ShellFirst;
    }
    m1ShellPinsOk &= m1Index.Contains("interface SubWindowSession")
        && m1Index.Contains("const SUB_WINDOW_DEFAULT_MAX: number = 2")
        && m1Index.Contains("const SUB_WINDOW_MAX: number = 8")
        && m1Index.Contains("const SUB_WINDOW_MIN_MAX: number = 2")
        && m1Index.Contains("const SUB_WINDOW_MAX_ENV: string = 'OHOS_SUBWINDOW_MAX'")
        && m1Index.Contains("const SUB_WINDOW_MAX_RAWFILE: string = 'ohos-subwindow-max.txt'")
        && m1Index.Contains("private subWindowLimit: number = SUB_WINDOW_DEFAULT_MAX")
        && m1Index.Contains("this.subWindows.size + this.subWindowCreating.size >= this.subWindowLimit")
        && m1Index.Contains("private readSubWindowLimitFromRawFile(")
        && m1Index.Contains("private resolveSubWindowLimitEnv(")
        && m1Index.Contains("this.applySubWindowLimit(this.readSubWindowLimitFromRawFile());")
        && m1Index.Contains("private subWindows: Map<string, SubWindowSession>")
        && m1Index.Contains("private subWindowCreating: Map<string, boolean>")
        && m1Index.Contains("this.subWindows.set(surfaceId, session)")
        && m1Index.Contains("this.subWindows.delete(session.surfaceId)")
        && m1Index.Contains("private findSubWindowSession(")
        && m1Index.Contains("private liveSubWindowSession(")
        && m1Index.Contains("private subWindowClosedPayload(")
        && m1Index.Contains("this.notifySubWindowEvent(SUB_EVENT_CLOSED, this.subWindowStatePayload(session))")
        && m1Index.Contains("close one before opening another")
        && !m1Index.Contains("const SUB_WINDOW_MAX: number = 2");
}
string m1SliceHostSource = FindHostSource("OpenHarmonyMauiAppHost.cs") is { } m1SliceHostPath
    ? File.ReadAllText(m1SliceHostPath) : string.Empty;
string m1SliceSubSource = FindHostSource("OpenHarmonySubWindow.cs") is { } m1SliceSubPath
    ? File.ReadAllText(m1SliceSubPath) : string.Empty;
string m1SampleSource = FindHostSource("test/hello-maui-app/App.cs") is { } m1SamplePath
    ? File.ReadAllText(m1SamplePath) : string.Empty;
bool m1SlicePinsOk = m1SliceHostSource.Contains("DefaultMaxManagedSubWindows = 2")
    && m1SliceHostSource.Contains("MaxSupportedManagedSubWindows = 8")
    && m1SliceHostSource.Contains("\"OHOS_SUBWINDOW_MAX\"")
    && m1SliceHostSource.Contains("_awaitingWindows.Count + _secondaryWindows.Count >= MaxManagedSubWindows")
    && m1SliceHostSource.Contains("OpenHarmonySubWindow.Close(shellCloseId)")
    && m1SliceSubSource.Contains("public static bool Close(string windowId)")
    && m1SliceSubSource.Contains("writer.WriteString(\"surfaceId\", windowId ?? string.Empty)");
M1Check("shell source", m1ShellPinsOk && m1ShellFirst.Length > 0);
M1Check("slice source", m1SlicePinsOk);
// N-SUBWINDOW: the demo app follows the same switch so the device round can raise the pairing
// with a deep link (?max=4 / app://subwindow/max/4) instead of a rebuild.
M1Check("n-subwindow switch", m1SlicePinsOk
    && m1SampleSource.Contains("private static int MaxManagedChildren()")
    && m1SampleSource.Contains("ApplySubWindowMaxFromUri")
    && m1SampleSource.Contains("\"OHOS_SUBWINDOW_MAX\"")
    && m1SampleSource.Contains("subwindow max switch: OHOS_SUBWINDOW_MAX="));

if (m1Failures > 0)
{
    throw new InvalidOperationException(
        $"{m1Failures} MULTIWINDOW-L3 M1 assertion(s) failed (the two managed subwindow sessions, their targeted close or the capacity bound regressed)");
}

// ---------------------------------------------------------------------------------------------
// MULTIWINDOW-L3 M2: the per-window identity handshake and the lifecycle closure. The managed
// side validates every child-page claim against the session it requested (a ready that arrived
// before the shell's Created is buffered and answered when the Created validates its generation;
// an unknown id is closed; a retired generation is ignored) and answers op 7; the app host
// stops/resumes each child exactly once and bounds focus to the addressed window. The shell half
// (own-window-name identity via UIContext.getWindowName, the per-child claim table, the op 7
// validation and the ack-gated XComponent mount) is pinned in every pack's Index/SubWindow.ets,
// and the slice half in maui-ohos.
int m2idFailures = 0;
void M2IdCheck(string name, bool ok)
{
    Console.WriteLine($"[verify] m2id {name} assert={ok}");
    if (!ok)
    {
        m2idFailures++;
    }
}

List<string> m2idCommands = new();
OpenHarmonySubWindow.CommandSender = (op, payload) => { m2idCommands.Add($"{op}:{payload}"); return true; };

// 1) Out-of-order identity: the page reports ready before the shell's Created report (device
// order: loadContent runs before showWindow). The claim is buffered, then the Created validates
// its generation and the managed side answers the handshake exactly once.
OpenHarmonySubWindow.CreateManagedSurface("sub-a", "maui-child", 0, 0, 100, 100, null);
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.PageReady,
    "{\"id\":900,\"surfaceId\":\"sub-a\",\"gen\":7,\"name\":\"ohos_dotnet_subwindow__sub-a.g7\",\"status\":0}");
bool m2idBuffered = OpenHarmonySubWindow.SessionCount == 0 && OpenHarmonySubWindow.PendingClaimCount == 1;
m2idCommands.Clear();
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Created,
    "{\"id\":900,\"surfaceId\":\"sub-a\",\"gen\":7}");
bool m2idAcked = m2idCommands.Count(entry => entry.StartsWith("7:", StringComparison.Ordinal)
        && entry.Contains("\"surfaceId\":\"sub-a\"", StringComparison.Ordinal)
        && entry.Contains("\"id\":900", StringComparison.Ordinal)
        && entry.Contains("\"gen\":7", StringComparison.Ordinal)) == 1
    && OpenHarmonySubWindow.SessionCount == 1 && OpenHarmonySubWindow.PendingClaimCount == 0
    && OpenHarmonySubWindow.IsSessionReady("sub-a") && OpenHarmonySubWindow.GenerationOf("sub-a") == 7
    && OpenHarmonySubWindow.ShellWindowIdOf("sub-a") == 900;
M2IdCheck($"out-of-order buffered={m2idBuffered} acked={m2idAcked}", m2idBuffered && m2idAcked);

// 2) A duplicate ready claim for the live session is idempotent: no second ack.
m2idCommands.Clear();
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.PageReady,
    "{\"id\":900,\"surfaceId\":\"sub-a\",\"gen\":7,\"status\":0}");
M2IdCheck("duplicate ready no re-ack", m2idCommands.Count(entry => entry.StartsWith("7:", StringComparison.Ordinal)) == 0
    && OpenHarmonySubWindow.IsSessionReady("sub-a"));

// 3) An unknown id (never requested, never created) is closed fail-closed, never bound.
m2idCommands.Clear();
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.PageReady,
    "{\"id\":901,\"surfaceId\":\"sub-zzz\",\"gen\":1,\"status\":0}");
M2IdCheck("unknown id closed fail-closed",
    m2idCommands.Count(entry => entry.StartsWith("5:", StringComparison.Ordinal)
        && entry.Contains("\"surfaceId\":\"sub-zzz\"", StringComparison.Ordinal)) == 1
    && m2idCommands.All(entry => !entry.StartsWith("7:", StringComparison.Ordinal))
    && OpenHarmonySubWindow.SessionCount == 1 && !OpenHarmonySubWindow.IsSessionReady("sub-zzz"));

// 4) A ready claim from a retired generation never readies the live session.
OpenHarmonySubWindow.CreateManagedSurface("sub-b", "maui-child", 0, 0, 100, 100, null);
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Created,
    "{\"id\":902,\"surfaceId\":\"sub-b\",\"gen\":2}");
m2idCommands.Clear();
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.PageReady,
    "{\"id\":902,\"surfaceId\":\"sub-b\",\"gen\":1,\"status\":0}");
bool m2idStaleDeclined = !OpenHarmonySubWindow.IsSessionReady("sub-b")
    && m2idCommands.All(entry => !entry.StartsWith("7:", StringComparison.Ordinal));
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.PageReady,
    "{\"id\":902,\"surfaceId\":\"sub-b\",\"gen\":2,\"status\":0}");
bool m2idCurrentAccepted = OpenHarmonySubWindow.IsSessionReady("sub-b")
    && m2idCommands.Count(entry => entry.StartsWith("7:", StringComparison.Ordinal)
        && entry.Contains("\"surfaceId\":\"sub-b\"", StringComparison.Ordinal)
        && entry.Contains("\"gen\":2", StringComparison.Ordinal)) == 1;
M2IdCheck($"stale declined={m2idStaleDeclined} current accepted={m2idCurrentAccepted}",
    m2idStaleDeclined && m2idCurrentAccepted);

// 5) Two sessions coexist and the legacy single-child mirror tracks the last created one.
M2IdCheck("sessions coexist", OpenHarmonySubWindow.SessionCount == 2
    && OpenHarmonySubWindow.CurrentSurfaceId == "sub-b"
    && OpenHarmonySubWindow.SurfaceId == "sub-b");
OpenHarmonySubWindow.Close("sub-a");
OpenHarmonySubWindow.Close("sub-b");
m2idCommands.Clear();

// 6) Lifecycle: the app host carries sub-1 (the M4 input window) and a new sub-2. The M4 checks
// left sub-1 stopped, so normalize it first; then a per-session suspend stops each child exactly
// once, a duplicate report is a no-op and the primary window is untouched.
List<string> m2idRequests = new();
m2Host.SubWindowSurfaceRequester = id => { m2idRequests.Add(id); return true; };
M4InputContent m2idContentB = new("m2id-b-label", "m2id-b-entry", "m2id-b-button");
Window m2idWindowB = new(m2idContentB.Page);
m2Application.OpenWindow(m2idWindowB);
M2Surface("sub-2", Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Created, 660, 440);
OpenHarmonyWindowHost? m2idHostA = m2Host.FindSecondaryWindow("sub-1");
OpenHarmonyWindowHost? m2idHostB = m2Host.FindSecondaryWindow("sub-2");
bool m2idTwoWindows = m2idRequests.Count == 1 && m2idRequests[0] == "sub-2"
    && m2idHostA is not null && m2idHostB is not null
    && ReferenceEquals(m2idHostB!.Window, m2idWindowB) && m2Application.Windows.Count == 3;
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Resumed,
    "{\"surfaceId\":\"sub-1\"}");
int m2idAStop = m2idHostA!.StoppedCount;
int m2idBStop = m2idHostB!.StoppedCount;
int m2idAResume = m2idHostA.ResumedCount;
int m2idBResume = m2idHostB.ResumedCount;
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Suspended,
    "{\"surfaceId\":\"sub-1\"}");
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Suspended,
    "{\"surfaceId\":\"sub-2\"}");
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Suspended,
    "{\"surfaceId\":\"sub-1\"}");
M2IdCheck("lifecycle suspend each once", m2idTwoWindows
    && m2idHostA.StoppedCount == m2idAStop + 1 && m2idHostB.StoppedCount == m2idBStop + 1
    && m2idHostA.IsStopped && m2idHostB.IsStopped
    && ReferenceEquals(m2Host.Window, m2MainWindow));

// 7) A duplicate resume is a no-op too; each child resumes exactly once.
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Resumed,
    "{\"surfaceId\":\"sub-1\"}");
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Resumed,
    "{\"surfaceId\":\"sub-2\"}");
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Resumed,
    "{\"surfaceId\":\"sub-1\"}");
M2IdCheck("lifecycle resume each once",
    m2idHostA.ResumedCount == m2idAResume + 1 && m2idHostB.ResumedCount == m2idBResume + 1
    && !m2idHostA.IsStopped && !m2idHostB.IsStopped);

// 8) Focus switch A -> B moves only the addressed windows. Normalize first (B deactivated, A
// activated), then the switch drives exactly the two events and the counters prove isolation.
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Inactive,
    "{\"surfaceId\":\"sub-2\"}");
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Active,
    "{\"surfaceId\":\"sub-1\"}");
int m2idAActivated = m2idHostA.ActivatedCount;
int m2idADeactivated = m2idHostA.DeactivatedCount;
int m2idBActivated = m2idHostB.ActivatedCount;
int m2idBDeactivated = m2idHostB.DeactivatedCount;
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Inactive,
    "{\"surfaceId\":\"sub-1\"}");
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Active,
    "{\"surfaceId\":\"sub-2\"}");
M2IdCheck("lifecycle focus isolation",
    m2idHostA.DeactivatedCount == m2idADeactivated + 1 && m2idHostA.ActivatedCount == m2idAActivated
    && m2idHostB.ActivatedCount == m2idBActivated + 1 && m2idHostB.DeactivatedCount == m2idBDeactivated);

// 9) Focus events while suspended are ignored (they must not clear the stopped state or deliver
// an event the matching resume owns) - the duplicate-Stopped door the M1 host left open.
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Suspended,
    "{\"surfaceId\":\"sub-1\"}");
int m2idAActivatedStopped = m2idHostA.ActivatedCount;
int m2idAStopped2 = m2idHostA.StoppedCount;
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Active,
    "{\"surfaceId\":\"sub-1\"}");
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Suspended,
    "{\"surfaceId\":\"sub-1\"}");
bool m2idFocusWhileStopped = m2idHostA.IsStopped
    && m2idHostA.ActivatedCount == m2idAActivatedStopped
    && m2idHostA.StoppedCount == m2idAStopped2;
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Resumed,
    "{\"surfaceId\":\"sub-1\"}");
M2IdCheck("lifecycle late active while stopped",
    m2idFocusWhileStopped && !m2idHostA.IsStopped && m2idHostA.ResumedCount == m2idAResume + 2);

// 10) The shell's targeted Closed report drops exactly the named child; the sibling survives.
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Closed,
    "{\"id\":2,\"x\":0,\"y\":0,\"w\":0,\"h\":0,\"surfaceId\":\"sub-2\"}");
M2IdCheck("lifecycle targeted close isolation", m2Host.FindSecondaryWindow("sub-2") is null
    && m2Host.FindSecondaryWindow("sub-1") is not null && m2Application.Windows.Count == 2);

// 11) A late ready claim for the closed id is closed fail-closed (it does not recreate the
// session or the window), and a late Closed/Active for it cannot revive anything either.
m2idCommands.Clear();
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.PageReady,
    "{\"id\":2,\"surfaceId\":\"sub-2\",\"gen\":2,\"status\":0}");
M2IdCheck("lifecycle late after close fail-closed",
    m2idCommands.Count(entry => entry.StartsWith("5:", StringComparison.Ordinal)
        && entry.Contains("\"surfaceId\":\"sub-2\"", StringComparison.Ordinal)) == 1
    && m2idCommands.All(entry => !entry.StartsWith("7:", StringComparison.Ordinal))
    && m2Host.FindSecondaryWindow("sub-2") is null
    && OpenHarmonySubWindow.SessionCount == 0 && OpenHarmonySubWindow.PendingClaimCount == 0);

// 12) Reopen: the freed id gets a new generation. A ready claim from the retired generation is
// ignored; the new generation readies the session and is acked exactly once.
m2idRequests.Clear();
M4InputContent m2idContentC = new("m2id-c-label", "m2id-c-entry", "m2id-c-button");
Window m2idWindowC = new(m2idContentC.Page);
m2Application.OpenWindow(m2idWindowC);
M2Surface("sub-2", Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Created, 640, 480);
bool m2idReopened = m2idRequests.Count == 1 && m2idRequests[0] == "sub-2"
    && ReferenceEquals(m2Host.FindSecondaryWindow("sub-2")!.Window, m2idWindowC);
m2idCommands.Clear();
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Created,
    "{\"id\":910,\"surfaceId\":\"sub-2\",\"gen\":9}");
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.PageReady,
    "{\"id\":910,\"surfaceId\":\"sub-2\",\"gen\":3,\"status\":0}");
bool m2idReopenStale = !OpenHarmonySubWindow.IsSessionReady("sub-2")
    && m2idCommands.All(entry => !entry.StartsWith("7:", StringComparison.Ordinal));
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.PageReady,
    "{\"id\":910,\"surfaceId\":\"sub-2\",\"gen\":9,\"status\":0}");
bool m2idReopenFresh = OpenHarmonySubWindow.IsSessionReady("sub-2")
    && OpenHarmonySubWindow.GenerationOf("sub-2") == 9
    && m2idCommands.Count(entry => entry.StartsWith("7:", StringComparison.Ordinal)
        && entry.Contains("\"gen\":9", StringComparison.Ordinal)) == 1;
M2IdCheck($"lifecycle reopen new generation bound={m2idReopened} stale={m2idReopenStale} fresh={m2idReopenFresh}",
    m2idReopened && m2idReopenStale && m2idReopenFresh);
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Closed,
    "{\"id\":910,\"x\":0,\"y\":0,\"w\":0,\"h\":0,\"surfaceId\":\"sub-2\"}");

// 13) Churn x20: each create/ready/close cycle is a fresh generation with exactly one ack and no
// residue; the requested/session/pending tables return to empty.
int m2idChurnAcks = 0;
bool m2idChurnClean = true;
for (int m2idChurn = 0; m2idChurn < 20; m2idChurn++)
{
    int m2idGeneration = m2idChurn + 1;
    int m2idShellId = 5000 + m2idChurn;
    OpenHarmonySubWindow.CreateManagedSurface("sub-churn", "maui-child", 0, 0, 100, 100, null);
    m2idCommands.Clear();
    OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Created,
        $"{{\"id\":{m2idShellId},\"surfaceId\":\"sub-churn\",\"gen\":{m2idGeneration}}}");
    OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.PageReady,
        $"{{\"id\":{m2idShellId},\"surfaceId\":\"sub-churn\",\"gen\":{m2idGeneration},\"status\":0}}");
    m2idChurnAcks += m2idCommands.Count(entry => entry.StartsWith("7:", StringComparison.Ordinal));
    m2idChurnClean &= OpenHarmonySubWindow.IsSessionReady("sub-churn")
        && OpenHarmonySubWindow.GenerationOf("sub-churn") == m2idGeneration;
    OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Closed,
        $"{{\"id\":{m2idShellId},\"surfaceId\":\"sub-churn\"}}");
    m2idChurnClean &= OpenHarmonySubWindow.SessionCount == 0 && OpenHarmonySubWindow.PendingClaimCount == 0;
}
M2IdCheck($"churn x20 handshakes acked={m2idChurnAcks}", m2idChurnAcks == 20 && m2idChurnClean);
OpenHarmonySubWindow.CommandSender = null;
m2Host.SubWindowSurfaceRequester = null;

// 14) Shell source pins: every pack carries the deterministic identity handshake (own window
// name, claim table, op 7 validation, ack-gated mount, generation in the child name, session
// liveness on every callback) and the four packs stay byte-identical.
bool m2idShellPinsOk = true;
string m2idShellFirst = string.Empty;
string m2idPageFirst = string.Empty;
foreach (string m2idShellVersion in new[] { "1.0.0-preview.22", "1.0.0-preview.23", "1.0.0-preview.24", "1.0.0-preview.28" })
{
    string m2idIndex = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{m2idShellVersion}/templates/ets/pages/Index.ets") is { } m2idIndexPath
        ? File.ReadAllText(m2idIndexPath) : string.Empty;
    string m2idPage = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{m2idShellVersion}/templates/ets/pages/SubWindow.ets") is { } m2idPagePath
        ? File.ReadAllText(m2idPagePath) : string.Empty;
    if (m2idShellFirst.Length == 0)
    {
        m2idShellFirst = m2idIndex;
        m2idPageFirst = m2idPage;
    }
    else
    {
        m2idShellPinsOk &= m2idIndex == m2idShellFirst;
        m2idShellPinsOk &= m2idPage == m2idPageFirst;
    }
    m2idShellPinsOk &= m2idIndex.Contains("const SUB_CMD_IDENTITY: number = 7")
        && m2idIndex.Contains("const SUB_WINDOW_CLAIM_KEY: string = 'ohos_dotnet_subwindow_claim'")
        && m2idIndex.Contains("const SUB_WINDOW_IDENTITY_KEY: string = 'ohos_dotnet_subwindow_identity'")
        && m2idIndex.Contains("const SUB_WINDOW_GENERATION_SEPARATOR: string = '.g'")
        && m2idIndex.Contains("private subWindowChildName(")
        && m2idIndex.Contains("private confirmSubWindowIdentity(")
        && m2idIndex.Contains("private publishSubWindowClaim(")
        && m2idIndex.Contains("private withdrawSubWindowClaim(")
        && m2idIndex.Contains("private clearSubWindowIdentity(")
        && m2idIndex.Contains("private subWindowRefPayload(")
        && m2idIndex.Contains("ack.gen === session.generation")
        && m2idIndex.Contains("claimName: childName")
        && m2idIndex.Contains("if (this.subWindows.get(surfaceId) === session) {")
        && m2idIndex.Contains("this.notifySubWindowEvent(op, this.subWindowRefPayload(session))")
        && m2idIndex.Contains("this.withdrawSubWindowClaim(session)")
        && m2idIndex.Contains("op !== SUB_CMD_IDENTITY");
    m2idShellPinsOk &= m2idPage.Contains("getUIContext().getWindowName()")
        && m2idPage.Contains("const SUB_WINDOW_GENERATION_SEPARATOR: string = '.g'")
        && m2idPage.Contains("private findSubWindowClaim(")
        && m2idPage.Contains("private onIdentityAck()")
        && m2idPage.Contains("@StorageLink('ohos_dotnet_subwindow_identity')")
        && m2idPage.Contains("identityConfirmed: boolean = false")
        && m2idPage.Contains("identityRejected: boolean = false")
        && m2idPage.Contains("this.surfaceId.length > 0 && this.identityConfirmed")
        && m2idPage.Contains("no matching shell claim for surface=")
        && m2idPage.Contains("subwindow identity confirmed:")
        && m2idPage.Contains("!this.windowIsOwn")
        && m2idPage.Contains("this.windowIsOwn = this.ownName.length > 0");
}
M2IdCheck("shell source", m2idShellPinsOk && m2idShellFirst.Length > 0 && m2idPageFirst.Length > 0);

// 15) Slice source pins: the managed session registry, the buffered claim, the identity ack and
// the stopped-window focus guard.
string m2idSlideHostSource = FindHostSource("OpenHarmonyWindowHost.cs") is { } m2idSlideHostPath
    ? File.ReadAllText(m2idSlideHostPath) : string.Empty;
string m2idSlideSubSource = FindHostSource("OpenHarmonySubWindow.cs") is { } m2idSlideSubPath
    ? File.ReadAllText(m2idSlideSubPath) : string.Empty;
string m2idHostBridgeSource = FindHostSource("src/OpenHarmonyHost/host_napi.cpp") is { } m2idHostBridgePath
    ? File.ReadAllText(m2idHostBridgePath) : string.Empty;
M2IdCheck("slice source", m2idSlideSubSource.Contains("public const int IdentityCommand = 7")
    && m2idSlideSubSource.Contains("private static readonly Dictionary<string, SurfaceSession> s_sessions")
    && m2idSlideSubSource.Contains("private static readonly HashSet<string> s_requestedSurfaces")
    && m2idSlideSubSource.Contains("private static void UpsertSessionLocked(")
    && m2idSlideSubSource.Contains("private static void CloseSessionLocked(")
    && m2idSlideSubSource.Contains("private static bool SendIdentityAck(")
    && m2idSlideSubSource.Contains("private static bool SendSessionClose(")
    && m2idSlideSubSource.Contains("s_pendingClaims[surfaceId] = new PendingClaim(")
    && m2idSlideSubSource.Contains("subwindow identity rejected: ")
    && m2idSlideHostSource.Contains("if (window is null || _stopped)")
    && m2idSlideHostSource.Contains("if (window is null || _stopped || !_activated)")
    && m2idHostBridgeSource.Contains("constexpr int kSubWindowLastOp = 7;")
    && m2idHostBridgeSource.Contains("if (op < 0 || op > kSubWindowLastOp)"));

if (m2idFailures > 0)
{
    throw new InvalidOperationException(
        $"{m2idFailures} MULTIWINDOW-L3 M2 assertion(s) failed (the identity handshake or the two-window lifecycle closure regressed)");
}

// ---------------------------------------------------------------------------------------------
// MULTIWINDOW-L2: the subwindow's ArkWeb second host. The managed half is the window-scoped
// OpenHarmonyChildWeb pool (transport + ready gate + event routing); the shell half is the child
// page's subWeb* host (pages/SubWindow.ets). The checks pin the pool semantics, the window
// routing of a real WebView through a real secondary window, the primary pool's isolation and
// the four-pack shell/host/slice source contract.
int l2Failures = 0;
void L2Check(string name, bool ok)
{
    Console.WriteLine($"[verify] l2 {name} assert={ok}");
    if (!ok)
    {
        l2Failures++;
    }
}

// The child pool is a process-wide static; clear it through the same reflective seam the
// OpenHarmonyOverlays drills use, so this section starts from a known state.
FieldInfo l2ChildHostsField = typeof(Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb)
    .GetField("s_hosts", BindingFlags.NonPublic | BindingFlags.Static)
    ?? throw new InvalidOperationException("OpenHarmonyChildWeb.s_hosts was not found; the L2 pool drill needs the state seam");
void L2ClearPool() => ((System.Collections.IDictionary)l2ChildHostsField.GetValue(null)!).Clear();
L2ClearPool();

var l2ChildCommands = new List<string>();
Action<string, string, string?> l2OnChildCommand = (id, op, arg) => l2ChildCommands.Add($"{id}|{op}|{arg}");
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.CommandSent += l2OnChildCommand;
var l2ChildEvents = new List<string>();
Action<string, int, string, string> l2OnChildEvent = (id, slot, state, url) => l2ChildEvents.Add($"{id}|{slot}|{state}|{url}");
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.PageEvent += l2OnChildEvent;

// Slot pool: first-free claims below MaxOverlays, owner-checked release, refusal when full, and
// no readiness before the child page advertises its capacity.
var l2OwnerA = new MultiOverlayFakeOwner("l2-a");
var l2OwnerB = new MultiOverlayFakeOwner("l2-b");
int l2ChildA = Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.Acquire("sub-1", l2OwnerA);
int l2ChildB = Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.Acquire("sub-1", l2OwnerA);
int l2ChildC = Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.Acquire("sub-1", l2OwnerB);
L2Check("pool", l2ChildA == 0 && l2ChildB == 1 && l2ChildC == -1
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsClaimedBy("sub-1", 0, l2OwnerA)
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsClaimedBy("sub-1", 1, l2OwnerB)
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsReady("sub-1")
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsApplicable(Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.PrimaryWindowId)
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.PrimaryWindowId == OpenHarmonyWindowSurface.PrimaryWindowId);

// Commands before the capacity advertisement are queued (and observed); the advertisement marks
// the host ready and flushes them in order.
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.Command("sub-1", "load",
    Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.Tag(l2ChildA, "https://example.test/a"));
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.Command("sub-1", "frame",
    Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.Tag(l2ChildA, "0\n0\n700\n500"));
L2Check("queue", l2ChildCommands.Count == 2
    && l2ChildCommands[0] == "sub-1|load|s0\nhttps://example.test/a"
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.PendingCount("sub-1") == 2
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.GetCapacity("sub-1") == 0);
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.CompleteState("w:sub-1|capacity|2", "");
L2Check("ready flush", Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsReady("sub-1")
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.GetCapacity("sub-1") == 2
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.PendingCount("sub-1") == 0
    && l2ChildCommands.Count == 2);

// Events route by window and slot; a second window's capacity never touches the first.
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.CompleteState("w:sub-1|s0|finished", "https://example.test/a");
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.CompleteState("w:sub-2|capacity|1", "");
L2Check("event route", l2ChildEvents.Count == 1
    && l2ChildEvents[0] == "sub-1|0|finished|https://example.test/a"
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsReady("sub-2")
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.PendingCount("sub-1") == 0);

// The capacity wire: the subwindow page emits the count inside the state
// ("w:<win>|capacity|<n>"), and the URL-carried variant (the primary page's shape, which the
// first device round's shell sent) must not be dropped silently either - that mismatch left
// the child pool unready and the queued child commands unflushed on the device.
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.CompleteState("w:sub-9|capacity|2", "");
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.CompleteState("w:sub-8|capacity", "1");
bool l2CapStateOk = Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsReady("sub-9")
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.GetCapacity("sub-9") == 2;
bool l2CapUrlOk = Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsReady("sub-8")
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.GetCapacity("sub-8") == 1;
L2Check($"capacity wire state={l2CapStateOk} url={l2CapUrlOk}", l2CapStateOk && l2CapUrlOk);

// A "w:main|..." tag is not a child host event: the parser must fail closed instead of letting
// the primary window's handlers be addressed through the child channel (SEC-SCAN-6).
bool l2PrimaryTagRejected = !Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.TryParseState(
        "w:main|s0|finished", out _, out _)
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.TryParseState(
        "w:|s0|finished", out _, out _);
L2Check("primary tag rejected", l2PrimaryTagRejected);

// The primary/unknown window keeps the historical transport byte-for-byte; a secondary window
// never touches it.
var l2PrimaryTransport = new List<string>();
Action<string, string?> l2OnPrimaryCommand = (op, arg) => l2PrimaryTransport.Add($"{op}|{arg}");
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.WebCommandSent += l2OnPrimaryCommand;
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.CommandForWindow(Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.PrimaryWindowId, "hide", "s1");
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.CommandForWindow(null, "hide", "s0");
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.CommandForWindow("sub-1", "hide", "s1");
bool l2TransportOk = l2PrimaryTransport.Count == 2 && l2PrimaryTransport[0] == "hide|s1"
    && l2PrimaryTransport[1] == "hide|s0"
    && l2ChildCommands.Count == 3 && l2ChildCommands[^1] == "sub-1|hide|s1";
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.WebCommandSent -= l2OnPrimaryCommand;
L2Check("transport", l2TransportOk);

// Release destroys the shell slot (all child slots are dynamic) and frees the claim.
bool l2ReleaseDestroy = Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.Release("sub-1", l2ChildA, l2OwnerA);
L2Check("release", l2ReleaseDestroy
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsClaimed("sub-1", l2ChildA)
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.Release("sub-1", l2ChildB, l2OwnerB)
    && l2ChildCommands.Contains("sub-1|slot|destroy\n0"));
L2ClearPool();

// --- integration: a real WebView inside a real secondary window claims the child pool only ----
if (m2Host.FindSecondaryWindow("sub-1") is { } l2Prior && l2Prior.Window is Microsoft.Maui.Controls.Window l2PriorWindow)
{
    // The M4 input window is still open at this point; close it so the deferred allocation can
    // hand out sub-1 again (session ids are lowest-free).
    m2Application.CloseWindow(l2PriorWindow);
}
// SEC-SCAN-6 C: the close hook dropped the closed window's a11y shadow frame (built from
// m4Input.Page by the L2-a drills above), so the id carries no dead tree into its next user.
L2Check("close drops a11y frame", OpenHarmonyAccessibility.NodesForWindow("sub-1").Count == 0);
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.SetCapacity("sub-1", 2);
List<string> l2SurfaceRequests = new();
m2Host.SubWindowSurfaceRequester = id =>
{
    l2SurfaceRequests.Add(id);
    return true;
};
L2WebContent l2Content = new("l2-web-page");
Window l2Window = new(l2Content.Page);
m2Application.OpenWindow(l2Window);
bool[] l2PrimaryUsedBefore = (((bool[]?)multiOvlUsedField.GetValue(null)) ?? Array.Empty<bool>()).ToArray();
M2Surface("sub-1", Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Created, 700, 500);
OpenHarmonyWindowHost? l2WindowHost = m2Host.FindSecondaryWindow("sub-1");
L2Check("window bound", l2WindowHost is not null && ReferenceEquals(l2WindowHost!.Window, l2Window)
    && l2SurfaceRequests.Count == 1 && l2SurfaceRequests[0] == "sub-1");

OpenHarmonyWebViewHandler? l2ViewHandler = l2Content.Web.Handler as OpenHarmonyWebViewHandler;
L2Check("child view claim", l2ViewHandler is not null
    && l2ViewHandler!.OverlayWindowId == "sub-1" && l2ViewHandler.OverlaySlot >= 0
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsClaimedBy("sub-1", l2ViewHandler.OverlaySlot, l2ViewHandler)
    && l2ChildCommands.Any(entry => entry.StartsWith($"sub-1|load|s{l2ViewHandler.OverlaySlot}", StringComparison.Ordinal)));
l2Content.Page.Measure(700, 500);
l2Content.Page.Arrange(new Rect(0, 0, 700, 500));
L2Check("child frame", l2ViewHandler is not null
    && l2ChildCommands.Any(entry => entry.StartsWith($"sub-1|frame|s{l2ViewHandler!.OverlaySlot}", StringComparison.Ordinal)));

// The child page's finished event reaches the child WebView only; a primary-tagged event with
// the same slot number never does (the red control for the window filter).
int l2NavBefore = l2Content.NavigatedLog.Count;
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.CompleteWebEvent(
    $"w:sub-1|s{l2ViewHandler!.OverlaySlot}|finished", "https://example.test/child");
// The harness runs more than one app host, and each host subscribes the same static
// OnPageEvent; the assertion is that the child handler was reached (and the last report is the
// routed Success), not the harness's subscription count.
L2Check($"child event routed nav={l2Content.NavigatedLog.Count - l2NavBefore}",
    l2Content.NavigatedLog.Count > l2NavBefore
    && l2Content.NavigatedLog[^1].Contains("Success", StringComparison.Ordinal));
int l2NavAfterChild = l2Content.NavigatedLog.Count;
Microsoft.OpenHarmony.Hosting.OpenHarmonyBridge.CompleteWebEvent(
    $"s{l2ViewHandler!.OverlaySlot}|finished", "https://example.test/main");
L2Check("primary event isolated", l2Content.NavigatedLog.Count == l2NavAfterChild);

// The primary pool is exactly as it was before the child WebView connected: the child claim
// never occupies a primary overlay slot (main-window zero regression).
bool[] l2PrimaryUsedAfter = ((bool[]?)multiOvlUsedField.GetValue(null)) ?? Array.Empty<bool>();
L2Check("primary pool untouched", l2PrimaryUsedBefore.SequenceEqual(l2PrimaryUsedAfter)
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsApplicable("main"));

// Closing the managed window releases the child claim and destroys its shell slot (the destroy
// command must arrive from this close, not from the earlier unit drill).
int l2CloseSlot = l2ViewHandler?.OverlaySlot ?? -1;
int l2CloseCommandBase = l2ChildCommands.Count;
m2Application.CloseWindow(l2Window);
bool l2CloseWindow = m2Host.FindSecondaryWindow("sub-1") is null;
bool l2CloseReleased = l2CloseSlot >= 0
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsClaimed("sub-1", l2CloseSlot);
bool l2CloseDestroyed = l2CloseSlot >= 0
    && l2ChildCommands.Skip(l2CloseCommandBase).Contains($"sub-1|slot|destroy\n{l2CloseSlot}");
string l2CloseTail = string.Join(" | ", l2ChildCommands.Skip(Math.Max(0, l2ChildCommands.Count - 3)));
L2Check($"close destroy win={l2CloseWindow} slot={l2CloseSlot} released={l2CloseReleased} destroyed={l2CloseDestroyed} tail={l2CloseTail}",
    l2CloseWindow && l2CloseReleased && l2CloseDestroyed);
// SEC-SCAN-6 C: the close hook dropped the window's child pool state (capacity/pending), so a
// window reusing the id starts not-ready and re-advertises instead of inheriting the stale
// ready state of the page that no longer exists.
bool l2ClosePoolDropped = Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.GetCapacity("sub-1") == 0
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsReady("sub-1")
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.PendingCount("sub-1") == 0;
L2Check("close drops child pool", l2ClosePoolDropped);

// MULTIWINDOW-L3: the child hybrid-invoke codec and dispatch. The subwindow shell tags its
// __hwvInvokeDotNet request ids with the child flag; the managed callback must route them to
// the child window's handler and the primary encoding/decoding must stay byte-for-byte.
bool l2ChildCodecOk = Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.EncodeChildInvokeRequestId(0, 5) == 0x41000005
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.EncodeChildInvokeRequestId(1, 7) == 0x42000007
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.TryDecodeChildInvokeRequestId(0x42000007, out int l2ChildCodecSlot, out int l2ChildCodecSeq)
    && l2ChildCodecSlot == 1 && l2ChildCodecSeq == 7
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.IsChildInvokeRequestId(0x41000005)
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.IsChildInvokeRequestId(0x01000005)
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.TryDecodeChildInvokeRequestId(0x01000005, out _, out _)
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.TryDecodeInvokeRequestId(0x41000005, out _, out _)
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.TryDecodeInvokeRequestId(0x01000005, out int l2PrimaryCodecSlot, out _)
    && l2PrimaryCodecSlot == 0;
L2Check("child invoke codec", l2ChildCodecOk);

// Dispatch: a child-tagged invocation runs on the child-window hybrid that owns the slot (the
// real invoke round trip through the same managed path), and an unclaimed child slot fails
// closed instead of falling back to a primary handler.
if (hybridProbe.Handler is OpenHarmonyHybridWebViewHandler l2ChildHybridHandler)
{
    FieldInfo l2HybridWindowField = typeof(OpenHarmonyHybridWebViewHandler)
        .GetField("_overlayWindowId", BindingFlags.NonPublic | BindingFlags.Instance)
        ?? throw new InvalidOperationException("OpenHarmonyHybridWebViewHandler._overlayWindowId was not found; the child invoke drill needs the window seam");
    FieldInfo l2HybridSlotField = typeof(OpenHarmonyHybridWebViewHandler)
        .GetField("_overlaySlot", BindingFlags.NonPublic | BindingFlags.Instance)
        ?? throw new InvalidOperationException("OpenHarmonyHybridWebViewHandler._overlaySlot was not found; the child invoke drill needs the slot seam");
    string l2HybridWindowBefore = (string)l2HybridWindowField.GetValue(l2ChildHybridHandler)!;
    int l2HybridSlotBefore = (int)l2HybridSlotField.GetValue(l2ChildHybridHandler)!;
    var l2ChildInvokeResults = new Dictionary<int, string>();
    void L2OnChildInvokeResult(int requestId, string payload) => l2ChildInvokeResults[requestId] = payload;
    OpenHarmonyHybridWebViewHandler.HybridInvokeResultSent += L2OnChildInvokeResult;
    try
    {
        l2HybridWindowField.SetValue(l2ChildHybridHandler, "sub-1");
        l2HybridSlotField.SetValue(l2ChildHybridHandler, 1);
        int l2ChildInvokeId = Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.EncodeChildInvokeRequestId(1, 77);
        await OpenHarmonyHybridWebViewHandler.OnHybridInvokeAsync(l2ChildInvokeId, "Echo", "[\"\\\"child\\\"\"]");
        bool l2ChildInvokeOk = l2ChildInvokeResults.TryGetValue(l2ChildInvokeId, out string? l2ChildPayload)
            && PayloadBool(l2ChildPayload, "IsError") == false
            && PayloadString(l2ChildPayload, "Result") == "\"echo:child\"";
        L2Check($"child invoke dispatch result={PayloadString(l2ChildInvokeResults.GetValueOrDefault(l2ChildInvokeId), "Result")}",
            l2ChildInvokeOk);
        int l2ChildMissId = Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.EncodeChildInvokeRequestId(0, 78);
        await OpenHarmonyHybridWebViewHandler.OnHybridInvokeAsync(l2ChildMissId, "Echo", "[]");
        bool l2ChildMissOk = l2ChildInvokeResults.TryGetValue(l2ChildMissId, out string? l2ChildMissPayload)
            && PayloadBool(l2ChildMissPayload, "IsError") == true
            && (PayloadString(l2ChildMissPayload, "ErrorMessage")?.Contains("child HybridWebView", StringComparison.Ordinal) ?? false);
        L2Check("child invoke miss", l2ChildMissOk);
    }
    finally
    {
        OpenHarmonyHybridWebViewHandler.HybridInvokeResultSent -= L2OnChildInvokeResult;
        l2HybridWindowField.SetValue(l2ChildHybridHandler, l2HybridWindowBefore);
        l2HybridSlotField.SetValue(l2ChildHybridHandler, l2HybridSlotBefore);
    }
}
else
{
    L2Check("child invoke dispatch", false);
    L2Check("child invoke miss", false);
}
m2Host.SubWindowSurfaceRequester = null;
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.CommandSent -= l2OnChildCommand;
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.PageEvent -= l2OnChildEvent;

// Source pins: every pack's SubWindow.ets carries the child host (registration probes, pool,
// tagged events, the MULTIWINDOW-L3 hybrid/Blazor asset bridge) and the primary page keeps its
// single sink; the host routes the child marker and the child hybrid-invoke results without a
// new export; the slice routes all three handlers by window and the child invokes by the flag.
bool l2ShellPinsOk = true;
bool l2PackIdentityOk = true;
string l2FirstPageText = string.Empty;
foreach (string l2ShellVersion in new[] { "1.0.0-preview.22", "1.0.0-preview.23", "1.0.0-preview.24", "1.0.0-preview.28" })
{
    string l2Index = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{l2ShellVersion}/templates/ets/pages/Index.ets") is { } l2IndexPath
        ? File.ReadAllText(l2IndexPath) : string.Empty;
    string l2Page = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{l2ShellVersion}/templates/ets/pages/SubWindow.ets") is { } l2PagePath
        ? File.ReadAllText(l2PagePath) : string.Empty;
    l2ShellPinsOk &= l2Index.Contains("registerWebSink") && !l2Index.Contains("registerChildWebSink")
        && l2Index.Contains("ensureWebSlot") && l2Index.Contains("webSlotCreated")
        && l2Page.Contains("import { webview as web_webview } from '@kit.ArkWeb';")
        && l2Page.Contains("registerChildWebSink")
        && l2Page.Contains("registerChildWebEvalSink")
        && l2Page.Contains("typeof host.registerChildWebSink !== 'function'")
        && l2Page.Contains("SUB_WEB_SLOT_MAX")
        && l2Page.Contains("subWebOverlay")
        && l2Page.Contains("childHybridInvokeResponse")
        && l2Page.Contains("registerChildDotNetHost")
        && l2Page.Contains("injectChildBlazorBootstrap")
        && l2Page.Contains("registerChildHybridInvokeResultSink")
        && l2Page.Contains("SUB_HYBRID_ORIGIN")
        && l2Page.Contains("`${SUB_WEB_STATE_PREFIX}${this.surfaceId}|${slotState}`")
        && l2Page.Contains("`capacity|${SUB_WEB_SLOT_MAX}`")
        && l2Page.Contains("completeChildWebEval(requestId, '', 1)");
    if (l2FirstPageText.Length == 0)
    {
        l2FirstPageText = l2Page;
    }
    else
    {
        l2PackIdentityOk &= l2Page == l2FirstPageText;
    }
}
L2Check("shell source", l2ShellPinsOk && l2PackIdentityOk && l2FirstPageText.Length > 0);

string l2HostSource = FindHostSource("src/OpenHarmonyHost/host_napi.cpp") is { } l2HostPath
    ? File.ReadAllText(l2HostPath) : string.Empty;
string l2HostCoreSource = FindHostSource("src/OpenHarmonyHost/openharmony_host.c") is { } l2HostCorePath
    ? File.ReadAllText(l2HostCorePath) : string.Empty;
string l2ExportsSource = FindHostSource("src/OpenHarmonyHost/host-exports.txt") is { } l2ExportsPath
    ? File.ReadAllText(l2ExportsPath) : string.Empty;
int l2ExportCount = l2ExportsSource.Split('\n').Count(line => line.Trim().Length > 0 && !line.StartsWith('#'));
L2Check("host source", l2HostSource.Contains("web_child")
    && l2HostSource.Contains("RegisterChildWebSink") && l2HostSource.Contains("RegisterChildWebEvalSink")
    && l2HostSource.Contains("kChildWebMarker")
    && l2HostSource.Contains("strncmp(effective_op, kChildWebMarker")
    && l2HostSource.Contains("registerChildWebSink\"")
    && l2HostSource.Contains("RegisterChildHybridInvokeResultSink")
    && l2HostSource.Contains("kChildHybridInvokeFlag")
    && l2HostSource.Contains("hybrid_invoke_result_child")
    && l2HostSource.Contains("registerChildHybridInvokeResultSink\"")
    && !l2HostCoreSource.Contains("kChildWebMarker")
    && !l2ExportsSource.Contains("ohos_host_web_command_child")
    && l2ExportCount == 164);   // L2-b adds no export; the L2-a six (attach/status/count/..._for + action listener) bring the contract from 157 to 163; the L3 a11y close-hook release adds ohos_host_accessibility_release_for (164) and the L3 child invoke result rides the existing ohos_host_hwv_invoke_result

string l2SliceView = FindHostSource("OpenHarmonyWebViewHandler.cs") is { } l2ViewPath
    ? File.ReadAllText(l2ViewPath) : string.Empty;
string l2SliceHosting = FindHostSource("OpenHarmonyMauiAppHost.cs") is { } l2HostingPath
    ? File.ReadAllText(l2HostingPath) : string.Empty;
string l2SliceWindowHost = FindHostSource("OpenHarmonyWindowHost.cs") is { } l2WindowHostPath
    ? File.ReadAllText(l2WindowHostPath) : string.Empty;
string l2SliceHybrid = FindHostSource("OpenHarmonyHybridWebViewHandler.cs") is { } l2HybridPath
    ? File.ReadAllText(l2HybridPath) : string.Empty;
string l2SliceBlazor = FindHostSource("OpenHarmonyBlazorWebViewHandler.cs") is { } l2BlazorPath
    ? File.ReadAllText(l2BlazorPath) : string.Empty;
string l2HostingSource = FindHostSource("src/Microsoft.OpenHarmony.Hosting/OpenHarmonyChildWeb.cs") is { } l2ChildWebPath
    ? File.ReadAllText(l2ChildWebPath) : string.Empty;
string l2OverlaysSource = FindHostSource("src/Microsoft.OpenHarmony.Hosting/OpenHarmonyOverlays.cs") is { } l2OverlaysPath
    ? File.ReadAllText(l2OverlaysPath) : string.Empty;
int l2TableStamp = l2SliceHosting.IndexOf("s_windowIdTable.TryGetValue(window, out WindowIdBox? box)", StringComparison.Ordinal);
int l2HandlerStamp = l2SliceHosting.IndexOf("window.Handler is OpenHarmonyWindowHandler handler)", StringComparison.Ordinal);
int l2AdoptStamp = l2SliceWindowHost.IndexOf("OpenHarmonyMauiAppHost.SetWindowId(_window, WindowId);", StringComparison.Ordinal);
int l2AdoptConnect = l2SliceWindowHost.IndexOf("OpenHarmonyHandlerConnector.ConnectTree(_window);", StringComparison.Ordinal);
L2Check("slice source", l2TableStamp >= 0 && l2HandlerStamp >= 0 && l2TableStamp < l2HandlerStamp
    && l2AdoptStamp >= 0 && l2AdoptConnect >= 0 && l2AdoptStamp < l2AdoptConnect
    && l2SliceView.Contains("OpenHarmonyChildWeb.AcquireForWindow")
    && l2SliceView.Contains("OpenHarmonyChildWeb.CommandForWindow")
    && l2SliceView.Contains("OpenHarmonyChildWeb.IsApplicable")
    && l2SliceView.Contains("RefreshOverlayWindow")
    && l2SliceView.Contains("HandlerMatches")
    && l2SliceHybrid.Contains("OpenHarmonyChildWeb.AcquireForWindow")
    && l2SliceHybrid.Contains("OpenHarmonyChildWeb.CommandForWindow")
    && l2SliceHybrid.Contains("TryDecodeChildInvokeRequestId")
    && l2SliceHybrid.Contains("ChildHandlerForWindow")
    && l2SliceBlazor.Contains("OpenHarmonyChildWeb.AcquireForWindow")
    && l2SliceBlazor.Contains("OpenHarmonyChildWeb.CommandForWindow")
    && l2HostingSource.Contains("CommandMarker") && l2HostingSource.Contains("MaxPendingCommands")
    && l2OverlaysSource.Contains("ChildInvokeFlag") && l2OverlaysSource.Contains("EncodeChildInvokeRequestId")
    && l2OverlaysSource.Contains("TryDecodeChildInvokeRequestId"));

if (l2Failures > 0)
{
    throw new InvalidOperationException(
        $"{l2Failures} MULTIWINDOW-L2 assertion(s) failed (the child ArkWeb host pool, its window routing or the primary-window isolation regressed)");
}

// ---------------------------------------------------------------------------------------------
// MULTIWINDOW-L3 M3: per-window IME/a11y/overlay/Back with two concurrent secondary windows.
// The managed half drives the production consumers (the alert host, the alert manager, the app
// host's subwindow routing and the a11y frames); the shell half is pinned in every pack's
// Index/SubWindow.ets (focus request generation + mutual exclusion + close cleanup, the
// active-window IME gate). The device matrix (two providers selfcheck status=1, keyboard
// follows the click, Back ownership) is M3's device half.
int m3sFailures = 0;
void M3SCheck(string name, bool ok)
{
    Console.WriteLine($"[verify] m3 {name} assert={ok}");
    if (!ok)
    {
        m3sFailures++;
    }
}

OpenHarmonySubWindow.CommandSender = (op, payload) => true;
// Normalize the host first: close whatever an earlier section left live, so the two services
// below are the only sessions while this section runs (the surface ids stay predictable).
foreach (OpenHarmonyWindowHost m3sLeftover in m2Host.SecondaryWindows.ToArray())
{
    OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Closed,
        "{\"id\":0,\"x\":0,\"y\":0,\"w\":0,\"h\":0,\"surfaceId\":\"" + m3sLeftover.WindowId + "\"}");
}
List<string> m3sRequests = new();
m2Host.SubWindowSurfaceRequester = id => { m3sRequests.Add(id); return true; };
M4InputContent m3ContentA = new("m3-a-label", "m3-a-entry", "m3-a-button");
M4InputContent m3ContentB = new("m3-b-label", "m3-b-entry", "m3-b-button");
Window m3WindowA = new(m3ContentA.Page);
Window m3WindowB = new(m3ContentB.Page);
m2Application.OpenWindow(m3WindowA);
string m3SurfaceA = m3sRequests.Count >= 1 ? m3sRequests[^1] : "sub-1";
M2Surface(m3SurfaceA, Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Created, 700, 500);
m2Application.OpenWindow(m3WindowB);
string m3SurfaceB = m3sRequests.Count >= 2 ? m3sRequests[^1] : "sub-2";
M2Surface(m3SurfaceB, Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Created, 900, 700);
OpenHarmonyWindowHost? m3HostA = m2Host.FindSecondaryWindow(m3SurfaceA);
OpenHarmonyWindowHost? m3HostB = m2Host.FindSecondaryWindow(m3SurfaceB);
m3ContentA.Page.Measure(700, 500);
m3ContentA.Page.Arrange(new Rect(0, 0, 700, 500));
m3ContentB.Page.Measure(900, 700);
m3ContentB.Page.Arrange(new Rect(0, 0, 900, 700));
bool m3TwoWindows = m3sRequests.Count == 2 && m3SurfaceA != m3SurfaceB
    && m3HostA is not null && m3HostB is not null && !ReferenceEquals(m3HostA, m3HostB);

// 1) Two shadow frames (the offline face of the two per-instance providers): each window owns
// its own tree, one window's release leaves the sibling's frame and republish path intact.
var m3TreeA = new VerticalStackLayout { Children = { new Label { Text = "m3-a11y-A" } } };
var m3TreeB = new VerticalStackLayout { Children = { new Label { Text = "m3-a11y-B" } } };
OpenHarmonyHandlerConnector.ConnectTree(m3TreeA);
OpenHarmonyHandlerConnector.ConnectTree(m3TreeB);
OpenHarmonyAccessibility.Refresh(m3SurfaceA, m3TreeA);
OpenHarmonyAccessibility.Publish(m3SurfaceA);
OpenHarmonyAccessibility.Refresh(m3SurfaceB, m3TreeB);
OpenHarmonyAccessibility.Publish(m3SurfaceB);
bool m3Frames = OpenHarmonyAccessibility.NodesForWindow(m3SurfaceA).Any(n => n.Text == "m3-a11y-A")
    && !OpenHarmonyAccessibility.NodesForWindow(m3SurfaceA).Any(n => n.Text == "m3-a11y-B")
    && OpenHarmonyAccessibility.NodesForWindow(m3SurfaceB).Any(n => n.Text == "m3-a11y-B")
    && !OpenHarmonyAccessibility.NodesForWindow(m3SurfaceB).Any(n => n.Text == "m3-a11y-A");
int m3SecondaryPasses = OpenHarmonyAccessibility.SecondaryPublishes;
OpenHarmonyAccessibility.ReleaseWindow(m3SurfaceA);
bool m3ReleasedA = OpenHarmonyAccessibility.NodesForWindow(m3SurfaceA).Count == 0;
OpenHarmonyAccessibility.Refresh(m3SurfaceB, m3TreeB);
OpenHarmonyAccessibility.Publish(m3SurfaceB);
OpenHarmonyAccessibility.Refresh(m3SurfaceA, m3TreeA);
OpenHarmonyAccessibility.Publish(m3SurfaceA);
bool m3ReleaseIsolation = m3ReleasedA
    && OpenHarmonyAccessibility.NodesForWindow(m3SurfaceB).Any(n => n.Text == "m3-a11y-B")
    && OpenHarmonyAccessibility.NodesForWindow(m3SurfaceA).Any(n => n.Text == "m3-a11y-A")
    && OpenHarmonyAccessibility.SecondaryPublishes > m3SecondaryPasses;
M3SCheck($"a11y two window frames={m3Frames} release isolated={m3ReleaseIsolation}",
    m3TwoWindows && m3Frames && m3ReleaseIsolation);

// 2) Accessibility action ownership with both secondaries live: a node id only resolves and
// executes against its own window's frame/view (the node id exists positionally in both).
OpenHarmonyAccessibility.Refresh(m3SurfaceA, m3ContentA.Page);
OpenHarmonyAccessibility.Refresh(m3SurfaceB, m3ContentB.Page);
OpenHarmonyAccessibilityNode? m3NodeA = OpenHarmonyAccessibility.NodesForWindow(m3SurfaceA)
    .FirstOrDefault(n => n.Role == "button");
OpenHarmonyAccessibilityNode? m3NodeB = OpenHarmonyAccessibility.NodesForWindow(m3SurfaceB)
    .FirstOrDefault(n => n.Role == "button");
int m3ClicksA = m3ContentA.Clicks;
int m3ClicksB = m3ContentB.Clicks;
bool m3ActionA = m3NodeA is not null && m2Host.HandleAccessibilityAction(m3SurfaceA, m3NodeA.Id,
    (int)OpenHarmonyAccessibilityAction.Click) && m3ContentA.Clicks == m3ClicksA + 1
    && m3ContentB.Clicks == m3ClicksB;
bool m3ActionB = m3NodeB is not null && m2Host.HandleAccessibilityAction(m3SurfaceB, m3NodeB.Id,
    (int)OpenHarmonyAccessibilityAction.Click) && m3ContentB.Clicks == m3ClicksB + 1;
M3SCheck($"a11y two window action ownership a={m3ActionA} b={m3ActionB}", m3ActionA && m3ActionB);

// 3) Overlay/alert ownership: each window keeps its own dialog. Two dialogs coexist, each has
// the geometry of its own surface, Hide(string) closes exactly one and Hide() still closes all.
OpenHarmonyAlertHost.SetSurface(m3SurfaceA, 700, 500);
OpenHarmonyAlertHost.SetSurface(m3SurfaceB, 900, 700);
OpenHarmonyAlertState m3AlertA = new()
{
    WindowId = m3SurfaceA, Title = "m3-alert-a", Message = "A", Accept = "OK", Cancel = "No",
    Complete = _ => { },
};
OpenHarmonyAlertState m3AlertB = new()
{
    WindowId = m3SurfaceB, Title = "m3-alert-b", Message = "B", Accept = "OK", Cancel = "No",
    Complete = _ => { },
};
OpenHarmonyAlertHost.Show(m3AlertA);
OpenHarmonyAlertHost.Show(m3AlertB);
bool m3AlertCoexist = ReferenceEquals(OpenHarmonyAlertHost.CurrentFor(m3SurfaceA), m3AlertA)
    && ReferenceEquals(OpenHarmonyAlertHost.CurrentFor(m3SurfaceB), m3AlertB)
    && OpenHarmonyAlertHost.CurrentFor(OpenHarmonyWindowSurface.PrimaryWindowId) is null
    && OpenHarmonyAlertHost.IsVisibleFor(m3SurfaceA) && OpenHarmonyAlertHost.IsVisibleFor(m3SurfaceB);
bool m3AlertGeometry = m3AlertA.BoxRect != m3AlertB.BoxRect
    && Math.Abs(m3AlertA.BoxRect.Center.X - 350) < 0.5f
    && Math.Abs(m3AlertB.BoxRect.Center.X - 450) < 0.5f;
OpenHarmonyAccessibility.Refresh(m3SurfaceA, m3ContentA.Page);
OpenHarmonyAccessibility.Refresh(m3SurfaceB, m3ContentB.Page);
bool m3AlertModalFrames = OpenHarmonyAccessibility.NodesForWindow(m3SurfaceA)
        .Any(n => n.Role == "dialog" && n.Text == "m3-alert-a")
    && !OpenHarmonyAccessibility.NodesForWindow(m3SurfaceA).Any(n => n.Text == "m3-alert-b")
    && OpenHarmonyAccessibility.NodesForWindow(m3SurfaceB)
        .Any(n => n.Role == "dialog" && n.Text == "m3-alert-b")
    && !OpenHarmonyAccessibility.NodesForWindow(m3SurfaceB).Any(n => n.Text == "m3-alert-a");
OpenHarmonyAlertHost.Hide(m3SurfaceA);
bool m3HideOne = OpenHarmonyAlertHost.CurrentFor(m3SurfaceA) is null
    && ReferenceEquals(OpenHarmonyAlertHost.CurrentFor(m3SurfaceB), m3AlertB);
OpenHarmonyAlertHost.Hide();
bool m3HideAll = OpenHarmonyAlertHost.CurrentFor(m3SurfaceB) is null && !OpenHarmonyAlertHost.IsVisible;
M3SCheck($"alert coexist={m3AlertCoexist} geometry={m3AlertGeometry} frames={m3AlertModalFrames} hideOne={m3HideOne} hideAll={m3HideAll}",
    m3AlertCoexist && m3AlertGeometry && m3AlertModalFrames && m3HideOne && m3HideAll);

// 4) IME/prompt ownership: the child window's tagged text edits that window's prompt only; a
// sibling window's text never crosses into it; Return completes the prompt with its own text.
OpenHarmonyAlertState? m3PromptA = null;
bool m3PromptCompleted = false;
string m3PromptAnswer = string.Empty;
m3PromptA = new OpenHarmonyAlertState
{
    WindowId = m3SurfaceA, Kind = OpenHarmonyAlertKind.Prompt, Title = "m3-prompt-a", Message = "p",
    Accept = "OK", Cancel = "Cancel",
    Complete = _ => { m3PromptCompleted = true; m3PromptAnswer = m3PromptA!.PromptText; },
};
OpenHarmonyAlertHost.Show(m3PromptA);
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.TextInput,
    "{\"surfaceId\":\"" + m3SurfaceA + "\",\"text\":\"ab\"}");
bool m3PromptOwned = m3PromptA.PromptText == "ab" && m3ContentA.Entry.Text == "m3-a-entry";
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.TextInput,
    "{\"surfaceId\":\"" + m3SurfaceB + "\",\"text\":\"zz\"}");
bool m3PromptNoCross = m3PromptA.PromptText == "ab";
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.TextSubmitted,
    "{\"surfaceId\":\"" + m3SurfaceA + "\",\"text\":\"ab\"}");
bool m3PromptSubmit = m3PromptCompleted && m3PromptAnswer == "ab"
    && OpenHarmonyAlertHost.CurrentFor(m3SurfaceA) is null;
M3SCheck($"prompt owned={m3PromptOwned} noCross={m3PromptNoCross} submit={m3PromptSubmit}",
    m3PromptOwned && m3PromptNoCross && m3PromptSubmit);

// 5) The production alert manager on a child page: the prompt is stored per window, the
// keyboard request is the child's (op 6, show=1) and the completion returns the prompt's own
// edited text (the M3 fix - the old closure read the primary Current slot, which a second
// window's alert had overwritten).
List<string> m3Commands = new();
OpenHarmonySubWindow.CommandSender = (op, payload) => { m3Commands.Add($"{op}:{payload}"); return true; };
PromptArguments m3PromptArguments = new("M3 prompt", "m3 child prompt");
new OpenHarmonyAlertManager().RequestPrompt(m3ContentB.Page, m3PromptArguments);
OpenHarmonyAlertState? m3ManagedPrompt = OpenHarmonyAlertHost.CurrentFor(m3SurfaceB);
bool m3ManagedFocus = m3ManagedPrompt is { Kind: OpenHarmonyAlertKind.Prompt }
    && m3Commands.Any(c => c.StartsWith("6:", StringComparison.Ordinal)
        && c.Contains("\"surfaceId\":\"" + m3SurfaceB + "\"", StringComparison.Ordinal)
        && c.Contains("\"show\":1", StringComparison.Ordinal));
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.TextInput,
    "{\"surfaceId\":\"" + m3SurfaceB + "\",\"text\":\"hello\"}");
bool m3ManagedText = m3ManagedPrompt is not null && m3ManagedPrompt.PromptText == "hello";
m3ManagedPrompt!.Complete(true);
OpenHarmonyAlertHost.Hide(m3SurfaceB);
string m3ManagedAnswer = await m3PromptArguments.Result.Task;
bool m3ManagedResult = m3ManagedAnswer == "hello"
    && OpenHarmonyAlertHost.CurrentFor(m3SurfaceB) is null;
M3SCheck($"prompt manager child focus={m3ManagedFocus} text={m3ManagedText} result={m3ManagedResult}",
    m3ManagedFocus && m3ManagedText && m3ManagedResult);

// 6) Back ownership: Back delivered to one secondary runs that window's own Back chain (its
// page), never the sibling's; a modal prompt in the window consumes Back first (no page call).
// The two service windows are closed first so the Back pair stays inside the managed capacity
// bound (MaxManagedSubWindows = 2).
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Closed,
    "{\"id\":0,\"x\":0,\"y\":0,\"w\":0,\"h\":0,\"surfaceId\":\"" + m3SurfaceA + "\"}");
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Closed,
    "{\"id\":0,\"x\":0,\"y\":0,\"w\":0,\"h\":0,\"surfaceId\":\"" + m3SurfaceB + "\"}");
int m3BacksA = 0;
int m3BacksB = 0;
M3BackPage m3BackPageA = new(() => m3BacksA++);
M3BackPage m3BackPageB = new(() => m3BacksB++);
Window m3BackWindowA = new(m3BackPageA);
Window m3BackWindowB = new(m3BackPageB);
m2Application.OpenWindow(m3BackWindowA);
string m3BackSurfaceA = m3sRequests.Count >= 3 ? m3sRequests[^1] : "sub-1";
M2Surface(m3BackSurfaceA, Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Created, 600, 400);
m2Application.OpenWindow(m3BackWindowB);
string m3BackSurfaceB = m3sRequests.Count >= 4 ? m3sRequests[^1] : "sub-2";
M2Surface(m3BackSurfaceB, Microsoft.OpenHarmony.Hosting.OpenHarmonySurfaceState.Created, 600, 400);
List<string> m3BackRouter = new();
Action<string> m3BackRecorder = id => m3BackRouter.Add(id);
OpenHarmonyWindowInputRouter.Back += m3BackRecorder;
List<string> m3BackConsumed = new();
OpenHarmonyAlertState m3BackPrompt = new()
{
    WindowId = m3BackSurfaceA, Kind = OpenHarmonyAlertKind.Prompt, Title = "m3-back-prompt",
    Message = "p", Accept = "OK", Cancel = "Cancel",
    Complete = _ => { m3BackConsumed.Add("modal"); },
};
OpenHarmonyAlertHost.Show(m3BackPrompt);
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Back,
    "{\"surfaceId\":\"" + m3BackSurfaceA + "\"}");
bool m3BackModal = m3BackConsumed.Count == 1 && m3BacksA == 0 && m3BacksB == 0
    && m3BackRouter.Count == 0 && OpenHarmonyAlertHost.CurrentFor(m3BackSurfaceA) is null;
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Back,
    "{\"surfaceId\":\"" + m3BackSurfaceB + "\"}");
OpenHarmonyWindowInputRouter.Back -= m3BackRecorder;
bool m3BackWindow = m3BacksA == 0 && m3BacksB == 1 && m3BackRouter.Count == 1
    && m3BackRouter[0] == m3BackSurfaceB;
M3SCheck($"back modal={m3BackModal} window={m3BackWindow}", m3BackModal && m3BackWindow);
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Closed,
    "{\"id\":0,\"x\":0,\"y\":0,\"w\":0,\"h\":0,\"surfaceId\":\"" + m3BackSurfaceA + "\"}");
OpenHarmonySubWindow.HandleNativeEvent((int)OpenHarmonySubWindowEventKind.Closed,
    "{\"id\":0,\"x\":0,\"y\":0,\"w\":0,\"h\":0,\"surfaceId\":\"" + m3BackSurfaceB + "\"}");

// 7) Shell + slice source contract: the focus request generation, the mutual-exclusion blur, the
// close cleanup and the active-window IME gate ship in every pack; the slice carries the
// per-window alert slot, the redraw routing and the window Back entry.
bool m3sShellPinsOk = true;
string m3ShellFirst = string.Empty;
string m3ShellPageFirst = string.Empty;
foreach (string m3ShellVersion in new[] { "1.0.0-preview.22", "1.0.0-preview.23", "1.0.0-preview.24", "1.0.0-preview.28" })
{
    string m3Index = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{m3ShellVersion}/templates/ets/pages/Index.ets") is { } m3IndexPath
        ? File.ReadAllText(m3IndexPath) : string.Empty;
    string m3Page = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{m3ShellVersion}/templates/ets/pages/SubWindow.ets") is { } m3PagePath
        ? File.ReadAllText(m3PagePath) : string.Empty;
    if (m3ShellFirst.Length == 0)
    {
        m3ShellFirst = m3Index;
        m3ShellPageFirst = m3Page;
    }
    else
    {
        m3sShellPinsOk &= m3Index == m3ShellFirst;
        m3sShellPinsOk &= m3Page == m3ShellPageFirst;
    }
    m3sShellPinsOk &= m3Index.Contains("gen?: number")
        && m3Index.Contains("private subWindowImeSurfaceId: string = ''")
        && m3Index.Contains("private blurSubWindowTextFocus(")
        && m3Index.Contains("focus moved")
        && m3Index.Contains("session closed")
        && m3Index.Contains("this.subWindowImeSurfaceId !== session.surfaceId")
        && m3Index.Contains("request.gen = session.generation")
        && m3Index.Contains("this.subWindowImeSurfaceId = session.surfaceId");
    m3sShellPinsOk &= m3Page.Contains("gen?: number")
        && m3Page.Contains("private windowActive: boolean = true")
        && m3Page.Contains("private pendingInputFocus: boolean = false")
        && m3Page.Contains("if (!this.windowActive)")
        && m3Page.Contains("this.pendingInputFocus = true")
        && m3Page.Contains("request.gen !== this.parsedGeneration")
        && m3Page.Contains("window.WindowEventType.WINDOW_ACTIVE");
}
string m3SliceAlert = FindHostSource("OpenHarmonyAlertHost.cs") is { } m3AlertPath
    ? File.ReadAllText(m3AlertPath) : string.Empty;
string m3SliceHosting = FindHostSource("OpenHarmonyMauiAppHost.cs") is { } m3sHostingPath
    ? File.ReadAllText(m3sHostingPath) : string.Empty;
string m3SliceWindowHost = FindHostSource("OpenHarmonyWindowHost.cs") is { } m3WindowHostPath
    ? File.ReadAllText(m3WindowHostPath) : string.Empty;
string m3SliceTable = FindHostSource("src/OpenHarmonyHost/host_a11y_table.h") is { } m3TablePath
    ? File.ReadAllText(m3TablePath) : string.Empty;
System.Text.RegularExpressions.Match m3PartitionCap =
    System.Text.RegularExpressions.Regex.Match(m3SliceTable, "OHOS_A11Y_MAX_NAMED_PARTITIONS\\s+(\\d+)");
int m3PartitionCapValue = m3PartitionCap.Success ? int.Parse(m3PartitionCap.Groups[1].Value) : 0;
bool m3SlicePinsOk = m3SliceAlert.Contains("s_windowAlerts")
    && m3SliceAlert.Contains("public static void Hide(string windowId)")
    && m3SliceAlert.Contains("public static void PromptAppend(string windowId, string text)")
    && m3SliceAlert.Contains("ChangedFor")
    && m3SliceAlert.Contains("public RectF BoxRect =>")
    && m3SliceHosting.Contains("OnAlertHostChanged")
    && m3SliceHosting.Contains("OpenHarmonyAlertHost.ChangedFor += OnAlertHostChanged")
    && m3SliceHosting.Contains("HandleBackRequested()")
    && m3SliceHosting.Contains("childPrompt.Complete(true)")
    && m3SliceWindowHost.Contains("internal bool HandleBackRequested()")
    && m3SliceWindowHost.Contains("OpenHarmonyAlertHost.Hide(WindowId);")
    && m3PartitionCapValue >= 2;
M3SCheck($"shell source {m3sShellPinsOk} slice source {m3SlicePinsOk} partitionCap={m3PartitionCapValue}",
    m3sShellPinsOk && m3SlicePinsOk && m3ShellFirst.Length > 0 && m3ShellPageFirst.Length > 0);

OpenHarmonySubWindow.CommandSender = null;
m2Host.SubWindowSurfaceRequester = null;
OpenHarmonyAlertHost.Hide();
if (m3sFailures > 0)
{
    throw new InvalidOperationException(
        $"{m3sFailures} MULTIWINDOW-L3 M3 assertion(s) failed (the per-window IME, a11y, overlay or Back isolation regressed)");
}

// ---------------------------------------------------------------------------------------------
// MULTIWINDOW-L3 M4: per-window child web slot pools. The managed transport tags every child
// command/eval with the window's surface id ("child:<window>|<op>"), the native module routes it
// to that window's own sink (registered with the surface id; an unknown/closed window is dropped
// fail closed) and the hybrid-invoke request id carries the window index, so two subwindows that
// both own slot 0 dispatch to their own handlers. The device half opens two subwindows with web
// content and runs the churn + soak.
int m4cFailures = 0;
void M4cCheck(string name, bool ok)
{
    Console.WriteLine($"[verify] m4c {name} assert={ok}");
    if (!ok)
    {
        m4cFailures++;
    }
}

// The window-tagged wire is single-sourced (WindowTagged) and the tag rules reject the empty
// ids and the separators the native parser also rejects at registration and routing.
bool m4cWireOk = Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.WindowTagged("sub-1", "load") == "child:sub-1|load"
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.WindowTagged("sub-2", "slot\ndestroy\n0") == "child:sub-2|slot\ndestroy\n0"
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.CommandMarker == "child:"
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsValidWindowTag("sub-1")
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsValidWindowTag(null)
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsValidWindowTag("")
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsValidWindowTag("sub|1")
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsValidWindowTag("sub\n1")
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsValidWindowTag(new string('w', 65));
M4cCheck("wire tag", m4cWireOk);

// The shell, the native registration map and the managed half derive the same window index from
// the surface id ("sub-1" -> 0, "sub-2" -> 1); unknown shapes clamp to the first window.
bool m4cIndexOk = Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.WindowIndexOf("sub-1") == 0
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.WindowIndexOf("sub-2") == 1
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.WindowIndexOf(null) == 0
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.WindowIndexOf("other") == 0;
M4cCheck("window index", m4cIndexOk);

// Two windows' pools are fully independent: each gets the same first-free slot numbers, capacity
// and readiness are per window, a pending queue belongs to its own window, and a release in one
// window turns into that window's destroy only (the two-window red control of the L2 drill).
L2ClearPool();
var m4cCommands = new List<string>();
Action<string, string, string?> m4cOnCommand = (id, op, arg) => m4cCommands.Add($"{id}|{op}|{arg}");
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.CommandSent += m4cOnCommand;
var m4cOwnerA = new MultiOverlayFakeOwner("m4c-a");
var m4cOwnerB = new MultiOverlayFakeOwner("m4c-b");
int m4cSlotA = Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.Acquire("sub-1", m4cOwnerA);
int m4cSlotB = Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.Acquire("sub-2", m4cOwnerB);
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.Command("sub-1", "load",
    Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.Tag(m4cSlotA, "https://example.test/a"));
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.Command("sub-2", "load",
    Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.Tag(m4cSlotB, "https://example.test/b"));
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.CompleteState("w:sub-1|capacity|2", "");
bool m4cAcquire = m4cSlotA == 0 && m4cSlotB == 0
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsClaimedBy("sub-1", 0, m4cOwnerA)
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsClaimedBy("sub-2", 0, m4cOwnerB)
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsReady("sub-1")
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.GetCapacity("sub-1") == 2
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsReady("sub-2")
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.PendingCount("sub-2") == 1
    && m4cCommands.Contains("sub-1|load|s0\nhttps://example.test/a");
bool m4cRelease = Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.Release("sub-1", m4cSlotA, m4cOwnerA)
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsClaimed("sub-1", 0)
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.IsClaimedBy("sub-2", 0, m4cOwnerB)
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.PendingCount("sub-2") == 1
    && m4cCommands.Contains("sub-1|slot|destroy\n0")
    && !m4cCommands.Contains("sub-2|slot|destroy\n0");
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.CommandSent -= m4cOnCommand;
L2ClearPool();
M4cCheck($"independent pools slots={m4cSlotA}/{m4cSlotB}", m4cAcquire && m4cRelease);

// The hybrid-invoke id carries the window index in bit 29: window 0 keeps the pre-M4 shape
// byte-for-byte, window 1 sets the bit, and both decode to their own window + slot.
bool m4cCodecOk = Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.EncodeChildInvokeRequestId(0, 0, 5)
        == Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.EncodeChildInvokeRequestId(0, 5)
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.EncodeChildInvokeRequestId(1, 0, 5)
        == (Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.ChildSecondWindowFlag
            | Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.EncodeChildInvokeRequestId(0, 5))
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.TryDecodeChildInvokeRequestId(
        Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.EncodeChildInvokeRequestId(1, 1, 9),
        out int m4cWin, out int m4cDecodedSlot, out int m4cSeq)
    && m4cWin == 1 && m4cDecodedSlot == 1 && m4cSeq == 9
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.TryDecodeChildInvokeRequestId(
        Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.EncodeChildInvokeRequestId(0, 1, 9),
        out int m4cWin0, out int m4cDecodedSlot0, out _)
    && m4cWin0 == 0 && m4cDecodedSlot0 == 1
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.TryDecodeChildInvokeRequestId(0x01000005, out _, out _, out _)
    && Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.TryDecodeChildInvokeRequestId(0x41000005, out int m4cLegacyWin, out int m4cLegacySlot, out _)
    && m4cLegacyWin == 0 && m4cLegacySlot == 0
    && !Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.TryDecodeChildInvokeRequestId(0x40000000, out _, out _, out _);
M4cCheck("hybrid window codec", m4cCodecOk);

// Dispatch: the probe handler owns window 1 (sub-2) slot 0; an invocation tagged for that window
// reaches it, while one tagged for window 0 fails closed instead of running on the other
// window's handler (the red control for the M4 window filter).
FieldInfo m4cHybridWindowField = typeof(OpenHarmonyHybridWebViewHandler)
    .GetField("_overlayWindowId", BindingFlags.NonPublic | BindingFlags.Instance)
    ?? throw new InvalidOperationException("OpenHarmonyHybridWebViewHandler._overlayWindowId was not found; the M4 child-window dispatch drill needs the window seam");
FieldInfo m4cHybridSlotField = typeof(OpenHarmonyHybridWebViewHandler)
    .GetField("_overlaySlot", BindingFlags.NonPublic | BindingFlags.Instance)
    ?? throw new InvalidOperationException("OpenHarmonyHybridWebViewHandler._overlaySlot was not found; the M4 child-window dispatch drill needs the slot seam");
string m4cHybridWindowBefore = (string)m4cHybridWindowField.GetValue(hybridProbeHandler)!;
int m4cHybridSlotBefore = (int)m4cHybridSlotField.GetValue(hybridProbeHandler)!;
var m4cInvokeResults = new Dictionary<int, string>();
void M4cOnInvokeResult(int requestId, string payload) => m4cInvokeResults[requestId] = payload;
OpenHarmonyHybridWebViewHandler.HybridInvokeResultSent += M4cOnInvokeResult;
try
{
    m4cHybridWindowField.SetValue(hybridProbeHandler, "sub-2");
    m4cHybridSlotField.SetValue(hybridProbeHandler, 0);
    int m4cWin1Id = Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.EncodeChildInvokeRequestId(1, 0, 21);
    await OpenHarmonyHybridWebViewHandler.OnHybridInvokeAsync(m4cWin1Id, "Echo", "[\"\\\"m4w2\\\"\"]");
    bool m4cWin1Ok = m4cInvokeResults.TryGetValue(m4cWin1Id, out string? m4cWin1Payload)
        && PayloadBool(m4cWin1Payload, "IsError") == false
        && PayloadString(m4cWin1Payload, "Result") == "\"echo:m4w2\"";
    int m4cWin0Id = Microsoft.OpenHarmony.Hosting.OpenHarmonyOverlays.EncodeChildInvokeRequestId(0, 0, 22);
    await OpenHarmonyHybridWebViewHandler.OnHybridInvokeAsync(m4cWin0Id, "Echo", "[]");
    bool m4cWin0Ok = m4cInvokeResults.TryGetValue(m4cWin0Id, out string? m4cWin0Payload)
        && PayloadBool(m4cWin0Payload, "IsError") == true
        && (PayloadString(m4cWin0Payload, "ErrorMessage")?.Contains("window 0 slot 0", StringComparison.Ordinal) ?? false);
    M4cCheck($"hybrid window dispatch win1={m4cWin1Ok} win0failclosed={m4cWin0Ok}", m4cWin1Ok && m4cWin0Ok);
}
finally
{
    OpenHarmonyHybridWebViewHandler.HybridInvokeResultSent -= M4cOnInvokeResult;
    m4cHybridWindowField.SetValue(hybridProbeHandler, m4cHybridWindowBefore);
    m4cHybridSlotField.SetValue(hybridProbeHandler, m4cHybridSlotBefore);
}

// Source pins: every pack's SubWindow.ets registers each sink with its own surface id, drops
// them on disappear and derives the second-window bit from the surface-derived index; the host
// carries the per-window sink map + unregister handler + window-tagged routing; the managed
// transport single-sources the tag; the slice dispatches the hybrid invoke by window + slot.
bool m4cShellOk = true;
string m4cShellFirst = string.Empty;
foreach (string m4cShellVersion in new[] { "1.0.0-preview.22", "1.0.0-preview.23", "1.0.0-preview.24", "1.0.0-preview.28" })
{
    string m4cPage = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{m4cShellVersion}/templates/ets/pages/SubWindow.ets") is { } m4cPagePath
        ? File.ReadAllText(m4cPagePath) : string.Empty;
    if (m4cShellFirst.Length == 0)
    {
        m4cShellFirst = m4cPage;
    }
    else
    {
        m4cShellOk &= m4cPage == m4cShellFirst;
    }
    m4cShellOk &= m4cPage.Contains("private childWindowIndex(): number")
        && m4cPage.Contains("const windowBit: number = this.childWindowIndex() > 0 ? 0x20000000 : 0;")
        && m4cPage.Contains("typeof host.unregisterChildWebSink === 'function'")
        && m4cPage.Contains("host.unregisterChildWebSink(this.surfaceId)")
        && m4cPage.Contains("this.unregisterChildWebHost();")
        && m4cPage.Split("}, this.surfaceId);").Length - 1 == 3;
}
M4cCheck("shell source", m4cShellOk && m4cShellFirst.Length > 0);

string m4cHostSource = FindHostSource("src/OpenHarmonyHost/host_napi.cpp") is { } m4cHostPath
    ? File.ReadAllText(m4cHostPath) : string.Empty;
M4cCheck("host source", m4cHostSource.Contains("child_web_windows")
    && m4cHostSource.Contains("child_web_index")
    && m4cHostSource.Contains("unregisterChildWebSink")
    && m4cHostSource.Contains("HostSplitChildWindowTag")
    && m4cHostSource.Contains("HostChildWebWindowReset")
    && m4cHostSource.Contains("HostChildWebWindowForIndex")
    && m4cHostSource.Contains("kChildHybridSecondWindowFlag")
    && m4cHostSource.Contains("no sink for window"));

string m4cChildWebSource = FindHostSource("src/Microsoft.OpenHarmony.Hosting/OpenHarmonyChildWeb.cs") is { } m4cChildWebPath
    ? File.ReadAllText(m4cChildWebPath) : string.Empty;
string m4cOverlaysSource = FindHostSource("src/Microsoft.OpenHarmony.Hosting/OpenHarmonyOverlays.cs") is { } m4cOverlaysPath
    ? File.ReadAllText(m4cOverlaysPath) : string.Empty;
string m4cSliceSource = FindHostSource("OpenHarmonyHybridWebViewHandler.cs") is { } m4cSlicePath
    ? File.ReadAllText(m4cSlicePath) : string.Empty;
M4cCheck("transport source", m4cChildWebSource.Contains("WindowTagged")
    && m4cChildWebSource.Contains("IsValidWindowTag")
    && m4cChildWebSource.Contains("WebCommandNative(WindowTagged(windowId, op)")
    && m4cChildWebSource.Contains("WebEvalNative(WindowTagged(windowId, tagged)")
    && m4cChildWebSource.Contains("public static int WindowIndexOf")
    && m4cOverlaysSource.Contains("ChildSecondWindowFlag")
    && m4cOverlaysSource.Contains("EncodeChildInvokeRequestId(int windowIndex, int slot, int sequence)")
    && m4cSliceSource.Contains("ChildHandlerForWindow")
    && m4cSliceSource.Contains("OpenHarmonyChildWeb.WindowIndexOf(handler._overlayWindowId) == windowIndex"));

if (m4cFailures > 0)
{
    throw new InvalidOperationException(
        $"{m4cFailures} MULTIWINDOW-L3 M4 assertion(s) failed (the per-window child web pool, its window routing or the hybrid window dispatch regressed)");
}

// ---------------------------------------------------------------------------------------------
// MULTIWINDOW-L3 B6: the child navigation veto. A subwindow page cancels a main-frame load it
// did not originate and asks for the same Navigating decision the primary window asks for; the
// ask travels on the child web-event channel ("w:<window>|s<slot>|navask|<id>", URL in the event
// URL slot) and the approval answers as a child "nav" command to that window. The primary B6
// channel and the primary handler behavior stay untouched (the B6 pins above still guard them;
// the child ask is only honored for a child-tagged window and slot).
int b6cFailures = 0;
void B6cCheck(string name, bool ok)
{
    Console.WriteLine($"[verify] b6c {name} assert={ok}");
    if (!ok)
    {
        b6cFailures++;
    }
}

L2ClearPool();
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.SetCapacity("sub-2", 2);
var b6cProbe = new Microsoft.Maui.Controls.WebView { HeightRequest = 200 };
OpenHarmonyHandlerConnector.Connect(b6cProbe);
if (b6cProbe.Handler is not OpenHarmonyWebViewHandler b6cHandler)
{
    throw new InvalidOperationException("the child B6 drill could not connect a WebView handler");
}
FieldInfo b6cWindowField = typeof(OpenHarmonyWebViewHandler).GetField("_overlayWindowId", BindingFlags.NonPublic | BindingFlags.Instance)
    ?? throw new InvalidOperationException("OpenHarmonyWebViewHandler._overlayWindowId was not found; the child B6 drill needs the window seam");
FieldInfo b6cSlotField = typeof(OpenHarmonyWebViewHandler).GetField("_overlaySlot", BindingFlags.NonPublic | BindingFlags.Instance)
    ?? throw new InvalidOperationException("OpenHarmonyWebViewHandler._overlaySlot was not found; the child B6 drill needs the slot seam");
string b6cWindowBefore = (string)b6cWindowField.GetValue(b6cHandler)!;
int b6cSlotBefore = (int)b6cSlotField.GetValue(b6cHandler)!;
var b6cEvents = new List<(string Url, bool Cancel)>();
bool b6cCancelNext = false;
void OnB6cNavigating(object? sender, WebNavigatingEventArgs e)
{
    if (e.Url is not null && e.Url.StartsWith("https://example.invalid/b6c", StringComparison.Ordinal))
    {
        e.Cancel = b6cCancelNext;
        b6cEvents.Add((e.Url, e.Cancel));
    }
}
b6cProbe.Navigating += OnB6cNavigating;
var b6cCommands = new List<string>();
void OnB6cCommand(string id, string op, string? arg) => b6cCommands.Add($"{id}|{op}|{arg}");
Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.CommandSent += OnB6cCommand;
try
{
    b6cWindowField.SetValue(b6cHandler, "sub-2");
    b6cSlotField.SetValue(b6cHandler, 0);

    // Route: the ask raises Navigating once and approves exactly the (id, url) back to the
    // asking window; the started event of that reload does not raise a second time, and the next
    // started event does (one-shot).
    OpenHarmonyWebViewHandler.OnPageEvent("w:sub-2|s0|navask|id-b6c-route", "https://example.invalid/b6c/allow");
    bool b6cRouteOk = b6cEvents.Count == 1 && b6cEvents[0] == ("https://example.invalid/b6c/allow", false)
        && b6cCommands.Count == 1
        && b6cCommands[0] == "sub-2|nav|s0\nid-b6c-route\nhttps://example.invalid/b6c/allow";
    int b6cEventsAfterRoute = b6cEvents.Count;
    OpenHarmonyWebViewHandler.OnPageEvent("w:sub-2|s0|started", "https://example.invalid/b6c/allow");
    bool b6cStartedSuppressed = b6cEvents.Count == b6cEventsAfterRoute;
    OpenHarmonyWebViewHandler.OnPageEvent("w:sub-2|s0|started", "https://example.invalid/b6c/allow");
    bool b6cOneShot = b6cEvents.Count == b6cEventsAfterRoute + 1;
    B6cCheck($"route approvals={b6cCommands.Count} startedSuppressed={b6cStartedSuppressed} oneShot={b6cOneShot}",
        b6cRouteOk && b6cStartedSuppressed && b6cOneShot);

    // Cancel: a denied ask raises Navigating with Cancel and sends no approval.
    b6cCancelNext = true;
    int b6cCommandsBeforeCancel = b6cCommands.Count;
    int b6cEventsBeforeCancel = b6cEvents.Count;
    OpenHarmonyWebViewHandler.OnPageEvent("w:sub-2|s0|navask|id-b6c-deny", "https://example.invalid/b6c/deny");
    bool b6cCancelOk = b6cEvents.Count == b6cEventsBeforeCancel + 1 && b6cEvents[^1].Cancel
        && b6cCommands.Count == b6cCommandsBeforeCancel;
    b6cCancelNext = false;
    B6cCheck("cancel no-approval", b6cCancelOk);

    // Fail closed: the H-C2 network-path spelling, a scheme-like/relative URL, a missing id, the
    // primary window tag and a slot beyond the child pool are all inert (no Navigating, no
    // approval); they can never make the child channel approve a load the shell did not cancel.
    int b6cCommandsBeforeFail = b6cCommands.Count;
    int b6cEventsBeforeFail = b6cEvents.Count;
    OpenHarmonyWebViewHandler.OnPageEvent("w:sub-2|s0|navask|id-b6c-hc2", "//evil.invalid/x");
    OpenHarmonyWebViewHandler.OnPageEvent("w:sub-2|s0|navask|id-b6c-scheme", "https:foo");
    OpenHarmonyWebViewHandler.OnPageEvent("w:sub-2|s0|navask|", "https://example.invalid/b6c/noid");
    OpenHarmonyWebViewHandler.OnPageEvent("w:main|s0|navask|id-b6c-main", "https://example.invalid/b6c/main");
    OpenHarmonyWebViewHandler.OnPageEvent("w:sub-2|s9|navask|id-b6c-slot", "https://example.invalid/b6c/slot");
    bool b6cFailClosedOk = b6cEvents.Count == b6cEventsBeforeFail && b6cCommands.Count == b6cCommandsBeforeFail;
    B6cCheck("fail closed", b6cFailClosedOk);

    // Window isolation: an ask from sub-1 reaches sub-1's own transport only; the sub-2 handler
    // never sees a Navigating for it (and the approval carries sub-1, not sub-2).
    int b6cEventsBeforeIso = b6cEvents.Count;
    int b6cCommandsBeforeIso = b6cCommands.Count;
    OpenHarmonyWebViewHandler.OnPageEvent("w:sub-1|s0|navask|id-b6c-iso", "https://example.invalid/b6c/iso");
    bool b6cIsolationOk = b6cEvents.Count == b6cEventsBeforeIso
        && b6cCommands.Count == b6cCommandsBeforeIso + 1
        && b6cCommands[^1] == "sub-1|nav|s0\nid-b6c-iso\nhttps://example.invalid/b6c/iso";
    B6cCheck("window isolation", b6cIsolationOk);
}
finally
{
    Microsoft.OpenHarmony.Hosting.OpenHarmonyChildWeb.CommandSent -= OnB6cCommand;
    b6cProbe.Navigating -= OnB6cNavigating;
    b6cWindowField.SetValue(b6cHandler, b6cWindowBefore);
    b6cSlotField.SetValue(b6cHandler, b6cSlotBefore);
    b6cProbe.Handler?.DisconnectHandler();
    b6cProbe.Handler = null;
}

// Source pins: every pack's SubWindow.ets carries the child veto (the ask state + the
// onLoadIntercept gateway + the approval command + the one-shot markers) and the slice routes
// the ask to the same Navigating decision while consuming the child approval on the
// window-scoped started event.
bool b6cShellOk = true;
string b6cShellFirst = string.Empty;
foreach (string b6cShellVersion in new[] { "1.0.0-preview.22", "1.0.0-preview.23", "1.0.0-preview.24", "1.0.0-preview.28" })
{
    string b6cPage = FindHostSource($"packs/Microsoft.OpenHarmony.Sdk/{b6cShellVersion}/templates/ets/pages/SubWindow.ets") is { } b6cPagePath
        ? File.ReadAllText(b6cPagePath) : string.Empty;
    if (b6cShellFirst.Length == 0)
    {
        b6cShellFirst = b6cPage;
    }
    else
    {
        b6cShellOk &= b6cPage == b6cShellFirst;
    }
    b6cShellOk &= b6cPage.Contains("const SUB_WEB_NAV_ASK_PREFIX: string = 'navask|';")
        && b6cPage.Contains(".onLoadIntercept((event) => {")
        && b6cPage.Contains("private isChildAppNavigation(slot: number, url: string): boolean")
        && b6cPage.Contains("private approveChildNavigation(arg: string): void")
        && b6cPage.Contains("this.subNavProgrammatic[slot] = { url: loadUrl")
        && b6cPage.Contains("} else if (op === 'nav') {")
        && b6cPage.Contains("this.retireChildNavigationMarker(startedUrl, slot);")
        && b6cPage.Contains("this.dropPendingChildNavigations(slot);");
}
bool b6cSliceOk = wHandler.Contains("ChildNavRequestPrefix = \"navask|\"")
    && wHandler.Contains("HandleChildNavigationRequest(string windowId, int slot, string url, string requestId)")
    && wHandler.Contains("ConsumeChildApprovedNavigation(windowId, slot, url)")
    && wHandler.Contains("ApproveChildNavigation(windowId, slot, url)")
    && wHandler.Contains("OpenHarmonyChildWeb.CommandForWindow(windowId, \"nav\", OpenHarmonyOverlays.Tag(slot, requestId + \"\\n\" + url))");
B6cCheck($"source shell={b6cShellFirst.Length > 0} slice={b6cSliceOk}", b6cShellOk && b6cShellFirst.Length > 0 && b6cSliceOk);

if (b6cFailures > 0)
{
    throw new InvalidOperationException(
        $"{b6cFailures} MULTIWINDOW-L3 B6 child assertion(s) failed (the child navigation veto, its wire or its fail-closed shapes regressed)");
}

// ---------------------------------------------------------------------------------------------
// PREPROBE-SWEEP: no slice source may call the raw System.Runtime.InteropServices.NativeLibrary
// loader again. The A11Y-SELFCHECK root cause was exactly that family - the managed loader
// answered "no export" while the in-process host served the export - so every host call is now
// a direct LibraryImport call whose DllNotFound/EntryPointNotFound miss is cached (-1). This pin
// scans the compiled slice directory (the same top-level *.cs glob as verify.csproj) for the
// `NativeLibrary.` API marker; the prose mentions of the retired family stay allowed.
string preprobeSliceDir = typeof(TestApp).Assembly
    .GetCustomAttributes<AssemblyMetadataAttribute>()
    .FirstOrDefault(a => a.Key == "MauiSliceDir")?.Value ?? string.Empty;
string[] preprobeSliceFiles = Directory.Exists(preprobeSliceDir)
    ? Directory.GetFiles(preprobeSliceDir, "*.cs")
    : Array.Empty<string>();
string[] preprobeOffenders = preprobeSliceFiles
    .Where(f => File.ReadAllText(f).Contains("NativeLibrary.", StringComparison.Ordinal))
    .ToArray();
bool preprobePinOk = preprobeSliceFiles.Length > 0 && preprobeOffenders.Length == 0;
Console.WriteLine($"[verify] preprobe sliceFiles={preprobeSliceFiles.Length} nativeLibraryUses={preprobeOffenders.Length} assert={preprobePinOk}");
if (!preprobePinOk)
{
    throw new InvalidOperationException(
        $"the PREPROBE-SWEEP pin failed: {preprobeOffenders.Length} of {preprobeSliceFiles.Length} slice file(s) still use the retired raw NativeLibrary loader: {string.Join(", ", preprobeOffenders.Select(Path.GetFileName))}");
}

// The suite's own check-count contract: report what was actually emitted and fail when it is
// below the declared floor. The CI job and scripts/preflight.sh read this line instead of
// repeating a threshold constant, so the count has a single source of truth (this file) and
// cannot drift between the two callers. `grep -c '[verify]'` must agree with `checks=`.
int verifyChecks = verifyStdout.VerifyLineCount;
bool verifyCheckContract = verifyChecks >= verifyCheckFloor;
Console.WriteLine($"[suite] checks={verifyChecks} total={verifyCheckTotal} floor={verifyCheckFloor} assert={verifyCheckContract}");
if (!verifyCheckContract)
{
    throw new InvalidOperationException(
        $"the interaction suite printed {verifyChecks} [verify] lines, below the {verifyCheckFloor}-line floor (declared total {verifyCheckTotal})");
}

// Target object for the HybridWebView JS -> .NET invocation checks. The reflection invoker
// matches methods by name and deserializes each JSON parameter value into the parameter type.
sealed class VerifyHybridInvokeTarget
{
    public string Echo(string value) => "echo:" + value;
    public int Add(int a, int b) => a + b;
}

/// <summary>
/// Perf probe canvas: the off-device rasterizer is absent, so the frame-path measurement must not
/// pay a failed native lookup for the renderer-level background fill (FillRectangle -> Polyline).
/// Only that one call is overridden; the rest of the managed canvas path is unchanged.
/// </summary>
sealed class PerfCanvas : Microsoft.OpenHarmony.Maui.Graphics.OpenHarmonyCanvas
{
    public override void FillRectangle(float x, float y, float width, float height)
    {
    }
}

/// <summary>
/// Cull probe canvas (INTERP-DRAW2): records the text the compositor draws without touching the
/// native host, so a render's surviving node set is visible to the off-device checks.
/// </summary>
sealed class CullProbeCanvas : Microsoft.OpenHarmony.Maui.Graphics.OpenHarmonyCanvas
{
    public List<string> Texts { get; } = new();

    public override void DrawString(string value, float x, float y, float width, float height,
        Microsoft.Maui.Graphics.HorizontalAlignment horizontalAlignment,
        Microsoft.Maui.Graphics.VerticalAlignment verticalAlignment, float lineSpacingAdjustment = 0)
        => Texts.Add(value);
}

/// <summary>
/// Overlay canvas that counts fills (T11): the diagnostics overlay paints an adorner with
/// FillRectangle, so a fill proves the window's adorner reached the frame host's overlay pass;
/// the rest of the canvas behaviour is irrelevant to the check.
/// </summary>
sealed class T11RecordingCanvas : Microsoft.OpenHarmony.Maui.Graphics.OpenHarmonyCanvas
{
    public int Fills { get; private set; }

    public override void FillRectangle(float x, float y, float width, float height) => Fills++;
}

/// <summary>
/// Tabbed-page probe canvas: records every string the compositor's text path draws, so the
/// FIX-TABBED checks can prove the selected page's content reached the frame while the
/// unselected page's content did not.
/// </summary>
sealed class TabbedProbeCanvas : Microsoft.OpenHarmony.Maui.Graphics.OpenHarmonyCanvas
{
    public List<string> Texts { get; } = new();

    public override void DrawString(string value, float x, float y, float width, float height,
        Microsoft.Maui.Graphics.HorizontalAlignment horizontalAlignment,
        Microsoft.Maui.Graphics.VerticalAlignment verticalAlignment, float lineSpacingAdjustment = 0)
        => Texts.Add(value);
}

/// <summary>
/// Text-draw recorder (T21): captures the last text the slice draws and the canvas font size at
/// that moment, so the system font scale can be pinned at the draw boundary.
/// </summary>
sealed class T21RecordingCanvas : Microsoft.OpenHarmony.Maui.Graphics.OpenHarmonyCanvas
{
    public string? LastText { get; private set; }

    public float LastTextFontSize { get; private set; }

    public override void DrawString(string value, float x, float y, float width, float height,
        HorizontalAlignment horizontalAlignment, VerticalAlignment verticalAlignment, float lineSpacingAdjustment = 0)
    {
        LastText = value;
        LastTextFontSize = FontSize;
    }

    public void Clear()
    {
        LastText = null;
        LastTextFontSize = 0f;
    }
}

sealed class ProbeDrawable : Microsoft.Maui.Graphics.IDrawable
{
    public int DrawCalls { get; private set; }
    public int TouchCalls { get; private set; }

    public void Draw(Microsoft.Maui.Graphics.ICanvas canvas, Microsoft.Maui.Graphics.RectF dirtyRect)
    {
        DrawCalls++;
        canvas.FillColor = Microsoft.Maui.Graphics.Colors.Magenta;
        canvas.FillRectangle(dirtyRect);
    }

    public void StartInteraction(Microsoft.Maui.Graphics.PointF[] points) => TouchCalls++;
    public void DragInteraction(Microsoft.Maui.Graphics.PointF[] points) { }
    public void EndInteraction(Microsoft.Maui.Graphics.PointF[] points, bool isInsideBounds) { }
}

static class gestures
{
    public static ProbeDrawable? Drawable;
    public static Microsoft.Maui.SwipeDirection LastSwipe;
    public static bool SwipeViewClicked;
    public static bool SwipeViewInvoked;
    public static int RefreshRuns;
    public static bool PointerEntered;
    public static bool PointerPressed;
    public static bool PointerReleased;
    public static bool PointerExited;
    public static string PinchLog = "";
    public static int TapCount;
    public static bool PanStarted;
    public static bool PanCompleted;
    public static double PanTotalY;
    public static int DragStartingCount;
    public static int DragOverCount;
    public static int DragLeaveCount;
    public static int DropCount;
    public static int DropCompletedCount;
    public static string? LastDragOverText;
    public static string? DroppedText;
    public static string LastDropResult = "?";

    public static string DropResultOf(Microsoft.Maui.Controls.DropCompletedEventArgs args)
    {
        // DropResult is internal in the Controls contract; read it reflectively in the harness.
        var prop = typeof(Microsoft.Maui.Controls.DropCompletedEventArgs).GetProperty("DropResult",
            System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public);
        return prop?.GetValue(args)?.ToString() ?? "unknown";
    }
}

class RoutedPage : ContentPage
{
    public RoutedPage()
    {
        Title = "Routed";
        Content = new Label { Text = "routed page" };
    }
}

/// <summary>
/// Custom ITableViewController model probe for T8: two sections, a header cell on the first
/// section and per-row text cells created by the default TableModel.GetCell, with selections
/// recorded to pin the RowSelected path.
/// </summary>
sealed class ProbeTableModel : Microsoft.Maui.Controls.Internals.TableModel
{
    private readonly string[][] _sections;
    private readonly string[] _titles;

    public ProbeTableModel(string[][] sections, string[] titles)
    {
        _sections = sections;
        _titles = titles;
    }

    public List<string> Selected { get; } = new();

    public override object GetItem(int section, int row) => _sections[section][row];

    public override int GetRowCount(int section) => _sections[section].Length;

    public override int GetSectionCount() => _sections.Length;

    public override string GetSectionTitle(int section) => _titles[section];

    public override Microsoft.Maui.Controls.Cell? GetHeaderCell(int section)
        => section == 0 ? new Microsoft.Maui.Controls.TextCell { Text = "model header" } : null;

    protected override void OnRowSelected(object item)
        => Selected.Add(item is Microsoft.Maui.Controls.TextCell cell ? cell.Text ?? string.Empty : item?.ToString() ?? string.Empty);
}

// A group object for the T13 footer-view check: the footer template binds to Name, so a
// materialised footer proves it was bound to the group instance.
class T13Group : List<string>
{
    public T13Group(string name, IEnumerable<string> items) : base(items) => Name = name;
    public string Name { get; }
    public override string ToString() => Name;
}

class TestApp : Application
{
    protected override Window CreateWindow(IActivationState? activationState)
        => new Window(new NavigationPage(BuildPage()) { Title = "Root", BarBackgroundColor = Colors.DarkSlateBlue });

    static ContentPage BuildPage()
    {
        var layout = new VerticalStackLayout { Padding = 24, Spacing = 16 };
        layout.Add(new Label { Text = "MAUI on OpenHarmony", FontSize = 40 });

        // Grid + HorizontalStackLayout exercise the layout handler.
        var grid = new Grid
        {
            ColumnDefinitions = { new ColumnDefinition(GridLength.Star), new ColumnDefinition(GridLength.Auto) },
        };
        var horizontal = new HorizontalStackLayout { Spacing = 12 };
        horizontal.Add(new Label { Text = "grid:", FontSize = 28 });
        var gridButton = new Button { Text = "grid button" };
        gridButton.Clicked += (_, _) => Console.WriteLine("[verify] grid button clicked");
        horizontal.Add(gridButton);
        grid.Add(horizontal);
        layout.Add(grid);

        var button = new Button { Text = "Tap me" };
        button.Clicked += (_, _) => Console.WriteLine("[verify] Button.Clicked fired");
        layout.Add(button);
        layout.Add(new Entry { Placeholder = "type here", FontSize = 30 });

        var image = new Image { Source = ImageSource.FromFile(Path.Combine(Path.GetTempPath(), "verify-image.png")), HeightRequest = 120 };
        layout.Add(image);

        // W22-2: value controls (all drawn by the slice).
        var checkBox = new CheckBox { IsChecked = false };
        var toggle = new Switch { IsToggled = false };
        var slider = new Slider { Minimum = 0, Maximum = 100, Value = 50, HeightRequest = 40 };
        var progress = new ProgressBar { Progress = 0.25, HeightRequest = 8 };
        var spinner = new ActivityIndicator { IsRunning = true, HeightRequest = 24 };
        slider.DragCompleted += (_, _) => Console.WriteLine($"[verify] slider DragCompleted value={slider.Value:0.#}");
        checkBox.CheckedChanged += (_, e) => Console.WriteLine($"[verify] checkbox CheckedChanged={e.Value}");
        toggle.Toggled += (_, e) => Console.WriteLine($"[verify] switch Toggled={e.Value}");
        var controls = new HorizontalStackLayout { Spacing = 12 };
        controls.Add(checkBox);
        controls.Add(toggle);
        controls.Add(slider);
        layout.Add(controls);
        layout.Add(progress);
        layout.Add(spinner);

        // W22-7: animation, picker, tabbed page.
        var fadeLabel = new Label { Text = "fade me", FontSize = 28, Opacity = 1.0 };
        layout.Add(fadeLabel);
        var pickerCtl = new Picker { Title = "choose", FontSize = 26 };
        pickerCtl.Items.Add("alpha");
        pickerCtl.Items.Add("beta");
        pickerCtl.Items.Add("gamma");
        layout.Add(pickerCtl);

        // W22-13b: grid collection view (3 columns).
        var gridCollection = new CollectionView
        {
            ItemsSource = Enumerable.Range(0, 9).Select(i => $"cell {i}").ToList(),
            ItemTemplate = new DataTemplate(() =>
            {
                var cellLabel = new Label { FontSize = 24 };
                cellLabel.SetBinding(Label.TextProperty, ".");
                return cellLabel;
            }),
            ItemsLayout = new GridItemsLayout(3, ItemsLayoutOrientation.Vertical),
            HeightRequest = 160,
        };
        layout.Add(gridCollection);

        // W22-15: grouped collection view (headers) + carousel looping.
        var grouped = new CollectionView
        {
            ItemsSource = new List<List<string>>
            {
                new() { "g1-item A", "g1-item B" },
                new() { "g2-item A", "g2-item B" },
            },
            ItemTemplate = new DataTemplate(() =>
            {
                var itemLabel = new Label { FontSize = 22 };
                itemLabel.SetBinding(Label.TextProperty, ".");
                return itemLabel;
            }),
            GroupHeaderTemplate = new DataTemplate(() =>
            {
                var header = new Label { FontSize = 24, TextColor = Colors.Gold };
                header.SetBinding(Label.TextProperty, ".");
                return header;
            }),
            IsGrouped = true,
            HeightRequest = 200,
        };
        layout.Add(grouped);

        // W22-12: legacy ListView (cells) + CarouselView.
        var listView = new ListView
        {
            ItemsSource = Enumerable.Range(0, 12).Select(i => $"list row {i}").ToList(),
            ItemTemplate = new DataTemplate(() =>
            {
                var cell = new TextCell();
                cell.SetBinding(TextCell.TextProperty, ".");
                return cell;
            }),
            HeightRequest = 200,
        };
        layout.Add(listView);

        var carousel = new CarouselView
        {
            ItemsSource = new List<string> { "slide A", "slide B", "slide C" },
            ItemTemplate = new DataTemplate(() =>
            {
                var label = new Label { FontSize = 34 };
                label.SetBinding(Label.TextProperty, ".");
                return label;
            }),
            HeightRequest = 140,
        };
        layout.Add(carousel);

        // Audit batch 2: GraphicsView / ContentView / ImageButton.
        layout.Add(new GraphicsView { Drawable = gestures.Drawable, HeightRequest = 80 });
        layout.Add(new ContentView
        {
            HeightRequest = 60,
            Content = new Label { Text = "content view", FontSize = 24 },
        });
        string buttonImagePath = Path.Combine(Path.GetTempPath(), "verify-button.png");
        File.WriteAllBytes(buttonImagePath, Convert.FromBase64String(
            "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg=="));
        layout.Add(new ImageButton { Source = ImageSource.FromFile(buttonImagePath), HeightRequest = 64 });

        // Audit batch: BoxView / IndicatorView / Frame / Editor (and a XAML page below).
        layout.Add(new BoxView { Color = Colors.Gold, HeightRequest = 18 });
        layout.Add(new IndicatorView { Count = 3, Position = 1, HeightRequest = 18 });
        layout.Add(new Frame
        {
            BorderColor = Colors.Teal,
            CornerRadius = 8,
            Content = new Label { Text = "framed", FontSize = 24 },
        });
        layout.Add(new Editor { Placeholder = "editor here", HeightRequest = 80 });

        // W22-9: async image source (stream).
        var streamImage = new Image { HeightRequest = 80 };
        streamImage.Source = ImageSource.FromStream(() => new MemoryStream(Convert.FromBase64String(
            "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==")));
        layout.Add(streamImage);

        // W22-8: date/time pickers; T7 adds a min/max-bounded DatePicker for the calendar clamp.
        var datePicker = new DatePicker { Date = new DateTime(2026, 9, 17), FontSize = 26 };
        var timePicker = new TimePicker { Time = new TimeSpan(14, 30, 0), FontSize = 26 };
        var boundedPicker = new DatePicker
        {
            Date = new DateTime(2026, 9, 15),
            MinimumDate = new DateTime(2026, 9, 10),
            MaximumDate = new DateTime(2026, 9, 20),
            FontSize = 26,
        };
        layout.Add(new HorizontalStackLayout { Spacing = 16, Children = { datePicker, timePicker, boundedPicker } });

        // Gap 1c: swipe gesture recognizer (reuses the drag tracking).
        var swipeLabel = new Label { Text = "swipe me", FontSize = 28 };
        var swipeGesture = new SwipeGestureRecognizer { Direction = SwipeDirection.Left | SwipeDirection.Right, Threshold = 30 };
        swipeGesture.Swiped += (_, e) => gestures.LastSwipe = e.Direction;
        swipeLabel.GestureRecognizers.Add(swipeGesture);
        layout.Insert(0, swipeLabel);

        // Limitations re-audit: pointer gestures (enter/press/release/exit).
        var pointerLabel = new Label { Text = "hover me", FontSize = 28 };
        var pointerGesture = new PointerGestureRecognizer();
        pointerGesture.PointerEntered += (_, _) => gestures.PointerEntered = true;
        pointerGesture.PointerPressed += (_, _) => gestures.PointerPressed = true;
        pointerGesture.PointerReleased += (_, _) => gestures.PointerReleased = true;
        pointerGesture.PointerExited += (_, _) => gestures.PointerExited = true;
        pointerLabel.GestureRecognizers.Add(pointerGesture);
        layout.Insert(1, pointerLabel);

        // Limitations re-audit: pinch gestures (shell reports phase/scale/centre).
        var pinchLabel = new Label { Text = "pinch me", FontSize = 28 };
        var pinchGesture = new PinchGestureRecognizer();
        pinchGesture.PinchUpdated += (_, e) => gestures.PinchLog += $"{e.Status}:{e.Scale:0.0} ";
        pinchLabel.GestureRecognizers.Add(pinchGesture);
        layout.Insert(2, pinchLabel);

        // Gap 1d: SwipeView with a right-hand item (revealed by a left drag).
        var swipeItem = new SwipeItem { Text = "Delete", BackgroundColor = Colors.OrangeRed };
        swipeItem.Clicked += (_, _) => gestures.SwipeViewClicked = true;
        swipeItem.Invoked += (_, _) => gestures.SwipeViewInvoked = true;
        var swipeRow = new SwipeView { HeightRequest = 120, Content = new Label { Text = "swipeable row" } };
        swipeRow.RightItems.Add(swipeItem);
        layout.Insert(1, swipeRow);

        // Gap 1d: RefreshView (pull down to refresh).
        var refreshView = new RefreshView { HeightRequest = 140, Content = new Label { Text = "pull to refresh" } };
        refreshView.Command = new Command(() => gestures.RefreshRuns++);
        layout.Insert(2, refreshView);

// W22-6: gestures + transforms.
        var tapLabel = new Label { Text = "tap me", FontSize = 28 };
        var tapGesture = new TapGestureRecognizer();
        tapGesture.Tapped += (_, _) => gestures.TapCount++;
        tapLabel.GestureRecognizers.Add(tapGesture);
        layout.Add(tapLabel);

        var panLabel = new Label { Text = "pan me", FontSize = 28 };
        var panGesture = new PanGestureRecognizer();
        panGesture.PanUpdated += (_, e) =>
        {
            if (e.StatusType == GestureStatus.Started) gestures.PanStarted = true;
            if (e.StatusType == GestureStatus.Running) gestures.PanTotalY = e.TotalY;
            if (e.StatusType == GestureStatus.Completed) gestures.PanCompleted = true;
        };
        panLabel.GestureRecognizers.Add(panGesture);
        layout.Add(panLabel);

        var animatedLabel = new Label { Text = "transformed", FontSize = 28, Opacity = 0.5, TranslationY = 12, Scale = 1.1, Rotation = 10 };
        layout.Add(animatedLabel);

        // W22-5: shapes, border, stepper, radio button, search bar.
        var shapes = new HorizontalStackLayout { Spacing = 12 };
        shapes.Add(new Microsoft.Maui.Controls.Shapes.Rectangle { WidthRequest = 60, HeightRequest = 60, Fill = Colors.OrangeRed, Stroke = Colors.White, StrokeThickness = 2 });
        shapes.Add(new Microsoft.Maui.Controls.Shapes.Ellipse { WidthRequest = 60, HeightRequest = 60, Fill = Colors.MediumSeaGreen });
        shapes.Add(new Microsoft.Maui.Controls.Shapes.Line { X1 = 0, Y1 = 0, X2 = 60, Y2 = 60, Stroke = Colors.Gold, StrokeThickness = 3 });
        layout.Add(shapes);

        var border = new Border
        {
            Stroke = Colors.DodgerBlue,
            StrokeThickness = 3,
            Padding = 10,
            Content = new Label { Text = "inside border", FontSize = 26 },
        };
        layout.Add(border);

        var controls2 = new HorizontalStackLayout { Spacing = 16 };
        var stepper = new Stepper { Minimum = 0, Maximum = 10, Increment = 1, Value = 1 };
        var radio = new RadioButton { Content = "radio choice", IsChecked = false };
        var search = new SearchBar { Placeholder = "search...", HeightRequest = 48 };
        controls2.Add(stepper);
        controls2.Add(radio);
        controls2.Add(search);
        layout.Add(controls2);

        // W22-4: collection view with a template (items materialized by the slice).
        var collection = new CollectionView
        {
            ItemsSource = Enumerable.Range(0, 20).Select(i => $"item {i}").ToList(),
            ItemTemplate = new DataTemplate(() =>
            {
                var itemLabel = new Label { FontSize = 26 };
                itemLabel.SetBinding(Label.TextProperty, ".");
                return itemLabel;
            }),
            HeightRequest = 300,
            SelectionMode = SelectionMode.Single,
        };
        layout.Add(collection);

        // A scroll view with more content than fits.
        var tall = new VerticalStackLayout { Spacing = 8 };
        for (int i = 0; i < 12; i++)
        {
            tall.Add(new Label { Text = $"scroll row {i}", FontSize = 26 });
        }
        layout.Add(new ScrollView { Content = tall, HeightRequest = 400 });
        return new ContentPage { Content = layout };
    }
}

/// <summary>
/// Passthrough stdout writer that counts the complete lines carrying the "[verify]" check
/// marker, so the suite can state its own contract line count in the [suite] summary and fail
/// when the run is below the declared floor.
/// </summary>
sealed class VerifyLineCountingWriter : TextWriter
{
    private readonly TextWriter _inner;
    private readonly System.Text.StringBuilder _line = new();

    public VerifyLineCountingWriter(TextWriter inner) => _inner = inner;

    public int VerifyLineCount { get; private set; }

    public override System.Text.Encoding Encoding => _inner.Encoding;

    public override void Flush() => _inner.Flush();

    public override void Write(char value)
    {
        Track(value);
        _inner.Write(value);
    }

    public override void Write(string? value)
    {
        if (value is null)
        {
            return;
        }

        foreach (char c in value)
        {
            Track(c);
        }

        _inner.Write(value);
    }

    private void Track(char c)
    {
        if (c == '\n')
        {
            if (_line.ToString().Contains("[verify]", StringComparison.Ordinal))
            {
                VerifyLineCount++;
            }

            _line.Clear();
        }
        else if (c != '\r')
        {
            _line.Append(c);
        }
    }
}

/// <summary>
/// MULTIWINDOW-L M2 dual-window app: the primary content plus whatever the OpenWindow calls
/// create (the suite's main TestApp stays untouched; this app owns only the M2 section).
/// </summary>
sealed class M2PerWindowApp : Microsoft.Maui.Controls.Application
{
    public M2Content Main { get; } = new("main-label", "main-button");

    protected override Window CreateWindow(IActivationState? activationState) => new(Main.Page);
}

/// <summary>
/// MULTIWINDOW-L M4 input content: label + entry + pinch label + button, so the per-window
/// focus/IME and pinch checks can drive a real text view and a real pinch recognizer inside a
/// secondary window without changing the M2/M3 content shape.
/// </summary>
sealed class M4InputContent
{
    public M4InputContent(string label, string entryText, string button)
    {
        Entry = new Entry { Text = entryText };
        Button = new Button { Text = button };
        Button.Clicked += (_, _) => Clicks++;
        PinchGestureRecognizer pinch = new();
        pinch.PinchUpdated += (_, e) => PinchLog += $"{e.Status}:{e.Scale:0.0} ";
        PinchLabel = new Label { Text = label + "-pinch" };
        PinchLabel.GestureRecognizers.Add(pinch);
        Page = new ContentPage
        {
            Content = new VerticalStackLayout
            {
                Children = { new Label { Text = label }, Entry, PinchLabel, Button },
            },
        };
    }

    public ContentPage Page { get; }

    public Entry Entry { get; }

    public Label PinchLabel { get; }

    public Button Button { get; }

    public int Clicks { get; private set; }

    /// <summary>One entry per received PinchUpdated (status:scale), the M4-04 routing evidence.</summary>
    public string PinchLog { get; private set; } = string.Empty;
}

/// <summary>One label + one button pair the M2 checks can frame and tap.</summary>
sealed class M2Content
{
    public M2Content(string label, string button)
    {
        Button = new Button { Text = button };
        Button.Clicked += (_, _) => Clicks++;
        Page = new ContentPage
        {
            Content = new VerticalStackLayout
            {
                Children = { new Label { Text = label }, Button },
            },
        };
    }

    public ContentPage Page { get; }

    public Button Button { get; }

    public int Clicks { get; private set; }
}

/// <summary>M3 Back-ownership probe: counts the Back presses this page handled (the page's
/// OnBackButtonPressed runs through IWindow.BackButtonClicked for the addressed window only).</summary>
sealed class M3BackPage : ContentPage
{
    private readonly Action _onBack;

    public M3BackPage(Action onBack)
    {
        _onBack = onBack;
        Content = new VerticalStackLayout { Children = { new Label { Text = "m3-back" } } };
    }

    protected override bool OnBackButtonPressed()
    {
        _onBack();
        return true;
    }
}

/// <summary>Records every DrawString a window's renderer emits, so each window's canvas target
/// can be proven independent (the M2 per-window canvas path).</summary>
sealed class M2RecordingCanvas : Microsoft.OpenHarmony.Maui.Graphics.OpenHarmonyCanvas
{
    public List<string> Texts { get; } = new();

    public override void DrawString(string value, float x, float y, float width, float height,
        Microsoft.Maui.Graphics.HorizontalAlignment horizontalAlignment,
        Microsoft.Maui.Graphics.VerticalAlignment verticalAlignment, float lineSpacingAdjustment = 0)
        => Texts.Add(value);
}

/// <summary>
/// MULTIWINDOW-L2: one WebView control the child-window checks drive. The URL source makes the
/// handler send its load through the window-scoped transport at connect, and the Navigated log
/// is the page-event routing evidence.
/// </summary>
sealed class L2WebContent
{
    public L2WebContent(string label)
    {
        Web = new Microsoft.Maui.Controls.WebView
        {
            Source = new Microsoft.Maui.Controls.UrlWebViewSource { Url = "https://example.test/child" },
            HeightRequest = 200,
        };
        Web.Navigated += (_, e) => NavigatedLog.Add($"{e.Result}:{e.Url}");
        Page = new ContentPage
        {
            Content = new VerticalStackLayout
            {
                Children = { new Label { Text = label }, Web },
            },
        };
    }

    public ContentPage Page { get; }

    public Microsoft.Maui.Controls.WebView Web { get; }

    public List<string> NavigatedLog { get; } = new();
}
